\section{Derivation of the UPE (1-3)}

We start from the Maxwell equations and consider the scalar approximation for the real-valued electric field $E(t,z,\br)$.
% with a central frequency $\omega_o$.
Considering the cubic (Kerr) nonlinearity, the Fourier transform of the field satisfies the nonlinear Helmholtz equation:
%$$
%\phi(t,z=0,r) = \psi_o(t,r) e^{-i\omega_o t} +c.c.
%$$
%Its Fourier transform $\hat\phi(\omega,z,\br) = \int \phi(t,z,\br)e^{i\omega t} dt$
%We consider the Helmholtz equation for the field $\phi(\omega,z,r)$:
%satisfies the nonlinear Hemholtz equation
\begin{equation}
\label{eq:helm}
\Delta \hat E + \frac{\omega^2}{c^2}  {\tilde n}^2(\omega,\br) \hat E  = -\frac{\omega^2}{c^2} \chi^{(3)} \widehat{E^3} ,
\end{equation}
where $\Delta =\Delta_\perp+\partial_z^2$ is the three-dimensional Laplacian, and $c$ is the vacuum light speed.
%${\tilde n}(\omega,\br)=n(\omega,\br)/n(\omega_o,{\bf 0})$ is the relative index of refraction.
% that does not depend on $z$ (waveguide axis).
% and is such that ${\tilde n}(\omega_o,{\bf 0})=1$. 
Here, ${\tilde n}(\omega,\br)$ is the index of refraction of the waveguide at the frequency $\omega$. We denote $n(\omega)={\tilde n}(\omega,{\bf 0})$ the index of refraction at $\br={\bf 0}$, and $n_o=n(\omega_o)$, with $\omega_o$ the central frequency of the field.
%and $c_o=c/{n}(\omega_o)$ is the homogeneous wave speed.
We may have ${\tilde n}^2(\omega,\br) = {n}^2(\omega)( 1-|\br|^2/a^2)$ for a parabolic (graded-index) fiber, or ${\tilde n}^2(\omega,\br) ={n}^2(\omega)$ 
 %(with Dirichlet boundary conditions for instance) 
 for a homogeneous (step-index) fiber.
%Then the index of refraction at  is ${n}(\omega)={n}(\omega_o) {\tilde n}_o(\omega)$, and $c_o = c/{n}(\omega_o)$, $c$ being the vacuum speed.
We introduce the real-valued orthonormal basis $u_m(\br)$, with eigenvalues $\beta_m$, which are solutions of
$$
%-\frac{1}{2k_o} \Delta_\perp u_m + \frac{k_o}{2}\big(1- {\tilde n}^2(\omega_o,\br)  \big) u_m=\beta_m u_m .
-\frac{1}{2k_o} \Delta_\perp u_m + \frac{\omega_o}{2n_oc}\big(n_o^2-n(\omega_o,\br)^2  \big) u_m=\beta_m u_m,
$$
where $k_o= n_o\omega_o/c$.
The field  can be expanded on the basis
$\hat E(\omega,z,\br) =\sum_m {a}_m(\omega,z) u_m(\br)$,
where ${a}_m(\omega,z) = \int u_m^*(\br) \hat E(\omega,z,\br) d\br$.
Note that ${a}_m(-\omega,z)={a}_m^*(\omega,z)$  because $E(t,z,\br)$ is real-valued.
By multiplying the Helmholtz equation (\ref{eq:helm}) by $u_m$ and integrating in $\br$, 
we get 
\begin{align*}
%&  \partial_z^2 {a}_m +\big(  q(\omega)^2   -  2k_o \beta_m\big)   {a}_m + \sum_p A_{mp}(\omega) {a}_p  \\
&  \partial_z^2 {a}_m +\big(  n_o^2\omega^2/c^2   -  2k_o \beta_m\big)   {a}_m + \sum_p A_{mp}(\omega) {a}_p  \\
&  =-\frac{\chi^{(3)} \omega^2}{(2\pi)^2 c^2}   \sum_{p,q,s} W_{mpqs} \int {a}_p(\omega_1){a}_q(\omega_2){a}_s(\omega_3) {\hat \delta}_\omega d\omega_{123},
\end{align*}
%with $q(\omega)=\omega/c_o$, 
with $W_{mpqs} = \int u_m(\br)u_p(\br)u_q(\br)u_s(\br) d\br$, ${\hat \delta}_\omega=\delta(\omega-\omega_1-\omega_2-\omega_3)$, $d\omega_{123}=d\omega_1 d\omega_2 d\omega_3$, and 
\begin{align*}
A_{mp}(\omega)&=  \int Q(\omega,\br) u_m(\br) u_p(\br) d\br   ,\\
%Q(\omega,\br)&= q^2(\omega)\big({\tilde n}^2(\omega,\br) -1\big) - k_o^2  \big({\tilde n}^2(\omega_o,\br) -1\big).
Q(\omega,\br)&= \frac{\omega^2}{c^2}\big({n}^2(\omega,\br) -n_o^2\big) - \frac{\omega_o^2}{c^2}  \big({n}^2(\omega_o,\br) -n_o^2\big).
\end{align*}
In general, the coefficients ${a}_m$ have rapid dominant phases of the form $\exp(i k_o z -i \beta_m z)$, so the terms $p\neq m$ in the sum over $p$ average out.
% (here we assume the absence of degenerate modes; in the presence of degenerate modes but ${\tilde n}^2$ is radial, we have $\int u_m^*(\br) ({\tilde n}^2-1) u_p(\br)d\br=0$ for $p\neq m$ such that $\beta_p=\beta_m$, which also ensures that the terms $p\neq m$ average out). 
The resulting equation can be written
\begin{align}
&  \partial_z^2 {a}_m +\big(  n_o^2\omega^2/c^2    -  2k_o \beta_m+\alpha_m (\omega)\big)     {a}_m 
\nonumber \\
&= -\frac{\chi^{(3)} \omega^2 }{(2\pi)^2 c^2}   \sum_{p,q,s} W_{mpqs} \int {a}_p(\omega_1) {a}_q^*(\omega_2) {a}_s(\omega_3) \delta_\omega d\omega_{123},
\label{eq:helm_am}
\end{align}
with $\alpha_m(\omega) = A_{mm}(\omega)$. 
This equation is obtained without approximations for the case of interest of a homogeneous trapping potential (step-index fiber), since $A_{mp}(\omega)=\alpha(\omega) \delta_{mp}$ is diagonal, with $\alpha(\omega)=(\omega^2/c^2) \big( n(\omega)^2-  n_o^2 \big)$.
Note that we have changed $\omega_2 \to -\omega_2$, so that the Dirac function reads
$\delta_\omega=\delta(\omega-\omega_1+\omega_2-\omega_3)$.

At variance with the multimode UPE in Ref.\cite{bejot19}, here $\beta_m$ and $W_{mpqr}$ do not depend on the frequency $\omega$, because we have expanded the field on the eigenmodes at frequency $\omega_o$. Then we just need to compute $\beta_m$, $\alpha_m(\omega)$ and $W_{mpqs}$, and not a function indexed by $m,p,q,s$ and four frequencies. The latter would have been necessary if we had chosen to expand the field on $\omega$-dependent modes.
\\

\noindent
{\bf The forward scattering approximation:}
We first remark that the general solution of (\ref{eq:helm_am}) without the nonlinear term has the form 
$$
{a}_m(\omega,z)= {a}_m^+(\omega) e^{ i (k_o  -{\tilde \beta}_m(\omega)) z} +{a}_m^-(\omega) e^{- i (k_o  -{\tilde \beta}_m(\omega)) z}  ,
$$
with
\begin{equation}
\label{eq:defBn2}
{\tilde \beta}_m(\omega)=k_o - \sqrt{  n_o^2\omega^2/c^2       -  2k_o \beta_m    + \alpha_m(\omega)  }  .
\end{equation}
Note that ${\tilde \beta}_m(\omega_o) \neq \beta_m$ in general.
In the presence of the nonlinearity we introduce
\begin{align*}
{a}_m^+(\omega,z) &= \frac{1}{2}\Big(  {a}_m(\omega,z)   + \frac{\partial_z {a}_m(\omega,z) }{i(k_o-{\tilde \beta}_m(\omega))} \Big) e^{-i(k_o-{\tilde \beta}_m(\omega))z} 
, \\
{a}_m^-(\omega,z) &= \frac{1}{2}\Big(  {a}_m(\omega,z)   - \frac{\partial_z {a}_m(\omega,z)}{i(k_o-{\tilde \beta}_m(\omega))}  \Big) e^{i(k_o-{\tilde \beta}_m(\omega))z} 
,
\end{align*}
so that the solution of (\ref{eq:helm_am}) has the form
\begin{align*}
{a}_m(\omega,z) = {a}_m^+(\omega,z) e^{ i (k_o  -{\tilde \beta}_m(\omega)) z } +{a}_m^-(\omega,z) e^{- i (k_o  -{\tilde \beta}_m(\omega)) z }  ,
\end{align*}
and ${a}_m^+(\omega,z) $ and ${a}_m^-(\omega,z) $
satisfy the coupled first-order system
\begin{align}
\partial_z {a}_m^+ &= - \frac{i}{2(k_o-{\tilde \beta}_m(\omega))} F [{\bm a}]_m e^{-i(k_o-{\tilde \beta}_m(\omega))z} ,\\
\partial_z {a}_m^- &= +\frac{i}{2(k_o-{\tilde \beta}_m(\omega))} F [{\bm a}]_m e^{+i(k_o-{\tilde \beta}_m(\omega))z} .
\end{align}
Neglecting the backscattered components ${a}_m^-$, introducing the mode amplitudes defined by 
${b}_m(\omega,z) = {a}_m(\omega,z) e^{-i k_oz }$, we obtain in a reference frame that propagates at the group velocity $v_g^{-1}=\partial_\omega k(\omega_o)$ the UPE (1):
\begin{align}
&i \partial_z {b}_m(\omega) = {\tilde B}_m(\omega)   {b}_m  -  \gamma \Gamma_m(\omega)   P_{m}({\bm b}),
\label{eq:upe1}\\
&P_{m}({\bm b})=\sum_{pqs} W_{mpqs} \int {b}_p(\omega_1) {b}_q^*(\omega_2){b}_s(\omega_3) \delta_{\omega} 
d\omega_{1-3},
\label{eq:upe2}
\end{align}
with ${\tilde B}_m(\omega)={\tilde \beta}_m(\omega)+\frac{\omega}{v_g}$, $\Gamma_m(\omega) = \frac{\omega^2}{\omega_o^2} \frac{ k_o}{k_o-{\tilde \beta}_m(\omega)}$ and $\gamma = \chi^{(3)} \omega_o/(8\pi^2 c)$.   


The UPE (\ref{eq:upe1}-\ref{eq:upe2}) conserves the Hamiltonian $H_{b}=E_{b}+U_{b}$:
\begin{align}
E_{b} &=\sum_m \int \frac{{\tilde B}_m(\omega)}{\Gamma_m(\omega)} |{b}_m(\omega)|^2 d\omega, 
\label{eq:H_E_b}\\
U_{b} &= -\frac{\gamma}{2} \sum_{mpqs} \int W_{mpqs}
{b}_m^*(\omega_1) {b}_p(\omega_2) {b}_q^*(\omega_3) {b}_s(\omega_4) \delta_\omega
d\omega_{1234}
\label{eq:H_U_b}
\end{align}
with  $\delta_\omega=\delta(\omega_1+\omega_3-\omega_2-\omega_4)$.
It also conserves the number of particles and the `temporal' momentum 
\begin{align}
N_{b} = \sum_m  \int \frac{|{b}_m(\omega)|^2}{\Gamma_m(\omega)} d\omega,  \ 
P_{b} = \sum_m   \int \omega \frac{|{b}_m(\omega)|^2}{\Gamma_m(\omega)} d\omega.
\label{eq:N_b_P_b}
\end{align}
The nonlinear length is defined by $L_{nl}=1/(|\gamma_0| {\bar N}_{b})$, where ${\bar N}_{b}=N_b/L$ is the optical power (averaged over the numerical time window, $L$), and $\gamma_0=\gamma/A_{\rm eff}^0$ the effective nonlinear coefficient (in W$^{-1}$m$^{-1}$), with $A_{\rm eff}^0=1/W_{0000}$ the effective area of the fundamental mode.  

