\noindent
{\bf The NLSE approximation:}
Making use of the slowly-varying envelope approximation in the time domain and the paraxial approximation in the space domain, and using 
$k(\omega)=k(\omega_o) + \partial_\omega k(\omega_o)(\omega-\omega_o)+\frac{1}{2}\partial_\omega^2 k(\omega_o)(\omega-\omega_o)^2 $, gives
%\begin{equation}
${\tilde B}_m(\omega) = \beta_m -\kappa_2 (\omega-\omega_o)^2$,  
%\end{equation}
%\begin{equation}
%{\tilde B}_m(\omega) = k_o-\Big( k(\omega_o) + k'(\omega_o)(\omega-\omega_o)+\frac{1}{2}k''(\omega_o)(\omega-\omega_o)^2 - \beta_m\Big) +\frac{\omega-\omega_o}{v_g} = \beta_m +d (\omega-\omega_o)^2 
%\label{eq:limit_step_nls}
%\end{equation}
%\endwidetext
because $\frac{1}{v_g}=\partial_\omega k(\omega_o)$ and $\kappa_2=\frac{1}{2}\partial_\omega^2 k(\omega_o)$.
The nonlinear coefficient reduces to a constant, $\Gamma_m(\omega)=1$.
%The equilibrium recovers the standard form:
%$n_m^{eq}(\omega)= \frac{T }{\beta_m + d (\omega-\omega_o)^2-\mu}$, 
%where we have assumed that $P(z = 0) = 0$, so that $\lambda= 0$ as a result
%of momentum conservation at equilibrium.


\bigskip
\noindent
{\bf The NEE approximation:}
The main difference with respect to the NLSE limit is that the NEE preserves the frequency dependence of $k(\omega)$, but neglects the dispersion of the refractive index, i.e., we set ${n}(\omega)={n}(\omega_o)$ in $k(\omega)={n}(\omega_o)\omega/c$ \cite{kolesik04}, so that  $\frac{2k_o \beta_m}{2 k(\omega)}\simeq \frac{\beta_m}{1+\frac{\omega-\omega_o}{\omega_o}}$, and
\begin{equation}
{\tilde B}_m(\omega) = \frac{\beta_m}{1+\frac{\omega-\omega_o}{\omega_o}} - \sum_{j\ge 2} \kappa_j (\omega-\omega_o)^j ,
\label{eq:limit_step_nee}
\end{equation}
with $\kappa_j=\frac{1}{j!}\partial_\omega^j k(\omega)|_{\omega_o}$.
%where $d_j = \frac{1}{j!}\big(\frac{\partial^j q(\omega)}{\partial \omega^j}\big)_{\omega_o}$.
The first term in (\ref{eq:limit_step_nee}) couples spatial and temporal effects.
The approximation ${\tilde \beta}_m(\omega)\simeq \beta_m\big( 1-\frac{\omega-\omega_o}{\omega_o}\big) - \sum_{j\ge 2} \kappa_j (\omega-\omega_o)^j$  is called partially-corrected NLS equation \cite{kolesik04}.\\
For the nonlinear coefficient $\Gamma_m(\omega)$, the NEE approximates $\sqrt{  k(\omega)^2  -  2k_o \beta_m } \simeq k(\omega)$. 
Neglecting the dispersion of the refractive index, we get 
%$\Gamma_m(\omega) \simeq \frac{\omega^2}{\omega_o^2} \frac{\gamma k_o}{{n}(\omega_o)\omega/c}=\gamma \big( 1+ \frac{\omega-\omega_o}{\omega_o} \big)$.
\begin{equation*}
\Gamma_m(\omega) \simeq \frac{\omega^2}{\omega_o^2} \frac{k_o}{{n}(\omega_o)\omega/c}=
 1+ \frac{\omega-\omega_o}{\omega_o}  .
\end{equation*}
%%In the NEE limit the governing equation is Eq.(\ref{eq:evol3_vg}) with ${\tilde B}_m(\omega)$ given by (\ref{eq:limit_step_nee}) and ${D}_m(\omega)$ given by (\ref{eq:limit_step_nee_Dm}). 

Note that the NEE can be written in the space-time domain.
Considering the complex envelope field $\psi(\br,t,z)$, the NEE reads
%\begin{align*}
%i\partial_z \psi &= \frac{1}{(1+i\omega_o^{-1} \partial_t)}
%\Big(-\frac{1}{2k_o}\nabla^2 \psi + V(\br) \psi \Big)
%+\sum_{j\ge 2} \kappa_j \partial_t^j \psi \\ 
%& \quad + \gamma \big(1+i\omega_o^{-1} \partial_t \big) |\psi|^2\psi.
%\end{align*}
%with ${\hat D}(i\partial_t)\psi=\sum_{j\ge 2} \kappa_j \partial_t^j \psi$.
\begin{align}
i\partial_z \psi(\br,t,z) &= \frac{-1}{2k_o(1+i\omega_o^{-1} \partial_t)}
\nabla^2 \psi 
+\frac{1}{(1+i\omega_o^{-1} \partial_t)} V(\br) \psi \nonumber \\
& \quad +\sum_{j\ge 2} \kappa_j \partial_t^j \psi 
- \gamma \big(1+i\omega_o^{-1} \partial_t \big) |\psi|^2\psi.
\label{eq:nee_rt}
\end{align}
By removing the operators $(1+i\omega_o^{-1} \partial_t)$ and by retaining only second-order dispersion effects ($j=2$), Eq.(\ref{eq:nee_rt}) recovers the NLSE approximation.

