\times \big[ {\check n}_m(\omega_1)^{-1}-{\check n}_p(\omega_2)^{-1}
+{\check n}_q(\omega_3)^{-1}-{\check n}_s(\omega_4)^{-1}\big] \delta(\omega_3-\omega_4+\omega_1-\omega_2)
\\
&
- {2 i\gamma } \Big[ \sum_{p'}
 \int L^*_{mpp'p'} (\omega_1,\omega_1,\omega,\omega) {\check n}_{p'}(\omega)d\omega\Big] \big( {\check n}_p(\omega_1)-{\check n}_m(\omega_1)\big) {\check n}_q(\omega_3) \delta_{qs}^K \delta(\omega_2-\omega_1) \delta(\omega_3-\omega_4+\omega_1-\omega_2)\\
&
- {2 i\gamma } \Big[ \sum_{p'}
\int L^*_{mp'p's}(\omega_1,\omega,\omega,\omega_1)  {\check n}_{p'}(\omega)d\omega\Big] \big( {\check n}_s(\omega_1)-{\check n}_m(\omega_1)\big) {\check n}_p(\omega_2) \delta_{pq}^K \delta(\omega_4-\omega_1) \delta(\omega_3-\omega_4+\omega_1-\omega_2)
\\
&
- {2 i\gamma } \Big[ \sum_{p'}
 \int L^*_{p'p'qs}(\omega,\omega,\omega_3,\omega_3) {\check n}_{p'}(\omega)d\omega\Big] \big( {\check n}_s(\omega_3)-{\check n}_q(\omega_3)\big) {\check n}_m(\omega_1) \delta_{pm}^K \delta(\omega_4-\omega_3) \delta(\omega_3-\omega_4+\omega_1-\omega_2)
\\
&
- {2 i\gamma } \Big[ \sum_{p'}
 \int L^*_{p'p'qp}(\omega,\omega,\omega_2,\omega_2) {\check n}_{p'}(\omega)d\omega\Big] \big( {\check n}_p(\omega_2)-{\check n}_q(\omega_2)\big) {\check n}_m(\omega_1) \delta_{sm}^K \delta(\omega_3-\omega_2) \delta(\omega_3-\omega_4+\omega_1-\omega_2)
