\end{align*}
where $\left< \check{b}_m(\omega_1) {\check{b}_{m'}^*}(\omega_1') \right> ={\check n}_m(\omega_1) \delta_{mm'}^K \delta(\omega_1-\omega_1')$.
By the presence of the factor $ \delta(\omega_3-\omega_4+\omega_1-\omega_2)$ in the rhs, we have
$$
 \left< {\check{b}_m^*(\omega_1)}
\check{b}_{p}(\omega_2) {\check{b}_{q}^*(\omega_3)} \check{b}_{s}(\omega_4) \right>
= \delta(\omega_3-\omega_4+\omega_1-\omega_2)
J_{mpqs}(\omega_1,\omega_2,\omega_3,\omega_4)
$$
