&+{{\cal U}_{qs}^*[{\bf {\check n}}]}(\omega_3) \big( {\check n}_s(\omega_4)-{\check n}_q(\omega_3) \big) {\check n}_m(\omega_1) \delta_{pm}^K \delta(\omega_2-\omega_1) 
\\
&+{{\cal U}_{qp}^*[{\bf {\check n}}]}(\omega_3) \big( {\check n}_p(\omega_2)-{\check n}_q(\omega_3) \big) {\check n}_m(\omega_1) \delta_{sm}^K \delta(\omega_4-\omega_1) ,
\nonumber\\
{\cal U}_{qp}[{\bf {\check n}}](\omega) =& \sum_{p'} \int L_{qpp'p'} (\omega,\omega,\omega',\omega') {\check n}_{p'}(\omega')d\omega' .
\end{align}
After simplification,
we finally obtain
\begin{align}
 \partial_z {\check n}_m(\omega_1) =&  -{2\gamma}    {\rm Im}\Big( \sum_{p,q,s}  \iint 
