\partial_z {J}_{mpqs}^{(1)}(\omega_1,\omega_2,\omega_3) =& i \Omega_{mpqs}(\omega_1,\omega_2,\omega_3,\omega_1+\omega_3-\omega_2) {J}_{mpqs}^{(1)}(\omega_1,\omega_2,\omega_3) \\
