\section{Higher Hida Theory} \label{sec:HHidaTh}

\subsection{On the Iwasawa algebra}
Let $G$ be a profinite group, and suppose that it is isomorphic to $\lim_m G_m$, where the $G_m$'s are finite groups. Let us write $A_\mathfrak p\llbracket G\rrbracket= \lim_m (A_{\mathfrak p}/\mathfrak p^m )[G_m]$.
 This algebra is called the Iwasawa algebra of $G$. In the special case when $G=A_\mathfrak p^\times$, we denote $A_\mathfrak p\llbracket G\rrbracket$ by $\Lambda$.  Our first goal of this section is to find a suitable description of the profinite structure of $\Lambda$.

%Let us denote $R_m=A_{\mathfrak p}/\mathfrak p^m [(A_{\mathfrak p})^\times/(1+\mathfrak p^m)]$ and $I_m=\ker (\Lambda \to R_m)$. Recall that the profinite group  $A_\mathfrak p^\times$ has a natural filtration by the open subgroups $(1+\mathfrak p^i)$,  $i\in \mathbb N$ such that the successive quotient are isomorphic to a $k(\mathfrak p)$-vector spaces of dimension $1$.
\begin{lem}\label{lem:iwalg}
The ring $\Lambda$ is a profinite semilocal ring 
\[
\Lambda \cong \prod_{ \chi \in {(\kappa(\mathfrak p)^\times)}^*} \Lambda_0,  
\]
for $\Lambda_0:=A_{\mathfrak p} \llbracket 1+\mathfrak p  \rrbracket $, the Iwasawa algebra of  $1+\mathfrak p $.
Moreover, we can choose a family of ideals  $I_r$ giving the profinite structure such that the $\Lambda$-action on $I_r/I_{r+1}$ factors via
\[
\prod_{ \chi \in {(\kappa(\mathfrak p)^\times)}^*} \kappa(\mathfrak p)^.
\]
\end{lem}


\begin{proof}
The decomposition of  $\Lambda$ over   ${ \chi \in {(\kappa(\mathfrak p)^\times)}^*}$ is via Fourier analysis (see \textnumero 5 \S 21 of \cite{Brbkalg8}). We have 
\[
A_{\mathfrak p} \llbracket 1+\mathfrak p \rrbracket  \cong \varprojlim_m A_{\mathfrak p}/\mathfrak p^m [(1+\mathfrak p)/(1+\mathfrak p^m)]
\]
which is profinite.
As $1+\mathfrak p$ is a pro-$p$ group in infinitely many generators, \[
A_{\mathfrak p} \llbracket 1+\mathfrak p  \rrbracket  \cong A_{\mathfrak p} \llbracket T_1, T_2, \ldots \rrbracket.
\]
We set $I_0=J_0=(\varpi, T_1, T_2, \ldots)$, $J_n=((\varpi, T_1, T_2, \ldots, T_n)^n, T_{n+1}, \ldots)$. Define $I_2=J_2$.
Suppose we have defined $I_3, \ldots, I_{\alpha(n)}=J_n$. 
Note that a basis of $J_n/J_{n+1}$ is given by
\[
\varpi^{n}, \varpi^{n-1}T_1, \ldots, T_n^n, T_{n+1}, T_{n+1}\varpi, T_{n+1}^2, T_{n+1}T_2 ,\ldots, T_{n+1}T_n^{n-1}.
\]
In short, all the monomials of degree $n$ in $\varpi, T_1, T_2, \ldots, T_n$ and all monomials with $\varpi, T_1, T_2, \ldots, T_n$ and $T_{n+1}$
whose degree is less than $n+1$ and divisible by $T_{n+1}$.
We define $I_{\alpha(n)+1}=((\varpi, T_1, T_2, \ldots, T_n)^{n+1}, T_{n+1}, \ldots)$. The action of $\Lambda$ on $I_{\alpha(n)+1}/I_{\alpha(n)}$ is trivial. 
We define  $I_{\alpha(n)+j}$ as generated by:
\begin{itemize}
    \item $(\varpi, T_1, T_2, \ldots, T_n)^{n+1}$;
    \item all the monomials in $\varpi, T_1, T_2, \ldots, T_n$ and $T_{n+1}$ of degree $j$ which are divisible by $T_{n+1}$;
    \item all the other variables  $ T_{n+2}, \ldots$.
\end{itemize}  For $j=1$ we get back  
$I_{\alpha(n)+1}$ as we only add $T_{n+1}$.
We need to show that \[ \frac{I_{\alpha(n)+j}}{I_{\alpha(n)+j+1}} \] has the trivial $\Lambda$-action. It is generated over $\kappa(\mathfrak p)=A_{\mathfrak p} /\mathfrak p$  by monomials in  $\varpi, T_1, T_2, \ldots, T_n$ and $T_{n+1}$ of exact degree $j$ with at least a single power of $T_{n+1}$. The action of the maximal ideal of $\Lambda$ is zero: the extra variables $T_{n+2}, \ldots $ all act trivially. The action of $\varpi, T_1, T_2, \ldots, T_n$ and $T_{n+1}$ is also trivial, as multiplication by any of these elements on the basis will give a a monomial of  degree $j+1$, still divisible by $T_{n+1}$, which is then in $I_{\alpha(n)+j+1}$.
\end{proof}


% Note that $I_m/I_{m+1}$ is isomorphic as a $k(\mathfrak p)$-vector space to $k(\mathfrak p)[k(\mathfrak p)]$. 


\begin{rmk} The ring $\Lambda$ is non-noetherian. For simplicity suppose that $A_\mathfrak p^\times \cong \mathbb F_p\llbracket X\rrbracket^{\times}=\mathbb F_p^\times \times (1+X\mathbb F_p\llbracket X\rrbracket) $. Now in this case, $1+X\mathbb F_p\llbracket X\rrbracket$ has infinitely many $\mathbb Z_p$-topological generators, given by $(1+X)^m$ with $m$ a positive integer coprime with $p$, in formula,
\begin{align*}
    1+X\mathbb F_p\llbracket X\rrbracket &\xrightarrow{\sim}\prod_{m\colon p\nmid m}\mathbb Z_p.\\
    ( 1+X)^m &\mapsto e_m,
\end{align*}
where $e_m$ is canonical $m$-coordinate basis of the Cartesian product. Then $\Lambda = A_{\mathfrak p}[\mathbb F_p^\times]\otimes A_{\mathfrak p}\llbracket X_i \colon i\in \mathbb{N}\rrbracket$. This discussion also show the following: let $m_\Lambda$ be the kernel of the natural projection $\Lambda \to R_1 =\kappa(\mathfrak p)[\kappa(\mathfrak p)^\times]$, then $\Lambda$ is complete in its limit topology, but it is not $m_\Lambda$-adically complete (see \href{https://stacks.math.columbia.edu/tag/05JA}{Tag 05JA}).
\end{rmk}


We give some useful properties of our Iwasawa algebra. For that let us define the following: Let $k \in \mathbb{Z}_p$;  we define the  ideal $P_k$ to be the kernel of the map 
    \[
    \begin{array}{ccccc}
      f_k  : & \Lambda_0    & \longrightarrow  & A_{\mathfrak p} \\
         & 1+\mathfrak p A_{\mathfrak p} \ni [u] & \mapsto & u^k.
    \end{array}
    \]
 We denote by $\mathcal{C}(\mathbb{Z}_p,  A_{\mathfrak p} )$ the space of continuous functions $\mathbb{Z}_p \rightarrow A_{\mathfrak p}$.

\begin{prop} \label{prop:densek} 
 There is an injective morphism $\iota:   \Lambda_0    \longrightarrow    \mathcal{C}(\mathbb{Z}_p,  A_{\mathfrak p} ) $, induced by $1+\mathfrak p A_{\mathfrak p} \ni [u] \mapsto  (s \mapsto u^s)$ and extended  $A_{\mathfrak p} $ linearly.
Moreover, the set of ideals $\left\{ P_k \right\}_{ k \in I}$ is Zariski dense in $\Lambda_0$ as long as $I$ is dense subset of $\Z_p$.

\end{prop}

\begin{proof}
   We show that we can embed $\Lambda_0 $ in the dual of $A_{\mathfrak p}$-valued continuous functions on $1+\mathfrak p$.
    % {\color{blue} We are not really using this,  right? First, recall that we have a Mahler isomorphism between the bounded linear functional on continuous functions on $A_{\mathfrak p}$ ({\it i.e.} measures or bounded distributions) and $A_{\mathfrak p}\llbracket  z \rrbracket \otimes_{A_{\mathfrak p}}\mathrm{Frac}(A_{\mathfrak p})$.} We define a measure associated with $x$, in the following way:
    Let $G=1+\mathfrak p$. If $x = \varprojlim x_i \in A[G/G_i]$, let $\mu_x$ be the measure such that $\mu_x(gG_i)=a_g$, where $x_i=\sum_{g G/G_i} a_g gG_i$. 
    This is indeed a measure: if  $x_{i+1}=\sum_{g' G/G_{i+1}} a_{g'} {g'}G_{i+1}$ is a lift of $x_i$, then we have $\sum_{g' \equiv g \bmod G_i } a_{g'}=a_g$, so writing $gG_i=\cup_{g' \equiv g \bmod G_i} g'G_{i+1}$ so we get 
    \[
    \sum_{g' \equiv g \bmod G_i} \mu_x(g'G_{i+1}) = \sum_{g' \equiv g \bmod G_i } a_{g'}=a_g = \mu_{x}(gG_i).
    \]
    We extend it to zero outside $1+\mathfrak p $.
  This map is injective  as if $\mu_x(gG_i)=0$ for all $i$'s and $g$, then $x_i=0$ for all $i$'s, and $x =0$.    
    By a result of Kaplansky (see \cite[Theorem 43.3]{Ultrametric calculus}) polynomial functions are dense in $\mathrm{Frac}(A_{\mathfrak p})$-valued continuous functions on $1+\mathfrak p$, so a distribution coming from $\Lambda_0\otimes_{A_{\mathfrak p}}\mathrm{Frac}(A_{\mathfrak p})$  that vanishes on all polynomials must be $0$. But $\otimes_{A_{\mathfrak p}}\mathrm{Frac}(A_{\mathfrak p})$ is flat, so we conclude that $\mu_x=0$ if it integrates all polynomials to $0$.

To show that the map $\iota$ is injective, suppose $\iota(x)(s)\equiv 0$. Then in particular it is $0$ when evaluated at a positive integer $k$. But $\mathrm{ev}_k \circ \iota$ is reducing modulo $P_k$ or equivalently $\mu_x(u^k)$, so $\mu_x=0$ by Kaplansky's result, and $x=0$.  For a general subset $I$ of $\mathbb Z_p$, we consider the map
\[
\begin{array}{ccccc}
     \prod_{k\in I} \mathrm{ev}_{k}:  &\mathcal{C}(\mathbb{Z}_p,  A_{\mathfrak p} )    & \longrightarrow  &  \prod_{k \in I} A_{\mathfrak p}  \\
         & f(s) & \mapsto & (f(k))_{k \in I}.
    \end{array}
\]
If $\iota(x)(s)$ vanishes for all $k \in I$, as $I$ is dense in $\Z_p$, then $\iota(x)(s)\equiv 0$ but as $\iota$ is injective, then $x=0$.
\end{proof}

\subsection{\texorpdfstring{The projectors $e(F)$ and $e(U_{\fp})$}{The projectors e(F) and e(Up)}}



We now can consider and define our main $\Lambda$-modules
\begin{center}
    $\operatorname{H}^0(\mathfrak X^{\ord},\omega^{\kappa^{un}})$ and $\operatorname{H}^1_c(\mathfrak X^{\ord},\omega^{\kappa^{un}}).$
\end{center}
Since $\mathfrak X^{\ord}$ is affine  and $\omega^{\kappa^{un}}$ a coherent sheaf, we can use the formalism of \cite{ClSc2019} to define the first cohomology group  of compact support. We are going to recall it. First, we define for every $n$ the cohomology group by $\operatorname{H}^1_c(X^{\ord}_n,\omega^{\kappa^{un}}\otimes (\Lambda/I_n))= \operatorname{H}^1(q_{n,!}\omega^{\kappa^{un}}\otimes (\Lambda/I_n))$, where $q_n\colon X_n^{\ord}\to \operatorname{Spec}(A_\mathfrak p/\mathfrak p^n)$ is the structure map of the ordinary locus. Now, we  define
\[\operatorname{H}^1_c(\mathfrak X^{\ord},\omega^{\kappa^{un}})=\lim \operatorname{H}^1_c(X^{\ord}_{n},\omega^{\kappa^{un}}\otimes (\Lambda/I_n)).\]
We have the following interpolation result:
\begin{prop} \label{prop:spk}
    We have the following identities: 
    \[\operatorname{H}^0(\mathfrak X^{\ord},\omega^{\kappa^{un}}) \otimes_{\Lambda,f_k}A_\fp=\operatorname{H}^0(\mathfrak X^{\ord},\omega^k), \quad k\geq 3.\]
    \[\operatorname{H}^1_c(\mathfrak X^{\ord},\omega^{\kappa^{un}}) \otimes_{\Lambda,f_k}A_\fp=\operatorname{H}^1_c(\mathfrak X^{\ord},\omega^k), \quad k\leq -1.\]
\end{prop}
\begin{proof}
For $\operatorname{H}^0$, it is essentialy \eqref{eq:sp k} combined with the vanishing of $\operatorname{H}^1$ on the ordinary locus.
For $\operatorname{H}^1_c$, we again take the long exact sequence coming from 
\[
0 \rightarrow \mathrm{Ker}(f_k)\rightarrow \Lambda \rightarrow A_\fp \rightarrow 0
\]
combined with the vanishing of $\operatorname{H}^i_c(\mathfrak X^{\ord}, \phantom{A})$ for $i=0,2$.
\end{proof}

Let $M=\lim M/I_nM$ and $T$ a $\Lambda$-endomorphism of $M$, where the $I_n$'s are the ones in Lemma \ref{lem:iwalg}. We say that $T$ is locally finite if for all $n$, the induced endomorphism $M/I_nM$ over the Artinian ring $R_n=\Lambda/I_n$ is locally finite in the sense of \cite[Section 2.2]{BoPi2022} reviewed in Section \ref{subsec:corrmodp}. We note that the definition of locally finite  in this context also comes from [\emph{loc.\,cit.}].

\begin{thm} \label{thm:projandinter}
    There exist locally finite operators $F$ and $U_\mathfrak p$ on $\operatorname{H}^1_c(\mathfrak X^{\ord},\omega^{\kappa^{un}})$ and $\operatorname{H}^0(\mathfrak X^{\ord},\omega^{\kappa^{un}})$, respectively, with projectors $e(F)$  and $e(U_{\mathfrak p})$ , respectively. These are defined via the formulas $e(F)=\lim_n F^{n!}$ and  $e(U_{\mathfrak p})=\lim_n U_{\mathfrak p}^{n!}$. Moreover, for the morphism $f_k$ defined above we have the following identities: 
    \[e(U_{\mathfrak p})\operatorname{H}^0(\mathfrak X^{\ord},\omega^{\kappa^{un}}) \otimes_{\Lambda,f_k}A_\fp=e(U_{\mathfrak p})\operatorname{H}^0(\mathfrak X^{\ord},\omega^k), \quad k\geq 3.\]
    \[e(F)\operatorname{H}^1_c(\mathfrak X^{\ord},\omega^{\kappa^{un}}) \otimes_{\Lambda,f_k}A_\fp=e(F)\operatorname{H}^1_c(\mathfrak X^{\ord},\omega^k), \quad k\leq -1.\]
\end{thm}

\begin{proof}
The result for $\operatorname{H}^0$ is essentially in \cite{NiRo2021} so we prove only the result for $\operatorname{H}^1_c$.  We follow very closely the arguments in \cite[Section 4.2]{BoPi2022}. As there, we focus on $F$ and aim to construct an action $F$ on $\operatorname{H}^1_c(X^{\ord}_{n},\omega^{\kappa^{un}}\otimes (\Lambda/I_n))$, compatible for all $n$. Recall that we write $X_0(\mathfrak p)_n \to {\rm Spec}(A_\mathfrak p/\mathfrak p^n)$ for the reduction modulo $\mathfrak p^n$ of $X_0(\mathfrak p)$, and $X_0(\mathfrak p)^{\ord}_n$ for its ordinary locus.

First we construct a cohomological correspondence on  $X_0(\mathfrak p)^{\ord}_n$: 
\[p_2^*\omega^{\kappa^{un}}/I_n\to p_1^!\omega^{\kappa^{un}}/I_n.\]
Recall that we have $X_0(\mathfrak p)^{\ord}_n=X_0(\mathfrak p)^{\ord,F}_n\coprod X_0(\mathfrak p)^{\ord,V}_n$. Moreover, the graph of $F$ with its two natural projections is $X_0(\mathfrak p)^{\ord,F}$ with $p_1$ and $p_2$. With this, we construct the correspondence in the following way, on $X_0(\mathfrak p)^{\ord,V}_n$ we define it as $0$, and on $X_0(\mathfrak p)^{\ord,F}_n$ as $F:F^*\omega^{\kappa^{un}}\to \omega^{\kappa^{un}}$, where we are using the graph identification just mentioned. 



To continue, we express $H^1_c$ in terms of the pushing forward from $X_n^{\ord}$ to $X_n$, as in Section \ref{subsec:corrmodp}. We let $\mathcal I \subset \mathcal{O}_{X_n}$
be a locally principal sheaf of ideals so that the complement of the corresponding closed subscheme is $X^{\ord}_n$. We take a coherent sheaf $\mathcal F$ over $X_n$ extending $\omega^{\kappa^{un}}/I_n$. We may assume that $\mathcal{F}$ is $\mathcal{I}$-torsion free by replacing $\mathcal{F}$ with its quotient by the subsheaf of $\mathcal{I}$-power torsion. Then, the multiplication map $\mathcal{I}\otimes \mathcal{O}_{X_n}\mathcal{F} \to  \mathcal{I}^l\mathcal{F}$
is an isomorphism for all $l\geq 0$, and we use this to make sense of $\mathcal{I}^l\mathcal{F}$ for all $l \in \mathbb Z$. Then, if $j\colon X^{\ord}_n\to X$ denotes the inclusion, we have $j_*\omega^{\kappa^{un}}/I_n = {\rm colim}_l \mathcal I^l\mathcal F$. With this, we have the following identification $\operatorname{H}^1_c(X^{\ord}_{n},\omega^{\kappa^{un}}/I_n)=\lim_l \operatorname{H}^1(X_{n},\mathcal I^l\mathcal F)$.

Now, we continue with the construction of $F$: By pushing forward via $j$ we obtain
\[{\rm colim}_lp_2^*(\mathcal{I}^{-l}\mathcal{F})\to{\rm colim}_lp_1^!(\mathcal{I}^{-l}\mathcal{F}). \] 
It follows that there exists some $c$ for which there is a map $p_2^*\mathcal{F}\to p_1^!(\mathcal{I}^{-c}\mathcal{F})$. Furthermore, we note that $p^*_1\mathcal{I}$ and $p^*_2\mathcal{I}$ can be identified with $p^{-1}(\mathcal I)\mathcal O_{X_0(\mathfrak p)_n}$ and $p^{-1}_2(\mathcal I)\mathcal O_{X_0(\mathfrak p)_n}$, and so we view them as locally principal sheaves of ideals in $\mathcal O_{X_0(\mathfrak p)_n}$. They define the same closed subset of $X_0(\mathfrak p)_n$ (the complement of $X_0(\mathfrak p)^{\ord}_n)$, and so in particular we can pick some $m$ with $p_2^*\mathcal{I}^m \subset p_1^*\mathcal{I}$. Using this inclusion  we deduce a map
\[p_2^*(\mathcal{I}^{lm})\to p_1^!(\mathcal{I}^{-c+l}\mathcal{F}),\]
for all $l\geq0$. Taking cohomology we obtain a map $F:\operatorname{H}^1(X_n,\mathcal{I}^{lm}\mathcal{F})\to \operatorname{H}^1(X_n,\mathcal{I}^{-c+l}\mathcal{F})$. Passing to the limit, we get our endormorphism $F$ of $\operatorname{H}^1_c(X_n^{\ord},\omega^{\kappa^{un}}/I_n)$.


The next point is to check that $F$ is locally finite. For this, we do an induction argument. The case $n=1$ follows from the analogous properties form the Drinfeld modular curve $X$. For the induction step we can use the exact sequence

\[
 \resizebox{\hsize}{!}{$0\to \operatorname{H}_c^1(X_n^{\ord},\omega^{\kappa^{un}}\otimes (I_n/I_{n+1})) \to \operatorname{H}_c^1(X_{n+1}^{\ord},\omega^{\kappa^{un}}\otimes (\Lambda/I_{n+1})) \to \operatorname{H}_c^1(X_{n}^{\ord},\omega^{\kappa^{un}}\otimes (\Lambda/I_{n}))\to 0.$}
\]
 Now, using exactness properties of the notion of locally finite, one can deduce the properties for $n+1$ from $n$ and $\operatorname{H}_c^1(X_n^{\ord},\omega^{\kappa^{un}}\otimes (I_n/I_{n+1}))$.


 To prove the control theorem, note that by functoriality of $f_k$ we have a natural map 
\[\operatorname{H}^1_c(\mathfrak X^{\ord},\omega^{\kappa^{un}}) \otimes_{\Lambda,f_k}A_\fp \rightarrow \operatorname{H}^1_c(\mathfrak X^{\ord},\omega^k),
\]
both modules are $\varpi$-torsion free, so it is enough to prove the results modulo $\varpi$ and invoke Nakayama's lemma. But the result modulo $\varpi$ is exactly Corollary \ref{cor:descent}.
\end{proof}
%To finish we check how this interpolation relates with information coming from the cohomology group over $X$. For that we firstly observe that in the ordinary locus we have an isomorphism $\omega\cong\omega_D$. Moreover, we can define the Hecke operator $T_{\fp}$ on $H^1(X,\omega^{1-k}\otimes\omega_D(-2D))$ and prove that it is locally finite in the sense of \cite[Section 2.2]{BoPi2022}.


\subsection{Duality for families} \label{sec:dualityfamilies}
We define the ``dualizing complex''  of $\omega^{\kappa^{un}}$ by 
 \[\Omega^1_{X/A_\fp}\otimes \operatorname{\underline{Hom}}(\omega^{\kappa^{un}},\Lambda\widehat\otimes \mathcal{O}_{\mathfrak X^{\ord}}).\]
We denote it by ${\bf D}(\omega^{\kappa^{un}})$. By Serre duality we already have a pairing 
\[\operatorname{H}^0(\mathfrak X^{\ord}, \omega^{\kappa^{un}}) \times \operatorname{H}^1_c(\mathfrak X^{\ord}, {\bf D}(\omega^{\kappa^{un}})) \to \Lambda.\]
Using the  Kodaira--Spencer isomorphism  and $\omega\cong\omega_D$ over $\mathfrak X^{\rm ord}$, we have that
\[{\bf D}(\omega^{\kappa^{un}})\cong \omega\otimes \omega_D(-2D)\otimes \operatorname{\underline{Hom}}(\omega^{\kappa^{un}},\Lambda\widehat\otimes \mathcal{O}_{\mathfrak X^{\ord}})\cong\omega^2(-2D)\otimes \operatorname{\underline{Hom}}(\omega^{\kappa^{un}},\Lambda\widehat\otimes \mathcal{O}_{\mathfrak X^{\ord}}).\]
 Moreover, the character $A_\mathfrak p^\times\to \Lambda^\times, t\mapsto t^2(\kappa^{un}(t))^{-1}$ induces an automorphism $d\colon \Lambda \to \Lambda$ and we have an isomorphism of $\mathcal{O}_{\mathfrak X^{\ord}}\widehat\otimes \Lambda$-modules ${\bf D}(\omega^{\kappa^{un}})\cong\omega^{\kappa^{un}}\otimes_{\Lambda,d}\Lambda$. 

\begin{defi}
We define the Atkin--Lehner involution $w$ of level $\mathfrak p$ to be the map on $X_0(\mathfrak p)$ sending the universal isogeny $\pi$ to $\pi^D$. 
\end{defi}

Note that $w$ corresponds to the adelic Hecke operator associated with $\left( 
 \begin{array}{cc}
    0  & 1 \\
     \varpi & 0
 \end{array}\right)$ and the diamond operator $\langle \varpi \rangle$ (defined in Section \ref{subsec:FU}) corresponds to $\left( 
 \begin{array}{cc}
    \varpi  & 0 \\
     0 & \varpi
 \end{array}\right)$ as defined in \cite[\S 6]{PinkSatake}. It easy to see that $w^2$ sends $(E,\pi)$ to $(\langle \varpi \rangle E, \pi)$.


\begin{thm}\label{thm:dualityfamilies}
    There is a locally finite operator $F$ of $\operatorname{H}^1_c(\mathfrak X^{\ord}, {\bf D}(\omega^{\kappa^{un}}))$ with  projector $e(F)$. The restriction of the pairing above to
    \[e(U_\mathfrak p)\operatorname{H}^0(\mathfrak X^{\ord}, \omega^{\kappa^{un}}) \times e(\langle \varpi^{-1} \rangle F)\operatorname{H}^1_c(\mathfrak X^{\ord}, {\bf D}(\omega^{\kappa^{un}}))\] 
    gives a perfect pairing.
\end{thm}
Note that the ordinary projector $e(\langle \varpi^{-1} \rangle F)$ and $e(F)$ are the same, as $\langle \varpi^{-1} \rangle$ acts via a finite order character.\footnote{Compare with the classical Atkin--Lehner operator of level $N$ for elliptic modular forms, that changes the Nebentypus to its complex conjugate, and the classical Petersson pairing which pairs forms of a given Nebentypus with the ones with complex conjugate Nebentypus.}
\begin{proof} Using ${\bf D}(\omega^{\kappa})
\cong \omega^{\kappa^{un}}\otimes_{\Lambda,d}\Lambda$, we define $F$ as a cohomological correspondence by defining it on the first term on the right hand side exactly as $F$ in Theorem \ref{thm:projandinter}. Furthermore, since $F$ is locally finite on $\omega^{\kappa^{un}}$, it is also locally finite on ${\bf D}(\omega^{\kappa})$, as it preserves the cuspidality condition, thus, we have the associated projector $e(F)$.

We now follow very closely the arguments in \cite[Section 4.3]{BoPi2022}. Applying the specialization map for all $k$ in Proposition \ref{prop:spk}, we have the following: 
\[
\begin{tikzcd}
    \operatorname{H}^0(\mathfrak X^{\ord}, \omega^{\kappa^{un}}) \times \operatorname{H}^1_c(\mathfrak X^{\ord}, {\bf D}(\omega^{\kappa^{un}})) \ar[r]\ar[d]& \Lambda\ar[d]\\
    \prod_{k\in \mathbb{Z}}\operatorname{H}^0(\mathfrak X^{\ord}, \omega^{k}) \times \operatorname{H}^1_c(\mathfrak X^{\ord},\omega^{1-k}\otimes\omega_D(-2D))  \ar[r]& A_\mathfrak p.
\end{tikzcd}
\]

We are left to relate ${\bf D}(F)$ and $U_\mathfrak p$.  We can use the density result from Proposition \ref{prop:densek} and reduce ourselves to proving that ${\bf D}(F)$ and $U_\mathfrak p$ almost coincide at classical weights.
We specialize Proposition \ref{prop:DualTp}, that says that ${\bf D}(T^{\text{naive}}_\mathfrak p) =\pi_{1-k}^{-1}\otimes {\rm tr}_{p_2}\otimes\pi^D_1 $, to the ordinary locus and we get
%We specialise Proposition \ref{prop:KS&Serre} to the ordinary locus,  $\mathrm{tr}_{p_2} \circ {\rm KS}^\vee $ coincides with $\mathrm{tr}_{p_1}\otimes \pi_1 \otimes (\pi_1^D)^{-1} {\rm KS}^\vee$. 
%If we substitute $\mathrm{tr}_{p_2} $ we get 
\[
{\bf D}(T^{\text{naive}}_\mathfrak p) = [\varpi]^{k-1} \pi^D_k\otimes {\rm tr}_{p_2} %T^{\text{naive},D}_\mathfrak p,
\]
where we used $\pi_{1-k}^{} \pi_{1-k}^{D} = [\varpi]^{1-k}$. 
%and where $T^{\text{naive},D}_\mathfrak p$ is defined as $T^{\text{naive}}_\mathfrak p$ but using $\pi_k^D$. 
Now, we need to compare $\pi^D_k\otimes {\rm tr}_{p_2}$ with $T^{\text{naive}}_{\mathfrak p}$: recall that the Atkin--Lehner map $w$ swaps $E$ to $E^D$ and the universal isogeny $\pi$ with $\pi^D$. From a direct linear algebra calculation on the torsion of the universal Drinfeld module, we get 
\[
p_1 w = p_2, \;  p_2w= \langle \varpi \rangle p_1.
\]
where we used that  $w^2$ amounts to the diamond operator $\langle \varpi \rangle$ on the prime-to-$\mathfrak{p}$ level structure and that $(E^D)^D \cong E$ \cite[Theorem 1.1(b)]{PaRa2003}. 
% \[
% \left( \begin{array}{cc}
%     0 & 1 \\
%     \varpi & 0
% \end{array}\right) \left( \begin{array}{cc}
%      0 & 1 \\
%     \varpi & 0
% \end{array}\right)=\left( \begin{array}{cc}
%      \varpi & 0 \\
%     0 & \varpi
% \end{array}\right); \; \left( \begin{array}{cc}
%     0 & 1 \\
%     \varpi & 0
% \end{array}\right) \left( \begin{array}{cc}
%     0 & 1 \\
%     \varpi & 0
% \end{array}\right) = \left( \begin{array}{cc}
%     \varpi & 0 \\
%    0  & \varpi
% \end{array}\right) 
% \]
Hence, via the pullback by $w$, $\pi^D_k\otimes {\rm tr}_{p_2}$ acts on cohomology as \[
\langle \varpi \rangle^{-1} [\varpi]^{k-1} T^{\text{naive}}_\mathfrak p.
\] To compare with the normalized $T_{\mathfrak p}$ note that if $k<0$ we multiply by $[\varpi]^{-k}$, which simplifies $[\varpi]^{k-1}$ leaving $[\varpi]^{-1}$. 

Also, note that $w$ swaps $\fX^{\ord, F} $ with $\fX^{\ord, V}$, and we can conclude 
\[
{\bf D}(F)= \langle \varpi \rangle^{-1}   U_\mathfrak p.
\]


Finally, using the calculation above for ${\bf D}(F)$ and Corollary \ref{cor:classic}, we have that the following commutative diagram for any $k\geq 3$:
\[
\begin{tikzcd}
    e(U_\mathfrak p)\operatorname{H}^0(\mathfrak X^{\ord}, \omega^{k}) \times e(F)\operatorname{H}^1_c(\mathfrak X^{\ord},\omega^{1-k}\otimes\omega_D(-2D))  \ar[d]\ar[r]& A_\mathfrak p,\\
     e(T_\mathfrak p)\operatorname{H}^0(X, \omega^{k}) \times  e(T_\mathfrak p)\operatorname{H}^1(X,\omega^{1-k}\otimes\omega_D(-2D)) \ar[ru] & 
\end{tikzcd}
\]
where the bottom part of the diagram corresponds to classical Serre duality. 
% \textcolor{blue}{Add the prime-to-varpi Nebentypus?}
\end{proof}



