\subsection{Theoretical properties}
The following result, Theorem~\ref{thm:relaxation-properties}, shows why \eqref{eqn:opt-br2} is a relaxation of the target problem \eqref{eqn:opt-bc3}. It shows that $f_\delta(\v t)$ is continuous on the hypercube $[0, 1]^p$ and its shape can be controlled by the auxiliary parameter $\delta$ while keeping the values of $f_\delta(\v t)$ fixed---independent of $\delta$---at all the (binary) corners $\v s \in \{ 0,1\}^p$. In addition, (iii) shows that $f_\delta(\v t)$ increases with $\delta$ for any fixed interior point $\v t$---see Figure~\ref{fig:surface-plots}(a) for an illustration---while (iv) shows that the optimum of \eqref{eqn:opt-br2} is on a simplex.
\begin{theorem}
    \label{thm:relaxation-properties}
    The following hold:
    \begin{itemize}
        \item[(i)] The objective function $f_\delta(\v t)$ in \eqref{eqn:opt-br2} is continuous on $[0,1]^p$.
        \item[(ii)] For every binary vector $\v s \in \{0, 1\}^p$ (i.e., a corner point on the hypercube $[0, 1]^p$),
        \[
        f_\delta(\v s) = - \v 1^\top  \Sigma_{[\v s]}^{-1} \v 1, \quad \text{for all}\,\, \delta > 0.
        \]
        %\item[(iii)] For every interior point $\v t \in (0, 1)^p$, the objective function $f_\delta(\v t)$ can be expressed as 
        %\begin{align}
        % f_\delta(\v t) = - \v 1^\top \Pi_{\v t}^{-1} \v 1,\quad \text{with}\,\,\,\,
        % \Pi_{\v t} = \Sigma + \delta D_{\v t} \,\,\, \text{and}\,\,\, D_{\v t} = T_{\v t}^{-2} - I.
        % \label{eqn:defn_Pit}
        % \end{align}
        \item[(iii)] For every fixed $\v t \in (0, 1)^p$, $f_\delta(\v t)$ is monotonically increasing in $\delta > 0$.
        \item[(iv)] For any $k =1, \dots, p$ and $\delta > 0$, 
        \[
        \minimize_{\v t \in \cC_k} f_\delta(\v t) = \minimize_{\v t \in \cS_k} f_\delta(\v t),
        \]
        here, the simplex $\cS_k = \{\v t \in [0, 1]^p : \v t^\top \v 1 =k \}$ corresponds to the polytope $\cC_k$ given in \eqref{eqn:defn-polytope}.
    \end{itemize}
\end{theorem}


