\begin{proof}[Proof of Lemma~\ref{lem:key-res2}]
The problem is convex and has a unique minimum. Using the method of Lagrange multipliers gives the result.
\end{proof}

\begin{proof}[Proof of Theorem~\ref{thm:monotonicity}]
It is well-known that every principal submatrix of a symmetric positive definite matrix is also positive definite \citep{Golub1996}. Since $\Sigma$ is symmetric positive definite, this implies that $\Sigma_{[\v s]}$ is also positive definite for every binary vector $\v s \neq \v 0$, and hence 
    \begin{align*}
            h(k) \coloneqq  \maximize_{\v s \in \{0, 1\}^p, \, \, \v 1^\top \v s = k} \v 1^\top \Sigma_{[\v s]}^{-1} \v 1.
    \end{align*}
is well-defined for all $k = 1, \dots, p$. 


Now fix $k$ and consider $\v s \in \{0, 1\}^p$ such that $\v 1^\top \v s = k$. Consider $\v s'$ with $\v 1^\top \v s' = k+1$ such that the Hamming distance between $\v s$ and $\v s'$ is $1$, that is, there is a unique $j \in \{1, \dots, p\}$ such that $s_i = s'_i$ for all $i \neq j$ and $0 = s_j < s_j' =1$. Then, the proof is complete if we show that
\begin{align}
    \v 1^\top  \Sigma_{[\v s]}^{-1} \v 1 \leq \v 1^\top  \Sigma_{[\v s']}^{-1} \v 1,
\label{eqn:monotonicity}
\end{align}
because, under \eqref{eqn:monotonicity},
$\v 1^\top  \Sigma_{[\v s]}^{-1} \v 1 \leq h(k+1)$ and hence $h(k) \leq h(k+1)$ by maximizing the left hand size over all $\v s$ with $|\v s| = k$. 


We prove \eqref{eqn:monotonicity} using the popular Banachiewicz inversion lemma \citep{YY05}. 
Without loss of generality we assume that such $\v s$ and $\v s'$ differ at the index $p$. 
Then, we write 
\[
\Sigma_{[\v s']} 
= 
\begin{bmatrix}
    \Sigma_{[\v s]} & & \v a \\
    & & \\
    \v a^\top & & b 
\end{bmatrix},
\]
for some appropriate vector $\v a$ and a scalar $b$. Note that both $\Sigma_{[\v s']}$ and $\Sigma_{[\v s]}$ are invertible and $b > 0$.  
Therefore, the Schur complement $c = b - \v a^\top \Sigma_{[\v s]}^\top \v a$ must be non-zero; see \cite{YY05}. 
Then,
\begin{align*}
    \Sigma_{[\v s']}^{-1} 
    =
    \begin{bmatrix}
        I & & - \frac{1}{c} \Sigma_{[\v s]}^{-1} \v a \\
        & & \\
        \v 0^\top & &\frac{1}{c}
    \end{bmatrix}
    \begin{bmatrix}
         \Sigma_{[\v s]}^{-1} & & \v 0 \\
         & & \\
        - \v a^\top  \Sigma_{[\v s]}^{-1} & & 1
    \end{bmatrix}
    =
    \begin{bmatrix}
         \Sigma_{[\v s]}^{-1} + \frac{1}{c} \Sigma_{[\v s]}^{-1} \v a \v a^\top  \Sigma_{[\v s]}^{-1} & & - \frac{1}{c} \Sigma_{[\v s]}^{-1} \v a \\
         & & \\
        - \frac{1}{c} \v a^\top  \Sigma_{[\v s]}^{-1} & & \frac{1}{c}
    \end{bmatrix}.
\end{align*}
Note that for any matrix $A$, $\v 1^\top A \v 1$ is simply the sum of all the elements of $A$. Similarly, for any vector $\v u$, $\v 1^\top \v u$ is the sum of all the elements of $\v u$. Thus, 
\begin{align*}
    \v 1^\top \Sigma_{[\v s']}^{-1} \v 1
    &= \v 1^\top \Sigma_{[\v s]}^{-1} \v 1 + \frac{1}{c} (\v 1^\top \Sigma_{[\v s]}^{-1} \v a)^2 - 2 \frac{1}{c}\v 1^\top \Sigma_{[\v s]}^{-1} \v a + \frac{1}{c} \\
    &= \v 1^\top \Sigma_{[\v s]}^{-1} \v 1 + \frac{1}{c} \lt(\v 1^\top \Sigma_{[\v s]}^{-1} \v a - 1\rt)^2.
\end{align*}
Therefore, to establish \eqref{eqn:monotonicity}, we just need to show that $c > 0$. For this, using simple block-matrix multiplication, observe that 
\begin{align*}
    \begin{bmatrix}
         I & & \v 0 \\
         & & \\
        - \v a^\top  \Sigma_{[\v s]}^{-1} & & 1
    \end{bmatrix}
    \begin{bmatrix}
        \Sigma_{[\v s]} & & \v a \\
        & & \\
        \v a^\top & & b \\
    \end{bmatrix} 
    \begin{bmatrix}
         I & & - \Sigma_{[\v s]}^{-1} \v a \\
         & & \\
         \v 0 & & 1
    \end{bmatrix}
    =     
    \begin{bmatrix}
         \Sigma_{[\v s]} & & \v 0 \\
         & & \\
         \v 0^\top & & c
    \end{bmatrix}.
\end{align*}
Since $\Sigma_{[\v s']}$ is positive definite, for any scalar $v \neq 0$ with $\v u = [\v 0^\top, v]^\top$, using the left hand side expression of the above equality,
\begin{align*}
    \v u^\top \begin{bmatrix}
         I &  \v 0 \\
         &  \\
        - \v a^\top  \Sigma_{[\v s]}^{-1} &  1
    \end{bmatrix}
    \begin{bmatrix}
        \Sigma_{[\v s]} & & \v a \\
        & & \\
        \v a^\top & & b \\
    \end{bmatrix} 
    \begin{bmatrix}
         I &  - \Sigma_{[\v s]}^{-1} \v a \\
         &  \\
         \v 0 &  1
    \end{bmatrix}
    \v u
    =    
\begin{bmatrix}
        - v \v a^\top  \Sigma_{[\v s]}^{-1} &  v
    \end{bmatrix}
        \Sigma_{[\v s']}
    \begin{bmatrix}
      - v \Sigma_{[\v s]}^{-1} \v a \\
         \\
         v 
    \end{bmatrix}
    > 0,
\end{align*}
and hence,
\[
\v u^\top     
\begin{bmatrix}
     \Sigma_{[\v s]} & & \v 0 \\
     & & \\
     \v 0^\top & & c
\end{bmatrix}
\v u = c v^2 > 0,
\]
which is possible only if $c > 0$.
\end{proof}

We need the following lemma in proving Theorem~\ref{thm:relaxation-properties}(iii).
\begin{lemma}
    \label{lem:simplified-f}
For every interior point $\v t \in (0, 1)^p$, the objective function $f_\delta(\v t)$ can be expressed as 
    \begin{align*}
    f_\delta(\v t) = - \v 1^\top \Pi_{\v t}^{-1} \v 1,\quad \text{with}\,\,\,\,
    \Pi_{\v t} = \Sigma + \delta D_{\v t} \,\,\, \text{and}\,\,\, D_{\v t} = T_{\v t}^{-2} - I.
    \end{align*}
\end{lemma}
\begin{proof}
    Note that $\v t^\top = \v 1^\top T_t$. Then,
\begin{align*}
f_\delta(\v t) & = -\v 1^\top T_{\v t} \widetilde{\Sigma}_{\v t}^{-1} T_{\v t} \v 1 \\
& = -\v 1^\top \left(T^{-1}_{\v t} \widetilde{\Sigma}_{\v t} T_{\v t}^{-1}\right)^{-1} \v 1 
\\
& = -\v 1^\top \left(\Sigma + \delta(T^{-2}_{\v t} - I)\right)^{-1} \v 1\\
& = -\v 1^\top \Pi^{-1}_{\v t} \v 1,
\end{align*}
since $T_{\v t}$ is invertible for every interior point $\v t$.
\end{proof}

\begin{proof}[Proof of Theorem~\ref{thm:relaxation-properties}]
To establish the continuity in (i), let $\v t_{1}, \v t_{2}, \cdots \in [0, 1]^p$ be a sequence of points converging to $\v t$ 
(element-wise or in the Euclidean norm). If $\v t$ contains zeros, without loss of generality, assume all these zeros appear at the front. Then, we can write
\[
T_{\v t_\ell} = 
\begin{bmatrix}
    F'_{\v t_\ell} & \v 0 \\
    \v 0 & F''_{\v t_\ell}
\end{bmatrix},
\]
where $F'_{\v t_\ell}$ is a diagonal matrix of the front elements of $\v t_\ell$ (that converge to zero) and $F''_{\v t_\ell}$ is a diagonal matrix of the remaining elements. Therefore, for all sufficiently large $\ell$, we can assume that $F''_{\v t_\ell}$ is invertible. 
Recall from \eqref{eqn:defn-Sigma} that $ \wt \Sigma_{\v t} = T_{\v t} \Sigma T_{\v t} + \delta (I - T_{\v t}^2)$. By dividing the $\Sigma$ matrix into four suitable sub-matrices, we can write
\begin{align*}
    \wt \Sigma_{\v t_\ell} &= 
    \begin{bmatrix}
    F'_{\v t_\ell} & \v 0 \\
    \v 0 & F''_{\v t_\ell}
    \end{bmatrix}
    \begin{bmatrix}
    \Sigma' & \wb \Sigma\\
    \wb \Sigma^\top & \Sigma''
    \end{bmatrix}
    \begin{bmatrix}
    F'_{\v t_\ell} & \v 0 \\
    \v 0 & F''_{\v t_\ell}
    \end{bmatrix}
    + 
    \delta  
    \begin{bmatrix}
    I - (F'_{\v t_\ell})^2 & \v 0 \\
    \v 0 & I - (F''_{\v t_\ell})^2
    \end{bmatrix}\\
    &=
    \begin{bmatrix}
    F'_{\v t_\ell} \Sigma' F'_{\v t_\ell} & F'_{\v t_\ell} \wb \Sigma F''_{\v t_\ell}\\
    F''_{\v t_\ell} \wb \Sigma^\top F'_{\v t_\ell} & F''_{\v t_\ell} \Sigma'' F''_{\v t_\ell}
    \end{bmatrix}
    + 
    \delta  
    \begin{bmatrix}
    I - (F'_{\v t_\ell})^2 & \v 0 \\
    \v 0 & I - (F''_{\v t_\ell})^2
    \end{bmatrix}\\
    &=
    \underbrace{\begin{bmatrix}
    \delta\lt(I - (F'_{\v t})^2\rt) & \v 0\\
    \v 0 & F''_{\v t} \Sigma'' F''_{\v t} + \delta\lt(I - (F''_{\v t})^2\rt)
    \end{bmatrix}}_{\wt \Sigma_{\v t} }\\
    &\hspace{1.5cm}+ 
    \underbrace{\begin{bmatrix}
    F'_{\v t_\ell} \Sigma' F'_{\v t_\ell} & F'_{\v t_\ell} \wb \Sigma F''_{\v t_\ell}\\
    F''_{\v t_\ell} \wb \Sigma^\top F'_{\v t_\ell} & F''_{\v t_\ell} \Sigma'' F''_{\v t_\ell} - F''_{\v t} \Sigma'' F''_{\v t} 
    \end{bmatrix}
    + 
    \delta  
    \begin{bmatrix}
    (F'_{\v t})^2 - (F'_{\v t_\ell})^2 & \v 0 \\
    \v 0 & (F''_{\v t})^2 - (F''_{\v t_\ell})^2
    \end{bmatrix}}_{E_\ell}\\
    &= 
    \wt \Sigma_{\v t} + E_{\ell},
\end{align*}
where $E_\ell = \wt \Sigma_{\v t_\ell} - \wt \Sigma_{\v t}$ clearly converges to an all-zero matrix. 
That means, the spectral radius of $E_\ell$ is less than $1$ for all sufficiently large values of $\ell$. Thus using the Neumann series \citep{horn2012matrix}, we can show that 
\[
\wt \Sigma_{\v t_\ell}^{-1} = (\wt \Sigma_{\v t} + E_\ell)^{-1} \rightarrow \wt \Sigma_{\v t}^{-1}, \quad \text{as}\, \, \ell \to \infty.
\]
As a consequence, $\lim_{\ell \to \infty} f_\delta(\v t_\ell) = f_\delta(\v t)$ for any $\delta > 0$.

To establish (ii),  observe that for any binary vector $\v s \in \{0,1\}^p$,
\[
\big(\wt \Sigma_{\v s}\big)_{[\v s]} = \big(T_{\v s} \Sigma T_{\v s}\big)_{[\v s]} = \Sigma_{[\v s]}, \quad \text{and}\quad 
\big(\wt \Sigma_{\v s}\big)_{[\v 1 - \v s]} = \delta I.
\]
Thus, $f_\delta(\v s) = - \v 1^\top  \Sigma_{[\v s]}^{-1} \v 1$.


To establish (iii), observe from Lemma~\ref{lem:simplified-f} that 
\begin{align*}
    \frac{d}{d\delta} f_\delta(\v t) & = -\v 1^\top \frac{d}{d\delta}\Pi^{-1}_{\v t} 1^\top \\  
    & = \v 1 ^\top \Pi_{\v t}^{-1}\left(\frac{d}{d\delta}\Pi_{\v t} \right)\Pi_{\v t}^{-1}\v 1 \\
    & = \v u^T \left(\frac{d}{d\delta}\Pi_{\v t} \right) \v u \\
    & = \v u^T \left(T^{-2}_{\v t} - I\right) \v u,
\end{align*}
with $\v u = \Pi^{-1}_{\v t}\v 1 \neq \v 0$. 
%since $\Pi^{-1}_{\v t}$ is positive definite. 
Since $\v t$ is in the unit interval, the matrix in the quadratic form is positive definite, which concludes the claim.

Finally, (iv) is a simple consequence of Lemma~\ref{lem:grad-hess} below which show that all the elements gradient $\nabla f_\delta(\v t)$ are non-positive. That means, in each coordinate $t_j$,  the objective function $f_\delta(\v t)$ is non-increasing along $t_j$. Thus, for each $k$, the simplex $\cS_k$ contains an optimal solution of Boolean relaxation~\eqref{eqn:opt-br2}.
\end{proof}

We now establish the gradient and the Hessian of the objective function $\wh f_\delta(\v t)$ using the scaling in Section~\ref{app:scaling}. Without scaling, the gradient and the Hessian of $f_\delta(\v t)$ are obtained by replacing $\v v$ with $\v 1$ in this lemma.

\begin{lemma}
    \label{lem:grad-hess}
    The gradient and the Hessian of $\wh f_\delta(\v t)$ at every $\v t \in (0,1)^p$ are respectively given by 
    \[
    \nabla \wh f_\delta(\v t) = -2\delta\frac{\v v \odot (\wh \Pi_{\v t}^{-1} \v 1)^2}{\v t^3},
    \]
and
    \[
    \wh H_\delta(\v t) = 2 \delta \diag\lt( \frac{\v v \odot (\wh \Pi_{\v t}^{-1} \v 1)}{\v t^3}\rt) \lt[3\diag(\v t^2 \odot \v w^2) - 4\delta  \wh{\Pi}_{\v t}^{-1} \rt] \diag\lt( \frac{\v v \odot (\wh \Pi_{\v t}^{-1} \v 1)}{\v t^3}\rt),
    \]
    where 
    \(
    \wh \Pi_{\v t} = \Sigma + \delta D_{\v t} \diag(\v v),
    \)
    and the division and power operations on vectors are element-wise.
\end{lemma}


\begin{proof}
Similar to Lemma~\ref{lem:simplified-f}, we can show that for any interior point $\v t \in (0, 1)^p$, 
\[
\wh f_\delta(\v t) = - \v 1^\top \wh \Pi_{\v t}^{-1} \v 1.
\]
Thus, for each $j =1, \dots, p$,
\begin{align*}
    \frac{\partial \wh f_\delta(\v t)}{\partial t_j} =  -\v 1^\top \frac{\partial \wh \Pi_{\v t}^{-1}}{\partial t_j} \v 1
    = \v 1^\top \wh \Pi_{\v t}^{-1} \frac{\partial \wh \Pi_{\v t}}{\partial t_j} \wh \Pi_{\v t}^{-1} \v 1.
\end{align*}
Since $\Sigma$ does not depend on $\v t$, from the definition of $\Pi_{\v t}$, 
\begin{align}
\frac{\partial \wh \Pi_{\v t}}{\partial t_j} = \delta \frac{\partial D_{\v t}}{\partial t_j} \diag(\v v) = - \frac{2 \delta v_j}{t_j^3} \v e_j \v e_j^\top,
\label{eqn:diff-Mt}
\end{align}
where $\v e_j$ is the vector with $1$ at the $j$-th location and $0$ everywhere else. 
Thus, we get the required expression for the gradient 
$\nabla \wh f_\delta(\v t)$. 

We now derive an expression of the Hessian of $\wh f(\v t)$. Toward this, to simplify the notation, let $\v u_{\v t} = \wh \Pi_{\v t}^{-1} \v 1$. Then, $j$-th column of the Hessian is given by
\begin{align*}
\frac{\partial }{\partial t_j} \nabla \wh f_\delta(\v t) &= \frac{6\delta v_j}{t_j^4} \v e_j \v e_j^\top (\v u_{\v t} \odot \v u_{\v t}) - 2\delta \lt(\frac{\v 1}{\v t^3} \rt) \odot \frac{\partial }{\partial t_j} (\v u_{\v t} \odot \v u_{\v t})\\
&= \frac{6\delta v_j}{t_j^4} \v e_j \v e_j^\top (\v u_{\v t} \odot \v u_{\v t}) - 4\delta \lt(\frac{\v u_{\v t}}{\v t^3}\rt) \odot \frac{\partial \v u_{\v t}}{\partial t_j} \\
&= \frac{6\delta v_j}{t_j^4} \v e_j \v e_j^\top (\v u_{\v t} \odot \v u_{\v t}) + 4\delta \lt(\frac{\v u_{\v t}}{\v t^3} \rt)\odot \left(\wh \Pi_{\v t}^{-1} \frac{\partial \wh \Pi_{\v t} }{\partial t_j} \v u_{\v t} \right).
\end{align*}
Using \eqref{eqn:diff-Mt}, we can write
\begin{align*}
\frac{\partial }{\partial t_j} \nabla \wh f_\delta(\v t)  
&= \frac{6\delta v_j}{t_j^4} \v e_j \v e_j^\top (\v u_{\v t} \odot \v u_{\v t}) -\frac{8\delta^2 v_j}{t_j^3} \lt(\frac{\v u_{\v t}}{\v t^3}\rt) \odot \left(\wh \Pi_{\v t}^{-1} \v e_j \v e_j^\top \v u_{\v t} \right).
\end{align*}
Consequently, the Hessian of $f_\delta$ at $\v t$ is given by
\begin{align*}
    \wh H_\delta(\v t) &= 6 \delta \lt[\diag\lt( \frac{\v v \odot \v u_{\v t}}{\v t^3}\rt)\rt]^2 T_{\v t}^2 \diag(\v 1/\v v) - 8\delta^2 \diag\lt( \frac{\v v \odot \v u_{\v t}}{\v t^3}\rt) \wh \Pi_{\v t}^{-1} \diag\lt( \frac{ \v v \odot \v u_{\v t}}{\v t^3}\rt)\nonumber\\
    &= 2 \delta \diag\lt( \frac{\v v \odot \v u_{\v t}}{\v t^3}\rt) \lt[3\diag(\v t^2 \odot \v w^2) - 4\delta  \wh \Pi_{\v t}^{-1} \rt] \diag\lt( \frac{\v v \odot \v u_{\v t}}{\v t^3}\rt),
\end{align*}
which completes the proof by recalling that $\v w = \v 1/ \sqrt{\v v}$.
\end{proof}

\begin{proof}[Proof of Theorem~\ref{thm:delta-prperties}] We establish the proof in generality under scaling, and Theorem~\ref{thm:delta-prperties} (no scaling) immediately holds by replacing $\v v$ with $\v 1$.


The Hessian $\wh H_\delta(\v t)$ is clearly symmetric at every $\v t \in (0, 1)^p$ and $\delta > 0$, but not necessarily positive definite. 
To show (i), note from Lemma~\ref{lem:grad-hess} that $\wh H_\delta(\v t)$ is negative definite if $4\delta  \wh \Pi_{\v t}^{-1} - 3\diag({\v t}^2 \odot \v w^2)$ is positive definite. To simplify the notation,  for a symmetric matrix $A$, we write $A \geq 0$ to denote that $A$ is positive semi-definite.

Suppose that $\Sigma = U \Delta U^\top$ is the singular value decomposition of $\Sigma$. Then, $\Sigma \leq \eta_1 I$ and thus, 
\begin{align*}
\wh \Pi_{\v t} = \Sigma + \delta D_{\v t} \diag(\v v)
\leq \eta_1 I + \delta D_{\v t} \diag(\v v)
= \diag\lt(\eta_1 \v 1 + \delta (\v 1/\v t^2 - \v 1) \odot \v v \rt).
\end{align*}
Hence, 
\[
\wh \Pi_{\v t}^{-1} \geq 
\diag \lt(\frac{\v t^2}{ \eta_1 \v t^2 + \delta (\v 1 - \v t^2) \odot \v v} \rt),
\]
and thus,
\begin{align*}
4\delta  \wh{\Pi}_{\v t}^{-1} - 3\diag(\v t^2 \odot \v w^2) \geq  \diag \lt(\frac{4\delta \v t^2}{ \eta_1 \v t^2 + \delta (\v 1 - \v t^2) \odot \v v} - 3 \frac{\v t^2}{\v v}\rt),
\end{align*}
here we used the fact that $\v v = 1/\v w^2$. Now it is enough to show that 
\begin{align*}
    \frac{4\delta}{\eta_1 t_j^2 + \delta (1 - t_j^2) v_j } - \frac{3}{v_j}  \geq 0 
\end{align*}
for all $j$ and $t_j \in (0, 1)$. Or equivalently, 
\begin{align*}
4\delta \geq \frac{3 }{v_j} \lt(\eta_1 t_j^2 + \delta (1 - t_j^2) v_j \rt).
\end{align*}
That is, 
\begin{align*}
(1 + 3t_j^2))\delta \geq 3 (\eta_1/v_j) t_j^2,
\end{align*}
or, 
\begin{align*}
\delta - 3 (\eta_1/v_j - \delta) t_j^2 \geq 0.
\end{align*}

Now, to establish the convexity property in (ii), observe that 
\begin{align*}
\wh \Pi_{\v t} = \Sigma + \delta D_{\v t} \diag(\v v)
\geq \eta_p I + \delta D_{\v t} \diag(\v v)
= \diag\lt(\eta_p \v 1 + \delta (\v 1/\v t^2 - \v 1) \odot \v v \rt).
\end{align*}
Hence, 
\[
\wh \Pi_{\v t}^{-1} \leq 
\diag \lt(\frac{\v t^2}{ \eta_p \v t^2 + \delta (\v 1 - \v t^2) \odot \v v} \rt),
\]
and thus,
\begin{align*}
4\delta  \wh{\Pi}_{\v t}^{-1} - 3\diag(\v t^2 \odot \v w^2) \leq  \diag \lt(\frac{4\delta \v t^2}{ \eta_p \v t^2 + \delta (\v 1 - \v t^2) \odot \v v} - 3 \frac{\v t^2}{\v v}\rt),
\end{align*}
Now it is enough to show that 
\begin{align*}
    \frac{4\delta}{\eta_p t_j^2 + \delta (1 - t_j^2) v_j } - \frac{3}{v_j}  \leq 0 
\end{align*}
for all $j$. Equivalently, 
\(
4\delta v_j \leq 3 \eta_p t_j^2 + 3\delta (1 - t_j^2) v_j.
\)
That is,
\(
\delta v_j \leq 3 \eta_p t_j^2 - 3\delta v_j t_j^2,
\)
or,
\begin{align*}
\delta  \leq \frac{1}{v_j}\lt(\frac{3 \eta_p t_j^2}{1 + 3 v_j t_j^2}\rt),
\end{align*}
which is true when for all $\v t \in (\varepsilon, 1)^p$ and $\delta > 0$ such that 
\[
\delta  \leq \frac{1}{\max_j v_j}\lt(\frac{3 \eta_p \varepsilon^2}{1 + 3  \varepsilon^2}\rt).
\]
\end{proof}

\begin{proof}[Proof of Theorem~\ref{thm:sol-continuity}]
Recall that for a fixed integer $k$,
    \[
    h_k(\delta) = \minimize_{\v t \in \cC_k} f_\delta(\v t)\quad 
    \text{and}
    \quad 
    \cD_{k,\delta} = \argmin_{\v t \in \cC_k} f_\delta(\v t).
    \]
Since $\Delta \coloneqq [\varepsilon, \eta_1]$ is compact for any $\varepsilon \in (0, \eta_1)$, from Chapter~9 of \cite{sundaram1996first}, $h_k(\delta)$ is continuous and $\cD_{k,\delta}$ is compact-valued, upper hemicontinuous\footnote{Upper hemicontinuity is sometimes referred to as upper semicontinuity.} correspondence on $\Delta$. This implies that for any sequence $\delta_\ell \to \eta_1$ and $\v t^{(\ell)} \in \cD_{k,\delta}$ with $\v t^{(\ell)} \to \v t^*$, we have $\v t^* \in \cD_{k,\eta_1}$.
% , where $\cD^*_k$ is equal to $\cD_{k,\eta_1}$, that is, 
% \[
%     \cD^*_k = \argmin_{\v t \in \cC_k} f_{\eta_1}(\v t).
% \]
We known from Theorem~\ref{thm:delta-prperties}(i) that  $f_{\eta_1}(\v t)$ is strictly concave on $\cC_k$, and thus, $\cD_{k,\eta_1}$ must be the solution set $\cD^*_k$ of the target optimization problem \eqref{eqn:opt-bc3}.
\end{proof}



