\noindent The observation that the fractional derivative of constant functions is zero, as indicated in equation (\ref{derpot}), results in the following equation
\begin{equation}
D^{\alpha}_{0+}\theta(z)=D^{\alpha}_{0+}(\theta(x)+\theta(z))\approx D^{\alpha}_{0+} y^{\prime}(z)=D^{\alpha+1}_{0+}y(z). \label{ddetheta}
\end{equation}

From (\ref{fpan}), we derive the following relationship
$$D^{\alpha}_{0+}S(z)|_{z=x} = \rho(x)D^{\alpha}_{0+}\theta(z)|_{z=x},$$
and by applying (\ref{deriS}) and (\ref{ddetheta}), we can deduce an analogue of (\ref{rccl})
$$\rho (x)= \frac{x^{1-\alpha}}{\Gamma(2-\alpha)} \cdot\frac{(1+(y^{\prime}(x))^{2})^{1/2}}{D^{\alpha+1}_{0+}y(x)}.$$
As in the previous case, if the square of $y^{\prime}(x)$ is significantly smaller than $1$, we arrive at the approximation
\begin{equation}
\rho(x) \approx \frac{x^{1-\alpha}}{\Gamma(2-\alpha)} \cdot \frac{1}{D^{\alpha+1}_{0+}y(x)}. \label{fraprc}
\end{equation}
This is similar to (\ref{aprccl}), but with the additional factor of $x^{1-\alpha}/\Gamma(2-\alpha)$.

\section{Solving the fractional differential equation}\label{SecAEx}

For $\alpha \in (0,1]$, we define the parameter $\lambda$ as follows
\begin{eqnarray*}
\lambda := \frac{P}{EI\,\Gamma(2-\alpha)},
\end{eqnarray*}
where $E$, $I$ and $P$ are positive constants. Our first aim is to solve the fractional differential equation
\begin{equation}
D_{0+}^{1+\alpha}y\left(x\right)=-\lambda x^{1-\alpha} \, y\left(x\right),\label{fDEq1}
\end{equation}
subject to the initial conditions
\begin{equation}
y(0)=b_{0}, \quad y^{\prime}(0)=b_{1}\label{fDEq2}.
\end{equation} 

Given the physical constraints of the problem, we have $b_{0}=0$. The initial condition for the derivative, denoted as $b_{1}$, remains undetermined. Identifying $b_{1}$ is crucial for calculating the critical load. We start by seeking the solution to the initial value problem (\ref{fDEq1})-(\ref{fDEq2}).

\begin{theorem} \label{Th1}
Let us set 
\begin{equation}
y\left(x\right) = b_{1} \left(a_{0} \, x+ \sum_{k=1}^{\infty}\left(-1\right)^{k}a_{k}\lambda^{k} x^{2k+1}\right) , \ \ x \in \mathbb{R}, \label{solFDE}
\end{equation}
where
$$a_{0}:=1, \quad a_{k}:=\prod_{i=1}^{k}\frac{\Gamma (2i+1-\alpha)}{\Gamma (2i+2)}, \ \ k\in \mathbb{N}.$$
The series converges absolutely and represents the solution to the initial value problem as stated in equations (\ref{fDEq1}) and (\ref{fDEq2}).
\end{theorem}

\begin{proof}
By applying the root criterion, we can ascertain that the power series in (\ref{solFDE}) converges absolutely over $\mathbb{R}$. This conclusion is drawn from the observation that
\begin{eqnarray*}
\limsup_{k\rightarrow \infty} \ (|(-1)^{k}a_{k}|)^{1/k}\leq \limsup_{k\rightarrow \infty} \ \frac{|(-1)^{k+1}a_{k+1}|}{|(-1)^{k}a_{k}|} = \limsup_{k\rightarrow \infty} \ \frac{\Gamma(2k+3-\alpha)}{\Gamma(2k+4)}=0.
\end{eqnarray*}
On the other hand, given that $y(0)=0$ and
\begin{equation*}
y^{\prime}\left(x\right)  =  b_{1}\left( 1+ \sum_{k=1}^{\infty} (-1)^{k} a_{k}\lambda^{k}\left(2k+1\right)x^{2k}\right),
\end{equation*}
yield $y^{\prime}(0)=b_{1}$. Now, let us calculate the fractional derivative of $y(x)$,
\begin{eqnarray*}
D_{0+}^{\alpha+1}y\left(x\right) = b_{1} \left( D_{0+}^{\alpha+1}x + \sum_{k=1}^{\infty}\left(-1\right)^{k}a_{k}\lambda^{k}D_{0+}^{\alpha+1}x^{2k+1}\right) .
\end{eqnarray*}
Since $\alpha+1\in\left(1,2\right]$, then $D_{0+}^{\alpha+1}x = 0$ (see (\ref{derpot})). Furthermore, for $k\ge 1$,
\begin{eqnarray*}
D_{0+}^{\alpha+1}x^{2k+1} = \frac{\Gamma(2k+2)}{\Gamma(2k+1-\alpha)}x^{2k-\alpha},
\end{eqnarray*}
from which we derive
\begin{eqnarray*}
D_{0+}^{\alpha+1}y\left(x\right)  & = & b_{1}\sum_{k=1}^{\infty}(-1)^{k}a_{k}\lambda^{k}\frac{\varGamma\left(2k+2\right)}{\varGamma\left(2k+1-\alpha\right)}x^{2k-\alpha}\\ 
 & = & b_{1}\left(-\lambda x^{2-\alpha}+\sum_{k=2}^{\infty}(-1)^{k}a_{k-1}\lambda^{k}x^{2k-\alpha}\right)\\
 & = & -\lambda x^{1-\alpha}b_{1}\left(x+\sum_{k=1}^{\infty}\left(-1\right)^{k}a_{k}\lambda^{k}x^{2k+1}\right)\\
 & = & -\lambda x^{1-\alpha}y(x).
\end{eqnarray*}
This result confirms the desired equality (\ref{fDEq1}).
\end{proof}

For $n \in \mathbb{N} \cup \{\infty\}$ we define
\begin{eqnarray*}
p_{n}(x) =\sum_{k=0}^{n}\left(-1\right)^{k}a_{k}x^{k}, \quad x\in \mathbb{R}.
\end{eqnarray*}
Then the solution $y(x)$ of (\ref{fDEq1}) can be expressed as
$$y(x)= b_{1} xp_{\infty}(\lambda x^{2}), \quad x\in [0,l].$$

We know that $y(l)=0$, then $b_{1}=0$ or $p_{\infty}(\lambda l^{2})=0$. If $b_{1}=0$, the column has not bent at all. On the other hand we have $p_{\infty}(\lambda l^{2})=0$. Thus we need to find the smallest positive root of the function $p_{\infty}$ in order to obtain the critical load (force).

We denote the smallest positive root of the polynomial $p_{n}$ as $r_{n}$. The existence of $r_{n}$ depends on whether $n$ is an odd or even integer. For odd integers $n$, a root $r_{n}$ always exists. This is due to the intermediate value theorem, as a polynomial of odd degree must cross the $x$-axis at least once, ensuring at least one real root. However, for even integers $n$, the existence of such a root is not guaranteed.

\begin{lemma} \label{ldescre}
Let $\alpha$ be in $(0,1]$. The following functions defined on $\mathbb{N}$
\begin{gather*}
f(x) = \frac{\Gamma(x+1)}{\Gamma(x-\alpha)}, \\
g(x) = \frac{x\Gamma(2x+4)}{(x+1)\Gamma(2x+3-\alpha)},
\end{gather*}
are both $f(x)$ and $g(x)$ strictly increasing functions.
\end{lemma}

\begin{proof}
To verify the monotonicity property, we will use the relation $\Gamma(x+1)=x\Gamma(x)$ for $x\in (0, \infty)$. Applying this, we have
 \begin{eqnarray*}
\frac{\Gamma(x+2)}{\Gamma(x+1-\alpha)}&=&\frac{(x+1)\Gamma(x+1)}{(x-\alpha)\Gamma(x-\alpha)}\\
 &\geq & \frac{x+1}{x} \cdot \frac{\Gamma(x+1)}{\Gamma(x-\alpha)}\\
 &= & \left(1+\frac{1}{x}\right) \cdot \frac{\Gamma(x+1)}{\Gamma(x-\alpha)}\\
 &>& \frac{\Gamma(x+1)}{\Gamma(x-\alpha)}
 \end{eqnarray*}
and
 \begin{eqnarray*}
 \frac{x+1}{x+2}\cdot \frac{\Gamma(2x+6)}{\Gamma(2x+5-\alpha)}&=&\frac{(x+1)^{2}(2x+5)(2x+4)}{x(x+2)(2x+4-\alpha)(2x+3-\alpha)}\cdot \frac{x\Gamma(2x+4)}{(x+1)\Gamma(2x+3-\alpha)}\\
 &\geq & \frac{(x+1)^{2}(2x+5)}{x(x+2)(2x+3)}\cdot \frac{x\Gamma(2x+4)}{(x+1)\Gamma(2x+3-\alpha)}\\ 
  &=&\left(1+\frac{2x+5}{2x^{3}+9x^{2}+10x}\right) \cdot \frac{x\Gamma(2x+4)}{(x+1)\Gamma(2x+3-\alpha)}\\
 &>& \frac{x\Gamma(2x+4)}{(x+1)\Gamma(2x+3-\alpha)}.
 \end{eqnarray*}
Thus, the desired property is clearly established.
\end{proof}

In what follows we require the following hypothesis.

\begin{description}
\item[Assumption A:] Let us suppose there is a polynomial $p_{n_{0}}$, with $n_{0}$ an even integer, such that it has a first positive root $r_{n_{0}}$ that satisfies the inequality
\begin{equation*}
\frac{\Gamma\left(2n_{0}+6\right)}{\Gamma\left(2n_{0}+5-\alpha\right)} \ge r_{n_{0}}.
\end{equation*}
\end{description}

\begin{lemma} \label{despp}
For each $n, m\in \mathbb{N}\cup\{0\}$ we have $p_{n_{0}+2n+1}<p_{\infty}<p_{n_{0}+2m}$ on $(0,r_{n_{0}}]$.
\end{lemma}

\begin{proof}
Given that the series below converges absolutely, we can rearrange the terms as follows
\begin{eqnarray*}
p_{\infty}(x)-p_{n_{0}+2n+1}(x)& = & \sum_{k=n_{0}+2n+2}^{\infty}(-1)^{k}a_{k}x^{k}\\
&=&\sum_{k=0}^{\infty}a_{n_{0}+2n+2k+2}\, x^{n_{0}+2n+2k+2}-\sum_{k=0}^{\infty}a_{n_{0}+2n+2k+3}\, x^{n_{0}+2n+2k+3}\\
&=& \sum_{k=0}^{\infty}a_{n_{0}+2n+2k+2}\, x^{n_{0}+2n+2k+2} \left(1-\frac{\Gamma(2n_{0}+4n+4k+7-\alpha)}{\Gamma(2n_{0}+4n+4k+8)}x \right).
\end{eqnarray*}
The monotonicity property of $f$, as stated in Lemma \ref{ldescre}, and the condition $x\in (0,r_{n_{0}}]$ imply
$$\frac{\Gamma(2n_{0}+4n+4k+8)}{\Gamma(2n_{0}+4n+4k+7-\alpha)}\geq \frac{\Gamma(2n_{0}+8)}{\Gamma(2n_{0}+7-\alpha)}>\frac{\Gamma(2n_{0}+6)}{\Gamma(2n_{0}+5-\alpha)}\geq r_{n_{0}}\geq x,$$
therefore, $p_{\infty}>p_{n_{0}+2n+1}$ on $(0,r_{n_{0}}]$. 

Now, let us consider
\begin{equation*}
p_{\infty}(x)-p_{n_{0}+2m}(x) = \sum_{k=0}^{\infty}a_{n_{0}+2m+2k+1}\, x^{n_{0}+2m+2k+1} \left(\frac{\Gamma(2n_{0}+4m+4k+5-\alpha)}{\Gamma(2n_{0}+4m+4k+6)}x-1 \right).
\end{equation*}
For $k\geq 1$ and $x\in (0,r_{n_{0}}]$, Lemma \ref{ldescre} implies
$$\frac{\Gamma(2n_{0}+4m+4k+6)}{\Gamma(2n_{0}+4m+4k+5-\alpha)} > \frac{\Gamma(2n_{0}+6)}{\Gamma(2n_{0}+5-\alpha)}\geq r_{n_{0}} \geq x,$$
thus $p_{n_{0}+2m}>p_{\infty}$ on $(0,r_{n_{0}}]$. This completes the proof of the desired inequalities.
\end{proof}

We now turn our attention to a result concerning the monotonicity of the sequence $(p_{n})_{n \in \mathbb{N}}$. This investigation will help us understand how the sequence behaves as $n$ varies, particularly in terms of its increasing or decreasing nature.

\begin{lemma} \label{lpoli}
Let $n$ and $m$ be two positive integers such that $n>m$. If $m$ and $n$ are  even integers, then $p_{n_{0}+n}<p_{n_{0}+m}$ on $(0,r_{n_{0}}]$. Additionally, if $m$ and $n$ are odd integers, then $p_{n_{0}+n}>p_{n_{0}+m}$ on $(0,r_{n_{0}}]$.
\end{lemma}

\begin{proof}
If $n$ and $m$ are even integers, with $n>m$, then 
\begin{eqnarray*}
p_{n_{0}+n}(x)-p_{n_{0}+m}(x) & = &\sum_{k=n_{0}+m+1}^{n_{0}+n}(-1)^{k}a_{k}x^{k}\\
&=& \sum_{k=0}^{(n-m-2)/2}a_{2k+n_{0}+m+1} \,x^{2k+n_{0}+m+1} \left(\frac{\Gamma(2n_{0}+2m+4k+5-\alpha)}{\Gamma(2n_{0}+2m+4k+6)}x-1\right).
\end{eqnarray*}
For $x\in (0,r_{n_{0}}]$ we have, from Lemma \ref{ldescre},
$$\frac{\Gamma(2n_{0}+2m+4k+6)}{\Gamma(2n_{0}+2m+4k+5-\alpha)}\geq \frac{\Gamma(2n_{0}+10)}{\Gamma(2n_{0}+9-\alpha)} > \frac{\Gamma(2n_{0}+6)}{\Gamma(2n_{0}+5-\alpha)}\geq r_{n_{0}} \geq x.$$
Therefore $p_{n_{0}+m}>p_{n_{0}+n}$ on $(0,r_{n_{0}}]$. 

Now, let $m$ and $n$ be two odd integers such that $n>m$, then 
\begin{equation*}
p_{n_{0}+n}(x)-p_{n_{0}+m}(x)  =  \sum_{k=0}^{(n-m-2)/2}a_{n_{0}+2k+m+1}\,x^{n_{0}+2k+m+1} \left(1-\frac{\Gamma(2n_{0}+4k+2m+5-\alpha)}{\Gamma(2n_{0}+4k+2m+6)}x \right).
\end{equation*}
Again, by Lemma \ref{ldescre} we have, for $x\in (0,r_{n_{0}}]$,
$$\frac{\Gamma(2n_{0}+4k+2m+6)}{\Gamma(2n_{0}+4k+2m+5-\alpha)}\geq \frac{\Gamma(2n_{0}+10)}{\Gamma(2n_{0}+9-\alpha)} > \frac{\Gamma(2n_{0}+6)}{\Gamma(2n_{0}+5-\alpha)}\geq r_{n_{0}} \geq x,$$
therefore $p_{n_{0}+m}<p_{n_{0}+n}$ on $(0,r_{n_{0}}]$. This proves the result.
\end{proof}

Note that $p_{n_{0}+1}(0)=1$ and
$$p_{n_{0}+1}(r_{n_{0}})=p_{n_{0}}(r_{n_{0}})-a_{n_{0}+1}\, x^{n_{0}+1}<0,$$
since $p_{n_{0}}(r_{n_{0}})=0$. Therefore, by the intermediate value theorem, there exists a root $r_{n_{0}+1}$ such that $0<r_{n_{0}+1}<r_{n_{0}}$. We are now equipped to demonstrate the existence of a positive root for $p_{\infty}$. 

\begin{theorem} \label{Th2}
The function $p_{\infty}$ has a first positive root, and this root is located in $(r_{n_{0}+1},r_{n_{0}})$.
\end{theorem}

\begin{proof}
By taking $m=0$ in Lemma \ref{despp}, we deduce that $p_{\infty}(r_{n_{0}})<p_{n_{0}}(r_{n_{0}})=0$. Given that $p_{\infty}(0)=1$,  the intermediate value theorem guarantees that $p_{\infty}$ must have a root in the interval $(0,r_{n_{0}})$. Let us denote by 
$s_{\bf 0}$ the first positive root of $p_{\infty}$. 

For each $n\in \mathbb{N} \cup \{0\}$, Lemma \ref{despp} implies that $p_{n_{0}+2n+1}(s_{\bf 0})<p_{\infty}(s_{\bf 0})=0$. Therefore, $p_{n_{0}+2n+1}$ has a root $r_{n_{0}+2n+1}$, and it follows that $r_{n_{0}+2n+1}<s_{\bf 0}$. Consequently, we obtain a sequence $(r_{n_{0}+2n+1})_{n\in \mathbb{N} \cup \{0\}}$. This sequence is increasing; indeed, Lemma \ref{lpoli} indicates that  $p_{n_{0}+2n+1}(r_{n_{0}+2n+3})<p_{n_{0}+2n+3}(r_{n_{0}+2n+3})=0$, implying that $r_{n_{0}+2n+1}<r_{n_{0}+2n+3}$. Let us define
$$r:=\lim_{n\rightarrow \infty} r_{n_{0}+2n+1}=\sup_{n\in \mathbb{N} \cup \{0\}}\{r_{n_{0}+2n+1}\}\leq s_{\bf 0}.$$
We aim to show that $r=s_{\bf 0}$. To do this, suppose that $r<s_{\bf 0}$. Take an $\tilde{r}\in (r,s_{\bf 0})$. By the definition of $s_{\bf 0}$ we have $p_{\infty}(x)>0$ for $x\in [r_{n_{0}+1}, \tilde{r}]$. The continuity of $p_{\infty}$ implies 
$$\min_{z\in [r_{n_{0}+1},\tilde{r}]}\{p_{\infty}(z)\}>0.$$
By Weierstrass's M-test, the sequence $(p_{n})_{n\in \mathbb{N}}$ converges uniformly over compact intervals. Hence, there exists $n_{1}\in \mathbb{N}$ such that for all $n\geq n_{1}$,
$$|p_{\infty}(x)-p_{n}(x)|<\frac{1}{2} \min_{z\in [r_{n_{0}+1},\tilde{r}]}\{p_{\infty}(z)\}, \quad x\in  [r_{n_{0}+1},\tilde{r}].$$
In particular, we can choose a sufficiently large odd integer $n$ such that $r_{n}\in (r_{n_{0}+1},r)$. The preceding inequality then leads to
$$0=p_{n}(r_{n})>\frac{1}{2} \, p_{\infty}(r_{n})>0.$$
This contradiction implies the desired equality, $r=s_{\bf 0}$.
\end{proof}

We now propose a method to approximate the first positive root of $p_{\infty}$. To this end, we introduce the following hypothesis.

\begin{description}
\item[Assumption B:] 
We assume that $p^{\prime}_{n_{0}}(x)\leq 0$ for $x$ on $[r_{n_{0}+1},r_{n_{0}}]$ and that
$$\frac{n_{0}+1}{n_{0}+2}\cdot \frac{\Gamma(2n_{0}+6)}{\Gamma(2n_{0}+5-\alpha)}\geq r_{n_{0}}.$$
\end{description}

\begin{theorem}  \label{Th3}
If $n\geq n_{0}$, regardless of whether $n$ is even or odd, the existence of the first root, $r_{n}$, of $p_{n}$ is guaranteed. Furthermore, the sequence $(r_{n})_{n\in \mathbb{N}}$ satisfies the condition
\begin{equation}
\lim_{n \rightarrow \infty}(r_{n+1}-r_{n})=0. \label{elim}
\end{equation}
Given an $\varepsilon>0$ we can find an integer $\tilde{n}$ (existence ensured by the first part of this theorem) such that
\begin{equation}
\left|r_{\tilde{n}}-r_{\tilde{n}+1}\right|<\varepsilon \label{apxdif}
\end{equation}
then 
\begin{equation}
\left|s_{\bf 0}-r_{\tilde{n}}\right|<\varepsilon. \label{aproot}
\end{equation}
Consequently, this provides an approximation to the first positive root, $s_{\bf 0}$, of $p_{\infty}$ with an error margin of at most $\varepsilon$ units.
\end{theorem}

\begin{proof}
For each $m\in \mathbb{N} \cup \{0\}$, we have $p_{n_{0}+2m}(0)=1$. Note that Lemma \ref{lpoli} implies $p_{n_{0}+2m}(r_{n_{0}})<p_{n_{0}}(r_{n_{0}})=0$. Therefore, $p_{n_{0}+2m}$ has a minimal positive root, $r_{n_{0}+2m}$, for all $m\in \mathbb{N} \cup \{0\}$. Additionally, Lemma \ref{despp} indicates that $p_{\infty}(x)<p_{n_{0}+2m}(x)$ in $(0,r_{n_{0}}]$ and since $p_{\infty}(s_{\bf 0})=0<p_{n_{0}+2m}(s_{\bf 0})$, it follows that $s_{\bf 0}<r_{n_{0}+2m}$. Furthermore, according to Lemma \ref{lpoli} we have $p_{n_{0}+2m+2}(r_{n_{0}+2m})<p_{n_{0}+2m}(r_{n_{0}+2m})=0$, implying $r_{n_{0}+2m+2}<r_{n_{0}+2m}$. Consequently, the sequence $(r_{n_{0}+2m})_{m}$ is monotonically decreasing and bounded below by  $s_{\bf 0}$. This leads to the conclusion that
$$ r:=\lim_{m\rightarrow \infty} r_{n_{0}+2m}=\inf_{m\in \mathbb{N}\cup \{0\}} \{r_{n_{0}+2m}\}\geq s_{\bf 0}.$$
Now, let us demonstrate that $s_{\bf 0}=r$. Suppose, for contradiction, that $s_{\bf 0}<r$. First, let us consider the expression
\begin{equation*}
p^{\prime}_{\infty}(x)-p^{\prime}_{n_{0}}(x) 
= \sum_{k=0}^{\infty}a_{n_{0}+2k}\, x^{n_{0}+2k+1} \left((n_{0}+2k+2)\frac{\Gamma(2n_{0}+4k+5-\alpha)}{\Gamma(2n_{0}+4k+6)}x-(n_{0}+2k+1)\right).
\end{equation*}
Using the monotonicity property of $g$ as established in Lemma \ref{ldescre}, for $x\in (0,r_{n_{0}}]$ and $k\geq 1$, we have
\begin{equation*}
\frac{n_{0}+2k+1}{n_{0}+2k+2}\cdot \frac{\Gamma(2n_{0}+4k+6)}{\Gamma(2n_{0}+4k+5-\alpha)} > 
\frac{n_{0}+1}{n_{0}+2}\cdot \frac{\Gamma(2n_{0}+6)}{\Gamma(2n_{0}+5-\alpha)}\geq r_{n_{0}}\geq x,
\end{equation*}
which implies that $p^{\prime}_{\infty}(s_{\bf 0})<p^{\prime}_{n_{0}}(s_{\bf 0})\leq 0$. The continuity of $p^{\prime}_{\infty}$ implies the existence of a $\delta > 0$ such that $p_{\infty}(x)<p_{\infty}(s_{\bf 0})=0$, for all $s_{\bf 0}\leq x < s_{\bf 0}+ \delta < r$. Let us take an $\tilde{x} \in (s_{\bf 0},s_{\bf 0}+\delta)$. Since $\lim_{n\rightarrow \infty}p_{n}(\tilde{x})=p_{\infty}(\tilde{x})$ we can find a large enough even integer $n$ such that
$$|p_{\infty}(\tilde{x})-p_{n}(\tilde{x})|<-p_{\infty}(\tilde{x}),$$
which implies that $p_{n}(\tilde{x})<0$. Given that $p_{n}(0)=1$  and by applying the intermediate value theorem, it follows that  $r_{n}<s_{\bf 0} + \delta < r$. However, this conclusion is contradictory, as we have established that $r\leq r_{n}$ for all even integer $n$. Consequently, it must be that $s_{\bf 0}=r$.

Given $\varepsilon>0$, there exists an integer $\tilde{n}$, such that if $i\geq \tilde{n}$ and  $j\geq \tilde{n}$, with $i$ an odd integer and $j$ an even integer, then 
$$|r_{i}-s_{\bf 0}|<\frac{\varepsilon}{2}, \quad |r_{j}-s_{\bf 0}|<\frac{\varepsilon}{2}.$$
Consequently, if $n\geq \tilde{n}$, we have
$$|r_{n+1}-r_{n}|<|r_{n+1}-s_{\bf 0}|+|r_{n}-s_{\bf 0}|<\varepsilon.$$
Thus, the limit as expressed in (\ref{elim}) is effectively established.
\end{proof}

In this context, we have find an approximation, $r_{\tilde{n}}$, of $s_{\bf 0}$. Therefore, if  $p_{\infty}(\lambda l^{2})=0$, it follows that
$$\frac{P}{EI\,\Gamma(2-\alpha)} \ l^{2} = s_{\bf 0}.$$
From this, we obtain an approximation critical load, see the formula (\ref{fcpandeo}).

\section{Some illustrative examples} \label{SecNE}

In this section, we will explore two illustrative examples to further elucidate the concepts.

\subsection{Non-existence of an even degree polynomial $p_{n_{0}}$ with a positive root}

In this subsection, we will take $\alpha=0.526$ and $n\in \mathbb{N}\cup \{0\}$. Observe that
\begin{equation*}
p_{\infty}(x)-p_{2n+1}(x)
= \sum_{k=0}^{\infty}a_{2n+2k+2}\, x^{2n+2k+2} \left(1-\frac{\Gamma(4n+4k+6.474)}{\Gamma(4n+4k+8)}x \right).
\end{equation*}
According to Lemma \ref{ldescre}, for $k\geq 1$,
$$\frac{\Gamma(4n+4k+8)}{\Gamma(4n+4k+6.474)} > \frac{\Gamma(4n+8)}{\Gamma(4n+6.474)},$$
therefore, $p_{\infty}>p_{2n+1}$ on $[0,\Gamma(4n+8)/\Gamma(4n+6.474)]$. This particularly implies that if
\begin{equation}
r_{2n+1}\in [0,\Gamma(4n+8)/\Gamma(4n+6.474)], \label{cplab}
\end{equation}
then $p_{\infty}$ does not have a root in $[0,r_{2n+1}]$. 

