  \draw (-1, 0.8) -- (-1,1) -- (-0.8, 1);
  \draw (1, 0.8) -- (1,1) -- (0.8, 1);
  \node at (-1.2,-1.2) {$L$};
  \node at (1.2,-1.2) {$L'$};
  \node at (0,-2) {$\varepsilon(L,L')=+1$};
  \begin{scope}[shift={(5,0)}]
  \draw (1,-1) -- (-1,1);
  \draw(-1,-1) -- (-0.2, -0.2);
  \draw (0.2, 0.2) -- (1, 1);
  \draw (-1, 0.8) -- (-1,1) -- (-0.8, 1);
  \draw (1, 0.8) -- (1,1) -- (0.8, 1);
