\section{An algebraic lemma}
For non-negative integers $a,b,c$, we define a polynomial function $f_{abc}\colon \mathbb{R}^3\to \mathbb{R}$ by
$$
    f_{abc}(x,y,z)=x^ay^bz^c.
$$
An easy computation shows that we have
    $$
        \langle v,w\rangle^n = \sum_{a+b+c=n}\dfrac{n!}{a!b!c!}f_{abc}(v)f_{abc}(w)
    $$
for any $v,w\in \mathbb{R}^3$, where $\langle {-},{-}\rangle$ denotes the standard inner product on $\mathbb{R}^3$.
We prepare the following algebraic lemma, which will be used in the proof of \Cref{directed}:

\begin{lemma}\label{algebraic}
    Let $n\geq 2$. Suppose that $v_1,\dots,v_n\in \mathbb{R}^3$ are unit vectors such that no two of them are parallel.
    Then, the symmetric matrix $S=(\|v_i\times v_j\|)_{i,j}$ is non-singular and has signature $(1,n-1)$.
\end{lemma}

\begin{proof}
    For the all-one vector $\mathbf{1}=(1,\dots,1)\in \mathbb{R}^n$, we have $\mathbf{1}^TS\mathbf{1}=\sum_{i,j}\|v_i\times v_j\|>0$.
    Let $H=\{(t_i)_i\in \mathbb{R}^n\mid \sum_i t_i=0\}$.
    It suffices to show that $S$ is negative definite on $H$.
    We have $\|v_i\times v_j\|=\sqrt{1-\langle v_i,v_j\rangle^2}$.
    The Taylor expansion of $\sqrt{1-x^2}$ is given by
    $$
        \sqrt{1-x^2} = 1-\sum_{k=1}^\infty \dfrac{1}{4^k(2k-1)}\binom{2k}{k} x^{2k},
    $$
    which converges for $-1\leq x\leq 1$.
    Therefore, the entries $s_{ij}$ of $S$ are given by
    \begin{align*}
        s_{ij} &{}= 1-\sum_{k=1}^\infty \dfrac{1}{4^k(2k-1)}\binom{2k}{k} \langle v_i,v_j\rangle^{2k}\\
        &{}=1-\sum_{k=1}^\infty\sum_{a+b+c=2k}C^{(k)}_{abc}f_{abc}(v_i)f_{abc}(v_j).\quad \left(C^{(k)}_{abc}:=\dfrac{1}{4^k(2k-1)}\binom{2k}{k}\dfrac{(2k)!}{a!b!c!}>0\right)
    \end{align*}
    For any vector $t=(t_i)_i\in \mathbb{R}^n$, we have
    \begin{align*}
        t^TSt = \sum_{i,j} s_{ij}t_it_j=\sum_{i,j}t_it_j - \sum_{i,j}\sum_{k=1}^\infty\sum_{a+b+c=2k}C^{(k)}_{abc}f_{abc}(v_i)f_{abc}(v_j)t_it_j.
    \end{align*}
    If $t\in H$, then the first term is $0$ and hence
    \begin{align*}
        t^TSt &{}= -\sum_{k=1}^\infty\sum_{a+b+c=2k}C^{(k)}_{abc}\left(\sum_{i=1}^nf_{abc}(v_i)t_i\right)^2\leq 0.
    \end{align*}
    This shows that $S$ is negative semi-definite on $H$.
    If $t^TSt=0$, then we have
    $$
        \sum_{i=1}^n f_{abc}(v_i)t_i=0
    $$
    for any $k\geq 0$ and any $a,b,c\geq 0$ with $a+b+c=2k$.
    This implies that for any polynomial $F\in \mathbb{R}[x,y,z]$ which has only even-degree terms, we have
    \begin{align}\label{eq1}
        \sum_{i=1}^n F(v_i)t_i=0.
    \end{align}
    For each $i\in \{1,2,\dots,n\}$, there is a linear function $f_i\colon \mathbb{R}^3\to \mathbb{R}$ such that $f_i(v_i)= 0$ and $f_i(v_j)\neq 0\ (i\neq j)$.
    Applying \eqref{eq1} for $F_i=\prod_{i\neq j}f_i^2$, we obtain $t_i=0$.
    This shows that $S$ is negative definite on $H$.
\end{proof}

\begin{remark}
    In the proof of \Cref{algebraic}, we expanded $\|v_i\times v_j\|$ as a power series in $\langle v_i,v_j\rangle$.
    Instead, we could also expand $\|v_i\times v_j\|$ by Legendre polynomials $P_\ell(\langle v_i,v_j\rangle)$ and use the addition theorem of spherical harmonic functions,
    $$
    P_\ell(\langle x,y\rangle)=\dfrac{4\pi}{2\ell+1}\sum_{-\ell\leq m\leq \ell} \overline{Y_\ell^m(x)}Y_\ell^m(y),
    $$
    to obtain the same result.
\end{remark}

\section{Proof of the main theorem}

Let $L,L'$ be two directed lines in $\mathbb{R}^3$ that are not coplanar.
Write $L=\mathbb{R}v+w$ and $L'=\mathbb{R}v'+w'$, where $v,v'\in \mathbb{R}^3$ are the unit vectors representing the direction of the line, and the vectors $w,w'\in \mathbb{R}^3$ are uniquely determined modulo $\mathbb{R}v$ (resp. $\mathbb{R}v'$).
We define the \emph{chirality} $\varepsilon(L,L')\in \{\pm 1\}$ by
$$
\varepsilon(L,L')=\sgn\langle v\times v',w-w'\rangle.
$$
One can easily see that this agrees with the intuitive definition of $\varepsilon(L,L')$ given in the introduction.
By definition, we have $\varepsilon(L,L')=\varepsilon(L',L)$.


Suppose that $L_1,\dots,L_n$ are directed lines in $\mathbb{R}^3$ such that no two of them are coplanar.
We define the \emph{chirality graph} of $\{L_1,\dots,L_n\}$ to be the signed complete graph on the vertex set $\{1,2,\dots,n\}$ whose sign on the edge $(i,j)$ is given by $\varepsilon(L_i,L_j)$.
If we reverse the direction of a line $L_i$, then the sign of the edges adjacent to the vertex $i$ will be reversed.

