\newcommand{\transitionarc}[4]{
    % #1: start angle, #2: end angle, #3: start radius, #4: end radius
    \pgfmathsetmacro{\steps}{30}
    \pgfmathsetmacro{\deltaAngle}{(#2 - #1)/\steps}
    \pgfmathsetmacro{\deltaRadius}{(#4 - #3)/\steps}
    \foreach \i in {0,...,\steps} {
        \pgfmathsetmacro{\angleA}{#1 + \i * \deltaAngle}
        \pgfmathsetmacro{\angleB}{#1 + (\i + 1) * \deltaAngle}
        \pgfmathsetmacro{\radiusA}{#3 + \i * \deltaRadius}
        \pgfmathsetmacro{\radiusB}{#3 + (\i + 1) * \deltaRadius}
        \draw[loosely dotted] 
            ({\radiusA*cos(\angleA)}, {\radiusA*sin(\angleA)}) -- 
            ({\radiusB*cos(\angleB)}, {\radiusB*sin(\angleB)});
    }

   % Arrowhead at the START point, pointing reverse (counterclockwise tangent)
    \pgfmathsetmacro{\startAngle}{#1}
    \pgfmathsetmacro{\startRadius}{#3}

    % Small step along the arc forward (clockwise)
