\caption{In blue we have the (Desmos prepared) picture of the graph of the function $f_0$.}
\label{fig}
\end{figure}


\begin{proop}
\label{prop2}
Let $W:=\{x\in \mathbb R^3 : x_1=0\}$ be a coordinate plane and consider a bounded triangle $P\subset W$. Denote the corresponding two-sided unbounded prism $C_P$ by
$$
C_P:=\{x\in \mathbb R^3 : x=v+\lambda e_1, \text{ where } v\in P , \lambda\in \mathbb R\}.
$$ 
\begin{enumerate}
\item \label{odin} Suppose first that $P$ is different from one of following four triangles with angles $(60^0,60^0,60^0), (30^0,30^0,120^0), (30^0,60^0,90^0), (45^0,45^0,90^0)$. Then  $f\in \mathcal H(\mathbb R^3)$ and $f\restr_{\partial C_p}=0$ implies $f=0$ identically.
\item \label{dva} Suppose second that $P$ is any of following four triangles with angles $(60^0,60^0$,\\ $60^0)$, $(30^0,30^0,120^0)$, $(30^0,60^0,90^0)$, $(45^0,45^0,90^0)$. Then there exists a function $f\in \mathcal H(\mathbb R^3)$ that is not zero identically and that vanishes at $\partial C_P$. 
\end{enumerate}
\end{proop}
\begin{proof}
Let us first proof the statement~\ref{dva}. Let $P_0$ be any of the aforementioned three triangles. According to~\cite{gardiner1993dirichlet}, there exists a nonzero harmonic function $f_0: C_P \rightarrow \mathbb C$ vanishing at the boundary of  $C_P$. Then, thanks to the Schwartz reflection principle, $f_0$ can be extended to the whole space $\mathbb R^3$. Here, we are using the fact that successive reflections of $P_0$ with respect to sides never self-intersect and form a tilling of the whole plane. 

We now concentrate on the proof of the statement~\ref{odin}. We will use the main result of the paper~\cite{barany1993reflecting} to say that in the contrary case the corresponding sequences of reflections of $P$ are dense in $\mathbb R^2$ and hence the function must be zero everywhere in $\mathbb R^3$. 
\end{proof}

\begin{rem}
Thanks to the work by Logunov and Malinnikova, see~\cite{logunov2015ratios} in the second statement of the proposition just above, in the case where $P$ is the unit square the corresponding function can be written out explicitly. Indeed, it is easy to see that the function
$$\psi(x):=\sin(a_1x_1)\cdot \ldots \cdot \sin(a_{d-1}x_{d-1})\sinh(a_{d}x_{d})$$
defined for all $x\in \mathbb R^d$ is harmonic, whenever real numbers $a_1,\ldots, a_d$ are such that holds $a_d^2=a_1^2+\ldots+a_{d-1}^2$. It is also clear that the function $\psi$ equals to zero at the boundary of the corresponding prism.
\end{rem}

\begin{rem}
It would be interesting to find out if such explicit formulas exist in the case of other $P$ as in~\ref{prop2} and in the case of several dimensions. Another interesting question is to classify \textit{all} nonzero harmonic functions that vanish on the boundary of a half-strip or a half-prism.
\end{rem}

