\subsubsection{$2\times 2$ Matrix Full Formula}\label{2x2FullMatrixFormula}

    $\operatorname{Sink}\left(A
        \left|\, 
        \vec{R},\vec{C}
        \right.\right)=
        \operatorname{Sink}\left(
        \begin{bmatrix}
            a_{11} & a_{12}\\
            a_{21} & a_{22}
        \end{bmatrix}
        \left|\, 
        \begin{bmatrix}
            R_1 \\ R_2
        \end{bmatrix},
        \begin{bmatrix}
            C_1 \\ C_2
        \end{bmatrix}
        \right.\right) = S = \begin{bmatrix}
        s_{11} & s_{12}\\
        s_{21} & s_{22}
    \end{bmatrix}$ where
    \begin{align*}
        s_{11} &= \dfrac{a_{11}a_{22}(R_2 - 2 C_1 - C_2)+ a_{12}a_{21}(- R_2 + C_1)+\sqrt{(a_{11}a_{22} (C_2+R_2)+ a_{12}a_{21} (C_1-R_2))^2- 4 a_{11}a_{22} C_2 R_2 \det(A)}}{-2\det(A)}\\
        s_{12} &= \dfrac{a_{11}a_{22}(R_2 - C_2)+ a_{12}a_{21}(-R_2 + C_1 + 2 C_2)-\sqrt{(a_{11}a_{22} (C_2+R_2)+ a_{12}a_{21} (C_1-R_2))^2- 4 a_{11}a_{22} C_2 R_2 \det(A)}}{-2\det(A)} \\
        s_{21} &= \dfrac{a_{11}a_{22}(-R_2+C_2)+ a_{12}a_{21}(R_2+C_1)-\sqrt{(a_{11}a_{22} (C_2+R_2)+ a_{12}a_{21} (C_1-R_2))^2- 4 a_{11}a_{22} C_2 R_2 \det(A)}}{-2\det(A)}\\
        s_{22} &= \dfrac{a_{11}a_{22}(-R_2-C_2)+ a_{12}a_{21}(R_2-C_1)+\sqrt{(a_{11}a_{22} (C_2+R_2)+ a_{12}a_{21} (C_1-R_2))^2- 4 a_{11}a_{22} C_2 R_2 \det(A)}}{-2\det(A)}
    \end{align*}

