\subsection{Python Test File}\label{PythonTestFile}

    This Python script was used to test results numerically. It gives the generalized Sinkhorn limit of any sized matrix.
    \lstset{language=Python}
    \begin{lstlisting}
import numpy as np

def generalized_sinkhorn_knopp(
    matrix: np.ndarray,
    target_row_sums: np.ndarray,
    target_col_sums: np.ndarray,
    tolerance: float = 1e-9,
    max_iterations: int = 1000,
    verbose: bool = True
) -> np.ndarray:
    """
    Calculates the generalized Sinkhorn-Knopp limit for a positive matrix,
    scaling its rows and columns to match specified target sums.

    Iteratively scales rows and then columns until convergence.

    Args:
        matrix (np.ndarray): Initial positive input matrix (2D numpy array).
                             All elements must be strictly positive.
        target_row_sums (np.ndarray): A 1D numpy array of target sums for each row.
                                      Must have the same number of elements as matrix rows.
                                      All elements must be strictly positive.
        target_col_sums (np.ndarray): A 1D numpy array of target sums for each column.
                                      Must have the same number of elements as matrix columns.
                                      All elements must be strictly positive.
        tolerance (float): The convergence criterion. The algorithm stops when the
                           Frobenius norm of the difference between successive matrices
                           is less than this tolerance.
        max_iterations (int): The maximum number of iterations to perform.
        verbose (bool): If True, prints iteration progress.

    Returns:
        np.ndarray: The scaled matrix that approximates the target row and column sums.

    Raises:
        ValueError: If inputs are invalid (e.g., non-positive, incompatible dimensions,
                    or sum mismatch between target row and column sums).
    """

    # --- Input Validation ---
    if not isinstance(matrix, np.ndarray) or matrix.ndim != 2:
        raise ValueError("Input 'matrix' must be a 2D numpy array.")
    if not np.all(matrix > 0):
        raise ValueError(
            "All elements of the input 'matrix' must be strictly positive.")

    if not isinstance(target_row_sums, np.ndarray) or target_row_sums.ndim != 1:
        raise ValueError("'target_row_sums' must be a 1D numpy array.")
    if not np.all(target_row_sums > 0):
        raise ValueError(
            "All elements of 'target_row_sums' must be strictly positive.")

    if not isinstance(target_col_sums, np.ndarray) or target_col_sums.ndim != 1:
        raise ValueError("'target_col_sums' must be a 1D numpy array.")
    if not np.all(target_col_sums > 0):
        raise ValueError(
            "All elements of 'target_col_sums' must be strictly positive.")

    num_rows, num_cols = matrix.shape
    if len(target_row_sums) != num_rows:
        raise ValueError(
            f"Length of 'target_row_sums' ({len(target_row_sums)}) must match "
            f"the number of matrix rows ({num_rows})."
        )
    if len(target_col_sums) != num_cols:
        raise ValueError(
            f"Length of 'target_col_sums' ({len(target_col_sums)}) must match "
            f"the number of matrix columns ({num_cols})."
        )

    # Check the consistency condition (sum of target row sums must equal sum of target column sums)
    if not np.isclose(np.sum(target_row_sums), np.sum(target_col_sums)):
        raise ValueError(
            f"Sum of target row sums ({np.sum(target_row_sums)}) must equal "
            f"sum of target column sums ({np.sum(target_col_sums)}). "
            "A solution does not exist otherwise."
        )

    # --- Algorithm Initialization ---
    current_matrix = np.copy(matrix).astype(
        float)  # Ensure float type for division

    # --- Iterative Scaling ---
    for i in range(max_iterations):
        prev_matrix = np.copy(current_matrix)

        # 1. Row Scaling
        current_row_sums = np.sum(current_matrix, axis=1)
        # Avoid division by zero or very small numbers, though inputs are positive
        # Add a small epsilon to avoid division by zero if sums somehow become zero (just in case)
        row_scaling_factors = target_row_sums / \
            (current_row_sums + np.finfo(float).eps)
        # Apply scaling (multiply each row by its corresponding factor)
        current_matrix = current_matrix * row_scaling_factors[:, np.newaxis]

        # 2. Column Scaling
        current_col_sums = np.sum(current_matrix, axis=0)
        # Add a small epsilon for robustness
        col_scaling_factors = target_col_sums / \
            (current_col_sums + np.finfo(float).eps)
        # Apply scaling (multiply each column by its corresponding factor)
        current_matrix = current_matrix * col_scaling_factors[np.newaxis, :]

        # --- Convergence Check ---
        if np.linalg.norm(current_matrix - prev_matrix, 'fro') < tolerance:
            if verbose:
                print(f"Converged in {i + 1} iterations.")
            break
    else:
        if verbose:
            print(f"Did not converge within {max_iterations} iterations.")

    return current_matrix


# --- Example Usage ---
if __name__ == "__main__":
