\section{Preliminary Results}
In this section we give preliminary results
 required to prove Theorems~\ref{thm:main1} and \ref{thm:main2}.
Henceforth we assume that condition~(A${}_1$) holds.

Let $v_l(x)$, $l=1,2$, be scalar functions on $\Rset$ or $\Cset$,
 and let $W(v_1(x),v_2(x))$ denote the Wronskian of $v_1(x)$ and $v_2(x)$, i.e.,
\begin{equation}
W(v_1(x),v_2(x))=\begin{vmatrix}
v_1(x) & v_2(x)\\
v_{1x}(x) & v_{2x}(x)
\end{vmatrix}
=v_1(x)v_{2x}(x)-v_2(x)v_{1x}(x).
\label{eqn:2a}
\end{equation}
Since the first-order derivative $v_x$ does not appear in \eqref{eqn:ZS0},
  the Wronskians of $\phi(x;-k),\phi(x;k)$ and of $\psi(x;k),\psi(x;-k)$ are independent of $x$,
  so that by \eqref{eqn:bc}
\begin{equation}
W(\phi(x;k),\phi(x;-k))=W(\psi(x;-k),\psi(x;k))=2ik.
\label{eqn:W}
\end{equation}
Replacing $k$ with $-k$ in \eqref{eqn:ab+}, we have
\begin{equation}
\phi(x;-k)=a(-k)\psi(x;k)+b(-k)\psi(x;-k),
\label{eqn:ab-}
\end{equation}
and consequently
\begin{equation}
a(k)a(-k)-b(k)b(-k)=1
\label{eqn:2b}
\end{equation}
by \eqref{eqn:W}.
We have the following properties of the scattering coefficients. 

\begin{prop}\
\label{prop:2a}
\begin{itemize}
\setlength{\leftskip}{-1.6em}
\item[(i)]
$a(k),b(k)$ are analytic in $\Rset^\ast;$
\item[(ii)]
$a(k)$ can be analytically continued in $\Cset_+;$
\item[(iii)]
$a(k)$ only has discrete zeros in $\Cset_+\cup\Rset;$
\item[(iv)]
If $b(k)=0$ for any $k\in\Rset^\ast$,
 then $a(k)$ only has finitely many zeros in $\Cset_+$.
\end{itemize}
\end{prop}

Similar results are obtained in Section~4.1
 (especially Proposition~4.1) of \cite{Y23}
 when $u(x)$ is analytic on $\Rset$.

\begin{proof}
Let $S$ denote the set of poles of $u(x)$.
Then $S$ is discrete and contains no accumulation point.
Choose a curve $\Gamma=\{\gamma(\xi)\in\Cset_+\mid \xi\in\Rset\}$ with
\[
\gamma(\xi)=\xi+ic\sech\xi
\]
does not intersect $S$.
%By \eqref{eqn:A1a}
Hence, $u(x)$ is analytic on $\Gamma$.

Regard \eqref{eqn:ZS0} as a differential equation on $\Gamma$
 and let $U$ be a neighborhood of $\Gamma$ in $\Cset_+$ such that $S\cap U=\emptyset$.
Then its solutions $v=\phi(x;k)$ and $\psi(x;k)$ are bounded and analytic
 in $k\in\Rset^\ast$ as well as in $x\in U$.
By \eqref{eqn:ab+} and \eqref{eqn:2a} we have
\begin{equation}
a(k)=\frac{W(\phi(x,k),\psi(x;k))}{2ik},\quad
b(k)=-\frac{W(\phi(x,k),\psi(x;-k))}{2ik}.
\label{eqn:prop2a1}
\end{equation}
Hence, we obtain part~(i).
Similarly we see that $v=\phi(x;k)$ and $\psi(x;k)$ are bounded and analytic
 in $\Cset_+$ for $x\in U$ satisfying $|x|<R$ with some $R>0$.
This yields part~(ii) along with \eqref{eqn:prop2a1}.

Equation~\eqref{eqn:ZS0} is written as
\begin{equation}
v_{\xi\xi}-\frac{\gamma_{\xi\xi}(\xi)}{\gamma_\xi(\xi)}v_\xi
 +\gamma_\xi(\xi)(k^2+u(\gamma(\xi)))v=0
\label{eqn:prop2a2}
\end{equation}
on $\Gamma$.
Changing the independent variable as $\xi\mapsto k\xi$ in \eqref{eqn:prop2a2}, we have
\[
v_{\xi\xi}-\frac{\gamma_{\xi\xi}(\xi/k)}{k\gamma_\xi(\xi/k)}v_\xi
 +\gamma_\xi(\xi/k)\left(1+\frac{1}{k^2}u(\gamma(\xi/k))\right)v=0,
\]
which reduces to
\[
v_{\xi\xi}+v=0
\]
as $k\to\infty$.
This implies that
\[
a(k)\to 1,\quad b(k)\to 0\quad\mbox{as $|k|\to\infty$}.
\]
We apply the identity theorem (e.g., Theorem~3.2.6 of \cite{AF03})
 to obtain  part~(iii), since $a(k)$ is analytic in $\Cset_+\cup\Rset$.
If $b(k)=0$ for any $k\in\Rset^\ast$,
 then by its analyticity $a(k)$ has no zero near $k=0$ in $\overline{\Cset}_+$.
Hence, part~(iv) follows from part~(iii).
\end{proof}

\begin{rmk}
The conclusion in Proposition~{\rm\ref{prop:2a}(iv)} holds
 under a weaker condition.
For example, if $\lim_{k\to 0} b(k)b(-k)\to b_0$ $(\neq -1)$, then it holds.
\end{rmk}

Let $G$ be the differential Galois group of \eqref{eqn:ZS0}.
Then $G$ is an algebraic group such that $G\subset\SL(2,\Cset)$
 since Eq.~\eqref{eqn:ZS0} has no term depending on $v_x$
 (see, e.g., Chapter~6 of \cite{K76} or Section 2.2 of \cite{M99}).
We have the following classification
 for such algebraic groups (see Section~2.1 of \cite{M99} for a proof).
Recall that an algebraic group $\G$ contains in general a unique maximal algebraic subgroup $\G^0$,
 which is called the \emph{connected component of the identity}
 or \emph{connected identity component}.


\begin{prop}
\label{prop:2b}
Any algebraic group $\G\subset\SL(2,\Cset)$ is similar to one of the following types:
\begin{enumerate}
\setlength{\leftskip}{-1.2em}
\item[(i)] $\G$ is finite and $\G^0= \{\id\}$,
 where $\id$ is the $2\times 2$  identity matrix$;$
%\item[(ii)] $G = G^0 = \left\{\begin{pmatrix}
%1&0\\
%\mu & 1 
%\end{pmatrix}
%\middle|\,\mu \in \Cset
%\right\}$;
\item[(ii)] $\G = \left\{
\begin{pmatrix}
\lambda & 0\\
\mu & \lambda^{-1} 
\end{pmatrix}
\middle|\,\lambda\text{ is a root of $1$, $\mu\in\Cset$}
\right\}$
and $\G^0 = \left\{\begin{pmatrix}
1&0\\
\mu & 1 
\end{pmatrix}
\middle|\,\mu \in \Cset\right\}$;
\item[(iii)] 
$\G = \G^0 = 
\left\{
\begin{pmatrix}
\lambda &0 \\
0 & \lambda ^{-1}
\end{pmatrix}
\middle|\,\lambda \in \Cset^{*}
\right\}$;
\item[(iv)]
$\G = \left\{
\begin{pmatrix}
\lambda & 0\\
0 & \lambda^{-1} 
\end{pmatrix},
\begin{pmatrix}
0 & -\beta^{-1}\\
\beta & 0 
\end{pmatrix}
\middle|\,\lambda, \beta \in \Cset^{*}
\right\}$
and $\G^0 = \left\{\begin{pmatrix}
\lambda &0\\
0 & \lambda^{-1}
\end{pmatrix}
\middle|\, \lambda \in \Cset^*\right\}$;
\item[(v)] $\G = \G^0 = \left\{
\begin{pmatrix}
\lambda & 0\\
\mu & \lambda^{-1}
\end{pmatrix}
\middle|\,\lambda \in \Cset^{*},\, \mu \in \Cset
\right\}$;
\item[(vi)] $\G = \G^0 = \SL (2,\, \Cset)$.
\end{enumerate}
\end{prop}

The system~\eqref{eqn:ZS0} is integrable in the sense of differential Galois theory
 unless $G$ is of type (vi).
Proposition~\ref{prop:2b} plays a key role
 in the proof of Theorem~\ref{thm:main2} in Section~4.

