\section{Proof of Theorem~\ref{thm:main1}}
In this section we give a proof of Theorem~\ref{thm:main1}.
Henceforth we assume that the hypotheses of Theorem~\ref{thm:main1} hold
 and $b(k)=0$ for $k\in\Rset^\ast$.

\begin{proof}[Proof of Theorem~$\ref{thm:main1}$]
We see by Proposition~\ref{prop:2a}(iii) and \eqref{eqn:2b}
 that $a(k)\neq 0$ for $k\in\Rset^\ast$
 and $a(k)$ has finitely many zeros in $\Cset_+$.
Assume that $a(k)$ has $n$ zeros and
 let $k_j$ be its zero of multiplicity $\nu_j$ in $\Cset_+$ for $j=1,\ldots,n$.
Let the curve $\Gamma=\{\gamma(\xi)\in\Cset_+\mid \xi\in\Rset\}$ contain no pole of $u(x)$,
 and let $U$ be a neighborhood of $\Gamma$ in $\Cset_+$ containing no pole of $u(x)$,
 as in the proof of Proposition~\ref{prop:2a}.

Let
\begin{equation}
M(x;k)=\phi(x;k)e^{ikx},\quad
N(x;k)=\psi(x;k)e^{ikx}.
\label{eqn:MN1}
\end{equation}
By \eqref{eqn:bc} we have
\begin{equation}
\mbox{$M(x;k)\sim 1$ as $x\to-\infty$},\quad
\mbox{%$N(x;k)\sim e^{2ikx}$ and 
$N(x;-k)\sim 1$ as $x\to+\infty$.}
\label{eqn:MN1a}
\end{equation}
Since $\phi(x;k)$ and $\psi(x;-k)$ are analytic in $x\in U$ and $k\in\Cset_+$,
 so are $M(x;k)$ and $N(x;-k)$.
Using \eqref{eqn:ab+}, we have
\begin{equation}
M(x;k)=a(k)N(x;-k)e^{2ikx}+b(k)N(x;k).
\label{eqn:MN1b}
\end{equation}
%which yields $M(x;k_j)=b(k_j)N_j(x)$, where $N_j(x)=N(x;k_j)$ for $j=1,\ldots,n$.
Let
\[
N_j^r(x):=\frac{\partial^rN}{\partial k^r}(x;k_j),\quad
r=0,\ldots,\nu_j-1,\quad
j=1,\ldots,n.
\]
Differentiating \eqref{eqn:MN1b} with respect $k$ and substituting $k=k_j$, we obtain
\begin{equation}
\frac{\partial^rM}{\partial k^r}(x;k_j)
=\frac{\partial^r}{\partial k^r}\bigl(b(k)N(x;k)\bigr)\Big|_{k=k_j},\quad
r=0,\ldots,\nu_j-1,
\label{eqn:MN1c}
\end{equation}
for $j=1,\ldots,n$ since $a(k)$ has a zero of multiplicity $\nu_j$ at $k=k_j$.
In particular, the right hand sides of \eqref{eqn:MN1c}
 can be represented by linear combinations of $N_j^r(x)$, $r=0,\ldots,\nu_j-1$.
Actually, when $\nu_j>1$, we have
\begin{align*}
M(x;k_j)
=b(k_j)N_j^0(x),\quad
\frac{\partial M}{\partial k}(x;k_j)
=b(k_j)N_j^1(x)+b_k(k_j)N_j^0(x),\quad
\ldots.
\end{align*}

Define the projection operators
\[
\P^\pm(f)=\frac{1}{2\pi i}\int_{-\infty}^\infty\frac{f(\kappa)}{\kappa-(k\pm i 0)}\d\kappa
\]
for $f\in L^1(\Rset)$, where $k\in\Cset_+$ or $\Cset_-$
 depending on whether the upper or lower signs are taken simultaneously.
If $f_+$ (resp. $f_-$) is analytic in $\Cset_+$ (resp. in $\Cset_-$)
 and $f_\pm(k)\to 0$ as $|k|\to\infty$, then
\[
\P^\pm(f_\pm)=\pm f_\pm,\quad
\P^\pm(f_\mp)=0
\]
(see, e.g., Chapter~7 of \cite{AF03}).
Dividing both sides of \eqref{eqn:MN1b} by $a(k)$ and noting \eqref{eqn:MN1a},
 we apply $\P^-$ to the resulting equation to obtain
\begin{equation}
N(x;k)e^{-2ikx}=1-\frac{1}{2\pi i}\sum_{j=1}^n\int_{|\kappa-k_j|=\delta}
 \frac{M(x;\kappa)}{(k+\kappa)a(\kappa)}\d\kappa
\label{eqn:MN1d}
\end{equation}
since $M(x;k)$ and $N(x;-k)$ are analytic for $k\in\Cset_+$ and $\Cset_-$, respectively,
 and $b(k)=0$ for $k\in\Rset^\ast$.
Using the method of residues, we see that the above integrals
 are represented by linear combinations of $N_j^r(x)$, $r=0,\ldots,\nu_j-1$.
For example, when $\nu_j=1$,
\[
\frac{1}{2\pi i}\int_{|\kappa-k_j|
 =\delta}\frac{M(x;\kappa)}{(k+\kappa)a(\kappa)}\d\kappa
 =\frac{b(k_j)}{(k+k_j)a_k(k_j)}N_j^0(x),
\]
and when $\nu_j=2$,
\begin{align*}
&
\frac{1}{2\pi i}\int_{|\kappa-k_j|=\delta}\frac{M(x;\kappa)}{(k+\kappa)a(\kappa)}\d\kappa\\
&
=\frac{2}{(k+k_j)a_{kk}(k_j)}
 \biggl(b(k_j)N_j^1(x)
 +\biggl(b_k(k_j)-\frac{b(k_j)}{k+k_j}
 -\frac{a_{kkk}(k_j)b(k_j)}{3a_{kk}(k_j)}\biggr)N_j^0(x)\biggr).
 \end{align*}

Differentiating \eqref{eqn:MN1d} with respect to $k$ up to $\nu_j-1$ times
 and setting $k=k_j$,
 we obtain a system of linear equations
 about $N_j^r(x)$, $r=0,\ldots,\nu_j-1$, $j=1,\ldots,n$,
 and solve it to obtain them as rational functions
 of $x$ and $\{e^{2ik_jx}\}_{j=1}^n$, using basic arithmetic operations.
Note that
\[
\frac{\partial}{\partial k}(N(x;k)e^{-2ik x})
=\left(\frac{\partial N}{\partial k}(x;k)-2ixN(x;k)\right)e^{-2ik x}
\]
and so on.
Hence, we see by \eqref{eqn:MN1} and \eqref{eqn:MN1d}
 that the Jost solution $\psi(x;k)$
 is also represented by a rational function of $x$ and $\{e^{ik_jx}\}_{j=1}^n$.
This means the desired result.
 \end{proof}

\begin{rmk}
We show that
\begin{equation}
u(x)=\frac{1}{\pi}\frac{\partial}{\partial x}\biggl(\sum_{j=1}^n\int_{|\kappa-k_j|=\delta}
 \frac{M(x;\kappa)}{a(\kappa)}\d\kappa\biggr)
\label{eqn:u1}
\end{equation}
$($see, e.g., Section~$9.3$ of {\rm\cite{A11})},
 so that $u(x)$ is also represented by rational functions of $x$ and $\{e^{ik_jx}\}_{j=1}^n$.
The sign of the corresponding formula {\rm(4.12)} in {\rm\cite{Y23}} contains an error.
Note that for example, when $\nu_j=1$,
\[
\frac{1}{\pi}\int_{|\kappa-k_j|}\frac{M(x;\kappa)}{a(\kappa)}\d\kappa
 =\frac{2ib(k_j)}{a_k(k_j)}N_j^0(x),
\]
and when $\nu_j=2$,
\begin{align*}
&
\frac{1}{\pi}\int_{|\kappa-k_j|}\frac{M(x;\kappa)}{a(\kappa)}\d\kappa\\
&
=\frac{4i}{a_{kk}(k_j)}\left(
 b(k_j)N_j^1(x)+\left(b_k(k_j)-\frac{a_{kkk}(k_j)b(k_j)}{3a_{kk}(k_j)}\right)N_j^0(x)\right).
\end{align*}
Since $\Im k_j>0$, $j=1,\ldots,n$,
 it follows from \eqref{eqn:MN1a} and \eqref{eqn:u1} that
\[
\lim_{x\to\pm\infty}u(x)=0.
\]
\end{rmk}

\begin{figure}
\includegraphics[scale=0.6]{ex1.eps}
\caption{Potential $u(x)$ in Example~\ref{ex:3a}.
\label{fig:3a}}
\end{figure}

\begin{ex}
\label{ex:3a}
Let $n=1$ and $\nu_1=2$ in the proof of Theorem~$\ref{thm:main1}$.
For simplicity we assume that $k_1=i$, $a_{kkk}(k_1),b_k(k_1)=0$ and
\begin{equation}
a_{kk}(k_1)=-\tfrac{1}{2},\quad
b(k_1)=1.
\label{eqn:ex3a}
\end{equation}
The system of linear equations about $N_1^0(x),N_1^1(x)$ becomes
\begin{align*}
&
N_1^0(x)e^{2x}
 =1-2iN_1^1(x)+N_1^0(x),\\
&
(N_1^1(x)-2ixN_1^0(x))e^{2x}
=N_1^1(x)+iN_1^0(x).
\end{align*}
Solving the above equation, we obtain
\begin{align*}
N_1^0(x)=\frac{e^{2x}-1}{e^{4x}-2(2x+1)e^{2x}-1},\quad
N_1^1(x)=\frac{i(2x e^{2x}+1)}{e^{4x}-2(2x+1)e^{2x}-1}.
\end{align*}
From \eqref{eqn:MN1} and \eqref{eqn:MN1d} we have
\begin{equation}
\psi(x;k) =N(x;k)e^{-ikx}
 =\biggl(1+\frac{4i[(2(k+i)x+i)e^{2x}+k]}{(k+i)^2(e^{4x}-2(2x+1)e^{2x}-1)}
\biggr)e^{ikx}.
\label{eqn:ex3apsi}
\end{equation}
Moreover, it follows from \eqref{eqn:u1} that
\begin{equation}
u(x)=-\frac{16e^{2x}(e^{2x}-1)((2x-1)e^{2x}+2x+3)}{(e^{4x}-2(2x+1)e^{2x}-1)^2}.
\label{eqn:ex3au}
\end{equation}
See Fig.~$\ref{fig:3a}$ for the shape of $u(x)$.
It has a pole of order two at $x=0.864558\ldots$.
The potential \eqref{eqn:ex3au} is of a negaton-type
 {\rm\cite{M02,MY04,Mat02,RSK96}}.

Let $k\in\Rset^\ast$.
We see that
\[
\psi(x;k)\sim\left(\frac{k-i}{k+i}\right)^2e^{ikx}
\]
as $x\to-\infty$.
Hence, it follows from \eqref{eqn:bc} that
\[
\phi(x;k)=\left(\frac{k-i}{k+i}\right)^2\psi(x;-k),
\]
which yields
\[
a(k)=\left(\frac{k-i}{k+i}\right)^2
\]
by \eqref{eqn:ab+}.
Thus, $a_k(i)=0$ and $a_{kk}(i)=-\tfrac{1}{2}$.
On the other hand, using \eqref{eqn:ex3apsi}, we see that $\psi(x;i)\sim e^x$
as $x\to-\infty$, and consequently $b(i)=1$.
These agree with our assumption \eqref{eqn:ex3a}.
\end{ex}

