\section{Proof of Theorem~\ref{thm:main2}}
In this section we give a proof of Theorem~\ref{thm:main2}.
Henceforth we assume that the hypotheses of Theorem~\ref{thm:main2} hold
 as well as $k\in\Rset^\ast$.

Letting $y=1/x$, we rewrite \eqref{eqn:ZS0} as
\begin{equation}
\frac{\d^2v}{\d y^2}+\frac{2}{y}\frac{\d v}{\d y}+\frac{k^2-\tilde{u}(y)}{y^4}v=0,
\label{eqn:v}
\end{equation}
where $\tilde{u}(y)=u(1/y)$.
Since $(k^2-\tilde{u}(y))/y^4$ has a pole of fourth order at $y=0$,
 we see by a standard result on higher-order scalar linear differential equations
 (see, e.g., Theorem~7 of \cite{B00}) that
 Eq.~\eqref{eqn:ZS0} has an irregular singularity at infinity $x=\infty$.
To obtain a necessary condition for its integrabilty,
 we compute its formal monodromy, exponential torus and Stokes matrices
 \cite{MS16,PS03,S09} around $y=0$ for \eqref{eqn:v}.
See these references for necessary information in the following computations.

Letting $\eta=(\d v/\d y)/v$ in \eqref{eqn:v}, we have a Riccati equation
\begin{equation}
\frac{\d\eta}{\d y}+\eta^2+\frac{2}{y}\eta+\frac{k^2-\tilde{u}(y)}{y^4}=0
\label{eqn:eta}
\end{equation}
To obtain a formal solution to \eqref{eqn:eta}, we write
\[
\eta=\sum_{j=0}^\infty \eta_jy^{j-2}.
\]
Substituting the above expression into \eqref{eqn:eta}, we have
\[
\eta_0^2+k^2=0,\quad
2\eta_0\eta_1=0,\quad
2\eta_0\eta_j+r_j(\eta_0,\ldots,\eta_{j-1})=0,\quad
j\ge 2,
\]
where $r_j(\eta_0,\ldots,\eta_{j-1})$ is a polynomial of $\eta_0,\ldots,\eta_{j-1}$ for $j\ge 2$.
Thus, we obtain formal solutions to \eqref{eqn:eta} as
\[
\eta(y)=\pm\frac{ik}{y^2}+\cdots
\]
and to \eqref{eqn:v} as
\begin{equation}
v(y)=\exp\left(\mp\frac{ik}{y}\right)v_\pm(y),
\label{eqn:solv}
\end{equation}
where $v_\pm(y)$ are formal power series in $y$,
 and the upper or lower signs are taken simultaneously.
Hence, we express have a formal fundamental matrix of \eqref{eqn:v} as
\begin{equation}
V(y)=\tilde{V}(y)e^{Q(y)},
\label{eqn:V}
\end{equation}
where $\tilde{V}(y)$ is a $2\times 2$ formal meromorphic invertible matrix of power series in $y$ and 
\begin{align*}
Q(y)=
\begin{pmatrix}
-ik/y & 0\\
0 & ik/y
\end{pmatrix}.
\end{align*}

\begin{figure}
\includegraphics[scale=0.6]{fig1.eps}
\caption{Singular directions $d_\pm$ and sectors $\Sigma_\pm$:
The boundaries of $\Sigma_+$ and $\Sigma_-$ are plotted as solid and dotted lines..
\label{fig:1}}
\end{figure}

Substitution of $re^{i\theta}$ into \eqref{eqn:V} yields
\[
V(re^{i\theta})=\tilde{V}(re^{i\theta})e^{Q(re^{i\theta})},
\]
so that the \emph{formal monodromy} becomes
\[
M=V(r)^{-1}V(re^{2\pi i})=\id
\]
by $V(re^{2\pi i})=V(r)M$.
The \emph{exponential torus} is given by
\[
\T=\mathrm{Gal}(\Cset(e^{\mp ik/y})/\Cset(y))
=\left\{
\begin{pmatrix}
c & 0\\
0 & c^{-1}
\end{pmatrix}
\bigg| c\in\Cset^\ast\right\}.
\]
Here $\mathrm{Gal}(\Lset/\Kset)$ denotes the differential Galois group,
 where $\Kset$ and $\Lset$ are differential fields
 such that $\Lset$ is a differential field extension of  $\Kset$.
The \emph{Stokes directions},
 on which $\Re(\mp ik/y)=0$, are given by $\arg y=0,\pi$.
We have $\Re(-ik/y)<0$ and  $\Re(ik/y)<0$ for $\arg y\in(0,\pi)$ and $(\pi,2\pi)$, respectively.
So the \emph{singular directions} $d_\mp$,
 which are bisectors of $(\tfrac{1}{2}\pi\mp\tfrac{1}{2}\pi,\tfrac{3}{2}\pi\mp\tfrac{1}{2}\pi)$,
 become $\arg y=\pi\mp\tfrac{1}{2}\pi$.
See Fig.~\ref{fig:1}.

Let $a(k)\neq 0$.
We take $\phi(1/y;k)$ and $\psi(1/y;-k)$ (resp. $\phi(1/y;-k)$ and $\psi(1/y;k)$)
 as solutions corresponding to the formal solution \eqref{eqn:solv}
 with the upper (resp. lower) sign,
 in the sectors $\Sigma_-$ and $\Sigma_+$ containing $\Re y<0$ and  $\Re y>0$, respectively,
 as well as the singular directions $d_\pm$.
Near the singular direction $d_-$, we have
\begin{equation}
\begin{pmatrix}
\phi(1/y;k) & \phi(1/y;-k)\\
\phi'(1/y;k) & \phi'(1/y;-k)
\end{pmatrix}
=\begin{pmatrix}
\psi(1/y;-k) & \psi(1/y;k)\\
\psi'(1/y;-k) & \psi'(1/y;k)
\end{pmatrix}
\begin{pmatrix}
a(k) & b(-k)\\
b(k) & a(-k)
\end{pmatrix}
\label{eqn:thm2}
\end{equation}
by \eqref{eqn:ab+} and \eqref{eqn:ab-},
 so that the associated Stokes matrix is given by
\[
S_-=
\begin{pmatrix}
a(k) & b(-k)\\
b(k) & a(-k)
\end{pmatrix}.
\]
Near the singular direction $d_+$,
 we use \eqref{eqn:2b} and \eqref{eqn:thm2} to obtain
\[
\begin{pmatrix}
\psi(1/y;-k) & \psi(1/y;k)\\
\psi'(1/y;-k) & \psi'(1/y;k)
\end{pmatrix}
=\begin{pmatrix}
\phi(1/y;-k) & \phi(1/y;k)\\
\phi'(1/y;-k) & \phi'(1/y;k)
\end{pmatrix}
\begin{pmatrix}
a(-k) & -b(-k)\\
-b(k) & a(k)
\end{pmatrix},
\]
so that the associated Stokes matrix is given by
\[
S_+=
\begin{pmatrix}
a(-k) & -b(-k)\\
-b(k) & a(k)
\end{pmatrix}=S_-^{-1}.
\]

Ramis' theorem \cite{L94,PS03,RM90}
 implies that the differential Galois group $G$ of \eqref{eqn:ZS0} contains
 the Zariski closure of a group generated by the formal monodromy $M=\id$,
 the exponential torus $\T$ and the Stokes matrices $S_\pm$.
In particular, $G$ is not finite,
 i.e., cases (i) and (ii) of Proposition~\ref{prop:2b} do not occur.
Moreover, case~(iv) of Proposition~\ref{prop:2b} does not occur
 since $a(k)\neq 0$.
Hence, if Eq.~\eqref{eqn:ZS0} is integrable in the sense of differential Galois theory,
 then we have $b(k)$ or $b(-k)=0$
 since either case~(iii) or (v) of Proposition~\ref{prop:2b} occurs.
So we have the following.

\begin{prop}
\label{prop:4a}
Let $k\in\Rset^\ast$ and assume that $a(k)\neq 0$.
If Eq.~\eqref{eqn:ZS0} is solvable by quadrature, then $b(k)$ or $b(-k)=0$.
\end{prop}

\begin{proof}[Proof of Theorem~$\ref{thm:main2}$]
Suppose that Eq.~\eqref{eqn:ZS0} is solvable by quadrature.
Since by Proposition~\ref{prop:2a}(iii) $a(k)=0$ only at discrete points,
 it follows from Proposition~\ref{prop:4a} that $b(k)$ or $b(-k)=0$ except at the discrete points.
Hence, by the identity theorem (e.g., Theorem~3.2.6 of \cite{AF03}),
  we have $b(k)=0$ for any $k\in\Rset^\ast$
  since by Proposition~\ref{prop:2a}(i) $b(k)$ is analytic
  in a neighborhood of $\Rset^\ast$ in $\Cset^\ast$.
Thus, we complete the proof.
\end{proof}

