\section{Proof of Theorem~\ref{thm:main3}}

In this section we give a proof of Theorem~\ref{thm:main3}.
The proof is mainly relied to the result of Kovacic \cite{K86}, which is briefly described in Appendix~A.

\begin{proof}[Proof of Theorem~$\ref{thm:main3}$]
Henceforth we assume that $m_2-m_1=1$.
Obviously, case (c) of Proposition~\ref{prop:K2} does not occur for $k\in\Rset^\ast$. 
So we only have to show that cases (a) and (b) of Proposition~\ref{prop:K1} do not occur
 for some $k\in\Rset^\ast$.
We rewrite \eqref{eqn:ZS0} in the form \eqref{eqn:req} with
\begin{equation}
r(x)=-k^2-u(x)
\label{eqn:sec5a}
\end{equation}
and expand $u(x)$ in the Laurent series at $x=\infty$ as
\[
u(x)=\frac{\bar{u}_1}{x}+\cdots,
\]
where $\bar{u}_1\neq 0$ is a constant.
Let $\S$ denote the set of poles of $u(x)$.

We assume that case (a) of Proposition~\ref{prop:K1} occurs
 as well as $k\in\Rset^\ast$.
Following the recipe of Appendix~A2,
 we have $d_c\in\Nset_0:=\Nset\cup\{0\}$ in \eqref{eqn:dc} and 
\[
\kappa_\infty^\pm=\pm\frac{i\bar{u}_1}{2k}
\]
since $\alpha=ik$ and $\beta=-\bar{u}_1$.
We easily see that $d_c\not\in\Nset_0$ when $k$ changes slightly
 even if $d_c\in\Nset_0$for some $k\in\Rset^\ast$ .
This implies that case~(a) of Proposition~\ref{prop:K1} does not occur
 in an open interval of $k\in\Rset^\ast$ since $\S$ is finite
 so that the number of a finite sequence $c$ of the symbols $\pm$ with $d_c\in\Nset_0$ is finite.

We next assume that case (b) of Proposition~\ref{prop:K1} occurs
 for an open interval of $k\in\Rset^\ast$.
Following the recipe of Appendix~A3,
 we have $d_e\in\Nset_0$ in \eqref{eqn:de}
 and there exists a monic polynomial $P(x)$ of order $d_e$ satisfying \eqref{eqn:P}.
Since
\[
\lim_{x\to\pm\infty}
(\theta''(x)+3\theta(x)\theta'(x)+\theta(x)^3+4(k^2+u(x))\theta(x)+2u'(x))=4k^2,
\]
we easily see that $d_e\neq 0$.
Let $d=d_e\ge 1$.
Since Eq.~\eqref{eqn:P} holds, we see that
\begin{equation}
\begin{split}
&
(\theta''(x)+3\theta(x)\theta'(x)+\theta(x)^3+4(k^2+u(x))\theta(x)+2u'(x)),\\
&
(\theta''(x)+3\theta(x)\theta'(x)+\theta(x)^3+4(k^2+u(x))\theta(x)+2u'(x))x\\
&\qquad
+(3\theta(x)^2+3\theta'(x)+4(k^2+u(x))),\\
&
(\theta''(x)+3\theta(x)\theta'(x)+\theta(x)^3+4(k^2+u(x))\theta(x)+2u'(x))x^2\\
&\quad
+2(3\theta(x)^2+3\theta'(x)+4(k^2+u(x)))x+6\theta(x),\\
&
(\theta''(x)+3\theta(x)\theta'(x)+\theta(x)^3+4(k^2+u(x))\theta(x)+2u'(x))x^j\\
&\quad
+j(3\theta(x)^2+3\theta'(x)+4(k^2+u(x)))x^{j-1}+3j(j-1)\theta(x)x^{j-2}\\
&\quad
+j(j-1)(j-2)x^{j-3},\quad
j=3,\ldots,d,
\end{split}
\label{eqn:prop2c1}
\end{equation}
are linearly dependent, on the interval of $k$,
 where the last equation is eliminated if $d=2$,
 and the last two equations are eliminated if $d=1$.
Hence,
\[
\theta(x),\quad
(\theta(x)x+j)x^{j-1},\quad
j=1,\ldots,d,
\]
are linearly dependent.
If $d=1$, then
\[
(\theta(x)x+1)+q_0\theta(x)
=\theta(x)(x+q_0)+1=0.
\]
If $d\ge 2$, then
\[
\theta(x),\quad
(\theta(x)x+j)x^{j-1},\quad
j=1,\ldots,d-1,
\]
are linearly independent, so that for certain constants $q_j$, $j=0,\ldots,d-1$,
\begin{align*}
&
(\theta(x)x+d)x^{d-1}+\sum_{j=1}^{d-1}q_j(\theta(x)x+j)x^{j-1}+q_0\theta(x)\\
&=\theta(x)\sum_{j=0}^d q_jx^j+\sum_{j=1}^d jq_jx^{j-1}=0,
\end{align*}
where $q_d=1$.
Thus, we have
\begin{equation}
\theta(x)=-\frac{q'(x)}{q(x)},\quad
q(x)=\sum_{j=0}^d q_jx^j,
\label{eqn:prop2c2}
\end{equation}
and
\begin{equation}
P(x)=\sum_{j=0}^dq_jx^j=q(x),
\label{eqn:prop2c3}
\end{equation}
since the functions given by \eqref{eqn:prop2c1}
 are linearly dependent on the interval of $k$.
Substituting \eqref{eqn:prop2c2} and \eqref{eqn:prop2c3} into \eqref{eqn:P},
 we obtain
 \[
q(x)u'(x)+4q'(x)u(x)=0,
 \]
which yields
\[
u(x)=Cq(x)^{-4},
\]
where $C\neq 0$ is a constant.
This means that $m_2-m_1=-4$ and yields a contradiction.
Thus we complete the proof.
\end{proof}

\begin{rmk}
In the above proof,
 an essential role was played
 by the fact that poles of $r(x)$ given by \eqref{eqn:sec5a} do not depend on $k$.
\end{rmk}

\begin{ex}
\label{ex:2b}
Consider the rational potential
\[
u(x)=-\frac{5}{16x^2}-\frac{5}{16(x-1)^2}-\frac{7}{8x}+\frac{5}{24(x-1)}
\]
and let $r(x)=-k^2-u(x)$.
Equation~\eqref{eqn:ZS0} satisfies $m_2-m_1=1$ 
 and only has singularities of order two at $x=0$ and $1$.
Following the recipe of Appendix~{\rm A.2}, we have $\beta=5/16$ and
\[
\kappa_s^\pm=\tfrac{1}{2}\pm\tfrac{3}{4}
\]
for $s=0,1$, and
\[
\kappa_\infty^\pm=\mp\frac{19i}{48k}
\]
since
\[
\bar{u}_1=\lim_{x\to\infty}xu(x)=-\tfrac{19}{24}.
\]
Hence, case {\rm(a)} of Proposition~{\rm\ref{prop:K1}} does not occur
 for any $k\in\Rset^\ast$.
Following the recipe of Appendix~{\rm A.3}, we have $\beta=5/16$ and
\[
E_s=\{-1,2,5\}
\]
for $s=0,1$.
We see that $d_e=1$ for $e_0,e_1=-1$ is only a non-negative integer, so that
\[
\theta(x)=-\frac{1}{2x}-\frac{1}{2(x-1)}.
\]
Substituting $P(x)=x+p_0$ into \eqref{eqn:P}, we obtain
\begin{align*}
&
\frac{1}{x^2(x-1)^3}
\bigl(-(k^2p_0+2k^2-\tfrac{4}{3})x^4+(2(5k^2+2)p_0+4k^2-1)x^3\\
&
-\tfrac{1}{3}(8(3k^2-5)p_0+2(3k^2+5))x^2
+\tfrac{1}{3}(2(3k^2+20)p_0+4)x+4p_0+1\bigr)=0.
\end{align*}
Hence, case~{\rm(b)} of Proposition~{\rm\ref{prop:K1}} holds with $p_0=-\tfrac{1}{4}$,
 so that Eq.~\eqref{eqn:ZS0} is solvable by quadrature,
 if and only if $k=\pm\tfrac{2}{3}\sqrt{3}$.

Let $k=\pm\tfrac{2}{3}\sqrt{3}$.
We have
\[
\hat{\theta}(x)=-\frac{1}{2x}-\frac{1}{2(x-1)}+\frac{4}{4x-1},
\]
so that the integrand in \eqref{eqn:solreq} satisfies
\[
\tfrac{1}{2}\left(-\hat{\theta}(x)
 \pm\sqrt{-4(k^2+u(x))-\hat{\theta}(x)^2-2\hat{\theta}'(x)}\right)
 \to \pm ik\left(1-\frac{19}{48k^2x}\right)+O(x^{-2})
\]
as $|x|\to\infty$ on $\Rset$.
This implies that Eq.~\eqref{eqn:ZS0} has two linearly independent solutions such that
\[
v(x)\to x^{-19i/48k}e^{ik x}\mbox{ and }x^{19i/48k}e^{-ikx}\quad\mbox{as $x\to\pm\infty$}.
\]
Thus, Eq.~\eqref{eqn:ZS0} does not have the Jost solutions satisfying \eqref{eqn:bc}
 even when it is solvable by quadrature.
\end{ex}

