\section{Kovacic's Result}

In this appendix we review necessary parts of Kovacic \cite{K86}
 on second-order linear differential equations on $\Cset(x)$.

\subsection{Fundamental results}
Consider second-order linear differential equations of the form
\begin{equation}
v_{xx}=r(x)v,
\label{eqn:req}
\end{equation}
where $r(x)\in\Cset(x)\setminus\Cset$.
Let $G$ be the differential Galois group of \eqref{eqn:req} over $\Cset(x)$.
We easily see that $G$ is an algebraic subgroup of $\SL(2,\Cset)$
 (see, e.g., Chapter~6 of \cite{K76}).
We have the following four cases for \eqref{eqn:req} (see \cite{CH11,K86} for a proof).

\begin{prop}[Kaplansky \cite{K76}, Kovacic\cite{K86}]
\label{prop:K1}
One of the following four cases occurs$\,:$
\begin{enumerate}
\setlength{\leftskip}{-1.8em}
\item[(a)]
$G$ is triangularizable$\,;$
% and Eq.~\eqref{eqn:req} has a solution of the form
%\begin{equation}
%v=\exp\left(\int\omega(x)\,\d x\right),
%\label{eqn:omega}
%\end{equation}
%where $\omega(x)\in\Cset(x);$
\item[(b)]
$G$ is conjugate to a subgroup of
\[
D^\dagger=\left\{
\begin{pmatrix}
c & 0\\
0 & c^{-1}
\end{pmatrix}
\bigg|
\,c\in\Cset^\ast\right\}\cup
\left\{
\begin{pmatrix}
0 & c\\
-c^{-1} & 0
\end{pmatrix}
\bigg|
\,c\in\Cset^\ast\right\},
\]
but it is not triangularizable$\,;$
%and
%Eq.~\eqref{eqn:req} has a solution of the form \eqref{eqn:omega},
% where $\omega(x)$ is algebraic over $\Cset(x)$ of degree two,
% and case {\rm(a)} does not hold
\item[(c)]
$G$ is finite, but neither triangulariable nor conjugate to $D^\dagger;$ 
%and 
% all solutions to \eqref{eqn:req} are algebraic over $\Cset(x)$
% and neither case~{\rm(a)} nor {\rm(b)} occurs
\item[(d)]
$G=\SL(2,\Cset)$.
\end{enumerate}
\end{prop}

%See \cite{K76} for the statements on $G$ in Proposition~\ref{prop:K1}.
If one of cases~(a)-(c) of Proposition~\ref{prop:K1} occurs,
 then the connected identity component $G^0$ of $G$ is solvable
 and Eq.~\eqref{eqn:req} is solvable.
On the other hand, if cases~(a)-(c) do not occur,
 then $G=G^0=\SL(2,\Cset)$, i.e.,
 Eq.~\eqref{eqn:req} is not integrable in the sence of  differential Galois theory.

Let $r(x)=r_1(x)/r_2(x)$, where $r_1(x),r_2(x)\in\Cset[z]$ are relatively prime.
Poles of $r(x)$ are zeros of $r_2(x)$
 and their orders are the multiplicities of the zeros of $r_2(x)$.
Let $\S\subset\Cset$ denote the set of all poles of $r(x)$.
By the \emph{order of $r(x)$ at $\infty$},
 we also mean the order of $\infty$ as a zero of $r(x)$, i.e., $\deg r_2(x)-\deg r_1(x)$.
We have the following necessary conditions for cases (a)-(c) in Proposition~\ref{prop:K1} to occur
 (see \cite{CH11,K86} for a proof).

\begin{prop}[Kovacic \cite{K86}]
\label{prop:K2}
The following conditions are necessary
 for the corresponding cases in Proposition~$\ref{prop:K1}$ to occur$\,:$
\begin{itemize}
\setlength{\leftskip}{-1.8em}
\item[(a)]
No pole of $r(x)$ is of odd order greater than one,
 and the order of $r(x)$ at $\infty$ is not an odd less than two$\,;$
\item[(b)]
There exists a pole of $r(x)$ such that its order is two or an odd greater than two$\,;$
\item[(c)]
No pole of $r(x)$ is of order greater than two
 and the order of $r(x)$ at $\infty$ is greater than one.
%Let
%\begin{equation}
%r(x)=\sum_i\frac{a_i}{(z-c_i)^2}+\sum_j\frac{b_j}{z-d_j}
%\label{eqn:r}
%\end{equation}
%be the fraction expansion of $r$, where $a_i,b_j\in\Cset$ and $c_i,d_j\in\S$,
% and let $\gamma=\sum_i a_i+\sum_j b_j d_j$.
%Then $\sqrt{1+4a_i},\sqrt{1+4\gamma}\in\Qset$ for each $i$, and $\sum_jb_j=0$.
\end{itemize}
\end{prop}

%In Proposition~\ref{prop:K2},
% the original statement of Theorem of Section 2.1 in \cite{K86} has been improved.
Note that cases~(a), (b) and (c) of Proposition~\ref{prop:K1} may not occur
 even though conditions~(a), (b) and (c) hold, respectively.
In particular, Proposition~\ref{prop:K2} only states fewer conditions for case~(c)
 than the original version in \cite{K86} since they are enough for our application
 in Section~5.
Kovacic \cite{K86} also gave an algorithm for finding a ``closed-form'' solution
 and detecting whether cases (a)-(c) in Proposition~\ref{prop:K1}
 really occur or not under conditions~(a), (b) and (c) of Proposition~\ref{prop:K1},
 respectively.
In the following
 we describe necessary parts of his algorithm for cases~(a) and (b)
 in the setting required in Section~5:
The order of $r(x)$ at $\infty$ is zero.
See \cite{CH11,K86} for the full version of his algorithm and its proof.

\subsection{Case (a)}
We assume that condition~(a) in Proposition~\ref{prop:K2} holds
 as well as the order of $r(x)$ at $\infty$ is zero.
When $g(x)$ has a pole of order $\ell\ge 2$ at $x=s$ and is expanded in a Laurent series
\[
g(x)=\sum_{j\ge-\ell}g_j(x-s)^j
\]
there, we write
\[
[g(x)]_s=\sum_{-\ell\le j\le -2}g_j(x-s)^j.
\]
Similarly, when $g(x)$ is of order $\ell$ at $\infty$ and is expanded in a Laurent series
\[
g(x)=\sum_{j\le\ell}g_jx^j
\]
there, we write
\[
[g(x)]_\infty=\sum_{0\le j\le\ell}g_jx^j.
\]
For $s\in\S\cup\{\infty\}$
 we define a rational function $\omega_s(x)$ and two constants $\kappa_s^\pm$ as follows:
\begin{enumerate}
\setlength{\leftskip}{-1.2em}
\setlength{\labelsep}{1em}
\item[($s_1$)]
If $s\in\S$ is of order $1$, then $\kappa_s^\pm=1$;
\item[($s_2$)]
If $s\in\S$ is of order $2$, then 
\[
\kappa_s^\pm=\tfrac{1}{2}\pm\tfrac{1}{2}\sqrt{1+4\beta},
\]
where $\beta$ is the coefficient of $1/(x-s)^2$ in the partial fraction expansion of $r(x);$
\item[($s_3$)]
If $s\in\S$ is of order $2\ell>2$, then
\[
\kappa_s^\pm=\tfrac{1}{2}\left(\pm\frac{\beta}{\alpha}+\ell\right),
\]
where $\alpha$ and $\beta$ are the coefficients of $(x-s)^{-\ell}$ and $(x-s)^{-(\ell+1)}$
 in the Laurent series expansions of $\sqrt{r(x)}$ and $r(x)-([\sqrt{r(x)}]_s)^2$, respectively;
\end{enumerate}
\begin{enumerate}
\setlength{\leftskip}{-0.7em}
\setlength{\labelsep}{1em}
\item[($\infty_1$)]
$\omega_\infty(x)=[\sqrt{r(x)}]_\infty$ and
\[
\kappa_\infty^\pm=\pm\frac{\beta}{2\alpha},
\]
where $\alpha$ and $\beta$ are the coefficients of $x^0$ and $x^{-1}$
 in the Laurent series expansions of $\sqrt{r(x)}$ and $r(x)$, respectively.
\end{enumerate}

For each sequence $c=\{c(s)\}_{s\in\S\cup\{\infty\}}$ with $c(s)=+$ or $-$, define
\begin{equation}
d_c=\kappa_\infty^{c(\infty)}-\sum_{s\in\S}\kappa_s^{c(s)}.
\label{eqn:dc}
\end{equation}
If $d_c$ is not a non-negative integer for any sequence $c$,
 then case~(a) of Proposition~\ref{prop:K1} does not occur.
We also have a further recipe to determine
 whether it occurs or not when $d_c$ is a non-negative integer,
 although it is not given here since it is not necessary for our purpose.
The reader who is interested in it should consult \cite{CH11,K86}.

\subsection{Case (b)}
We assume that condition~(b) in Proposition~\ref{prop:K2} holds
 as well as the order of $r(x)$ at $\infty$ is zero.
For $s\in\S\cup\{\infty\}$ we define a set $E_s\subset\Zset$ as follows:
\begin{enumerate}
\setlength{\leftskip}{-1.2em}
\setlength{\labelsep}{1em}
\item[($s_1$)]
If $s\in\S$ is of order $1$, then $E_s=\{4\}$;
\item[($s_2$)]
If $s\in\S$ is of order $2$, then
\[
E_s=\{2+l\sqrt{1+4\beta}\mid l=0,\pm 2\}\cap\Zset,
\]
where $\beta$ is the coefficient of $1/(x-s)^2$ in the partial fraction expansion of $r\,;$
\item[($s_3$)]
If $s\in\S$ is of order $j>2$, then $E_s=\{j\}$.
\end{enumerate}
%\begin{enumerate}
%\setlength{\leftskip}{-0.7em}
%\setlength{\labelsep}{1em}
%\item[($\infty_1$)]
%If $r$ is of order $j<2$ at $\infty$, then $E_\infty=\{j\}$.
%\end{enumerate}

For each tuple $e=\{e_s\in E_s\mid s\in\S\}$, let
\begin{equation}
d_e=-\tfrac{1}{2}\sum_{s\in\S}e_s.
\label{eqn:de}
\end{equation}
If $d_e$ is not a non-negative integer for any $e$, %for any sequence $e$,
 then case~(b) of Proposition~\ref{prop:K1} does not occur.

Let $E=\{e\mid d_e\in\Nset_0\}$ and let
\begin{equation}
\theta(x)=\tfrac{1}{2}\sum_{s\in\S}\frac{e_s}{x-s}
\label{eqn:theta1}
\end{equation}
for $e\in E$.
By \eqref{eqn:de} and \eqref{eqn:theta1} we see that
 the Laurent series of $\theta(x)$ at $\infty$ is given by
\[
\theta(x)=-\frac{d_e}{x}+\cdots.
\]
If there exists a monic polynomial $P(x)$ of degree $d_e$ satisfying
\begin{align}
&P'''+3\theta(x)P''+(3\theta(x)^2+3\theta'(x)-4r(x))P'\notag\\
&
+(\theta''(x)+3\theta(x)\theta'(x)+\theta(x)^3-4r(x)\theta(x)-2r'(x))P=0,
\label{eqn:P}
\end{align}
then case~(b) of Proposition~\ref{prop:K1} occurs and
\begin{equation}
v(x)=\exp\left(\int\tfrac{1}{2}\left(-\hat{\theta}(x)
  \pm\sqrt{4r(x)-\hat{\theta}(x)^2-2\hat{\theta}'(x)}\right)\d x\right)
\label{eqn:solreq}
\end{equation}
are solutions to \eqref{eqn:req},
 where $\hat{\theta}(x)=\theta(x)+P'(x)/P(x)$.
If such a polynomial is not found for any sequence $e$,
 then it does not occur.

