\stitle{Local graph algorithms.} Local graph algorithms for several related problems have been extensively studied. For instance, ~\cite{liu2020strongly,fountoulakis2019variational,fountoulakis2020p,fountoulakis2023flow} investigate local algorithms for conductance-based graph clustering, while ~\cite{lofgren2013personalized,lofgren16bidirection,bressan2018sublinear,wang2024revisiting,wei2024approximating} explore local algorithms for PageRank computation. Additionally, ~\cite{cohen2018approximating,jin2023moments} examine local algorithms for graph spectral density approximation, and ~\cite{andoni2018solving} study local algorithms to solve Laplacian systems. The problem setting of our work, which focuses on the local computation of ER for a single-pair vertices, shares similarities with these problems. However, the techniques developed for these related problems cannot be applied directly in our setting.

\stitle{Lower bounds for ER computation.} For the local computation of ER, in addition to our lower bound concerning the approximation parameter $\epsilon$, previous studies have also focused on establishing lower bounds related to the condition number $\kappa(\mathcal{L})$. \cite{andoni2018solving} proved that any local algorithm that $\epsilon$-approximates a coordinate of the Laplacian linear system requires at least $\Omega(\kappa(\mathcal{L})^2)$ queries, when setting $\epsilon=\Theta(1/\log n)$. However, since their problem setting differs from our local ER computation problem, their results cannot be directly generalized to our problem. In addition, ~\cite{cai2023effective} provides a lower bound for the single-pair ER approximation problem for non-expander graphs. They proved that there exists a non-expander graph $\mathcal{G}$ with minimum degree $\delta\geq 3$, and an adjacent vertex pair $(s,t)\in \mathcal{E}$, such that any local algorithm requires $\Omega (n)$ queries to $\epsilon$-approximates $r_\mathcal{G}(s,t)$ for any $\epsilon\leq 0.01$. It can be easily proved that the condition number of their construction is $\kappa(\mathcal{L})=\Theta(n)$, thus implies the $\Omega (\kappa(\mathcal{L}))$ lower bound for the $\epsilon$-approximation of $s,t$-ER value, for a given $\epsilon\leq 0.01$. However, it remains an open problem to study the relationship between $\epsilon$ and $\kappa(\mathcal{L})$ for local algorithms, so as to unify the different cases for expanders and non-expanders (since for expanders $\kappa(\mathcal{L})=\tilde{O}(1)$).

\stitle{Applications of ER computation.} Since ER approximation algorithms can be used as a crucial subroutine for other graph analysis algorithms, many related studies have focused on ER approximation and its applications. Among them, recent advancements in graph clustering and counting random spanning trees are closely related to our results. For instance, ~\cite{alev2017graph} proposed the ER-based graph clustering algorithm in $\tilde{O}(nm)$ time with non-trivial theoretical guarantees. 
~\cite{chu2020graph} design an $\tilde{O}(m+n^{1.875}/\delta^{1.75})$ time algorithm that computes a $(1+\delta)$-approximation of the number of spanning trees. This result was later improved by ~\cite{li2023new} to $\tilde{O}(m+n^{1.5}/\delta)$, achieving optimality for determinant sparsifier-based methods in the case of expander graphs. These works leverage the ER sketch algorithm as a key subroutine. Beyond these applications, ER computation has also been utilized in graph sparsification ~\cite{spielman2008graph} and robust routing in road networks ~\cite{sinop2023robust}, among others. The potential impact of our algorithms on enhancing the efficiency of these applications remains an open direction for future research.

\section{Preliminaries}\label{sec:preliminary}

%In this section, we define some basic notations used in this paper. 

\stitle{General matrix notations.} Given a matrix $\mathbf{X}\in \mathbb{R}^{n\times n}$, we use $\lambda(\mathbf{X})$ to denote its spectrum, $\lambda_i(\mathbf{X})$ represents the $i$-th eigenvalue of $\mathbf{X}$, $\mathbf{u}_i$ denotes the corresponding eigenvector. For a positive semi-definite (PSD) matrix $\mathbf{X}$, the condition number is defined as $\kappa(\mathbf{X})=\frac{\lambda_{max}(\mathbf{X})}{\lambda_{min}(\mathbf{X})}$, where $\lambda_{max}(\mathbf{X})$ is the maximum eigenvalue of $\mathbf{X}$, $\lambda_{min}(\mathbf{X})$ is the minimum non-zero eigenvalue of $\mathbf{X}$. Note that for singular matrix, this represents the finite condition number instead of the original definition $\kappa(\mathbf{X})=\infty$. Let $\mathbf{e}_s\in \mathbb{R}^n$ be the one-hot vector, which takes value $1$ at $s\in [n]$ and $0$ elsewhere.

\stitle{Graph notations.} Given an undirected, unweighted graph $\mathcal{G}=(\mathcal{V},\mathcal{E})$, we denote $\mathcal{V}$ as the vertex set and $\mathcal{E}$ as the edge set. Let $|\mathcal{V}|=n$ be the number of vertices and $|\mathcal{E}|=m$ be the number of edges of $\mathcal{G}$. For a node $u\in \mathcal{V}$, the set of neighbors is denoted as $\mathcal{N}(u)=\{v|(u,v)\in \mathcal{E}\}$, and the degree of node $u$ is denoted as $d_u=|\mathcal{N}(u)|$. Let $\mathbf{D}$ be the diagonal degree matrix, with diagonal entry $\mathbf{D}_{i,i}=d_i$ (the degree of node $i$). Denote by $\mathbf{A}$ the adjacency matrix with $\mathbf{A}_{i,j}=1$ if and only if $(i,j)\in \mathcal{E}$. Then, the Laplacian matrix is defined as $\mathbf{L}=\mathbf{D}-\mathbf{A}$. Let $\mathcal{A}=\mathbf{D}^{-1/2}\mathbf{A}\mathbf{D}^{-1/2}$ be the normalized adjacency matrix, $\mathbf{P}=\mathbf{AD}^{-1}$ be the probability transition matrix, and $\mathcal{L}=\mathbf{D}^{-1/2}\mathbf{L}\mathbf{D}^{-1/2}=\mathbf{I}-\mathcal{A}$ be the normalized Laplacian matrix. We denote $0=\lambda_1(\mathcal{L})< \lambda_2(\mathcal{L})\leq...\leq \lambda_n(\mathcal{L})\leq 2$ as the eigenvalues of $\mathcal{L}$, and $1=\lambda_1(\mathcal{A})> \lambda_2(\mathcal{A})\geq...\geq \lambda_n(\mathcal{A})\geq -1$ as the eigenvalues of $\mathcal{A}$. By definition, we have $\lambda_i(\mathcal{A})=1-\lambda_i(\mathcal{L})$ for each $i\in[n]$.
Following ~\cite{dwaraknath2024towards,cai2023effective}, we define the expander graphs based on conductance.

\begin{definition}{(Expander)}
    We define the conductance of a graph $\mathcal{G}$ as:
    $$\phi_\mathcal{G}=\min_{S\subset \mathcal{V}} {\frac{|\{(u,v)\in \mathcal{E}: u\in S,v\in \mathcal{V}-S \}|}{\min \{\sum_{u\in S}{d_u},\sum_{u\in \mathcal{V}-S}{d_u}\}}}.$$

    We refer to the graph $\mathcal{G}$ as a expander if $\phi_\mathcal{G}=\tilde{\Omega}(1)$.
\end{definition}


By the classical Cheeger's inequality (that is, $\lambda_2(\mathcal{L})/2\leq \phi_\mathcal{G}\leq \sqrt{2\lambda_2(\mathcal{L})}$, see e.g. ~\cite{spielman2019sagt} Chapter 21), we have $\phi_\mathcal{G}=\tilde{\Omega}(1)$ if and only if $\lambda_2(\mathcal{L})=\tilde{\Omega}(1)$, where $\lambda_2(\mathcal{L})$ is the second smallest eigenvalue of the normalized Laplacian $\mathcal{L}$ (also the smallest non-zero eigenvalue). Consequently, the definition of an expander graph can be equivalently characterized by $\lambda_2(\mathcal{L})=\tilde{\Omega}(1)$  or by the condition number $\kappa(\mathcal{L})=\tilde{O}(1)$.

\section{Basic representation}\label{sec:basic_repre}

Following ~\cite{peng2021local,li2023new,dwaraknath2024towards}, we start by interpreting the ER value through the Taylor expansion of the Laplacian pseudo-inverse (but our interpretation is simpler and slightly differs from the previous works ~\cite{peng2021local,li2023new,dwaraknath2024towards}). We begin by stating the following lemma, which expresses $r_\mathcal{G}(s,t)$ as the sum of infinite step of lazy random walks. 

\begin{lemma}[\downlink{proof_of_lemma:ER_taylor_expansion}]\label{lemma:ER_taylor_expansion}
 The following Equation holds
    \begin{align*}
r_\mathcal{G}(s,t)&=(\mathbf{e}_s-\mathbf{e}_t)^T\mathbf{L}^{\dagger}(\mathbf{e}_s-\mathbf{e}_t)\\
&=\frac{1}{2}(\mathbf{e}_s-\mathbf{e}_t)^T\mathbf{D}^{-1}\sum_{l=0}^{+\infty}{\left(\frac{1}{2}\mathbf{I}+\frac{1}{2}\mathbf{P}\right)^l}(\mathbf{e}_s-\mathbf{e}_t)
\end{align*}
with $\mathbf{P}=\mathbf{AD}^{-1}$ denotes the probability transition matrix.
\end{lemma}

By the Taylor expansion of $r_\mathcal{G}(s,t)$ from Lemma \ref{lemma:ER_taylor_expansion}, we define the $L$-step truncated ER value $r_{\mathcal{G},L}(s,t)$ as follows.

\begin{definition}\label{def:truncate_ER}
%The $L$ step truncate ER value $r_{\mathcal{G},L}(s,t)$ is defined as：
We define
%\begin{align*}
$$r_{\mathcal{G},L}(s,t)=\frac{1}{2}(\mathbf{e}_s-\mathbf{e}_t)^T\mathbf{D}^{-1}\sum_{l=0}^{L}{\left(\frac{1}{2}\mathbf{I}+\frac{1}{2}\mathbf{P}\right)^l}(\mathbf{e}_s-\mathbf{e}_t)$$
%\end{align*}
as the $L$ step truncation ER value.
\end{definition}

Next, we aim to ensure that $r_{\mathcal{G},L}(s,t)$ serves as an  $\epsilon$-approximation of $r_\mathcal{G}(s,t)$ by selecting a sufficiently large truncation step $L$. However, for expander graphs, we will prove that $L=\tilde{O}(1)$ is sufficient to achieve this approximation.

\begin{lemma}[\downlink{proof_of_lemma:ER_truncate}]\label{lem:ER_truncate}
   $r_{\mathcal{G},L}(s,t)$ is the $\epsilon$-approximation of $r_\mathcal{G}(s,t)$ when setting $L\geq 2\kappa(\mathcal{L}) \log \frac{n}{\epsilon}$.
\end{lemma}

By Lemma~\ref{lem:ER_truncate}, the truncation step is only required to be $L=\tilde{O}(1)$, since $\kappa(\mathcal{L})=\tilde{O}(1)$ for expander graphs. Inspired by Lemma \ref{lem:ER_truncate}, we define the following vector.

\begin{definition}\label{def:p_L}
$\mathbf{p}_{L,u}=\frac{1}{2}\sum_{l=0}^{L}{\left(\frac{1}{2}\mathbf{I}+\frac{1}{2}\mathbf{P}\right)^l}\mathbf{e}_u$ for any given $u\in \mathcal{V}$. 
\end{definition}

From Definition \ref{def:truncate_ER} and Definition \ref{def:p_L}, we have the following representation of $r_\mathcal{G}(s,t)$:
\begin{equation}\label{equ:ER_p_expression}
\begin{aligned}
    r_{\mathcal{G},L}(s,t)&=\frac{1}{2}(\mathbf{e}_s-\mathbf{e}_t)^T\mathbf{D}^{-1}\sum_{l=0}^{L}{\left(\frac{1}{2}\mathbf{I}+\frac{1}{2}\mathbf{P}\right)^l}(\mathbf{e}_s-\mathbf{e}_t)\\
    &=\mathbf{e}_s^T\mathbf{D}^{-1}\mathbf{p}_{L,s}-\mathbf{e}_t^T\mathbf{D}^{-1}\mathbf{p}_{L,s}-\mathbf{e}_s^T\mathbf{D}^{-1}\mathbf{p}_{L,t}+\mathbf{e}_t^T\mathbf{D}^{-1}\mathbf{p}_{L,t}\\
    &=\frac{\mathbf{p}_{L,s}(s)}{d_s}-\frac{\mathbf{p}_{L,s}(t)}{d_t}-\frac{\mathbf{p}_{L,t}(s)}{d_s}+\frac{\mathbf{p}_{L,t}(t)}{d_t}.
\end{aligned}
\end{equation}

Below, we give some basic properties of $\mathbf{p}_{L,u}$ and $r_\mathcal{G}(s,t)$ which will be frequently used in our analysis later.

\begin{fact}[\downlink{proof_of_fact:p_L_norm_1}]\label{fact:p_L_norm_1}
    $\Vert \mathbf{p}_{L,u} \Vert_1\leq \frac{L}{2}$ for any $u\in \mathcal{V}$.
\end{fact}

\begin{fact}[\downlink{proof_of_fact:p_L_transform}]\label{fact:p_L_transform}
    $\frac{\mathbf{p}_{L,u}(v)}{d_v}=\frac{\mathbf{p}_{L,v}(u)}{d_u}$ for any $u,v\in \mathcal{V}$.
\end{fact}

%Finally, we provide a simple lower bound on $r_\mathcal{G}(s,t)$.
\begin{fact}[\downlink{proof_of_fact:ER_lower_bound}]\label{fact:ER_lower_bound}
    $r_\mathcal{G}(s,t)\geq \frac{1}{2}\left(\frac{1}{d_s}+\frac{1}{d_t}\right)$.
\end{fact}

\section{Online ER Computation Algorithms}

In this section, we present our online-computation algorithm for single-pair ER computation and prove Theorem \ref{thm:bidir_complexity}. By combining Eq.~(\ref{equ:ER_p_expression}) with Lemma \ref{lem:ER_truncate}, we only need to find the approximation $\hat{\mathbf{p}}_{L,u}(v)$ for each $u,v\in\{s,t\}$ to approximate the ER value $r_\mathcal{G}(s,t)$. The approximation is given by $\hat{r}_\mathcal{G}(s,t)=\frac{\hat{\mathbf{p}}_{L,s}(s)}{d_s}-\frac{\hat{\mathbf{p}}_{L,s}(t)}{d_t}-\frac{\hat{\mathbf{p}}_{L,t}(s)}{d_s}+\frac{\hat{\mathbf{p}}_{L,t}(t)}{d_t}$. Formally, we prove the following Theorem.

\begin{theorem}[\downlink{proof_of_theorem:bidir_guarantee_specific}]\label{thm:bidir_guarantee_specific}
    There exists an Algorithm (i.e. our Algorithm \ref{algo:bidir_single_pair}) outputs the approximation $\hat{\mathbf{p}}_{L,u}(v)$ of $\mathbf{p}_{L,u}(v)$ such that $|\mathbf{p}_{L,u}(v)-\hat{\mathbf{p}}_{L,u}(v)|/d_v\leq \frac{\epsilon}{d}$ for each $u,v\in\{s,t\}$ w.h.p., where $d=\min\{d_s,d_t\}$. Furthermore, the time complexity of this Algorithm can be bounded by $\tilde{O}(\frac{\sqrt{d}}{\epsilon})$.
\end{theorem}

