Next, we describe our algorithm to find the approximation $\hat{\mathbf{p}}_{L,u}(v)$ of $\mathbf{p}_{L,u}(v)$. The pseudo-code is outlined in Algorithm \ref{algo:bidir_single_pair}. Algorithm \ref{algo:bidir_single_pair} consists of two stages:

\begin{itemize}
\item Stage I: we perform a deterministic search, called \push, to obtain a coarse approximation of the vector $\mathbf{p}_{L,u}$, denote as $\mathbf{q}_{L,u}$. We output the residuals $\mathbf{r}_{i,u}$ for every $i\in[L]$.

\item Stage II: we perform random walks to obtain the precise approximation of $\mathbf{p}_{L,s}(s)$ (resp., $\mathbf{p}_{L,s}(t),\mathbf{p}_{L,t}(s),\mathbf{p}_{L,t}(t)$), denote as $\hat{\mathbf{p}}_{L,s}(s)$ (resp., $\hat{\mathbf{p}}_{L,s}(t),\hat{\mathbf{p}}_{L,t}(s),\hat{\mathbf{p}}_{L,t}(t)$). Thus we obtain the $\epsilon$-approximation of $r_\mathcal{G}(s,t)$.
\end{itemize}

As we discussed in Section \ref{sec:intro}, the high-level idea of our Algorithm is to use the deterministic search to reduce the variance produced by random walks, see Fig. \ref{fig:our_algo} (a) as an illustration. More precisely, for Stage I we use a variant of the classical coordinate gradient descent algorithm to approximate $\mathbf{p}_{L,u}$. We denote $\mathbf{x}_{l,u}=\frac{1}{2}(\frac{1}{2}\mathbf{I}+\frac{1}{2}\mathbf{P})^l\mathbf{e}_u$, therefore $\mathbf{p}_{L,u}=\frac{1}{2}\sum_{l=0}^{L}{\left(\frac{1}{2}\mathbf{I}+\frac{1}{2}\mathbf{P}\right)^l}\mathbf{e}_u=\sum_{l=0}^{L}{\mathbf{x}_{l,u}}$. Notice that $\mathbf{x}_{l+1,u}=(\frac{1}{2}\mathbf{I}+\frac{1}{2}\mathbf{P})\mathbf{x}_{l,u}$ for each $l< L$, so computing $\mathbf{p}_{L,u}$ is equivalent to solving the following linear system:
\begin{align*} \small
  \begin{bmatrix}
       \begin{array}{ccccc}
        \mathbf{I} &  & &  & \\
        -\frac{1}{2}\mathbf{I}-\frac{1}{2}\mathbf{P} &  \mathbf{I}  &  & & \\
         & \ddots  &  \ddots & & \\
         & & &\mathbf{I}  &\\
         & & & -\frac{1}{2}\mathbf{I}-\frac{1}{2}\mathbf{P} &   \mathbf{I} 
        \end{array}
        \end{bmatrix} 
\begin{bmatrix}
    \begin{array}{c}
         \mathbf{x}_{0,u}  \\
         \mathbf{x}_{1,u} \\
         \mathbf{x}_{2,u} \\
         \vdots \\
         \mathbf{x}_{L,u}
    \end{array}
\end{bmatrix}
=
\begin{bmatrix}
    \begin{array}{c}
         \frac{1}{2}\mathbf{e}_u \\
         0 \\
         0 \\
         \vdots \\
         0
    \end{array}
\end{bmatrix}
\end{align*}

For this linear system, we compute the approximation $\hat{\mathbf{x}}_{l,u}$ for each $l\in [L]$ and thus obtain the approximation $\mathbf{q}_{L,u}=\sum_{l=0}^{L}{\hat{\mathbf{x}}_{l,u}}$. For a given source node $u$, the Coordinate Gradient Descent (\push) Algorithm outputs the approximation $\mathbf{q}_{L,u}$ and residuals $\mathbf{r}_{i,u}$ for every $i\in[L]$ (without explicitly outputs each approximation $\hat{\mathbf{x}}_{l,u}$). Initially, we define the residual vector $\mathbf{r}_{i,u}=0$ for $i\in [1,...,L]$ and $\mathbf{r}_{0,u}=\frac{1}{2}\mathbf{e}_u$ and the approximation $\mathbf{q}_{L,u}=0$. Next, for each $i\in [0,...,L]$, for each $w\in \mathcal{V}$ with $\mathbf{r}_{i,u}(w)>\frac{r_{max}}{L^2}d_w$, we perform the following three steps (Line 4-11 of Algorithm \ref{algo:push}): (i) add the score $\mathbf{q}_{L,u}(w)$ by $\mathbf{r}_{i,u}(w)$; (ii) uniformly distribute $\frac{1}{2}\mathbf{r}_{i,u}(w)$ to the neighbor of $w$, namely $\mathbf{r}_{i+1,u}(v)\leftarrow \mathbf{r}_{i+1,u}(v)+\frac{1}{2d_w}\mathbf{r}_{i,u} (w)$ for $v\in \mathcal{N}(w)$ and $\mathbf{r}_{i+1,u}(w)\leftarrow \mathbf{r}_{i+1,u}(w)+\frac{1}{2}\mathbf{r}_{i,u}(w)$; (iii) set $\mathbf{r}_{i,u}(w)$ to $0$. When the iteration stops, Algorithm \ref{algo:push} outputs $\mathbf{q}_{L,u}$ as the coarse approximation of $\mathbf{p}_{L,u}$, and $L$ residual vectors $\mathbf{r}_{i,u}$ for each $i\in [L]$. For Stage II, we sample $n_r$ lazy random walks from the source node $s$, each random walk has length $L$ to refine the approximation (Line 6 of Algorithm \ref{algo:bidir_single_pair}). Specifically, a lazy random walk of length $L$ from $s$ denotes a sequence $(v_0=s,v_1,...,v_L)$ such that for every $1\leq k\leq L$, $v_{k}$ is a random neighbor of $v_{k-1}$ with probability $\frac{1}{2}$, and $v_{k+1}=v_k$ with probability $\frac{1}{2}$. For each step $k\leq L$ when the lazy random walk arrives at a node $w=v_k$, we update $\hat{\mathbf{p}}_{L,t}(s)\leftarrow \hat{\mathbf{p}}_{L,t}(s)+\sum_{i=0}^{L-k}{\frac{\mathbf{r}_{i,t}(w)}{d_w}}$ and $\hat{\mathbf{p}}_{L,s}(s)\leftarrow \hat{\mathbf{p}}_{L,s}(s)+\sum_{i=0}^{L-k}{\frac{\mathbf{r}_{i,s}(w)}{d_w}}$. We perform  similar steps for the sink node $t$ (Line 7 of Algorithm \ref{algo:bidir_single_pair}).

\begin{algorithm}[t!]
%\caption{70\% of the column width!}
\small
	\SetAlgoLined
    \renewcommand{\algorithmicrequire}{\textbf{Input:}}
	\renewcommand{\algorithmicensure}{\textbf{Output:}}
    \caption{Our algorithm for single pair ER estimation}\label{algo:bidir_single_pair}
    \begin{algorithmic}[1]
	\REQUIRE $\mathcal{G},s,t, L,\epsilon$
    %\STATE $//$ Stage I: deterministic search\;
    \STATE $d\leftarrow \min\{d_s,d_t\}$; $r_{max}\leftarrow \epsilon/\sqrt{d}$\; \hfill $\triangleright$ Stage I: deterministic search
	\STATE $\mathbf{q}_{L,s},\mathbf{r}_{i,s}$ for $i\in[L]\leftarrow$ \push ($\mathcal{G},s, L,r_{max}$) 
    \STATE $\mathbf{q}_{L,t},\mathbf{r}_{i,t}$ for $i\in[L]\leftarrow$ \push ($\mathcal{G},t, L,r_{max}$) 
   % $\hat{\mathbf{p}}_{L,u}(v)\leftarrow \mathbf{q}_{L,u}(v)$ for $u,v\in \{s,t\}$\;
    %\STATE $//$ Stage II: random walk sampling\;
    \STATE $n_r\leftarrow \frac{4L^2}{\epsilon^2}r_{max} d \log n$\; \hfill $\triangleright$ Stage II: random walk sampling
    \FOR{$j$ from $1$ to $n_r$}
    \STATE Perform lazy random walk of length $L$ start from $s$. For each step $k$ with $k\leq L$ it arrive at a node $w$, we update $\hat{\mathbf{p}}_{L,t}(s)\leftarrow \hat{\mathbf{p}}_{L,t}(s)+\frac{d_s}{n_r}\sum_{i=0}^{L-k}{\frac{\mathbf{r}_{i,t}(w)}{d_w}}$ and $\hat{\mathbf{p}}_{L,s}(s)\leftarrow \hat{\mathbf{p}}_{L,s}(s)+\frac{d_s}{n_r}\sum_{i=0}^{L-k}{\frac{\mathbf{r}_{i,s}(w)}{d_w}}$\;
    \STATE Perform lazy random walk of length $L$ start from $t$. For each step $k$ with $k\leq L$ it arrive at a node $w$, we update $\hat{\mathbf{p}}_{L,s}(t)\leftarrow \hat{\mathbf{p}}_{L,s}(t)+\frac{d_t}{n_r}\sum_{i=0}^{L-k}{\frac{\mathbf{r}_{i,s}(w)}{d_w}}$ and $\hat{\mathbf{p}}_{L,t}(t)\leftarrow \hat{\mathbf{p}}_{L,t}(t)+\frac{d_t}{n_r}\sum_{i=0}^{L-k}{\frac{\mathbf{r}_{i,t}(w)}{d_w}}$\;
    \ENDFOR
    \ENSURE $\hat{r}_\mathcal{G}(s,t)=\frac{\hat{\mathbf{p}}_{L,s}(s)}{d_s}-\frac{\hat{\mathbf{p}}_{L,s}(t)}{d_t}-\frac{\hat{\mathbf{p}}_{L,t}(s)}{d_s}+\frac{\hat{\mathbf{p}}_{L,t}(t)}{d_t}$ as the approximation of $r_\mathcal{G}(s,t)$
    \end{algorithmic}
\end{algorithm}

\begin{algorithm}[t!]
%\caption{70\% of the column width!}
\small
	\SetAlgoLined
    \caption{Coordinate Gradient Descent (\push)}\label{algo:push}
    \renewcommand{\algorithmicrequire}{\textbf{Input:}}
	\renewcommand{\algorithmicensure}{\textbf{Output:}}
    \begin{algorithmic}[1]
	\REQUIRE $\mathcal{G},u, L,r_{max}$
   \STATE The approximation $\mathbf{q}_{L,u}(w)=0$ for each $w\in \mathcal{V}$\;
    \STATE $\mathbf{r}_{i,u}(w)=0$ for each $w\in \mathcal{V}$, $i\in [L+1]$, and $\mathbf{r}_{0,u}=\frac{1}{2}\mathbf{e}_s$\;
	\FOR{$i=0,1,2,...,L$}
        \WHILE{$\exists w\in \mathcal{V}$ such that $\mathbf{r}_{i,u}(w)>\frac{r_{max}}{L^2}d_w$}
            \STATE $\mathbf{q}_{L,u}(w)\leftarrow \mathbf{q}_{L,u}(w)+\mathbf{r}_{i,u}(w)$\;
            \FOR {$v\in \mathcal{N}(w)$}
               \STATE $\mathbf{r}_{i+1,u}(v)\leftarrow \mathbf{r}_{i+1,u}(v)+\frac{1}{2d_w}\mathbf{r}_{i,u} (w)$\;
            \ENDFOR
             \STATE $\mathbf{r}_{i+1,u}(w)\leftarrow \mathbf{r}_{i+1,u}(w)+\frac{1}{2}\mathbf{r}_{i,u}(w)$\;
            \STATE $\mathbf{r}_{i,u}(w)\leftarrow 0$\;
        \ENDWHILE
    \ENDFOR
    \ENSURE $\mathbf{q}_{L,u}$ as the coarse approximation of $\mathbf{p}_{L,u}$, residuals $\mathbf{r}_{i,u}$ for each $i\in [L]$
	\end{algorithmic}
\end{algorithm}


