    \centering
    \subfigure[graph $\mathcal{G}_1$]{
    \includegraphics[scale=0.3]{illustrative_figure/lower_bound_G1.pdf} \vspace{-0.3cm}
    }
    \subfigure[graph $\mathcal{G}_2$]{
    \includegraphics[scale=0.3]{illustrative_figure/lower_bound_G2.pdf} \vspace{-0.3cm}
    }
    \subfigure[parallel resistor illustration]{
    \includegraphics[scale=0.25]{illustrative_figure/parallel_resistors.pdf}
    }
    \caption{illustration of the construction of our lower bound}\vspace{-0.5cm}
    \label{fig:lower_bound}
\end{figure}



\begin{theorem}
\label{thm:lower_bound_specific}
    $|r_{\mathcal{G}_1}(s,t)-r_{\mathcal{G}_2}(s,t)|> \frac{\epsilon}{4} r_{\mathcal{G}_1}(s,t)$, but any randomized local algorithm requires $\Omega(\frac{1}{\epsilon})$ time to distinguish $\mathcal{G}_1$ and $\mathcal{G}_2$ with probability $\geq 2/3$.
\end{theorem}

First, to get intuitions for why $|r_{\mathcal{G}_1}(s,t)-r_{\mathcal{G}_2}(s,t)|> \frac{\epsilon}{4} r_{\mathcal{G}_1}(s,t)$, we use the representation of parallel resistors, see Fig. \ref{fig:lower_bound} (c) as an illustration. By our construction, we connect $x$ neighbors of $s$ to $S_1$ and connect $(d_s-x)$ neighbors of $s$ to $S_2$. Then, we connect the two parts of the resistor $S_1,S_2$ in parallel. For $\mathcal{G}_1$ all the neighbors of $s$ is in $S_1$; for $\mathcal{G}_2$ we choose $x=(1-\epsilon)d_s$, thereby there are $(1-\epsilon)$ fraction of the neighbors of $s$ in $S_1$ and $\epsilon$ fraction of the neighbors in $S_2$. We prove the $s,t$ resistance from $S_1$ is $\frac{1}{x}+o(\frac{1}{x})$; while the $s,t$ resistance from $S_2$ is $\frac{2}{d_s-x}$. As a result, the ER value $r_{\mathcal{G}_1}(s,t)$ and $r_{\mathcal{G}_2}(s,t)$ will differ by $\frac{\epsilon}{4}$ in terms of relative error. To reach this end, we first prove the following Lemma.

%\begin{figure}
    %\centering
    %\includegraphics[scale=0.45]{illustrative_figure/parallel_resistors.png} \vspace{-0.3cm}
    %\caption{illustration of the parallel resistors}\vspace{-0.5cm}
    %\label{fig:parallel}
%\end{figure}

\begin{lemma}[\downlink{proof_of_lemma:parallel_resistance}]\label{lem:parallel_resistance}
    $r_{S_1}(s,t)=\frac{1}{x}+O(\frac{1}{dx}\log n_1 )=\frac{1}{x}+O(\frac{1}{d_s x} )$, and $r_{S_2}(s,t)=\frac{2}{d_s-x}$. Where $r_{S_1}(s,t)$ denotes the $s,t$ resistance only consider the edges between $S_1\cup \{s,t\}$ and $r_{S_2}(s,t)$ denotes the $s,t$ resistance only consider the edges between $S_2\cup \{s,t\}$.
\end{lemma}



Armed with Lemma \ref{lem:parallel_resistance} and the parallel resistance formula, we prove that $r_{\mathcal{G}_1}(s,t)$ and $r_{\mathcal{G}_2}(s,t)$ differs by $\frac{\epsilon}{4}$ in terms of relative error.

\begin{lemma}[\downlink{proof_of_lemma:G1G2_differ}]\label{lem:G1G2_differ}
    $|r_{\mathcal{G}_1}(s,t)-r_{\mathcal{G}_2}(s,t)|> \frac{\epsilon}{4} r_{\mathcal{G}_1}(s,t).$
\end{lemma}

Finally, we prove that any local algorithms to distinguish $\mathcal{G}_1$ and $\mathcal{G}_2$ requires at least $\Omega(\frac{1}{\epsilon})$ queries. 

\begin{lemma}[\downlink{proof_of_lemma:G1G2_distinguish}]\label{lem:G1G2_distinguish}
    Any local algorithm that distinguish $\mathcal{G}_1$ and $\mathcal{G}_2$ with probability $\geq 2/3$ requires at least $\Omega(\frac{1}{\epsilon})$ queries.
\end{lemma}

Combining Lemma \ref{lem:G1G2_differ} and Lemma \ref{lem:G1G2_distinguish}, we immediately prove Theorem \ref{thm:lower_bound_specific}, which implies Theorem \ref{thm:lower_bound}.
%\end{proof}

\section{Index-based Algorithms for ER Computation}

In this section, we present a more efficient index-based ER computation algorithm and prove Theorem \ref{thm:ER_sketch}. Note that by Theorem \ref{thm:bidir_complexity}, if we directly use Algorithm \ref{algo:bidir_single_pair} to compute the all pair ER values, the time complexity is bounded by:
\begin{align*} \small
    \tilde{O}\left(\sum_{u\in \mathcal{V}}{\sum_{v\in \mathcal{V},d_v\leq d_u}{\frac{\sqrt{d_v}}{\epsilon}}}\right)
    &\leq \tilde{O}\left(\sum_{u\in \mathcal{V}}{\sum_{v\in \mathcal{V}}{\frac{\sqrt{d_v}}{\epsilon}}}\right)\\
   (Cauchy-Schwarz) &\leq \tilde{O}\left(\frac{1}{\epsilon}\sum_{u\in \mathcal{V}}{\left(\left(\sum_{v\in \mathcal{V}}{1^2}\right)^{1/2}\left(\sum_{v\in \mathcal{V}}{(\sqrt{d_v})^2}\right)^{1/2}\right)}\right)\\
    &=\tilde{O}\left(\frac{1}{\epsilon}\sum_{u\in \mathcal{V}}{\sqrt{nm}}\right)=\tilde{O}\left(\frac{1}{\epsilon}n\sqrt{nm}\right).
\end{align*}

In this section, we will prove that $\tilde{O}(\sqrt{nm}/{\epsilon})$ processing time is enough for the ER sketch algorithms. Recall that by Eq. (\ref{equ:ER_p_expression}), given any vertex pair $(s,t)$, one can approximate $r_\mathcal{G}(s,t)$ by the linear combination of $\mathbf{p}_{L,s}(s),\mathbf{p}_{L,s}(t),\mathbf{p}_{L,t}(s)$ and $\mathbf{p}_{L,t}(t)$. Therefore, if one can approximates these $n$ vectors $\mathbf{p}_{L,u}$ for all $u\in \mathcal{V}$, one can approximate $r_\mathcal{G}(s,t)$ for any given vertex pair $(s,t)$. We prove the following Theorem.

\begin{theorem}[\downlink{proof_of_theorem:ER_sketch_specific}]\label{thm:ER_sketch_specific}
There exists an algorithm (i.e. Algorithm \ref{algo:bidir_sketch}) that outputs the approximation $\hat{\mathbf{p}}_{L,u}$ for every $u\in \mathcal{V}$, such that $|\hat{\mathbf{p}}_{L,u}(v)-\mathbf{p}_{L,u}(v)|\leq \epsilon$ for every $ v$ with $d_v\leq d_u$. In addition, the time complexity of this algorithm is $\tilde{O}(\sqrt{nm}/{\epsilon})$, the space complexity is $\tilde{O}(n/{\epsilon})$.
\end{theorem}

The key observation here is that we can approximate the vector $\mathbf{p}_{L,u}$ within almost the same time as just approximate $\mathbf{p}_{L,u}(v)$ for a vertex $v$. The pseudo-code of our ER sketch algorithm is outlined in Algorithm \ref{algo:bidir_sketch}. To compute the approximation vector $\hat{\mathbf{p}}_{L,u}$, Algorithm \ref{algo:bidir_sketch} consists of three stages, see Fig. \ref{fig:our_algo} (b) as an illustration.

\begin{itemize}
\item Stage I: perform $n_r^{(1)}$ random walks to find a candidate set, denote as $S'_{\epsilon,u}=\{w\in \mathcal{V}:\mathbf{p}'_{L,u}(w)\geq \epsilon/2\}$;

\item Stage II: perform \push operations from each $v\in S'_{\epsilon,u}$;

\item Stage III: perform random walks start from $u$ to derive the final approximation $\hat{\mathbf{p}}_{L,u}$.
\end{itemize}

Specifically, our algorithm is implemented as follows. First, we perform a traversal for all $u\in \mathcal{V}$. For each $u$, we compute the approximation $\hat{\mathbf{p}}_{L,u}$. For Stage I, we perform $n_r^{(1)}$ random walks from the source node $u$ to compute a very coarse approximation $\mathbf{p}'_{L,u}$ (Lines 2-4 in Algorithm \ref{algo:bidir_sketch}). We define the candidate set $S'_{\epsilon,u}=\{w\in \mathcal{V}:\mathbf{p}'_{L,u}(w)> \epsilon/2\}$ and next we focus on the approximation on the candidate set $S'_{\epsilon,u}$ (the size of the candidate set $S'_{\epsilon,u}$ is only $\tilde{O}(\frac{1}{\epsilon})$, independent of $n$). For Stage II, we perform \push operations from each $v\in S'_{\epsilon,u}$ with the threshold $\frac{r_{max}}{2 \mathbf{p}'_{L,u}(v)}$ (Lines 5-8 in Algorithm \ref{algo:bidir_sketch}). For Stage III, we perform $n_r^{(3)}$ random walks from the source node $u$ (Lines 9-10 in Algorithm \ref{algo:bidir_sketch}). The key mechanism here is that the random walks can share the computation of \push for different $\mathbf{p}_{L,u}(v_1)$ and $\mathbf{p}_{L,u}(v_2)$ with $v_1\neq v_2$. Therefore, to approximate the vector $\mathbf{p}_{L,u}$ we only need to perform random walks from the source node $u$ without the traversal for $w\in \mathcal{V}$. Finally, we update the result and get the final approximation $\hat{\mathbf{p}}_{L,u}(v)$ for every $v\in S'_{\epsilon,u}$ with $d_v\leq d_u$ (Lines 11-13 in Algorithm \ref{algo:bidir_sketch}). For this step, the operation time is at most the same as Stage II, this enables the local computation of the vector $\mathbf{p}_{L,u}$.


\begin{algorithm}[t!]
%\caption{70\% of the column width!}
\small
\SetAlgoLined
    \renewcommand{\algorithmicrequire}{\textbf{Input:}}
	\renewcommand{\algorithmicensure}{\textbf{Output:}}
    	\caption{Our algorithm for building the index}\label{algo:bidir_sketch}
    \begin{algorithmic}[1]
	\REQUIRE $\mathcal{G},s,t, L,\epsilon$
    \FOR{$u\in \mathcal{V}$}
   \STATE $n_r^{(1)}\leftarrow \frac{ L^2\log n}{\epsilon}$, $\mathbf{p}'_{L,u}\leftarrow 0$  \hfill $\triangleright$ Stage I: find the $\epsilon$-contributing set\;
   \STATE Perform $n_r^{(1)}$ lazy random walks of length $L$ start from $u$. For each lazy random walk, for each step $k$ with $k\leq L$ it arrive at a node $w$, we update $\mathbf{p}'_{L,u}(w)\leftarrow \mathbf{p}'_{L,u}(w)+\frac{1}{2n_r^{(1)}}$\;
    \STATE Define $S'_{\epsilon,u}=\{w\in \mathcal{V}:\mathbf{p}'_{L,u}(w)> \epsilon/2\}$ as the candidate set\;
   \STATE $r_{max}\leftarrow L\epsilon\sqrt{\frac{n}{m}}$ \hfill $\triangleright$ Stage II: \push from candidate set $S_{\epsilon,u}'$\;
    \FOR{$v\in S'_{\epsilon,u}$}
	  \STATE $\mathbf{q}_{L,v},\mathbf{r}_{i,v}$ for $i\in[L]\leftarrow$ \push ($\mathcal{G},w, L,\frac{r_{max}}{2 \mathbf{p}'_{L,u}(v)}$)\;
    \ENDFOR
    \STATE $n_r^{(3)}\leftarrow \frac{L}{\epsilon^2}r_{max}d_u\log  n$ \hfill $\triangleright$ Stage III: random walk sampling from $u$\;
    %\FOR{$j\in [n_r^{(3)}]$}
    %{
     \STATE Perform $n_r^{(3)}$ lazy random walks of length $L$ start from $u$, denote $N^{(3)}_{u,w,k}$ as the number of walks arrive at $w$ at step $k$ with $k\leq L$.
   % }
    \FOR{$v\in S'_{\epsilon,u}$ with $d_v\leq d_u$}
        \STATE $\hat{\mathbf{p}}_{L,u}(v)\leftarrow \frac{\mathbf{q}_{L,v}(u)d_v}{d_u}+\frac{d_v}{n_r^{(3)}}\sum_{k=0}^{L}{\sum_{w\in\mathcal{V}}{\left(\sum_{i=0}^{L-k}{\frac{\mathbf{r}_{i,u}(w)}{d_w}}\right)N^{(3)}_{u,w,k}}}$\;
    \ENDFOR
    \ENDFOR
    \ENSURE $\hat{\mathbf{p}}_{L,u}$ for every $u\in \mathcal{V}$
\end{algorithmic}
\end{algorithm}


\begin{algorithm}[t!]
%\caption{70\% of the column width!}
\small
	\SetAlgoLined
    \caption{Our query algorithm for $s,t$-ER value}\label{algo:sketch_query}
    \renewcommand{\algorithmicrequire}{\textbf{Input:}}
	\renewcommand{\algorithmicensure}{\textbf{Output:}}
    \begin{algorithmic}[1]
	\REQUIRE $s,t$, $\hat{\mathbf{p}}_{L,u}$ for all $u\in\mathcal{V}$
    \IF{$d_s\leq d_t$}
    \STATE $\hat{r}_\mathcal{G}(s,t)=\frac{\hat{\mathbf{p}}_{L,s}(s)}{d_s}-2\frac{\hat{\mathbf{p}}_{L,t}(s)}{d_s}+\frac{\hat{\mathbf{p}}_{L,t}(t)}{d_t}$\;
    \ELSE
   \STATE $\hat{r}_\mathcal{G}(s,t)=\frac{\hat{\mathbf{p}}_{L,s}(s)}{d_s}-2\frac{\hat{\mathbf{p}}_{L,s}(t)}{d_t}+\frac{\hat{\mathbf{p}}_{L,t}(t)}{d_t}$\;
    \ENDIF
    \ENSURE $\hat{r}_\mathcal{G}(s,t)$
    \end{algorithmic}
\end{algorithm}



\section{Conclusion}
In this paper, we propose several new algorithms for approximating Effective Resistance (ER) with reduced dependency on the error parameter $\epsilon$. For online ER computation algorithms, we integrate deterministic search with random walk sampling to develop an $\tilde{O}(\sqrt{d}/{\epsilon})$-time algorithm that $\epsilon$-approximates the single-pair ER value in expander graphs. Additionally, we establish that $\Omega(1/\epsilon)$ represents the lower bound for local ER approximation, even in the case of expander graphs. For index-based ER computation algorithms, we extend our techniques and propose an ER sketch algorithm that advances the state-of-the-art. For the open problems, beyond the natural challenge of improving both upper and lower bounds, it would particularly be interested in exploring the relationship between $\kappa(\mathcal{L})$ and $\epsilon$ in the context of the lower bound for local ER computation, so as to unify the analysis for both expander and non-expander graphs.








