\section{Other Omitting Proofs}\label{sec:other_proofs}

\stitle{Proof of Lemma \ref{lemma:ER_taylor_expansion}.}\hypertarget{proof_of_lemma:ER_taylor_expansion}{}
%\begin{proof}
    We use the similar argument as Lemma 4.3 in ~\cite{peng2021local}. First, we note that $\mathbf{L}=\mathbf{D}-\mathbf{A}=\mathbf{D}^{1/2}(\mathbf{I}-\mathcal{A})\mathbf{D}^{1/2}$, where $\mathcal{A}$ is the normalized adjacency matrix. Therefore, we have:
 \begin{align*}
    \mathbf{L}^\dagger&=\mathbf{D}^{-1/2}(\mathbf{I}-\mathcal{A})^\dagger\mathbf{D}^{-1/2}
    =\mathbf{D}^{-1/2}\sum_{j=2}^{n}{\frac{1}{1-\lambda_j(\mathcal{A})}\mathbf{u}_j\mathbf{u}_j^T}\mathbf{D}^{-1/2}\\
    &=\frac{1}{2}\mathbf{D}^{-1/2}\sum_{j=2}^{n}{\sum_{l=0}^{\infty}{\left(\frac{1}{2}+\frac{1}{2}\lambda_j(\mathcal{A})\right)^l}\mathbf{u}_j\mathbf{u}_j^T}\mathbf{D}^{-1/2}\\
    &=\frac{1}{2}\mathbf{D}^{-1/2}\sum_{l=0}^{\infty}{\sum_{j=2}^{n}{\left(\frac{1}{2}+\frac{1}{2}\lambda_j(\mathcal{A})\right)^l}\mathbf{u}_j\mathbf{u}_j^T}\mathbf{D}^{-1/2}\\
    &=\frac{1}{2}\mathbf{D}^{-1/2}\sum_{l=0}^{\infty}{\left(\left(\frac{1}{2}\mathbf{I}+\frac{1}{2}\mathcal{A}\right)^l-\mathbf{u}_1\mathbf{u}_1^T\right)}\mathbf{D}^{-1/2}.\\
 \end{align*}
 Where $\mathbf{u}_j$ denotes the eigenvector of $\mathcal{A}$ corresponding to the eigenvalue $\lambda_j(\mathcal{A})$. Next, we notice the fact that $\mathbf{u}_1=\mathbf{D}^{1/2}\mathbf{1}\perp \mathbf{D}^{-1/2}(\mathbf{e}_s-\mathbf{e}_t)$ for any $s,t\in \mathcal{V}$, where $\mathbf{1}$ is the all-one vector. Therefore,
 \begin{align*}
     r_\mathcal{G}(s,t)&=(\mathbf{e}_s-\mathbf{e}_t)^T\mathbf{L}^{\dagger}(\mathbf{e}_s-\mathbf{e}_t)\\
     &=\frac{1}{2}(\mathbf{e}_s-\mathbf{e}_t)^T\mathbf{D}^{-1/2}\sum_{l=0}^{\infty}{\left(\left(\frac{1}{2}\mathbf{I}+\frac{1}{2}\mathcal{A}\right)^l-\mathbf{u}_1\mathbf{u}_1^T\right)}\mathbf{D}^{-1/2}(\mathbf{e}_s-\mathbf{e}_t)\\
     &=\frac{1}{2}(\mathbf{e}_s-\mathbf{e}_t)^T\mathbf{D}^{-1/2}\sum_{l=0}^{+\infty}{\left(\frac{1}{2}\mathbf{I}+\frac{1}{2}\mathcal{A}\right)^l}\mathbf{D}^{-1/2}(\mathbf{e}_s-\mathbf{e}_t)\\
     &=\frac{1}{2}(\mathbf{e}_s-\mathbf{e}_t)^T\mathbf{D}^{-1}\sum_{l=0}^{+\infty}{\left(\frac{1}{2}\mathbf{I}+\frac{1}{2}\mathbf{P}\right)^l}(\mathbf{e}_s-\mathbf{e}_t).
 \end{align*}
 This finishes the proof.\hfill$\blacksquare$\par
%\end{proof}

\stitle{Proof of Lemma \ref{lem:ER_truncate}.}\hypertarget{proof_of_lemma:ER_truncate}{}
    By the definition of $r_{\mathcal{G},L}(s,t)$, we have that
    \begin{align*}
        &|r_\mathcal{G}(s,t)-r_{\mathcal{G},L}(s,t)|\\
        &= \left|\frac{1}{2}(\mathbf{e}_s-\mathbf{e}_t)^T\mathbf{D}^{-1}\sum_{l=L+1}^{\infty}{\left(\frac{1}{2}\mathbf{I}+\frac{1}{2}\mathbf{P}\right)^l}(\mathbf{e}_s-\mathbf{e}_t)\right|\\
        &=\left|\frac{1}{2}(\mathbf{e}_s-\mathbf{e}_t)^T\mathbf{D}^{-1/2}\sum_{l=L+1}^{\infty}{\left(\frac{1}{2}\mathbf{I}+\frac{1}{2}\mathcal{A}\right)^l}\mathbf{D}^{-1/2}(\mathbf{e}_s-\mathbf{e}_t)\right|\\
        &=\left|\frac{1}{2}(\mathbf{e}_s-\mathbf{e}_t)^T\mathbf{D}^{-1/2}\sum_{l=L+1}^{\infty}{\sum_{j=2}^{n}{\left(\frac{1}{2}+\frac{1}{2}\lambda_j(\mathcal{A})\right)^l}\mathbf{u}_j\mathbf{u}_j^T}\mathbf{D}^{-1/2}(\mathbf{e}_s-\mathbf{e}_t)\right|.
    \end{align*}

    Next, we denote $\alpha_j=\mathbf{u}_j^T\mathbf{D}^{-1/2}(\mathbf{e}_s-\mathbf{e}_t)$, and $\alpha=(\alpha_1,...,\alpha_n)^T=(\mathbf{u}_1,...,\mathbf{u}_n)^T\mathbf{D}^{-1/2}(\mathbf{e}_s-\mathbf{e}_t)$. Therefore, we can bound
    \begin{align*}
    \Vert\alpha\Vert_2&=\Vert(\mathbf{u}_1,...,\mathbf{u}_n)\mathbf{D}^{-1/2}(\mathbf{e}_s-\mathbf{e}_t)\Vert_2
    \leq \Vert\mathbf{D}^{-1/2}(\mathbf{e}_s-\mathbf{e}_t)\Vert_2\leq \sqrt{2}.
    \end{align*}
    And thus $\sum_{j=1}^{n}{\alpha_j^2}\leq 2$. Therefore,
    \begin{align*}
        |r_\mathcal{G}(s,t)-r_{\mathcal{G},L}(s,t)|&=\left|\frac{1}{2}\sum_{l=L+1}^{\infty}{\sum_{j=2}^{n}{\left(\frac{1}{2}+\frac{1}{2}\lambda_j(\mathcal{A})\right)^l}}\alpha_j^2\right|
        \leq \sum_{l=L+1}^{\infty}{\left(\frac{1}{2}+\frac{1}{2}\lambda_2(\mathcal{A})\right)^l},\\
    \end{align*}
    where $\lambda_2(\mathcal{A})$ is the second largest eigenvalue of $\mathcal{A}$. By the property of the eigenvalues of normalized Laplacian matrix, $\lambda_2(\mathcal{L})=1-\lambda_2(\mathcal{A})$. Therefore,
    \begin{align*}
        |r_\mathcal{G}(s,t)-r_{\mathcal{G},L}(s,t)|
        &\leq \sum_{l=L+1}^{\infty}{\left(1-\frac{1}{2}\lambda_2(\mathcal{L})\right)^l}
        \leq \left(1-\frac{1}{2}\lambda_2(\mathcal{L})\right)^L\frac{2}{\lambda_2(\mathcal{L})} \\
        &\leq \left(1-\frac{1}{2}\lambda_2(\mathcal{L})\right)^L\kappa(\mathcal{L}) \leq \frac{\epsilon}{n}.
    \end{align*}
    The final inequality holds when setting $L=\log \frac{\epsilon}{n\kappa(\mathcal{L})}/ \log \left(1-\frac{1}{2}\lambda_2(\mathcal{L})\right)$. We notice the fact $\log \left(1-\frac{1}{2}\lambda_2(\mathcal{L})\right)\leq  -\frac{1}{2}\lambda_2(\mathcal{L})$ and $\kappa(\mathcal{L})\leq \frac{2}{\lambda_2(\mathcal{L})}$, so we set $L\geq 2\kappa(\mathcal{L}) \log \frac{n}{\epsilon}$ is enough. Finally, by the fact $r_\mathcal{G}(s,t)\geq \frac{1}{d_s}+\frac{1}{d_t}\geq \frac{1}{n}$, we have $ |r_\mathcal{G}(s,t)-r_{\mathcal{G},L}(s,t)|\leq \frac{\epsilon}{n}\leq\epsilon r_\mathcal{G}(s,t)$, thus $r_{\mathcal{G},L}(s,t)$ is the $\epsilon$-approximation of $r_\mathcal{G}(s,t)$.\hfill$\blacksquare$\par
%\end{proof}



