\stitle{Proof of Lemma \ref{lem:parallel_resistance}.}\hypertarget{proof_of_lemma:parallel_resistance}{}
To prove Lemma \ref{lem:parallel_resistance}, we need the following two Propositions. The first Proposition is the submatrix representation of ER value, and the second Proposition is the classic block matrix inverse formula.

\begin{proposition}{(Corollary 1 in ~\cite{liao2023resistance})}\label{prop:landmark}
    $r_\mathcal{G}(s,t)=(\mathbf{e}_s-\mathbf{e}_t)^T\mathbf{L}^\dagger(\mathbf{e}_s-\mathbf{e}_t)=(\mathbf{L}_s^{-1})_{tt}=( \mathbf{L}_t^{-1})_{ss}$ for any graph $\mathcal{G}$. Where $\mathbf{L}$ denotes the Laplacian matrix of $\mathcal{G}$, and $\mathbf{L}_s$ (resp., $\mathbf{L}_t$) denotes the submatrix of $\mathbf{L}$, deleting the row and column indexed by node $s$ (resp., $t$).
\end{proposition}

\begin{proposition}\label{prop:block_inverse}
      Let $S=D-CA^{-1}B$, we have:
      \begin{align*}
      \begin{bmatrix}
       \begin{array}{cc}
       A & B\\
       C & D
        \end{array}
        \end{bmatrix}^{-1}=
        \begin{bmatrix}
       \begin{array}{cc}
       A^{-1}+A^{-1}BS^{-1}CA^{-1} & -A^{-1}BS^{-1}\\
       -S^{-1}CA^{-1} & S^{-1}
        \end{array}
        \end{bmatrix}
        \end{align*}
\end{proposition}

Now we use Proposition \ref{prop:landmark} and Proposition \ref{prop:block_inverse} to prove Lemma \ref{lem:parallel_resistance}. We observe that the resistance $r_{S_2}(s,t)$ is simply the the parallel connection of $(d_s-x)$ resistors with resistance value $2$. Thus, by the parallel resistance formula, $r_{S_2}(s,t)=\frac{2}{d_s-x}$. For $r_{S_1}(s,t)$, we define $\mathbf{L}_{S_1\cup\{s,t\}}\in \mathbb{R}^{(n_1+2)\times(n_1+2)}$ as the Laplacian matrix constraint on the edges between $S_1\cup \{s,t\}$, $\mathbf{L}_{S_1}\in \mathbb{R}^{n_1\times n_1}$ as the Laplacian matrix constraint on the edges between $S_1$. Let $\mathbf{e}_{\mathcal{N}_1}$ denotes the indicating vector that only takes value $1$ in $\mathcal{N}_1$ and $0$ elsewhere, $\mathbf{I}_{\mathcal{N}_1}$ denotes the diagonal matrix that only takes value $1$ at diagonal entries indexed by $\mathcal{N}_1$ and $0$ elsewhere, where $ \mathcal{N}_1=\{v_1,...,v_x\}$ is the set of the neighbors of $s$ in $S_1$. By the definition of ER and the submatrix representation (Proposition \ref{prop:landmark}), we have:
\begin{align*}
    r_{S_1}(s,t)&=(\mathbf{e}_s-\mathbf{e}_t)^T\mathbf{L}_{S_1\cup\{s,t\}}^\dagger(\mathbf{e}_s-\mathbf{e}_t)
    =\begin{bmatrix}
       \begin{array}{cc}
       x & -\mathbf{e}_{\mathcal{N}_1}^T\\
       -\mathbf{e}_{\mathcal{N}_1} & \mathbf{L}_{S_1}+\mathbf{I}+\mathbf{I}_{\mathcal{N}_1}
        \end{array}
        \end{bmatrix}_{s,s}^{-1}
\end{align*}

Next, we use the block matrix inverse formula (Proposition \ref{prop:block_inverse}), we have:
\begin{equation}\label{equ:compute_lower_bound}
\begin{aligned}
    & \begin{bmatrix}
       \begin{array}{cc}
       x & -\mathbf{e}_{\mathcal{N}_1}^T\\
       -\mathbf{e}_{\mathcal{N}_1} & \mathbf{L}_{S_1}+\mathbf{I}+\mathbf{I}_{\mathcal{N}_1}
        \end{array}
        \end{bmatrix}_{s,s}^{-1}
        =\frac{1}{x}+\frac{1}{x^2}\mathbf{e}_{\mathcal{N}_1}^T\left[\mathbf{L}_{S_1}+\mathbf{I}+\mathbf{I}_{\mathcal{N}_1}-\frac{1}{x}\mathbf{e}_{\mathcal{N}_1}\mathbf{e}_{\mathcal{N}_1}^T\right]^{-1}\mathbf{e}_{\mathcal{N}_1}
\end{aligned}
\end{equation}

Now we prove the second term of the right hand side of Eq. (\ref{equ:compute_lower_bound}) is at most $O(\frac{\log n_1}{dx})$. To this end, we notice that $|\mathcal{N}_1|=x$ and $\mathbf{I}_{\mathcal{N}_1}-\frac{1}{x}\mathbf{e}_{\mathcal{N}_1}\mathbf{e}_{\mathcal{N}_1}^T\succeq 0$, thus
\begin{align*}
    \mathbf{L}_{S_1}+\mathbf{I}+\mathbf{I}_{\mathcal{N}_1}-\frac{1}{x}\mathbf{e}_{\mathcal{N}_1}\mathbf{e}_{\mathcal{N}_1}^T\succeq \mathbf{L}_{S_1}+\mathbf{I}.
\end{align*}

Next, we define $\mathbf{A}_{S_1},\mathbf{P}_{S_1}\in \mathbb{R}^{n_1\times n_1}$ to be the adjacency matrix and probability transition matrix constraint on the edges between $S_1$, respectively. By our construction, we have
\begin{align*}
    \mathbf{L}_{S_1}+\mathbf{I}&=(d+1)\mathbf{I}-\mathbf{A}_{S_1}=(d+1)\mathbf{I}-d\mathbf{P}_{S_1}\\
    &=(d+1)\left[\mathbf{I}-\left(1-\frac{1}{d+1}\right)\mathbf{P}_{S_1}\right].
\end{align*}
Therefore, we can bound:
\begin{equation}\label{equ:compute_lower_bound_2}
\begin{aligned}
    0 \leq \mathbf{e}_{\mathcal{N}_1}^T\left[\mathbf{L}_{S_1}+\mathbf{I}+\mathbf{I}_{\mathcal{N}_1}-\frac{1}{x}\mathbf{e}_{\mathcal{N}_1}\mathbf{e}_{\mathcal{N}_1}^T\right]^{-1}\mathbf{e}_{\mathcal{N}_1} 
    &\leq 
    \frac{1}{d+1}\mathbf{e}_{\mathcal{N}_1}^T\left[\mathbf{I}-\left(1-\frac{1}{d+1}\right)\mathbf{P}_{S_1}\right]^{-1}\mathbf{e}_{\mathcal{N}_1}\\
    &=\frac{1}{d+1}\sum_{k=0}^{\infty}{\left(1-\frac{1}{d+1}\right)^k\mathbf{e}_{\mathcal{N}_1}^T\mathbf{P}_{S_1}^{k}\mathbf{e}_{\mathcal{N}_1}}.
\end{aligned}
\end{equation}

Next we use the classical random walk mixing result. For expander graph $S_1$, if we start a random walk with initial probability $\mathbf{\pi}_{\mathcal{N}_1}=\frac{1}{|\mathcal{N}_1|} \mathbf{e}_{\mathcal{N}_1}$, after $K=O(\log n_1)$ steps, $\left\Vert \mathbf{P}_{S_1}^K\mathbf{\pi}_{\mathcal{N}_1}-\frac{\mathbf{1}}{n}\right\Vert_2\leq \frac{1}{n^2}$. Combing this result with Eq. (\ref{equ:compute_lower_bound_2}), we have:
\begin{align*}
&\mathbf{e}_{\mathcal{N}_1}^T\left[\mathbf{L}_{S_1}+\mathbf{I}+\mathbf{I}_{\mathcal{N}_1}-\frac{1}{x}\mathbf{e}_{\mathcal{N}_1}\mathbf{e}_{\mathcal{N}_1}^T\right]^{-1}\mathbf{e}_{\mathcal{N}_1}\\
&\leq 
\frac{1}{d+1}\left[\sum_{k=0}^{K}{\left(1-\frac{1}{d+1}\right)^k\mathbf{e}_{\mathcal{N}_1}^T\mathbf{P}_{S_1}^{k}\mathbf{e}_{\mathcal{N}_1}} + \sum_{k=K}^{\infty}{\left(1-\frac{1}{d+1}\right)^k\mathbf{e}_{\mathcal{N}_1}^T\mathbf{P}_{S_1}^{k}\mathbf{e}_{\mathcal{N}_1}}\right]\\
&\leq 
\frac{1}{d+1}\left[K|\mathcal{N}_1|+\frac{\left(1-\frac{1}{d+1}\right)^{K+1}}{1-\left(1-\frac{1}{d+1}\right)}|\mathcal{N}_1|^2\frac{2}{n_1}\right]\\
&\leq \frac{x}{d+1}O(\log n_1) + \frac{2x^2}{n_1}.
\end{align*}

Finally, we set $n_1\geq 2d^3\geq 2d x^2$, the above inequality is bounded by $O(\frac{x\log n_1}{d})$. Combining this result with Eq. (\ref{equ:compute_lower_bound}), we obtain $r_{S_1}(s,t)=\frac{1}{x}+O(\frac{1}{dx}\log n_1 )$. This finishes the proof.\hfill$\blacksquare$\par
%\end{proof}

\stitle{Proof of Lemma \ref{lem:G1G2_differ}.}\hypertarget{proof_of_lemma:G1G2_differ}{}
%\begin{proof}
    Recall that by our construction, for $\mathcal{G}_1$ all neighbors of $s$ is in $S_1$. Thus, $r_{\mathcal{G}_1}(s,t)=r_{S_1}(s,t)=\frac{1}{d_s}+O(\frac{\log n_1}{d d_s})=\frac{1}{d_s}+O(\frac{1}{d_s^2})$. This is equivalently saying $d_s r_{\mathcal{G}_1}(s,t) = 1+ O(\frac{1}{d_s})$. On the other hand, for $\mathcal{G}_2$, the neighbors of $s$ are $x=(1-\epsilon)d_s$ in $S_1$ and $\epsilon d_s$ in $S_2$. By the parallel resistance formula and Lemma \ref{lem:parallel_resistance},
    \begin{align*}
        r_{\mathcal{G}_2}(s,t) &= \frac{r_{S_1}(s,t)r_{S_2}(s,t)}{r_{S_1}(s,t)+r_{S_2}(s,t)} = \frac{\frac{2}{d_s-x}\left(\frac{1}{x}+O(\frac{1}{d_s x})\right)}{\frac{2}{d_s-x}+\frac{1}{x}+O(\frac{1}{d_s x})}\\
        &=\frac{2+O(\frac{1}{d_s})}{d+x+O(\frac{d_s-x}{d_s})}=\frac{2+O(\frac{1}{d_s})}{(2-\epsilon)d_s+O(\epsilon)}.
    \end{align*}

Thus, we have
\begin{align*}
   d_s r_{\mathcal{G}_2}(s,t) &= \frac{2d_s\left(1+O(\frac{1}{d_s})\right)}{(2-\epsilon)d_s+O(\epsilon)}= \frac{2}{2-\epsilon}\frac{1+O(\frac{1}{d_s})}{1+O(\frac{\epsilon}{d_s})}\\
   &=\frac{2}{2-\epsilon}\left(1+O(\frac{1}{d_s})\right).
\end{align*}

Finally, we set $d_s\gg \frac{1}{\epsilon}$, thus $d_s r_{\mathcal{G}_2}(s,t)=\frac{2}{2-\epsilon}\left(1+o(\epsilon)\right)$. Therefore, 
\begin{align*}
   | r_{\mathcal{G}_1}(s,t)-r_{\mathcal{G}_2}(s,t)|&=\frac{1}{d_s}\left[\frac{2}{2-\epsilon}-1+o(\epsilon)\right]=\frac{1}{d_s}\left[\frac{\epsilon}{2-\epsilon}+o(\epsilon)\right]\\
   &\geq \frac{\epsilon}{2}\frac{1}{d_s}\geq \frac{\epsilon}{4}r_{\mathcal{G}_1}(s,t).
\end{align*}

    The final inequality holds because $r_{\mathcal{G}_1}(s,t)=\frac{1}{d_s}+O(\frac{1}{d_s^2})\leq \frac{2}{d_s}$. This finishes the proof.\hfill$\blacksquare$\par
%\end{proof}

\stitle{Proof of Lemma \ref{lem:G1G2_distinguish}.}\hypertarget{proof_of_lemma:G1G2_distinguish}{}
Through our construction, we observe that the only way to distinguish between $\mathcal{G}_1$ and $\mathcal{G}_2$ is to perform a neighbor query on node $s$. For $\mathcal{G}_1$, we have all the neighbors of $s$, $\mathcal{N}_{\mathcal{G}_1}(s)\subset S_1$. For $\mathcal{G}_2$, we have $\mathcal{N}_1\subset S_1$ with $|\mathcal{N}_1|=(1-\epsilon)d_s$, $\mathcal{N}_2\subset S_2$ with $|\mathcal{N}_2|=\epsilon d_s$ and $\mathcal{N}_1\cup \mathcal{N}_2=\mathcal{N}_{\mathcal{G}_2}(s)$ is the neighbor set of $s$. Thus, distinguishing $\mathcal{G}_1$ and $\mathcal{G}_2$ via a neighbor query on $s$ reduces to determining whether the elements of $\mathcal{N}_{\mathcal{G}_1}(s), \mathcal{N}_{\mathcal{G}_2}(s)$ follow the same distribution. We prove this result using the classical Yao's Minimax Principle.

\begin{theorem}{(Yao's Minimax Principle, see e.g. Lemma D.1 from ~\cite{cai2023effective})}\label{thm:minimax_principle}
    Let $\mathcal{X}$ denotes the set of inputs of a problem, $\Delta(\mathcal{X})$ denotes the set of all distributions over $\mathcal{X}$. Let $\mathcal{A}_\mu$ denotes minimum cost among all deterministic algorithms that solves the problem with probability $\geq 2/3$, with respect to the distribution $\mu\in \Delta(\mathcal{X})$. Let $\mathcal{R}$ denotes the minimum cost among all randomized algorithms that solves the problem for all $x\in \mathcal{X}$. Then, $\mathcal{R}\geq \max_{\mu\in \mathcal{X}}{\mathcal{A}_\mu}$.
\end{theorem}

In our case, we choose the problem inputs $\mathcal{X}=\{\mathcal{N}(s)\}$, and we consider the following two events $C_1,C_2\subset \mathcal{X}$:
\begin{align*}
C_1=\{&\mathcal{N}(s):\forall v\in \mathcal{N}(s), v\in S_1\}\\
C_2=\{&\mathcal{N}(s):\mathcal{N}(s)=\mathcal{N}_1\cup \mathcal{N}_2, \\
&\mathcal{N}_1\subset S_1,
\mathcal{N}_2\subset S_2,\ and\  |\mathcal{N}_1|=(1-\epsilon)|\mathcal{N}(s)| \}
\end{align*}

Next, we consider the distribution $\mu$ over $\mathcal{X}$, such that: (i) $C_1$ happens with probability $\frac{1}{2}$ and $\forall x \in C_1\subset \mathcal{X}$ happens with equal probability; (ii) $C_2$ happens with probability $\frac{1}{2}$ and $\forall x \in C_2\subset \mathcal{X}$ happens with equal probability. We consider any property testing deterministic algorithm $A$, such that $A$ should answer YES if there are $\geq \epsilon|\mathcal{N}(s)|$ number of nodes $v\in \mathcal{N}(s)$ in $S_2$; $A$ should answer NO if there are $< \epsilon|\mathcal{N}(s)|$ number of nodes $v\in \mathcal{N}(s)$ in $S_2$. We denote $A(C_1)$, $A(C_2)$ as the random variable, which represents the answer of $A$ on some $x\in  C_1$ uniformly randomly (resp., $x\in  C_2$ uniformly randomly). We consider when $A$ succeeds with probability $\geq 2/3$:
\begin{align*}
    \frac{2}{3}\leq \mathbb{P}_{\mu}[A\ \ succeeds]=\frac{1}{2} \mathbb{P}[A(C_1)=NO]+\frac{1}{2} \mathbb{P}[A(C_2)=YES].
\end{align*}

Since $C_1$ is fixed, we only need to consider the second probability $\mathbb{P}[A(C_2)=YES]$. We assume $A$ makes $q$ queries on $C_2$. Then,
\begin{equation}\label{equ:AC2}
\begin{aligned}
    \mathbb{P}[A(C_2)=YES]&=\mathbb{P}[A(C_2)=YES | A(C_1)=A(C_2)]\mathbb{P}[A(C_1)=A(C_2)]\\
    &+\mathbb{P}[A(C_2)=YES | A(C_1)\neq A(C_2)]\mathbb{P}[A(C_1)\neq A(C_2)]\\
    &\leq \mathbb{P}[A(C_1)=YES]+\mathbb{P}[A(C_1)\neq A(C_2)]\\
    &= \mathbb{P}[A(C_1)=YES] + \mathbb{P}[one\ query\ returns\ v\in S_2 ]\\
    &\leq 1-\mathbb{P}[A(C_1)=NO] + \epsilon q.
\end{aligned}
\end{equation}

The final inequality holds because there are only $\epsilon|\mathcal{N}(s)|$ randomly chosen elements in $S_2$. For each fixed query, the probability that we find some $v\in S_2$ is at most $\epsilon$. Arming with Eq. (\ref{equ:AC2}), we have:
\begin{align*}
    \frac{2}{3}&\leq \frac{1}{2} \mathbb{P}[A(C_1)=NO]+\frac{1}{2} \mathbb{P}[A(C_2)=YES]\leq \frac{1}{2}+\frac{1}{2}\epsilon q.
\end{align*}

As a result, $q\geq \frac{1}{3\epsilon}$. This implies $A$ makes at least $\Omega(\frac{1}{\epsilon})$ queries on $C_2$. By Yao's Minimax Principle, any randomized algorithm with success probability $\geq 2/3$ that distinguish $\mathcal{N}_{\mathcal{G}_1}(s)$ and $\mathcal{N}_{\mathcal{G}_2}(s)$ requires $\Omega(\frac{1}{\epsilon})$ queries. This finishes the proof of Theorem \ref{thm:lower_bound_specific}.\hfill$\blacksquare$\par

