\end{array}\right]$,
$M^{(4)}_2 = \frac{1}{2} \left[\begin{array}{cccc}
1 & -1 & -i & -i\\
1 & -1 & i & i\\
1 & 1 & i & -i\\
1 & 1 & -i & i\\
\end{array}\right]$,

$M^{(4)}_3 = \frac{1}{2} \left[\begin{array}{cccc}
1 & -i & -i & -1\\
1 & -i & i & 1\\
