		\begin{abstract}
		Marzo and Ortega-Cerd\`a \cite{MO08} gave geometric characterizations for $L^p$-Logvinenko-Sereda sets on the standard sphere for all $1\le p<\infty$. Later, Ortega-Cerd\`a and Pridhnani \cite{OCP13} further investigated $L^2$-Logvinenko-Sereda sets and $L^2$-Carleson measures on compact manifolds without boundary. In this paper, we  characterize $L^p$-Logvinenko-Sereda sets and $L^p$-Carleson measures on compact manifolds with or without boundary for all $1<p<\infty$.   Furthermore, we investigate $L^p$-Logvinenko-Sereda sets and $L^p$-Carleson measures for eigenfunctions on compact manifolds without boundary, and we completely characterize them on the standard sphere $S^m$ for $p > \frac{2m}{m-1}$. For the range $p < \frac{2m}{m-1}$, we conjecture that $L^p$-Logvinenko-Sereda sets for eigenfunctions on the standard sphere $S^m$ are characterized by the tubular geometric control condition and we provide some evidence. These results provide new progress on an open problem raised  by Ortega-Cerd\`a and Pridhnani.  
		\end{abstract}
		\maketitle


\section{Introduction}		



		Let $(M,g)$ be a smooth connected compact  Riemannian manifold with boundary $\partial M$. The dimension of $M$ is $m\ge2$. The boundary $\partial M$ is smooth and can be empty.  If $\partial M\neq \emptyset$ and  $\nu$ is the outward unit normal vector field along $\partial\Omega$, we assume the boundary condition is either  Dirichlet ($u|_{\partial\Omega}=0$) or Neumann ($\partial_\nu u|_{\partial\Omega}=0$).  Then  the Laplacian operator $-\Delta$ on $M$ is nonnegative, self-adjoint and has discrete spectrum $\{\la_j^2\}$ where $0\le \la_1\le \la_2\le ...$ are arranged in increasing order and we account for
		multiplicity. For $\la\ge1$, let $E_\la$ be the subspace of $L^2(M)$ generated by eigenfunctions of eigenvalues bounded by $\la^2$, namely
		\[E_\la=\Big\{\sum_{\la_j\le \la}\alpha_je_j:\alpha_j\in \mathbb{C},\ -\Delta e_j=\la_j^2e_j\Big\}\]
		where  $\{e_j\}_j$ is an orthonormal eigenbasis corresponding to  $\{\la_j\}_j$. 

		Let $1\le p<\infty$. The question is to characterize the measures $\mu=\{\mu_\la\}_\la$ such that for all $\la\ge1$ and $f\in E_\la$,
		\begin{equation}\label{goal}
			\int_M|f|^pd\mu_\la \approx \int_M|f|^pdV.
		\end{equation}
		Let $B(z,r)$ be the geodesic ball in $M$ centered at $z$ of radius $r$.  Heuristically, since the function $f$ is frequency-localized  in a ball of radius $\la$, by the uncertainty principle it behaves like a constant in every ball of radius $1/\la$ in the physical space. Thus, it is natural to introduce the following conditions, which will be useful to characterize the measures satisfying \eqref{goal}.


		We call $\mu$ is \textbf{relatively dense} if there exist $r>0$ and $\rho>0$ such that for all $\la\ge1$ and $z\in M$,
		\begin{equation}\label{mudense}
			\frac{\mu_\la(B(z,r/\la))}{\text{vol}(B(z,r/\la))}\ge \rho.
		\end{equation}
		 	We call $\mu$ is \textbf{relatively sparse} if there exist $r>0$ and $C>0$ such that for all $\la\ge1$ and $z\in M$,
		 \begin{equation}\label{musparse}
		 	\frac{\mu_\la(B(z,r/\la))}{\text{vol}(B(z,r/\la))}\le C.
		 \end{equation}





		 First, let us focus on the special case where $d\mu_\la=\1_{A_\la}dV$ where $\1_{A_\la}$ is the indicator function of the set $A_\la\subset M$.	Let $\mathcal{A}=\{A_\la\}_\la$ be a sequence of sets in $M$. We say that $\mathcal{A}$ is \textbf{$L^p$-Logvinenko-Sereda}  if there exists  $C>0$ such that for all $\la\ge1$ and $f\in E_\la$,
		 	\begin{equation}\label{LSdef}
		 	\int_{A_\la}|f|^pdV\ge  C	\int_M |f|^pdV.\end{equation}
		 		 We say that $\mathcal{A}$ is relatively dense if there exist $r>0$ and $\rho>0$ such that for all $\la\ge1$ and $z\in M$,
		 		\begin{equation}\label{RDdef}
		 			\frac{{\rm vol}(A_\la\cap B(z,r/\la))}{{\rm vol}(B(z,r/\la))}\ge\rho.
		 		\end{equation}
	By definition, $\mathcal{A}$ is relatively dense if and only if $\mu$ is relatively dense.





Our first result is  that  the relatively dense condition actually  characterizes $L^p$-Logvinenko-Sereda  sets on compact manifolds with or without boundary.

\begin{theorem}\label{LSthm}
	For $1<p<\infty$, the sequence of sets $\mathcal{A}=\{A_\la\}_\la$ is $L^p$-Logvinenko-Sereda  if it is relatively dense. For $1\le p<\infty$, the converse is true.
\end{theorem}


The classical Logvinenko-Sereda  theorem describes this type of comparable norms for functions in the Paley-Wiener space, which consists of functions in $L^p(\mathbb{R}^m)$ whose  Fourier transform is supported  in a prefixed bounded set in $\mathbb{R}^m$. See Logvinenko-Sereda \cite{LS74}, Havin-Jöricke \cite[p. 112-116]{HJ94}. Luecking \cite{L83} studied this notion in Bergman spaces. 
Following his idea, Marzo and Ortega-Cerd\`a \cite{MO08} characterized $L^p$-Logvinenko-Sereda sets on the sphere for all $1\le p<\infty$. Later, Ortega-Cerd\`a and Pridhnani \cite{OCP13} characterized $L^2$-Logvinenko-Sereda sets on compact manifolds without boundary. Our Theorem \ref{LSthm} completely characterizes $L^p$-Logvinenko-Sereda sets on compact manifolds with or without boundary for all $1<p<\infty$. 








Next, let $1\le p<\infty$ and let $\mu=\{\mu_\la\}_\la$ be a sequence of measures on $M$. We say that $\mu$ is  \textbf{$L^p$-Carleson}  if there exists $C>0$ such that for all $\la\ge1$ and $f\in E_\la$,
\begin{equation}\label{cardef}
	\int_M |f|^pd\mu_\la\le C\int_M|f|^pdV.
\end{equation}

Similarly, we may characterize the $L^p$-Carleson measures by the relatively sparse condition. Nevertheless, it is sensitive to the boundary condition.
\begin{theorem}\label{carthm}
For $1<p<\infty$,  the sequence of measures $\mu=\{\mu_\la\}_\la$ is $L^p$-Carleson  if it is relatively sparse. For $1\le p<\infty$, the converse is true when the boundary is empty or the  boundary condition is Neumann, but the converse is false when the  boundary condition is Dirichlet.
\end{theorem}
 On compact  manifolds without boundary, Ortega-Cerd\`a and Pridhnani \cite{OCP13} proved that the relatively sparse condition is sufficient and necessary for $\mu$ to be $L^2$-Carleson. Later, Xu \cite{xu21} studied this problem on compact manifolds with boundary, and observed that the relatively sparse condition is not necessary for $L^2$-Carleson under Dirichlet boundary condition. We observe that due to   the conservation property of the heat kernel \eqref{conser},  the relatively sparse condition is necessary for Carleson measures in  the boundaryless case and the Neumann case.

Furthermore, we investigate the problem with  $E_\la$ replaced by the $\la$-eigenspace. This open problem was raised by Ortega-Cerd\`a and Pridhnani in \cite[Remark 5.12]{OCP13}. It is  much more complicated, so we  only consider  compact manifolds without boundary for now. We say that $\mathcal{A}=\{A_\la\}_\la$ is \textbf{$L^p$-Logvinenko-Sereda for eigenfunctions} on $M$  if there exists $C>0$ such that for all  $\la\ge1$ and eigenfunctions $e_\la$ satisfying $-\Delta e_\la=\la^2e_\la$ we have \begin{equation}\label{LSdef2}
	\int_{A_\la}|e_\la|^pdV\ge C\int_M |e_\la|^pdV.
\end{equation}
In other words, every eigenfunction $e_\la$ is $L^p$-concentrated on $A_\la$. For example, on the compact hyperbolic surface $M$, every eigenfunction  is $L^2$-concentrated on any fixed nonempty open set $\Omega\subset M$.  See e.g. Dyatlov-Jin \cite{DJ18}, Dyatlov-Jin-Nonnenmacher \cite{DJ21}. By Theorem \ref{LSthm}, the relatively dense condition  is sufficient for $\mathcal{A}$ to be  $L^p$-Logvinenko-Sereda  for eigenfunctions for all $1<p<\infty$, but it is not necessary for some $p$. See \cite[Remark 5.12]{OCP13} for a counterexample when $p=1$.   More precisely, we can show that it is not necessary whenever  $p$ is small. 

\begin{prop}\label{smallpls}
	For any $1\le p<\frac{2m}{m-1}$, the relatively dense condition  is not necessary for $\mathcal{A}$ to be  $L^p$-Logvinenko-Sereda  for eigenfunctions on $M$. For $p=\frac{2m}{m-1}$, the relatively dense condition  is not necessary for $\mathcal{A}$ to be  $L^p$-Logvinenko-Sereda  for eigenfunctions on $M$ with a generic metric.
\end{prop}
Here we use the fact that $\|e_\la\|_{L^\infty(M)}=o( \la^{\frac{m-1}2})\|e_\la\|_{L^2(M)}$ for a generic metric on any compact manifold. For the definition of generic metric and more related results, see Sogge-Zelditch \cite[Theorem 1.4]{sz01}, Sogge-Toth-Zelditch \cite{stz11}, Sogge-Zelditch \cite{sz16,sz162}.  

On the sphere $S^m=\{x\in\mathbb{R}^{m+1}:|x|=1\}$, we call $\mathcal{A}$ is \textbf{symmetric relatively dense} if there exist $r>0$ and $\rho>0$ such that for all $\la\ge1$ and $z\in S^m$,
\begin{equation}\label{RDdefsym}
	\frac{\text{vol}(A_\la\cap B(z,r/\la))+\text{vol}(A_\la\cap B(-z,r/\la))}{\text{ vol}(B(z,r/\la))}\ge\rho.
\end{equation}
It is weaker than the relatively dense condition.  However,  this condition is still not necessary for small $p$.
\begin{prop}\label{smallplssphere}
	Let $(S^m,g)$ be the sphere equipped with a Riemannian metric. For any $1\le p<\frac{2m}{m-1}$, the symmetric relatively dense condition  is not necessary for $\mathcal{A}$ to be  $L^p$-Logvinenko-Sereda  for eigenfunctions on $S^m$. For $p=\frac{2m}{m-1}$, the symmetric relatively dense condition  is not necessary for $\mathcal{A}$ to be  $L^p$-Logvinenko-Sereda  for eigenfunctions on $S^m$ with a generic metric.
\end{prop}
Nevertheless, we can characterize $L^p$-Logvinenko-Sereda sets for eigenfunctions on the standard sphere for large $p$ by the symmetric relatively dense condition.
\begin{theorem}\label{largepls}
	For any $\frac{2m}{m-1}<p<\infty$, the symmetric relatively dense condition  is  necessary and sufficient for $\mathcal{A}$ to be  $L^p$-Logvinenko-Sereda sets for eigenfunctions on the standard sphere $S^m$.
\end{theorem}
By Proposition \ref{smallplssphere}, the range of $p$ in Theorem \ref{largepls} is essentially sharp. For the range $1\le p<\frac{2m}{m-1}$, we propose a conjecture that $L^p$-Logvinenko-Sereda sets for eigenfunctions on the standard sphere can be characterized by the tubular geometric control condition. See Conjecture \ref{tubeconj} and  some evidence in Section \ref{gausssect}.




 Similarly, it is interesting to characterize $L^p$-Carleson measures for eigenfunctions. We say that $\mu=\{\mu_\la\}_\la$ is  \textbf{$L^p$-Carleson for eigenfunctions} if there exists $C>0$ such that for all  $\la\ge1$ and eigenfunctions $e_\la$ satisfying $-\Delta e_\la=\la^2e_\la$ we have
\begin{equation}\label{cardef2}
	\int_M |e_\la|^pd\mu_\la\le C\int_M|e_\la|^pdV.
\end{equation} 
By Theorem \ref{carthm}, the relatively sparse condition is sufficient for $\mu$ to be $L^p$-Carleson for eigenfunctions, but we observe that it is not necessary for small $p$. 


\begin{prop}\label{smallp}
	For any $1\le p<\frac{2m}{m-1}$, the relatively sparse condition  is not necessary for $\mu$ to be $L^p$-Carleson for eigenfunctions on $M$. For $p=\frac{2m}{m-1}$, the relatively sparse condition  is not necessary for $\mu$ to  be $L^p$-Carleson for eigenfunctions on $M$ with a generic metric.
\end{prop}
On the other hand, we are able to characterize $L^p$-Carleson measures for eigenfunctions on the standard sphere for large $p$ by the relatively sparse condition.
\begin{theorem}\label{largep}
	 For  any $\frac{2m}{m-1}<p<\infty$, the relatively sparse condition  is  necessary and sufficient for $\mu$ to be $L^p$-Carleson for eigenfunctions on the standard sphere $S^m$.
\end{theorem}
By Proposition \ref{smallp}, the range of $p$ in Theorem \ref{largep} is essentially sharp. We essentially use the property that at every point of the sphere, there exists a sequence of eigenfunctions (e.g. zonal spherical harmonics)  with maximal eigenfunction growth (measured by  $L^\infty$ norm) at that point.  Sogge-Zelditch \cite[Theorem 1.1]{sz01} gave a necessary condition for this property using geodesic loops. It would be interesting to look for a sufficient condition.



\noindent\textbf{Outline for the proof of Theorem \ref{LSthm} and Theorem \ref{carthm}.} 

To prove the sufficiency part of  Theorem \ref{LSthm}, we first handle the boundaryless case and then deal with the Dirichlet case and the Neumann case separately. The boundaryless case can be proved by the harmonic extension method in Ortega-Cerd\`a and Pridhnani \cite{OCP13}. We need the $L^p$-mean value inequality for harmonic functions and the $L^p$-boundedness for the spectral multipliers. For the Dirichlet case, we find a good control  for the contribution for the part close to the boundary so we  eventually reduce the proof to  the boundaryless case. We need Bernstein inequalities that essentially rely on the Gaussian heat kernel upper bounds.  For the Neumann case, we need to establish the gradient estimate \eqref{gradest} for harmonic functions under Neumann boundary condition in order to proceed in the way as the boundaryless case. Our argument is inspired by the book of Li \cite{li12}, Chen \cite{chen90} and Wang \cite{wang97}.

To prove the necessity part,  heuristically one may  take $f=\1_{B(z,r/\la)}$ in \eqref{LSdef} to get \eqref{RDdef}, but this function is not in $E_\la$. Nevertheless, this heuristic can be made more precise. We shall use the complex time heat kernel estimates to construct appropriate functions in $E_\la$ that are essentially supported in the ball of radius $1/\la$. We also exploit Seeley's spectral function estimates and Bernstein inequalities. 


 The proof of Theorem \ref{carthm} is based on the similar strategy. The sufficiency part is simpler and we only use the $L^p$-mean value inequality for the harmonic extensions and the $L^p$-boundedness of spectral multipliers. To prove the necessity part, we shall exploit the two-sided estimate for the heat kernel on the diagonal, which holds when the boundary is empty or the  boundary condition is Neumann. It is due to the conservation property of the heat kernel. We also need the complex time heat kernel estimates  to construct functions in $E_\la$ that  approximate the indicator function $f=\1_{B(\xi,1/\la)}$. Furthermore, we construct a counterexample when the boundary condition is Dirichlet.

\noindent\textbf{Remarks.}
 1. It is natural to consider the endpoint case $p=1$ in Theorem \ref{LSthm} and Theorem \ref{carthm}. Recall that Marzo and Ortega-Cerd\`a \cite{MO08} characterized $L^p$-Logvinenko-Sereda sets on the sphere for $1\le p<\infty$, by using classical estimates on the Jacobi polynomials. However, the endpoint case $p=1$ seems more subtle on general Riemannian manifolds, and our approach essentially relies on the $L^p$-mean value inequality \eqref{mv} for harmonic functions and  the $L^p$-boundedness of spectral multipliers in Lemma \ref{Lplemma}.




2. It is an interesting open problem to characterize $L^p$-Logvinenko-Sereda sets and $L^p$-Carleson measures for eigenfunctions on $M$ for $1\le p\le \frac{2m}{m-1}$, even if $M$ is the standard sphere. We can choose Gaussian beams as test functions to give some necessary conditions. See Section \ref{gausssect} for  a conjecture and some evidence on the standard sphere.


\noindent\textbf{Organization of the paper.} In Section 2, we introduce the estimates of the heat kernels and the spectral functions. In Section 3, we prove the sufficiency part of Theorem \ref{LSthm}. In Section 4, we prove the necessity  part of Theorem \ref{LSthm}. In Section 5, we prove Theorem \ref{carthm}. In Section 6, we prove Proposition \ref{smallpls}, Proposition \ref{smallplssphere} and Theorem \ref{largepls}.  In Section 7, we prove Proposition \ref{smallp} and Theorem \ref{largep}. In Section 8, we further discuss $L^p$-Logvinenko-Sereda sets and $L^p$-Carleson measures for eigenfunctions on the standard sphere for small $p$.

\noindent\textbf{Notations.} Throughout this paper, $X\ls Y$ means $X\le CY$  for some positive constants $C$ independent of $\la$.   If $X\ls Y$ and $Y\ls X$, we denote $X\approx Y$. We write $X\ll Y$ if $CX\le Y$  for some large positive constants $C$ independent of $\la$. Let $d(\cdot, \cdot)$ be the Riemannian distance function on $M$.  Let $dV$ be the volume element of $M$. Let $\text{vol}(E)$ be the volume of the set $E\subset M$. Let $B(z,r)$ be the geodesic ball in $M$ centered at $z$ of radius $r$, and $\mathbb{B}(z,r)$ be the Euclidean ball in $\mathbb{R}^m$ centered at $z$ of radius $r$.

