\left[ \mathbf{v}_2\mathbf{v}_2^H\right]_{i,j} \cdot 
\left[ \mathbf{a}_r^H(\mathbf{p}) \, \overline{\mathbf{a}}_{\text{R},k}(\mathbf{p})\right]_i \cdot
\left[ \overline{\mathbf{a}}_{\text{R},k}^H(\mathbf{p}) \, \mathbf{a}_r(\mathbf{p}) \right]_j\\
=&Z_{\mu,\text{1}}\sum_{i=1}^{L} \sum_{j=1}^{L}
\left[ \mathbf{v}_2\mathbf{v}_2^H\right]_{i,j} \\&
\cdot e^{-j \frac{2\pi}{\lambda} \left( d_{r,i}(\mathbf{p}_i) - d_{\text{S},k,i}(\mathbf{p}_i) \right)} \cdot 
e^{j \frac{2\pi}{\lambda} \left( d_{r,j}(\mathbf{p}_j) - d_{\text{S},k,j}(\mathbf{p}_j) \right)},\label{66}
\end{aligned}
\end{equation}
where $d_{r,l}(\mathbf{p}_l)  = p_{x,l} \sin(\phi_{r}) \cos(\psi_r) + p_{y,l} \sin(\psi_{r})$ and $d_{\text{S},k,l}(\mathbf{p}_l) = p_{x,l} \sin(\phi_{\text{R},k}) \cos(\psi_{\text{R},k}) + p_{y,l} \sin(\psi_{\text{R},k}).$
It is evident that when \( i = j \), the complex exponential components cancel each other out, resulting in constant terms that are independent of the position variable \( \mathbf{p} \). Moreover, since \(  \mathbf{v}_2\mathbf{v}_2^H\) is a Hermitian matrix, the terms with \( i \neq j \) appear in conjugate pairs. Leveraging this structure, and by focusing on the \( l \)th element (i.e., when \( i = l \) or \( j = l \)) while discarding the constant terms associated with \( i = j \),  the optimization-equivalent form of \eqref{66} is given by
\vspace{-1.0ex}
\begin{equation} \small
\begin{aligned}
\mathbf{A}_{\mu,\text{1}}(\mathbf{p}_l)& \equiv  Z_{\mu,\text{1}} \sum_{\mathclap{i=1,\; i \neq l}}^{L}
2\Re \{ \left[\mathbf{v}_2\mathbf{v}_2^H \right]_{i,l}\\& \cdot 
e^{-j \frac{2\pi}{\lambda} \left( d_{r,i}(\mathbf{p}_i) - d_{\text{S},k,i}(\mathbf{p}_i) \right)} \cdot 
e^{j \frac{2\pi}{\lambda} \left( d_{r,l}(\mathbf{p}_l) - d_{\text{S},k,l}(\mathbf{p}_l) \right)}\}.\label{38}
\end{aligned}
\end{equation}
It can be observed that the term 
\( \left[ \mathbf{v}_2 \mathbf{v}_2^H \right]_{i,l} \cdot 
e^{-j \frac{2\pi}{\lambda} \left( d_{r,i}(\mathbf{p}_i) - d_{\text{S},k,i}(\mathbf{p}_i) \right)} \)
is independent of \( \mathbf{p}_l \) when only the \( l \)th element is considered. Therefore, it can be treated as a constant, denoted by \( s_{i,l,k} \). Since the amplitude of \( s_{i,l,k} \) is equal to 1,  \eqref{66} can be further simplified as
\begin{equation} \small
\begin{aligned}
\mathbf{A}_{\mu,\text{1}}(\mathbf{p}_l)& \equiv Z_{\mu,\text{1}} \sum_{\mathclap{i=1,\; i \neq l}}^{L}
2\Re \{ s_{i,l,k}
e^{j \frac{2\pi}{\lambda} \left( d_{r,l}(\mathbf{p}_l) - d_{\text{S},k,l}(\mathbf{p}_l) \right)}\}
\\&\equiv Z_{\mu,\text{1}} \sum_{\mathclap{i=1,\; i \neq l}}^{L}\cos{(\angle s_{i,l,k} +\frac{2\pi}{\lambda}\Delta d_{k,l}(\mathbf{p}_l)) },\label{39}
\end{aligned}
\end{equation}
where $\angle s_{i,l,k}$ denotes the phase of $s_{i,l,k}$, and $\Delta d_{k,l}(\mathbf{p}_l)$ denotes the term of $\left( d_{r,l}(\mathbf{p}_l) - d_{\text{S},k,l}(\mathbf{p}_l) \right)$. 

Next, by optimizing the position of one FSTAR-RIS element at a time, we further simplify \eqref{41A} and \eqref{42} as
\begin{equation} \small
\begin{aligned}
&\mathbf{A}_{\mu,\text{2}}(\mathbf{p}_l)=
\tilde Z_{\mu,\text{2},l}e^{-j \frac{2\pi}{\lambda} \left( d_{r,l}(\mathbf{p}_l) - d_{\text{S},k,l}(\mathbf{p}_l) \right)}
=\tilde Z_{\mu,\text{2},l}e^{-j \frac{2\pi}{\lambda} \Delta d_{k,l}(\mathbf{p}_l)}\\
=&\tilde Z_{\mu,\text{2},l}\left(\cos(-\frac{2\pi}{\lambda}\Delta d_{k,l}(\mathbf{p}_l))+j\sin(-\frac{2\pi}{\lambda}\Delta d_{k,l}(\mathbf{p}_l))\right),
\end{aligned}
\end{equation}
\begin{equation} \small
\begin{aligned}
&\mathbf{A}_{\mu,\text{3}}(\mathbf{p}_l) =
\tilde Z_{\mu,\text{3},l}e^{j \frac{2\pi}{\lambda} \left( d_{r,l}(\mathbf{p}_l) - d_{\text{S},k,l}(\mathbf{p}_l) \right)}
=\tilde Z_{\mu,\text{3},l}e^{j \frac{2\pi}{\lambda} \Delta d_{k,l}(\mathbf{p}_l)}\\&=\tilde Z_{\mu,\text{3},l}\left( \cos(\frac{2\pi}{\lambda}\Delta d_{k,l}(\mathbf{p}_l))+j\sin(\frac{2\pi}{\lambda}\Delta d_{k,l}(\mathbf{p}_l))\right) ,
\end{aligned}
\end{equation}
where $\tilde Z_{\mu,\text{2},l}=\left [Z_{\mu,\text{2}}\right ]_l$ and $\tilde Z_{\mu,\text{3},l}=\left [Z_{\mu,\text{3}}\right ]_l$. 

Define $\mathbf{T}_{\mu}(\mathbf{p}_l) =\mathbf{A}_{\mu,\text{2}}(\mathbf{p}_l)+\mathbf{A}_{\mu,\text{3}}(\mathbf{p}_l) $, we further simplify the expression by rewriting $\mathbf{T}_{\mu}$. Since $\tilde Z_{\mu,\text{2},l}=\tilde Z_{\mu,\text{3},l}^H$ and both are scalar values, they can be expressed as  
 $\tilde Z_{\mu,\text{2},l} = \Re(\tilde Z_{\mu,\text{2},l})+j\Im(\tilde Z_{\mu,\text{2},l})$, and $\tilde Z_{\mu,\text{3},l} = \Re(\tilde Z_{\mu,\text{2},l})-j\Im(\tilde Z_{\mu,\text{2},l})$. Applying the standard trigonometric properties $\cos(x)=\cos(-x)$
and $\sin(-x)=-\sin(x)$, we obtained:
\begin{equation} \small
\begin{aligned}
&\mathbf{T}_{\mu}(\mathbf{p}_l)=\left(\Re(\tilde Z_{\mu,\text{2},l})+j\Im(\tilde Z_{\mu,\text{2},l})
\right)\cos(\frac{2\pi}{\lambda}\Delta d_{k,l}(\mathbf{p}_l))
\\&
-\left(\Re(\tilde Z_{\mu,\text{2},l})+j\Im(\tilde Z_{\mu,\text{2},l})
\right)j\sin(\frac{2\pi}{\lambda}\Delta d_{k,l}(\mathbf{p}_l))
\\&+
\left(\Re(\tilde Z_{\mu,\text{2},l})-j\Im(\tilde Z_{\mu,\text{2},l})\right) \cos(\frac{2\pi}{\lambda}\Delta d_{k,l}(\mathbf{p}_l))\\&
+\left(\Re(\tilde Z_{\mu,\text{2},l})-j\Im(\tilde Z_{\mu,\text{2},l})\right)j\sin(\frac{2\pi}{\lambda}\Delta d_{k,l}(\mathbf{p}_l))\\=&
2\Re(\tilde Z_{\mu,\text{2},l}) \cos(\frac{2\pi}{\lambda}\Delta d_{k,l}(\mathbf{p}_l))
+2\Im(\tilde Z_{\mu,\text{2},l})\sin(\frac{2\pi}{\lambda}\Delta d_{k,l}(\mathbf{p}_l)).\label{45}
\end{aligned}
\end{equation}

This completes the derivation.

\section{Derivation of the Gradient and Hessian in \eqref{41}} \label{appendix:derivation3}

This appendix provides the detailed derivations of the gradient and Hessian matrices of $\mathbf{A}_{\mu,\text{1}}(\mathbf{p}_l)$ and $\mathbf{T}_{\mu}(\mathbf{p}_l)$ with respect to the position of the $l$th FSTAR-RIS element, denoted by $\mathbf{p}_l = [p_{x,l}, p_{y,l}]^T$.

To simplify the notation, we define the directional index $d \in \{x, y\}$ and the corresponding coefficients as
$\hat{D}_{x,k} = \frac{2\pi}{\lambda} \left( \sin(\phi_{r}) \cos(\psi_r) - \sin(\phi_{\text{R},k}) \cos(\psi_{\text{R},k}) \right), \quad 
\hat{D}_{y,k} = \frac{2\pi}{\lambda} \left( \sin(\phi_{r}) - \sin(\phi_{\text{R},k}) \right).$

Then, the partial derivatives of $\mathbf{A}_{\mu,\text{1}}(\mathbf{p}_l)$ are expressed as{\small
\begin{subequations} 
\begin{align}
\frac{\partial \mathbf{A}_{\mu,\text{1}}(\mathbf{p}_l)}{\partial p_{d,l}} &= -Z_{\mu,\text{1}} \hat{D}_{d,k} \sum_{\mathclap{i=1,\; i \neq l}}^{L} \sin\left( \angle s_{i,l,k} + \frac{2\pi}{\lambda} \Delta d_{k,l}(\mathbf{p}_l) \right), \\
\frac{\partial^2 \mathbf{A}_{\mu,\text{1}}(\mathbf{p}_l)}{\partial p_{d,l}^2} &= -Z_{\mu,\text{1}} \hat{D}_{d,k}^2 \sum_{\mathclap{i=1,\; i \neq l}}^{L} \cos\left( \angle s_{i,l,k} + \frac{2\pi}{\lambda} \Delta d_{k,l}(\mathbf{p}_l) \right), \\
\frac{\partial^2 \mathbf{A}_{\mu,\text{1}}(\mathbf{p}_l)}{\partial p_{x,l} \partial p_{y,l}} &= -Z_{\mu,\text{1}} \hat{D}_{x,k} \hat{D}_{y,k} \sum_{\mathclap{i=1,\; i \neq l}}^{L} \cos\left( \angle s_{i,l,k} + \frac{2\pi}{\lambda} \Delta d_{k,l}(\mathbf{p}_l) \right).
\end{align}
\end{subequations}}

The gradient and Hessian matrix are then assembled as
\[
\begin{aligned}
\nabla \mathbf{A}_{\mu,\text{1}}(\mathbf{p}_l) &= 
\begin{bmatrix}
\frac{\partial \mathbf{A}_{\mu,\text{1}}}{\partial p_{x,l}} &
\frac{\partial \mathbf{A}_{\mu,\text{1}}}{\partial p_{y,l}}
\end{bmatrix}^T, \\
\nabla^2 \mathbf{A}_{\mu,\text{1}}(\mathbf{p}_l) &= 
\begin{bmatrix}
\frac{\partial^2 \mathbf{A}_{\mu,\text{1}}}{\partial p_{x,l}^2} & \frac{\partial^2 \mathbf{A}_{\mu,\text{1}}}{\partial p_{x,l} \partial p_{y,l}} \\
\frac{\partial^2 \mathbf{A}_{\mu,\text{1}}}{\partial p_{y,l} \partial p_{x,l}} & \frac{\partial^2 \mathbf{A}_{\mu,\text{1}}}{\partial p_{y,l}^2}
\end{bmatrix}.
\end{aligned}
\]


Similarly, the partial derivatives of $\mathbf{T}_{\mu}(\mathbf{p}_l)$ are given by
\begin{subequations} \small
\begin{align}
\frac{\partial \mathbf{T}_{\mu}(\mathbf{p}_l)}{\partial p_{d,l}} &= 
-2\Re(\tilde Z_{\mu,2,l}) \hat{D}_{d,k} \sin\left(\frac{2\pi}{\lambda} \Delta d_{k,l}(\mathbf{p}_l)\right) 
\\&+ 2\Im(\tilde Z_{\mu,2,l}) \hat{D}_{d,k} \cos\left(\frac{2\pi}{\lambda} \Delta d_{k,l}(\mathbf{p}_l)\right), \\
\frac{\partial^2 \mathbf{T}_{\mu}(\mathbf{p}_l)}{\partial p_{d,l}^2} &= 
-2\Re(\tilde Z_{\mu,2,l}) \hat{D}_{d,k}^2 \cos\left(\frac{2\pi}{\lambda} \Delta d_{k,l}(\mathbf{p}_l)\right) 
\\&- 2\Im(\tilde Z_{\mu,2,l}) \hat{D}_{d,k}^2 \sin\left(\frac{2\pi}{\lambda} \Delta d_{k,l}(\mathbf{p}_l)\right), \\
\frac{\partial^2 \mathbf{T}_{\mu}(\mathbf{p}_l)}{\partial p_{x,l} \partial p_{y,l}} &= 
-2\Re(\tilde Z_{\mu,2,l}) \hat{D}_{x,k}\hat{D}_{y,k} \cos\left(\frac{2\pi}{\lambda} \Delta d_{k,l}(\mathbf{p}_l)\right) \notag\\
&\quad - 2\Im(\tilde Z_{\mu,2,l}) \hat{D}_{x,k}\hat{D}_{y,k} \sin\left(\frac{2\pi}{\lambda} \Delta d_{k,l}(\mathbf{p}_l)\right).
\end{align}
\end{subequations}

The gradient and Hessian matrix of $\mathbf{T}_{\mu}(\mathbf{p}_l)$ are thus given by
\[
\begin{aligned}
\nabla \mathbf{T}_{\mu}(\mathbf{p}_l) &= 
\begin{bmatrix}
\frac{\partial \mathbf{T}_{\mu}}{\partial p_{x,l}} &
\frac{\partial \mathbf{T}_{\mu}}{\partial p_{y,l}}
\end{bmatrix}^T, \\
\nabla^2 \mathbf{T}_{\mu}(\mathbf{p}_l) &= 
\begin{bmatrix}
\frac{\partial^2 \mathbf{T}_{\mu}}{\partial p_{x,l}^2} & \frac{\partial^2 \mathbf{T}_{\mu}}{\partial p_{x,l} \partial p_{y,l}} \\
\frac{\partial^2 \mathbf{T}_{\mu}}{\partial p_{y,l} \partial p_{x,l}} & \frac{\partial^2 \mathbf{T}_{\mu}}{\partial p_{y,l}^2}
\end{bmatrix}.
\end{aligned}
\]
This completes the derivation.

\section{Derivation of \eqref{56}} \label{appendix:derivation4}
It can be observed that \( \mathcal{C}_{\text{T},q} \) and \( \mathcal{D}_{\text{T},q} \) share the same structural form, differing only in the beamforming vectors. To streamline the formulation, we introduce a unified notation \( \mathbf{B}_\mu \), defined as
\begin{equation} \small
\mathbf{B}_\mu = |\mathbf{F}_{\text{T},q} \mathbf{w}_\mu|^2 
= Z_{\mu,1} \mathbf{a}_{\text{r}}(\mathbf{p})^H 
\overline{\mathbf{a}}_{\text{T},q}(\mathbf{p}) \mathbf{v}_2 \mathbf{v}_2^H 
\overline{\mathbf{a}}_{\text{T},q}^H(\mathbf{p}) \mathbf{a}_{\text{r}}(\mathbf{p}),
\end{equation}
where \( \overline{\mathbf{a}}_{\text{T},q}(\mathbf{p}) = \operatorname{diag}(\mathbf{a}_{\text{T},q}(\mathbf{p})) \). This expression is structurally identical to \( \mathbf{A}_{\mu,1} \), with only the angular steering vector replaced. Therefore, the derivation is omitted for brevity.

By considering a single element position \( \mathbf{p}_l = [p_{x,l}, p_{y,l}]^T \), the partial derivatives of \( \mathbf{B}_\mu(\mathbf{p}_l) \) are given by
\begin{subequations} \small \label{eq:main_equation}
\begin{align}
\frac{\partial \mathbf{B}_\mu(\mathbf{p}_l)}{\partial p_{d,l}} &= -Z_{\mu,1} \hat{D}_{d,q} \sum_{\mathclap{i=1,\; i \neq l}}^{L} \sin \left( \angle s_{i,l,q} + \frac{2\pi}{\lambda} \Delta d_{q,l}(\mathbf{p}_l) \right), \\
\frac{\partial^2 \mathbf{B}_\mu(\mathbf{p}_l)}{\partial p_{d,l}^2} &= -Z_{\mu,1} \hat{D}_{d,q}^2 \sum_{\mathclap{i=1,\; i \neq l}}^{L} \cos \left( \angle s_{i,l,q} + \frac{2\pi}{\lambda} \Delta d_{q,l}(\mathbf{p}_l) \right), \\
\frac{\partial^2 \mathbf{B}_\mu(\mathbf{p}_l)}{\partial p_{x,l} \partial p_{y,l}} &= \frac{\partial^2 \mathbf{B}_\mu(\mathbf{p}_l)}{\partial p_{y,l} \partial p_{x,l}} \notag \\
&= -Z_{\mu,1} \hat{D}_{x,q} \hat{D}_{y,q} \sum_{\mathclap{i=1,\; i \neq l}}^{L} \cos \left( \angle s_{i,l,q} + \frac{2\pi}{\lambda} \Delta d_{q,l}(\mathbf{p}_l) \right),
\end{align}
\end{subequations}
where \( d \in \{x, y\} \). The gradient and Hessian matrix are compactly expressed as
\[
\begin{aligned}
\nabla \mathbf{B}_\mu(\mathbf{p}_l) &= 
\begin{bmatrix}
\frac{\partial \mathbf{B}_\mu}{\partial p_{x,l}} &
\frac{\partial \mathbf{B}_\mu}{\partial p_{y,l}}
\end{bmatrix}^T, \\
\nabla^2 \mathbf{B}_\mu(\mathbf{p}_l) &= 
\begin{bmatrix}
\frac{\partial^2 \mathbf{B}_\mu}{\partial p_{x,l}^2} & \frac{\partial^2 \mathbf{B}_\mu}{\partial p_{x,l} \partial p_{y,l}} \\
\frac{\partial^2 \mathbf{B}_\mu}{\partial p_{y,l} \partial p_{x,l}} & \frac{\partial^2 \mathbf{B}_\mu}{\partial p_{y,l}^2}
\end{bmatrix}.
\end{aligned}
\]

The auxiliary terms \( \Delta d_{q,l} \), \( s_{i,l,q} \), and \( \hat{D}_{d,q} \) are omitted here for brevity.


