\section{Operators}\label{apdx:operators}

  We shall give the propositions and lemmas,
  and the symbols $\X$, $\X^*$, $\K$,
  $\XP$, $I^*$, $I$, $\MMM$ and $\Theta$ are the same spaces and operators presented in \Cref{sec:prelimnaries,sec:mainresult}.
  \begin{proposition}\label{prop:OpnormOfIandI*}
    Let $\X$ be a Banach space.
    $I^*:\X^*\to\XP$ and $I:\XP\to\X$ are bounded, and their operator norms satisfy
    \begin{equation*}
      \OPN{I^*} = \OPN{I} = \OPN{\K}^{1/2}.
    \end{equation*}
  \end{proposition}

  \begin{proof}
    Recall that $\K$ is a bounded linear operator between Banach space $\X^*$ and $\X$. The map $I^*:\X^*\to\XP$ is a bounded linear operator with $\OPN{I^*}\leq\OPN{\K}^{1/2}$, since 
    \begin{equation*}
      \norm{I^*\mu}_{\XP}^2
      = \innerp{\mu,\K\mu}
      \leq \OPN{\K}\norm{\mu}^2.
    \end{equation*}
    Moreover, $I:\XP\to\X$ is also a bounded linear operator with $\OPN{I}\leq\OPN{\K}^{1/2}$, since
    \begin{equation*}
      \begin{aligned}
        \norm{Iz}_{\X}
        &= \sup_{\norm{\mu}\leq1} \innerp{\mu,Iz}
        = \sup_{\norm{\mu}\leq1} \qty( I^*\mu, z )_{\XP} \\
        &\leq \sup_{\norm{\mu}\leq1} \norm{I^*\mu}_{\XP} \norm{z}_{\XP}
        \leq \OPN{\K}^{1/2} \norm{z}_{\XP}
      \end{aligned}
    \end{equation*}
    for any $z \in \XP$. Finally, $\OPN{\K} \leq \OPN{I}\OPN{I^*}$ leads us the consequence.
  \end{proof}

  \begin{lemma}\label{lem:sym_schwartz}
    For $\mu,\nu \in \MM$, we have
    \begin{equation*}
        \SN{\K\mu} \le \OPN{\K} \MTN{[\mu]},
        \quad 
        |\innerp{ \mu, \K\nu }| \le \SN{\K \mu} \MTN{[\nu]}
        \quad \text{and} \quad 
        \norm{ \K \mu }_{\HP}^2
        \le \OPN{\K} \norm{[\mu]}^2_{\MMM}
    \end{equation*}
  \end{lemma}

  \begin{proof}
    By the definition of the quotient norm, 
    \begin{equation*}
        \begin{aligned}
          \SN{\K\mu}
          &= \inf_{\varphi\in N} \SN{ \K (\mu+\varphi)}
          \le \inf_{\varphi\in N} \OPN{\K} \MN{\mu+\varphi}\\ 
          &= \OPN{\K} \inf_{\varphi\in N} \MN{\mu+\varphi}
          =\OPN{\K} \MTN{[\mu]}.
        \end{aligned}
    \end{equation*}
    In addition, since $\K$ is symmetric,
    \begin{equation*}
        \begin{aligned}
          |\innerp{ \mu, \K \nu }| 
          &= \inf_{\varphi\in N} \abs{ \innerp{ \nu, \K(\mu+\varphi) } }
          = \inf_{\varphi\in N}\abs{ \innerp{ \mu+\varphi, \K\nu } } \\
          &\le \inf_{\varphi\in N}\MN{\mu+\varphi} \SN{\K\nu}
          = \MTN{[\mu]} \SN{\K\nu}.
        \end{aligned}
    \end{equation*}
    Therefore, $\norm{ \K \mu }_{\HP}^2
        = \abs{ \innerp{ \mu, \K \mu } }
        \le \OPN{\K} \norm{[\mu]}^2_{\MMM}$.
  \end{proof}

  \begin{lemma}\label{lem:measure_partial_change}
    If $\mu_{\theta}$ is differentiable with respect to $\theta$, then 
    \begin{itemize}
      \item $\partial_i \innerp{ \mu_\theta, x } = \innerp{ \partial_i \mu_\theta, x }$ for $x \in \CC$.
      \item $\partial_i \innerp{ \mu_{\theta}, \K \mu_{\theta} } = 2 \innerp{ \partial_i\mu_{\theta}, \K \mu_{\theta} }$.
      \item Moreover, if $\mu_{\theta}$ is twice differentiable, then
        \begin{equation*}
            \partial_{ij} \innerp{ \mu_{\theta}, \K \mu_{\theta} } = 2 \innerp{ \partial_{ij} \mu_{\theta}, \K \mu_{\theta} } + 2 \innerp{ \partial_i\mu_{\theta}, \K (\partial_j\mu_{\theta}) }.
        \end{equation*}
        \end{itemize}
  \end{lemma}

  \begin{proof}
    Since $\MM=\CC^*$,  
    \begin{equation*}
      \partial_i \innerp{ \mu_\theta, x }
      = \lim_{\delta\to 0} \frac{ \innerp{ \mu_{\theta+\delta e_i}, x } - \innerp{ \mu_\theta, x } }{\delta}
      = \lim_{\delta\to 0} \innerp*{ \frac{\mu_{\theta+\delta e_i}-\mu_\theta}{\delta} , x }
      =\innerp{ \partial_i \mu_\theta, x }.
    \end{equation*}
    Similarly, we obtain 
    \begin{align*}
      \partial_i  \innerp{ \mu_\theta, \K \nu_\theta }
      &= \lim_{\delta\to 0} 
        \frac{ \innerp{ \mu_{\theta+\delta e_i}, \K\nu_{\theta+\delta e_i} } - \innerp{ \mu_\theta, \K\nu_\theta } }{\delta} \\
      &= \lim_{\delta\to 0} 
        \qty{ \innerp*{\frac{\mu_{\theta+\delta e_i} - \mu_\theta}{\delta}, \K \nu_\theta} 
        + \innerp*{\mu_{\theta+\delta e_i}, \K \frac{\nu_{\theta+\delta e_i}-\nu_\theta}{\delta}}}\\
      &= \innerp{\mu_\theta, \K(\partial_i \nu_\theta)} + \innerp{\partial_i \mu_\theta, \K \nu_\theta}.
    \end{align*}
    Moreover, it follows that
    \begin{align*}
      \partial_{ij} \innerp{ \mu_{\theta}, \K \mu_{\theta} }
      &= 2 \, \partial_j \innerp{ \partial_i\mu_{\theta}, \K \mu_{\theta} } \\
      &= 2 \lim_{\delta\to 0} 
        \frac{\innerp{ \partial_i\mu_{\theta+ \delta e_j}, \K\mu_{\theta+ \delta e_j} } 
        - \innerp{ \partial_i\mu_{\theta+ \delta e_j}, \K \mu_{\theta} } }{\delta} \\ 
      &\quad 
        + 2 \lim_{\delta\to 0} 
        \frac{ \innerp{ \partial_i\mu_{\theta+ \delta e_j}, \K\mu_\theta } 
        - \innerp{ \partial_i\mu_{\theta}, \K \mu_{\theta} } }{\delta}\\
      &= 2 \innerp*{ \partial_{ij} \mu_{\theta}, \K \mu_{\theta} } 
        + 2 \innerp*{ \partial_i\mu_{\theta}, \K (\partial_j\mu_{\theta}) }.
    \end{align*}
  \end{proof}

  \begin{lemma}\label{lem:convergence of discret.mu}
    For $\theta\in\Theta$ and $\mu_\theta \in \MM$,
    \begin{itemize}
      \item If $\mu_\theta$ is differentiable with respect to $\theta$, then discretization operator $(\cdot)^n$ for $\mu_\theta$ and the differential operator $\partial_i=\pdv{\theta_i}$ are commutable, i.e., $\partial_i \left(\mu^n_\theta \right) = \left(\partial_i \mu_\theta \right)^n$. 
      \item $\sup_{n\in\N}\MN{\mu^n_\theta} \le \MN{\mu_\theta}$.
      \item The sequence $\{\mu^n_\theta\}_{n\in \mathbb{N}}$ converges 
            in the weak$^{*}$ topology to $\mu_\theta$, 
            i.e.,
            $\innerp{\mu^n_\theta,f} \to \innerp{\mu_\theta,f},\quad n\to\infty$ for any $f\in \CC$. 
            Moreover, if $f\in \K(\M)$ and $\sup_{\theta} \MN{\mu_\theta}<\infty$, 
            then this convergence holds uniformly with respect to $\theta\in\Theta$:
            \begin{equation*}
              \sup_{\theta\in\Theta} \abs{ \innerp{\mu^n_\theta,f} - \innerp{\mu_\theta,f} } \to 0,\quad n\to\infty.
            \end{equation*}
      \item $\OPN{\K^n- \K}\to 0,\quad n\to\infty$.
    \end{itemize}
  \end{lemma}

  \begin{proof}
    It follows from the definition of $\partial_j(\mu^n_\theta)$ that
    \begin{align*}
      \partial_j(\mu^n_\theta) 
      &= \lim_{\gamma\to 0} \frac{\sum_{i=1}^n \mu_{\theta+\gamma e_j}(T_i^n) \, \delta_{t_i^n} - \sum_{i=1}^n \mu_{\theta}(T_i^n) \, \delta_{t_i^n}}{\gamma}\\
      &= \lim_{\gamma\to 0} \sum_{i=1}^n \frac{\mu_{\theta+\gamma e_j}-\mu_\theta}{\gamma}(T_i) \, \delta_{t_i}
      = \sum_{i=1}^n \qty( \partial_j\mu_\theta ) \qty(T_i) \, \delta_{t_i}
      = \qty( \partial_j\mu_\theta )^n.
    \end{align*}
    We see that
    \begin{equation*}
      \MN{\mu^n_\theta}
      = \sup_{\SN{f}\le 1} \abs{ \innerp{ \mu^n_\theta, f } }
      \le \sup_{\SN{f}\le 1} \sum_{i=1}^n \int_{T_i} \abs{ 
      f(t_i^n) } \, \abs{\mu_\theta}(\dd{s})
      \le \MN{\mu_\theta}.
    \end{equation*}

    For any $f \in \CC$,
    \begin{equation*}
        \begin{aligned}
          \abs{ \innerp{ \mu^n_\theta-\mu_\theta, f } }
          &= \abs{ \sum_{i=1}^n \mu_\theta(T^n) f(t_i) - \int_T f(t) \, \mu_\theta(\dd{t}) } \\
          &= \abs{ \int_T \qty(f^n(t) - f(t)) \, \mu_\theta(\dd{t}) }
          = \abs{ \innerp{\mu_\theta,f^n-f} }.
        \end{aligned}  
    \end{equation*}
    Since $f$ is uniformly continuous on $T$ 
    and $\displaystyle \lim_{n\to \infty} \sup_{i=1,\dots,n} |t_i-t_{i-1}| =0$, 
    \begin{equation*}
      \innerp{\mu^n_\theta,f} \to \innerp{\mu_\theta,f},\quad n\to\infty.
    \end{equation*}
    Moreover, if there exists $\nu\in\M$ such that $f=\K \nu$, then
    \begin{equation*}
      \sup_{\theta\in\Theta} \abs{ \innerp{\mu^n_\theta - \mu_\theta, f} } =\sup_{\theta\in\Theta} \abs{ \innerp{\mu_\theta, (\K\nu)^n-\K\nu)} } 
      \le \sup_{\theta\in\Theta} \MN{\mu_\theta}\SN{(\K\nu)^n - \K\nu}.
    \end{equation*}
    Therefore, we obtain uniform convergence in $\theta$.

    Since $K(s,t)$ is uniformly continuous and $\displaystyle \lim_{n\to \infty} \sup_{i=1,\dots,n} |t_i-t_{i-1}| =0$,
    \begin{equation*}
        \begin{aligned}
          \OPN{\K^{n}-\K} 
          &= \sup_{\MN{\mu}\le 1} \SN{\left(\K^{n}-\K \right)\mu}
          = \sup_{\MN{\nu}\le 1} \sup_{\MN{\mu}\le 1} \abs{ \innerp{\nu,( \K^{n}-\K ) \mu} }\\
          &\le \sup_{\MN{\nu}\le 1} \sup_{\MN{\mu}\le 1} \sum_{i,j=1}^n \int_{\substack{{s\in T_i}\\ {t\in T_j}}} \abs{ K(t_i, t_j) - K(s,t) } \, \abs{\mu}(\dd{s}) \, \abs{\mu}(\dd{t})\\
          &\le \sup_{\MN{\nu}\le 1} \sup_{\MN{\mu}\le 1} \MN{\mu} \MN{\nu} \max_{i,j=1,\dots,n} \sup_{\substack{{s\in T_i}\\ {t\in T_j}}} \left| K(t_i, t_j) - K(s,t) \right|
          \to 0,
        \end{aligned}
    \end{equation*}
    as $ n\to \infty$.
  \end{proof}

\section{Fundamental Tools}

    In this section, we introduce two fundamental tools.

  \begin{proposition}\label{prop:M-estimator}
    Let $ (\Phi_\varepsilon)_{\varepsilon>0}$ be a family of random functions on $\Theta$, and let $\Phi$ be a deterministic function on $\Theta$ such that for every $\delta>0$ and some $\theta_0\in\Theta$;
    \begin{equation}
        \begin{aligned}
            \sup_{\theta\in\Theta} |\Phi_\varepsilon(\theta)-\Phi(\theta)| 
            &\asconv 0, \quad \varepsilon\to 0,\\
            \sup_{\|\theta - \theta_0\|>\delta} \Phi(\theta)
            &< \Phi(\theta_0).
        \end{aligned}
        \label{eq:assump2}
    \end{equation}
    Then, any sequence of estimators $\hat{\theta}_\varepsilon$ satisfying that  $\Phi_\varepsilon ( \hat{ \theta }_\varepsilon ) \ge \Phi_\varepsilon (\theta_0)$ converges almost surely to $\theta_0$.
  \end{proposition}
  \begin{proof}
    The proof is almost the same as for Theorem 5.7 in \textcite{vaart1998asymptotic}. 
    \begin{equation}\label{eq:osaekomi}
      \Phi(\theta_0) - \Phi(\hat{\theta}_\varepsilon )
      \le \Phi_\varepsilon(\hat{\theta}_\varepsilon) - \Phi(\hat{\theta}_\varepsilon) + o(1)\asconv 0,
    \end{equation}
    as $\varepsilon \to 0$, where $o(1)$ means a sequence in $\R$ which converges to $0$.
    By \Cref{eq:assump2}, for any $\delta>0$, there exists $\eta>0$ such that 
    if $\abs{\theta-\theta_0} \ge \delta$, then $\Phi(\theta) < \Phi(\theta_0) -\eta. $        
    By contraposition, if
    $\Phi(\theta_0) - \Phi(\theta) \le \eta$ ,then
    $\abs{\theta-\theta_0}
    < \delta.$
    Then, by \Cref{eq:osaekomi},
    there exists $\varepsilon_0>0$ such that if $ 0<\varepsilon<\varepsilon_0 $, then
    $\Phi(\theta_0) - \Phi(\hat{\theta}_\varepsilon) \le \eta $
    which implies $\hat{\theta}_\varepsilon \to \theta_0$ as $\varepsilon \to 0$.
  \end{proof}

  \begin{remark}\label{rmk:DefOfEstimator}
    In order to present a more rigorous proof for \Cref{prop:M-estimator}, 
    we should set $\hat{\theta}_\varepsilon$ in the statement as 
    \begin{equation*}
      \hat{\theta}_\varepsilon \coloneqq 
      \Set{ \theta\in\Theta | \Phi_\varepsilon(\theta) > \Phi_\varepsilon(\theta_0) + o_\varepsilon },
    \end{equation*}
    where $o_\varepsilon$ is a sequence in $\R$ with $o_\varepsilon=o(1)$.
    Then, by the same argument, we obtain 
    \begin{equation*}
      \sup_{\theta\in\hat{\theta}_\varepsilon} \abs{ \theta - \theta_0 }
      \asconv 0
      \quad \text{as} \  
      \varepsilon\to0.
    \end{equation*}
  \end{remark}

  \begin{proposition}[Morrey's inequality]\label{prop:Morrey}
    Let $\Theta\subseteq\mathbb{R}^p$ be a closed bounded convex set with smooth boundary and with an interior point.
    For $\mu_\bullet\in\CkThM[1]$, $f\in\CC$ and $q>p$,
    \begin{equation*}
      \sup_{\theta\in\Theta} \abs{ \innerp*{ \mu_\theta, f } }
      \leq C \qty{ \qty( \int_\Theta \abs{ \innerp*{ \mu_\theta, f } }^q  \dd{\theta} )^{1/q}
      + \sum_{i=1}^p \qty( \int_\Theta \abs{ \innerp*{ \partial_i \mu_\theta, f } }^q  \dd{\theta} )^{1/q} },
    \end{equation*}
    where the constant $C$ depends only on $p$, $q$ and $\Theta$.
  \end{proposition}

  \begin{proof}
    Let $f\in\CC$.
    \Cref{lem:measure_partial_change} implies that $\innerp*{ \mu_\bullet, f }:\Theta\to\mathbb{R}$, $\theta\mapsto\innerp*{ \mu_\theta, f }$ is differentiable with bounded derivatives, 
    so that $\innerp{\mu_\bullet,f}\in W^{1,q}(\Theta)$ for any $q\geq1$, in particular, for any $q>p$.
    Thus, the conclusion holds by the usual Morrey inequality (see, e.g., Theorem 5.6.5 in \textcite{evans2010partial}).
  \end{proof}

\section{Usual argument to see \Cref{thm:QGAIC}}\label{sec:AnotherProofModelSelection}

  \begin{lemma}\label{lem:r1}
    For $A'_{n,\varepsilon}$ in the proof in \Cref{thm:dis_parametric asymptotic normality}, let us denote by 
    \begin{equation*}
      r^1_{n,\varepsilon} \coloneqq \left(\grad_\theta \Phi_{n,\varepsilon}(\hat\theta_{n,\varepsilon})\right)^\transp (\hat\theta_{n,\varepsilon} -\theta_0)  \idv_{(A'_{n,\varepsilon})^\complement}.
    \end{equation*}
    Under \Cref{assump:Theta,assump:cont,assump:isolated,assump:convex_Theta,assump:Sigma_regular,assump:convergent_rate,assump:MuIsC^2}, it holds that
    \begin{equation*}
      \E \qty[ \abs{ r^1_{n,\varepsilon} } ] = o(\varepsilon^2),
      \quad \varepsilon\to 0, \  n\to\infty.
    \end{equation*}
  \end{lemma}

  \begin{proof}
    It follows from \Cref{thm:dis_parametric_consistency} that, for any $\eta>0$,
    \begin{equation*}
      \Prob(\varepsilon^{-2}r_{n,\varepsilon}^1 > \eta) < \Prob((A_{n,\varepsilon})^\complement)\to 0, \quad \varepsilon\to 0, \  n\to \infty, 
    \end{equation*}
    and that, from \Cref{assump:MuIsC^2,lem:convergence of discret.mu},  
    \begin{align*}
      \abs{ \partial_i \Phi_{n,\varepsilon}(\hat\theta_{n,\varepsilon}) }^2 
      &= \abs{ \innerp{\partial_i \hat{\mu}_{n,\varepsilon}^n, h_0+\varepsilon Z} - \innerp{\partial_i \hat{\mu}_{n,\varepsilon}^n, \K \hat{\mu}_{n,\varepsilon}^n} }^2 \\
      &= \abs{ \innerp{\partial_i \hat{\mu}_{n,\varepsilon}^n, \K \mu_{\theta_0}} + \varepsilon \innerp{\partial_i \hat\mu_{n,\varepsilon}^n, Z} - \innerp{\partial_i \hat{\mu}_{n,\varepsilon}^n, \K \hat{\mu}_{n,\varepsilon}^n} }^2 \\
      &\le 2 \varepsilon^2 \innerp*{\partial_i \hat{\mu}_{n,\varepsilon}^n, Z}^2 
      + 2 \innerp{(\partial_i  \hat{\mu}_{n,\varepsilon})^n - \partial_i \mu_{\theta_0} , \K (\hat{\mu}_{n,\varepsilon})^n}^2,
    \end{align*}
    for any $i=1,\dots,p$.
    Since $Z$ is a Gaussian vector, we have that 
    \begin{equation*}
      \E\qty[ \innerp{\partial_i \hat{\mu}_{n,\varepsilon}^n, Z}^2 ] 
      = \innerp{\partial_i \hat{\mu}_{n,\varepsilon}^n, \K \partial_i \hat{\mu}_{n,\varepsilon}^n}
      = \innerp{\partial_i \hat{\mu}_{n,\varepsilon}, \K^n \partial_i \hat{\mu}_{n,\varepsilon}}.
    \end{equation*}
    Therefore 
    $\E[ | \grad_\theta \Phi_{n,\varepsilon}(\hat\theta_{n,\varepsilon}) |^2 ]$ is bounded by \Cref{assump:MuIsC^2,lem:convergence of discret.mu},.
    Thus,  we obtain from \Cref{prop:MomentConvergence} and H\"{o}lder's inequality that
    \begin{align*}
      \E \qty[ \abs{ r_{n,\varepsilon}^1 } ] 
      &= 
        \E\qty[ \qty( \grad_\theta \Phi_{n,\varepsilon}(\hat\theta_{n,\varepsilon}) )^2 ]^{1/2} 
        \E\qty[\abs{\varepsilon^{-1}(\hat\theta_{n,\varepsilon}-\theta_0)}^3 ]^{1/3} 
        \E\qty[ \idv_{(A'_{n,\varepsilon})^\complement} ]^{1/6} \\
      &= 
        \E\qty[ \qty(\grad_\theta \Phi_{n,\varepsilon}(\hat\theta_{n,\varepsilon}) )^2 ]^{1/2} 
        \E \qty[ \abs{ \varepsilon^{-1}(\hat\theta_{n,\varepsilon} -\theta_0) }^3 ]^{1/3} 
        \Prob((A'_{n,\varepsilon})^\complement)^{1/6} \\
      &=o(\varepsilon^2),
    \end{align*}
    as $\varepsilon\to 0$ and $n\to\infty$.
  \end{proof}

  \begin{lemma}\label{lem:r2} 
    For any $u\in(0,1)$ and $\widetilde{\theta}_{n,\varepsilon}'\coloneqq u \theta_0 + (1-u) \hat{\theta}_{n,\varepsilon}$, let 
    \begin{align*}
      r_{n,\varepsilon}^2 
      &\coloneqq 
      \frac12 (\hat{\theta}_{n,\varepsilon} - \theta_0)^\transp \left\{\nabla_\theta^2 \Phi(\widetilde{\theta}_{n,\varepsilon}) - \nabla_\theta^2 \Phi(\theta_0)\right\} (\hat{\theta}_{n,\varepsilon}-\theta_0),\\
      r_{n,\varepsilon}^3 
      &\coloneqq 
      \frac12 (\hat{\theta}_{n,\varepsilon} - \theta_0)^\transp \left\{\nabla_\theta^2 \Phi_{n,\varepsilon}(\widetilde{\theta}_{n,\varepsilon}) - \nabla_\theta^2 \Phi(\widetilde{\theta}_{n,\varepsilon})\right\} (\hat{\theta}_{n,\varepsilon}-\theta_0).
    \end{align*}
    Under \Cref{assump:Theta,assump:cont,assump:isolated,assump:convex_Theta,assump:Sigma_regular,assump:MuIsC^3,assump:SmoothBoundaryForMorrey,assump:convergent_rate,assump:MuIsC^2}, it follows that
    \begin{equation*}
      \E\qty[ \abs{ r_{n,\varepsilon}^2 } ] 
      = o(\varepsilon^2) 
      \quad \text{and} \quad
      \E \qty[ \abs{ r_{n,\varepsilon}^3 } ] 
      = o(\varepsilon^2),\quad \varepsilon\to 0, \  n\to\infty.
    \end{equation*}
  \end{lemma}

  \begin{proof}
    The function $\theta\mapsto \nabla_{\theta}^2 \Phi(\theta)$ is Lipschitz continuous: there exists $C>0$ such that
    \begin{equation*}
      \abs{ \nabla_{\theta}^2 \Phi(\theta_1) - \nabla_{\theta}^2 \Phi(\theta_2) } 
      < C \abs{ \theta_1 - \theta_2 }, 
    \end{equation*}
    for any $\theta_1, \theta_2 \in \Theta$.
    Therefore, we obtain from \Cref{prop:MomentConvergence} that 
    \begin{equation*}
      \E \qty[ \abs{ r_{n,\varepsilon}^2 } ] 
      \le \frac{C\varepsilon^3}2 
        \E \qty[ \abs{ \varepsilon^{-1}(\hat\theta_{n,\varepsilon} -\theta_0) }^3 ] 
      = \order{\varepsilon^3}
      \quad 
      \text{as} \  \varepsilon\to 0, \  n\to\infty.
    \end{equation*}    

    Moreover, it follows from \Cref{prop:MomentConvergence} and Schwarz's inequality that
    \begin{equation*}
      \E \qty[ \abs{ r_{n,\varepsilon}^3 } ] 
      \le \frac{\varepsilon^2}{2} \E \qty[ \sup_{\theta\in\Theta} \abs{ \nabla_\theta^2 \Phi_{n,\varepsilon}(\theta) - \nabla_\theta^2 \Phi(\theta) }^2 ]^{\frac{1}{2}} \E \qty[ \abs{ \varepsilon^{-1}(\hat\theta_{n,\varepsilon} -\theta_0) }^4 ]^{\frac{1}{2}}.
    \end{equation*}
    Therefore, it suffices to show by \Cref{prop:MomentConvergence} that
    \begin{equation*}
      \E\left[\sup_{\theta\in\Theta} \left| \nabla_\theta^2 \Phi_{n,\varepsilon}(\theta) - \nabla_\theta^2 \Phi(\theta) \right|^2 \right] < \infty,\quad \varepsilon\to 0, \  n\to\infty.
    \end{equation*}

    For $j,k=1,\dots,p$, 
    it is analogous to the proof of \Cref{lem:discrete_twice_nabla_uni_conv} that
    \begin{align*}
      &\sup_{\theta\in\Theta} \left|\partial_{jk} \left\{\Phi_{n,\varepsilon} (\theta)- \Phi(\theta) \right\}\right|^2 \\
      \le& \sup_{\theta\in\Theta}
      \Bigl\{ \varepsilon\innerp{(\partial_{jk} \mu_\theta)^n,Z} + \innerp{(\partial_{jk}\mu_\theta)^n -\partial_{jk}\mu_\theta, \K\mu_0}\\
      &\qquad\qquad\left.
      +\OPN{\K^n-\K}\left(\MN{\partial_{jk}\mu_\theta}\MN{\mu_\theta} + \MN{\partial_{j}\mu_\theta}\MN{\partial_k\mu_\theta}\right)\right\}^2\\
      \le& \sup_{\theta\in\Theta}
      4 \Bigl\{ \varepsilon\innerp{(\partial_{jk} \mu_\theta)^n,Z}^2 + \innerp{(\partial_{jk}\mu_\theta)^n -\partial_{jk}\mu_\theta, \K\mu_0}^2\\
      &\qquad\qquad\left.
      +\OPN{\K^n-\K}^2\left(\MN{\partial_{jk}\mu_\theta}\MN{\mu_\theta} + \MN{\partial_{j}\mu_\theta}\MN{\partial_k\mu_\theta}\right)^2\right\}.
    \end{align*}
    By \Cref{assump:MuIsC^3,assump:Theta,lem:convergence of discret.mu}, the proof ends if we show that there exists $C>0$ independent of $n,j,k$ such that
    \begin{equation}
        \E \qty[ \sup_{\theta\in\Theta} \innerp{(\partial_{jk} \mu_\theta)^n,Z}^2 ] < C
        \label{eq:AICD1Bdd}.
    \end{equation}
    Applying \Cref{prop:Morrey} from \Cref{assump:MuIsC^3}, we see that there exists a constant $C_1>0$ depending only on $p,q,\Theta$ such that
    \begin{equation}
        \begin{aligned}
            & \E \qty[ \sup_{\theta\in\Theta} \innerp{(\partial_{jk} \mu_\theta)^n,Z}^2 ] \\
            &\quad \le 2C_1 \qty{ \E \qty[ \qty( \int_\Theta \abs{ \innerp*{ \partial_{jk}\mu_\theta, Z } }^q  \dd{\theta} )^{2/q} ]
            + \sum_{i=1}^p \E \qty[ \qty( \int_\Theta \abs{ \innerp*{ \partial_{ijk} \mu_\theta, Z } }^q  \dd{\theta} )^{2/q} ] }.
        \end{aligned}
        \label{eq:AICD1BddMor}
    \end{equation}
    Since $\innerp*{ \partial_{ijk} \mu_\theta, Z }\sim N\left(0,\innerp*{\partial_{ijk} \mu_\theta, \K (\partial_{ijk} \mu_\theta)}  \right)$, it follows from \Cref{assump:MuIsC^3} that 
    \begin{equation*}
        \E\left[\innerp*{ \partial_{ijk} \mu_\theta, Z } ^{2q}\right] 
        = 
        \frac{(2q)!}{2^q\cdot q!}
        \innerp*{ \partial_{ijk} \mu_\theta, \K \partial_{ijk} \mu_\theta} ^q
        \le \frac{(2q)!}{2^q\cdot q!} 
        \MN{\partial_{ijk} \mu_\theta}^2 \OPN{\K}, 
    \end{equation*}
    and by \Cref{assump:MuIsC^3,assump:Theta},
    \begin{equation}
        \E\left[\qty( \int_\Theta \abs{ \innerp*{ \partial_{ijk} \mu_\theta, Z} }^q  \dd{\theta} )^{2/q} \right] 
        \le C_1\qty( \int_\Theta \E\left[\innerp*{ \partial_{ijk} \mu_\theta, Z } ^{2q}\right] \dd{\theta} )^\frac{1}{q}
        \leq C_2
        \MN{\partial_{ijk} \mu_\theta}^{2} \OPN{\K},
        \label{eq:AICD1Bdd1}
    \end{equation}
    where the constant $C_2$ depends only on $p,q$ and $\Theta$. Similarly, we obtain
    \begin{equation}
        \E\left[ \qty( \int_\Theta \abs{ \innerp*{ \partial_{jk}\mu_\theta, Z} }^q  \dd{\theta} )^{2/q}\right]
        \leq C_2
        \MN{\partial_{jk} \mu_\theta}^{2} \OPN{\K}.
        \label{eq:AICD1Bdd2}
    \end{equation}
    By combining \cref{eq:AICD1BddMor,eq:AICD1Bdd1,eq:AICD1Bdd2}, we obtain \Cref{eq:AICD1Bdd}. This completes the proof. 
  \end{proof}

  \begin{proof}[Proof of \Cref{thm:QGAIC}]
      \begin{align*}
            \Phi_{n,\varepsilon}(\hat{\theta}_{n,\varepsilon})-\Phi(\hat{\theta}_{n,\varepsilon}) 
            &= \qty\Big(\Phi_{n,\varepsilon}(\hat{\theta}_{n,\varepsilon}) - \Phi_{n,\varepsilon}(\theta_0))
                + \qty\Big(\Phi_{n,\varepsilon}(\theta_0) - \Phi(\theta_0))
                + \qty\Big(\Phi(\theta_0) - \Phi(\hat{\theta}_{n,\varepsilon})) \\
            &\eqqcolon D_1 + D_2 + D_3.
      \end{align*}
      By Taylor's formula, there exist  $u_1\in(0,1)$ and $\widetilde{\theta}_{n,\varepsilon}'\coloneqq u_1 \theta_0 + (1-u_1) \hat{\theta}_{n,\varepsilon}$ such that 
      \begin{align*}
          D_1
          =& \left(\grad_\theta \Phi_{n,\varepsilon}(\hat{\theta}_{n,\varepsilon}) \right)^\transp (\hat\theta_{n,\varepsilon} -\theta_0) (\idv_{A'_{n,\varepsilon}} + \idv_{(A'_{n,\varepsilon})^\complement}) 
          + \frac{1}{2} (\hat{\theta}_{n,\varepsilon} -\theta_0)^\transp \left(\nabla_\theta^2 \Phi_{n,\varepsilon}(\widetilde{\theta}_{n,\varepsilon})\right) (\hat{\theta}_{n,\varepsilon} - \theta_0)\\
          =& -\frac{1}{2} (\hat{\theta}_{n,\varepsilon} - \theta_0)^\transp \Sigma(\hat{\theta}_{n,\varepsilon} - \theta_0) + r_{n,\varepsilon}^1 + r_{n,\varepsilon}^2 + r_{n,\varepsilon}^3.
      \end{align*}
      Thus, we see by \Cref{lem:r1,lem:r2} that
      \begin{equation}
          \begin{aligned}
              \varepsilon^{-2}\E\left[D_1 \right] 
              &=-\frac{1}{2}\E\left[\frac{1}{\varepsilon}(\hat{\theta}_{n,\varepsilon} - \theta_0)^\transp \;\Sigma\; \frac{1}{\varepsilon}(\hat{\theta}_{n,\varepsilon} - \theta_0) \right] +o(1)\\
              &= -\frac{1}{2} \tr\left(\Sigma\ \E\left[\frac{1}{\varepsilon}(\hat{\theta}_{n,\varepsilon} - \theta_0)^\transp\;\frac{1}{\varepsilon}(\hat{\theta}_{n,\varepsilon} - \theta_0)\right]\right) +o(1) \\
              &= -\frac{1}{2} \tr\left(\Sigma\Sigma^{-1}\right) + o(1)
              = -\frac{p}{2} + o(1), \quad \varepsilon\to 0, \  n\to\infty.
          \end{aligned}
          \label{eq:AIC_D1}
      \end{equation}

      Since $Z$ is a centered Gaussian vector, it follows by \Cref{eq:ConvergenceRateForAIC} and the same argument of \labelcref{eq:NormConvergenceOfMeanByCovSmoothness} that
      \begin{equation} 
          \varepsilon^{-2}\E\left[D_2\right] 
          = \varepsilon^{-2}\innerp{\mu_{\theta_0}, \K (\mu^n_{\theta_0}-\mu_{\theta_0})} 
          - \frac{1}{2\varepsilon^2}\innerp{\mu_{\theta_0}, (\K^n - \K)\mu_{\theta_0}}
          = o(1) 
          \label{eq:AIC_D2} 
      \end{equation}
      as $\varepsilon\to0$, $n\to\infty$.

          By \Cref{assump:Theta,assump:MuIsC^2}, $\nabla^2_\theta \Phi_{n,\varepsilon}$ is continuous on the bounded set $\Theta$. Applying Taylor's formula, there exists $u_2\in(0,1)$ and $\theta_{n,\varepsilon}'\coloneqq u_2 \theta_0 + (1-u_2) \hat{\theta}_{n,\varepsilon}$ such that
      \begin{equation*}
          D_3 = \frac{1}{2} (\hat{\theta}_{n,\varepsilon} - \theta_0)^\transp \nabla_\theta^2 \Phi(\theta_0)  (\hat{\theta}_{n,\varepsilon}-\theta_0)
          +\frac{1}{2} (\hat{\theta}_{n,\varepsilon} - \theta_0)^\transp \qty{ \nabla_\theta^2 \Phi(\theta_{n,\varepsilon}') - \nabla_\theta^2 \Phi(\theta_0) } (\hat{\theta}_{n,\varepsilon}-\theta_0).
      \end{equation*}
      Analogously to the discussion to obtain \Cref{eq:AIC_D1},
      \begin{equation*}
          \varepsilon^{-2}\E[D_3] = -\frac{p}{2} + o(1),\quad \varepsilon\to 0, \  n\to \infty.
          \label{eq:AIC_D3}
      \end{equation*}

      By combining \Cref{eq:AIC_D1,eq:AIC_D2}
      \begin{equation*}
          \E \qty[ \Phi_{n,\varepsilon}(\hat{\theta}_{n,\varepsilon}) - \Phi(\hat{\theta}_{n,\varepsilon}) ]
          =\E[D_1] +  \E[D_2] + \E[D_3]
          = -\varepsilon^2 p + o(\varepsilon^2)
      \end{equation*}
      as $\varepsilon\to 0$, $n\to \infty$, and so, we have shown the desired result.
  \end{proof}

