\section{Scalar-on-function model properties}\label{app_A}

% Note: in this sample, the section number is hard-coded in. Following
% proper LaTeX conventions, it should properly be coded as a reference:

%In this appendix we prove the following theorem from
%Section~\ref{sec:textree-generalization}:

In this appendix we prove the scalar-on-function (SoF) model for the IV framework with stratification, and show the properties of the weight function.


Assume $ Y= h(X) + U $ and the valid instrument $Z$. Assume that there exits the lower bound $l$ for the exposure domain $\mathcal{X}$ such that $\mathbb{P}( l < X )=1 $ almost surely. We let the effect function is continuous.
We have 
\begin{equation} \label{app_e1}
    \begin{split}
        \frac{Cov( Z ,Y )}{ Cov( Z,X )} &= \frac{Cov( Z , h(X) + U )}{ Cov( Z,X )} \\
               &= \frac{Cov( Z , \int _l^X h'(x) \text{d}x + h(l) + U )}{ Cov( Z,X )} \\& =  \frac{Cov( Z , \int _l^\infty h'(x) I\{X\geq x \} \text{d}x + h(l) + U )}{ Cov( Z,X )} \\
               &= \frac{Cov( Z , \int _l^\infty h'(x) I\{X\geq x \} \text{d}x )}{ Cov( Z,X )} \\
               &=    \int_\mathcal{X} h'(x)  \underbrace{\frac{ Cov(  Z, I\{X\geq x \} ) }{ Cov(Z,X)}}_{=: W(x)} \text{d}x
    \end{split}
\end{equation}
Note that this conclusion is easily extended to the complex case $h(X,\epsilon)$ with exogenous term $\epsilon$, given that $h(X,\epsilon)=\int _l^X h'(x,\epsilon) \text{d}x + h(l,\epsilon)$ where $h'(x,\epsilon) = \delta h(x,\epsilon)/ \delta x $ exists. In this case, we have $h'(x) = \mathbb{E}_\epsilon(  h'(x,\epsilon) ) $ in Equation \eqref{app_e1}.

In terms of the weight function $W(x)$, we can show
\begin{equation}
    \begin{split}
          \int_\mathcal{X}  W(x) \text{d}x  &=  \frac{  \int_\mathcal{X} Cov(Z, I\{ 
X\geq x \})   }{  Cov(Z,X)  } \\
     &= \frac{  Cov(   Z , \int_\mathcal{X}  I\{ X\geq x\} \text{d}x   ) }{ Cov(Z,X) } \\ 
     &= \frac{Cov(Z,X)}{ Cov(Z,X)} =1
    \end{split}
\end{equation}

Given the instrument-exposure model with linearity and homogeneity so that $X=\alpha Z + g_X(U,\epsilon_X)$ with confounder $U$ and exogenous variable $\epsilon_X$ and w.o.l.g. the instrumental effect $\alpha   >0$. Denote $ g_X(U,\epsilon_X) $ by $E$, we have 
\begin{equation}
    \begin{split}
        W(x)&=  \frac{   [  \mathbb{E}( Z|X \geq x) - \mathbb{E}( Z ) ] \mathbb{P}(X\geq x)   }{Cov(Z,X)} \\
            &= \frac{   [  \mathbb{E}( Z|X \geq x) - \mathbb{E}( Z | X < x) ]  \mathbb{P}(X< x)\mathbb{P}(X\geq x)   }{Cov(Z,X)} \\ 
            &=  \frac{ \mathbb{P}(X< x)\mathbb{P}(X\geq x) }{  \alpha^2 Var(Z) } 
            \left[   \int_\mathcal{Z} z  [    f_Z(z|X \geq x ) -f_Z(z|X \leq x )     ]\text{d}z          \right]
    \end{split}
\end{equation}
Since $  f_Z(  z | X \geq x ) =  \frac{   f_Z(z) f_E( x-\alpha z )   }{  \mathbb{P}(  X \leq x  )  } $, while $ \mathbb{P}( E \geq x-\alpha z )  $ is a monotone non-decreasing function over $z$; similar to $f_Z(  z | X \leq x )  $ with the monotone non-increasing function $ \mathbb{P}( E \leq x-z )  $; hence there exists an constant $z^\ast$ such that $  f_Z(  z | X \geq x ) \geq f_Z(  z | X \leq x )  $ when $ z \geq z^\ast $ and $  f_Z(  z | X \geq x ) \leq f_Z(  z | X \leq x )  $ otherwise. Therefore, 
\begin{equation}
\begin{split}
     \int_\mathcal{Z} z  [    f_Z(z|X \geq x ) -f_Z(z|X \leq x )     ]\text{d}z = &     \int_{\mathcal{Z}<z^\ast} z  [    f_Z(z|X \geq x ) -f_Z(z|X \leq x )     ]\text{d}z +\\
     & \int_{\mathcal{Z}\geq z^\ast} z  [    f_Z(z|X \geq x ) -f_Z(z|X \leq x )     ]\text{d}z  \\
      \geq & \, z^\ast  \int_{\mathcal{Z}<z^\ast}  [    f_Z(z|X \geq x ) -f_Z(z|X \leq x )     ]\text{d}z + \\
      & \, z^\ast  \int_{\mathcal{Z}\geq z^\ast}  [    f_Z(z|X \geq x ) -f_Z(z|X \leq x )     ]\text{d}z  \\
      =& z^\ast \int_{\mathcal{Z}}  [    f_Z(z|X \geq x ) -f_Z(z|X \leq x )     ]\text{d}z =0 
\end{split}    
\end{equation}
which means that $W(x) \geq 0$. This conclusion is easy to extend to the more general case that $  X=m(Z) + g_X(U,\epsilon_X) $ with a monotone instrumental effect function $m(\cdot)$.

In the case that $\{ Z,X  \}$ follows a joint normal distribution that 
\begin{equation}  
\left( \begin{array}{c} 
Z \\ 
X 
\end{array} \right)     \sim \mathcal{N}\left(
\left( \begin{array}{c} 
\mu_Z \\ 
\mu_X
\end{array} \right)  ,
\left( \begin{array}{cc} 
\sigma_Z^2 &  \sigma_{Z,X} \\ 
\sigma_{Z,X} & \sigma_X^2 
\end{array} \right)		\right)   
\end{equation}
which means $$   \mathbb{E}(  Z|X=x ) = \mu_Z+ \frac{\sigma_{Z,X}}{\sigma_X^2 }( x- \mu_X ) $$
We have the weight function

\begin{equation}
\begin{split}
W(s)=&   \frac{1}{\sigma_{Z,X}} \left[ \mathbb{E}( I\{X\geqslant s\}Z ) -\mathbb{E}( I\{X\geqslant s\})\mathbb{E}(Z)  \right]   \\
=&  \frac{1}{\sigma_{Z,X}} \left[  \int_{ [s,\infty )} f_X(x)   \int z  f_{Z|X}(z|x) dz dx  -  \int_{ [s,\infty )} f_X(x)   \int z  f_{Z}(z) dz dx\right]  \\
=&  \frac{1}{\sigma_{Z,X}} \left[ \int_{ [s,\infty )}
f_X(x)   \left[     \mathbb{E}(Z|X=x) - \mathbb{E}(Z)  \right]dx
\right] \\
=&  \frac{1}{\sigma_{Z,X}} \left[ \int_{ [s,\infty )}
f_X(x)   \left[ \frac{\sigma_{Z,X}}{\sigma_X^2 }( x- \mu_X )     \right]dx\right] \\
=&   \frac{1}{\sigma_X^2 } \int_{ [s,\infty )}
f_X(x)    ( x- \mu_X )     dx \\
=& \frac{1}{\sqrt{2 \pi} \sigma_X}   \int_{[s,\infty]} \frac{1}{\sigma_X^2} \exp\left\{  - \frac{  (x-\mu_X)^2 }{  2 \sigma_X^2  }  \right\} (x-\mu_X)  dx\\
=& \frac{1}{\sqrt{2 \pi} \sigma_X} \left. \left\{   -  \exp\left(  - \frac{  (x-\mu_X)^2 }{  2 \sigma_X^2  }  \right) \right \}  \right|_s^\infty  = 
\frac{1}{\sqrt{2 \pi} \sigma_X} \exp\left\{  - \frac{  (s-\mu_X)^2 }{  2 \sigma_X^2  }  \right\} = f_X(s)
\end{split}
\end{equation}
which means $W(s)$ is the marginal normal density of $X$. \hfill\BlackBox



\section{Linearity testing}\label{linearity_test}
The null hypothesis of effect linearity implies that $ h'(x) $ remains constant for all $x$, equaling the average treatment effect $\beta$. Denoting the stratum-specific genetic association estimators for the exposure and the outcome as $ \hat{\alpha}_s$ and $  \hat{\theta}_s $, respectively, we obtain the asymptotic result for each stratum:
\begin{equation} \label{linearity_con}
    \frac{   \hat{\theta}_s }{  \hat{\alpha}_s }  \overset{ p }{\to}  \beta \qquad \text{for }\, s = 1,\ldots, K.
\end{equation}
Since stratification results in multiple strata ($K > 1$), we can leverage over-identification or coherence approaches to test for effect linearity based on Equation \eqref{linearity_con} \citep{hansen1982large}. A common approach is to use Cochran’s $Q$-based statistic:
\begin{equation}\label{Q_statistic}
    Q(  \beta ) := \sum_{s=1}^K    \left\lbrace  
\frac{      \left(   \hat{\theta}_s   -   \beta \hat{{\alpha}}_s   \right) ^2    }{
	s.e.(  \hat{\theta}_s  )^2    +  \beta^2  s.e.(  \hat{\alpha}_s  )^2  }
\right\rbrace,  
\end{equation}
which is a simplified version (e.g., ignoring the correlation between $\hat{\theta}_s$ and $\hat{\alpha}_s$) commonly used in meta-analysis and Mendelian randomization \citep{hardy1998detecting,greco2015detecting}. 

In practice, we compare the observed $Q$ statistic, $Q(  \hat{\beta} )$, where $ \hat{\beta}  = \argmin_{\beta} Q(\beta)$ or any fundamental IV estimator under the linearity assumption, to its approximated $\chi^2$ distribution with degrees of freedom $K-1$ under the null hypothesis. The $Q$ statistic can also be interpreted as the maximal profile likelihood in an error-in-variable model that accounts for measurement error in $\alpha_s$, treating $\alpha_s$ as a nuisance parameter \citep{zhao2020statistical}, or as the residual sum of squares from an inverse-variance weighted (IVW) regression of $\hat{\theta}_s$ on $\hat{\alpha}_s$ using second-order weights \citep{bowden2019improving}. 
Rejection of the $Q$ test provides evidence for effect nonlinearity.


\section{Complicated model scenario}\label{invalid_scenarios}
In this section, we extend our analysis to a more complex model 
\begin{equation}
    Y = h(X, Z, \epsilon) + g(U, Z, \epsilon).
\end{equation}
We assume that the instrument $Z$ can be used for stratification, ensuring that Features 1 and 2 hold. Under this assumption, we construct the SoF model introduced before within each stratum. 
For reference, we define the simplest model, $Y = h(X) + U$, as \textbf{Scenario 0}. Below, we outline several complex model scenarios, each designed for specific objectives, along with illustrative examples. 

\medskip
\noindent 
{\bf Complex scenario 1.} {\it When there exists exogenous effect modifiers such that 
\begin{equation}
    Y=h(X,\epsilon) + g(U,\epsilon) 
\end{equation}
with regular conditions, all the ideas introduced above can be applicable to the objectives described by the mean effect function, $h(x):= \mathbb{E}_{\epsilon}( h(x,\epsilon) ) $, or the modifier-controlled effect function, $h(x, \epsilon^\ast)$, for a modifier layer $\epsilon^\ast$ when the modifier is measurable. For example, sex can be the measured modifier of the effect function, hence sex-strata may be first constructed for any downstream sex-specific nonlinear effect analysis. In addition, sex generally cannot be the downstream effect of the instrument and the confounder, hence selection on sex should not induce collider bias.}

\medskip
\noindent
{\bf Complex scenario 2.} {\it In the case that there exists the additive instrumental direct effect on the outcome (one typical case that violation of the exclusion restriction), in the sense that
\begin{equation}
    Y=h(X,\epsilon) + g(Z,U,\epsilon) 
\end{equation}
if we have the decomposition that $g(Z,U,\epsilon) =g_1(Z,\epsilon)   + g_2(U,\epsilon)$ so that the instrumental direct effect is not modified by confounders, one can still utilize the stratification and SoF model to test the effect linearity via testing the constant value among the stratum-specific IV estimates (details see Appendix \ref{app_e2}). The decomposition property is a quite common condition used in invalid IV models, like \cite{bowden2015mendelian,tchetgen2021genius}. 
The decomposition property allows that the linearity test is now robust to certain invalid IV cases, and also indicates that certain confounders in some applications can serve as the instrument for linearity testing. For example, in the exposure scenario where one believes the rank-preserving assumption between age and exposure is plausible and the age also has a direct effect on the outcome, one may still able to treat age as the 'instrument' to test the linear effect of the exposure on the outcome. Similarly in Mendelian randomization, some genes may have the direct effect on the outcome rather than through the exposure, which in genetics is called horizontal pleiotropy \citep{paaby2013many}; if one believes the genetic direct effect is not modified by the confounder, they are still valid for effect linearity testing even though they are invalid in IV context.}

\medskip
\noindent
{\bf Complex scenario 3.} {\it In the case that the instrument modifies the effect of the exposure on the outcome  (i.e. another typical case that violation of the exclusion restriction), in the sense that
\begin{equation}
     Y=h(X,Z,\epsilon) + g(U,\epsilon) 
\end{equation}
if we have the factorization that $ h(X,Z,\epsilon)=h_0(X,\epsilon) f(Z,\epsilon) $, one can still utilize the stratification and SoF model to test the effect linearity regarding $h_0(\cdot)$ via testing the constant value among the stratum-specific IV estimates (details see Appendix \ref{app_e2}). Note that this conclusion can be combined with the further decomposition scenario that $g(Z,U,\epsilon) =g_1(Z,\epsilon)   + g_2(U,\epsilon)$. For example, in some applications where the age (treated as an invalid instrument) has both the additive direct effect and the modified effect on the outcome, the linearity of the exposure effect can still be tested, given that the stratification assumption and the decomposition/factorization model assumption are plausible.    }


