\section{Information-theoretic thresholds for multiple feature matching}\label{sec:informationalfeatureMatching}

As discussed in Section~\ref{sec:multiple_feature}, the Multiple Feature Matching problem can be seen as the problem of clustering the  $n=KM$ data points $\big\{Y_{k}^{(m)}:(k,m)\in [K]\times [M]\big\}$ into $K$ groups, with the constraint that,  for each $m\in[M]$, each cluster $G^*_{k}$ contains one, and only one, observation from $\ac{Y_{k}^{(m)}:k\in [K]}$. In this section, we build on this observation for deriving a minimax optimal matching procedure, and we discuss thoroughly the link between clustering and multiple feature matching.

\paragraph{IT thresholds for multiple feature matching.}
A minimax near optimal algorithm for clustering a Gaussian Mixture Model is the Exact $K$-means estimator~\cite{Even24}. We adapt below this estimator to the Multiple Feature Matching problem.  
Given a $M$-tuple of permutations $\pi=(\pi_{m})_{m\in[M]}\in (\mathcal{S}_{K})^{M}$, we define 
\begin{equation}\label{eq:critpi}
    Crit(\pi)=\sum_{k\in[K]}\sum_{m\in[M]}\Big\|Y^{(m)}_{\pi_{m}^{-1}(k)}-\frac{1}{M}\sum_{m\in[M]}Y^{(m)}_{\pi_{m}^{-1}(k)}\Big\|^{2}\enspace .
\end{equation}
This criterion corresponds to the exact $K$-means criterion applied to the partition of $[M]\times [K]$ induced by $\pi$. Our estimator $\hat{\pi}$ will be any minimizer of this criterion over all  $M$-tuples of permutations 
\begin{equation}\label{eq:CKmeans}
\hat{\pi}\in \argmin_{\pi\in (\mathcal{S}_{K})^{M}} Crit(\pi)\enspace.
\end{equation}
The partition of $[K]\times [M]$ induced by $\hat{\pi}$ corresponds to the minimizer of the $K$-means criterion over the partitions that verify  $|G_{k}\cap ([K]\times \{m\})|=1$ for every $m\in[M]$ and $k\in[K]$. Adapting  the analysis of the exact $K$-means Criterion made in \cite{Even24}, we readily derive the following property, the proof of which is sketched in Appendix~\ref{prf:upperboundinformationalfeature}.

\begin{prop}\label{prop:upperboundinformationalfeature}
There exist positive numerical constants $c,c_1,c_2,c_3$ such that the following holds. If $\Delta^2\geq c_1\pa{\log(K)+\sqrt{\frac{p\log(K)}{M}}}$, then, with probability at least $1-\frac{c_2}{n^2}$, the estimator \eqref{eq:CKmeans} fulfills $$err(\hat{\pi}, \pi^*)\leq \exp\pa{-c_3\pa{\Delta^2\wedge \frac{\Delta^4 M}{p}}}\enspace.$$
In particular, if $\Delta^2\geq c\pa{\log(KM)+\sqrt{\frac{p\log(KM)}{M}}}$, then, with the same probability we have $err(\hat{\pi}, \pi^*)=0$. 
\end{prop}


Proposition \ref{prop:upperboundinformationalfeature} implies that partial recovery (i.e. a small $err(\hat{\pi},\pi^*)$) is possible when 
\begin{equation}\label{eq:IT-partial}
\Delta^2\gtrsim \log(K)+\sqrt{p\log(K)\over M}\ ,
\end{equation}
and perfect recovery (i.e. $err(\hat{\pi},\pi^*)=0$) is possible when 
\begin{equation}\label{eq:IT-exact}
\Delta^2\gtrsim \log(Km)+\sqrt{p\log(Km)\over M}\ .
\end{equation}
We now prove that these separation conditions are, up to some multiplicative constant, minimax optimal for multiple feature matching. 

Given $\bar{\Delta}>0$, we denote $\Theta_{\bar{\Delta}}$ the set of $K$-tuple $(\mu_{1},...,\mu_{K})\in (\R^{p})^{K}$ such that 
$$\frac{min_{k\neq l}\|\mu_{k}-\mu_{l}\|^2}{2\sigma^2}\geq \bar{\Delta}^2.$$
 Given a $K$-tuple $\mu=(\mu_{1},...,\mu_{K})\in (\R^{p})^{K}$, and a set of permutations $\pi=\ac{\pi_{m}:m\in[M]}$, we denote $\P_{\mu,\pi}$ the distribution of $Y=\pa{Y_k^{(m)}}_{k,m\in [K]\times [M]}$, for which all the $Y_{k}^{(m)}$'s are drawn independently and  $Y_{k}^{(m)}\sim \cN\pa{\mu_{\pi^*_m(k)}, \sigma^2I_p}$. Next theorem, proved in Appendices~\ref{prf:lowerboundexact} and~\ref{prf:lowerboundpartial}, provides minimax lower-bounds, matching the rates \eqref{eq:IT-partial} and \eqref{eq:IT-exact} derived for the constrained $K$-means estimator~\eqref{eq:CKmeans}.



\begin{thm}\label{thm:lowerboundinformationalfeature}
We have the following minimax lower bounds for the multiple feature matching problem.
\begin{enumerate}       
\item \textbf{Perfect recovery.} There exist positive numerical constants $c$, $C$, and $K_{0}$ such that the following holds. If $\bar{\Delta}^{2}\leq c \pa{\log(KM)+\sqrt{\frac{p}{M}\log(KM)}}$ and $K\geq K_{0}$, $$\inf_{\hat{\pi}:\R^{K\times M\times p}\to (\mathcal{S}_K)^{M}}\sup_{\mu\in\Theta_{\bar{\Delta}}}\sup_{\pi^*\in\pa{\mathcal{S}_K}^{M}}\P_{\mu,\pi^*}\pa{err(\hat{\pi}, \pi^*)\neq 0}\geq C\enspace.$$

\item \textbf{Partial recovery.} There exist positive numerical constants $c$, $c'$, $c''$, $C$, and $K_{0}$ such that the following holds. Suppose that $p\geq c\log(K)$, $K\geq K_0$ and $\bar{\Delta}^{2}\leq c' \pa{\log(K)+\sqrt{\frac{p}{M}\log(K)}}$, then, $$\inf_{\hat{\pi}:\R^{K\times M\times K}\to (\mathcal{S}_K)^{M}}\sup_{\mu\in\Theta_{\bar{\Delta}}}\sup_{\pi^*\in\pa{\mathcal{S}_K}^{M}}\E_{\mu,\pi^*}\pa{err(\hat{\pi}, \pi^*)}\geq C\enspace.$$
\end{enumerate}
\end{thm}




Combining Proposition \ref{prop:upperboundinformationalfeature} and Theorem \ref{thm:lowerboundinformationalfeature}, we conclude that the minimax rate for perfect recovery in multiple feature matching is  \eqref{eq:IT-partial} and \eqref{eq:IT-exact}, up to some multiplicative factor. Comparing these rates to  the LD rate \eqref{eq:LD-MFM} provides evidence for the existence of a statistical-computational gap for the multiple feature matching problem, when $p\geq_{\log}M/K$.



\paragraph{Multiple feature matching versus clustering.}
As mentioned before, multiple feature matching can be seen as the problem of clustering the  $n=KM$ data points $\big\{Y_{k}^{(m)}:(k,m)\in [K]\times [M]\big\}$ into $K$ groups, with the constraint that,  for each $m\in[M]$, each cluster $G^*_{k}$ contains one and only one observation from $\ac{Y_{k}^{(m)}:k\in [K]}$. Given this last constraint, we can expect that a lower separation $\Delta^2$ is required  for successful multiple feature matching, than for clustering $n=KM$ points in dimension $p$.
Yet, we observe that both the IT rates \eqref{eq:IT-partial}--\eqref{eq:IT-exact}, and the  LD rate \eqref{eq:LD-MFM} for multiple feature matching are the same than those for clustering $n=KM$ points in dimension $p$~\cite{Even24,Even25a}.  This means, that, in terms of rates (blind to constant factors), multiple feature matching is not easier than clustering.  Let us give some intuitions for explaining this observation.

For the IT threshold, the optimal algorithm for multiple feature matching and for clustering is, in both cases, a minimizer of the same $K$-means 
 criterion, the only difference is that the minimization is performed over $(\mathcal{S}_K)^{M}$ for multiple feature matching, and over the set $\cP_{K}(KM)$ of all partitions of $[KM]$ into $K$ groups for clustering. Since the performance of both minimizers of the $K$-means criterion is mainly driven by the concentration of the same quadratic functionals of $Y$, as a first approximation, only the size of the log-cardinalities 
 $\log\pa{|(\mathcal{S}_K)^{M}|}$  and  $\log\pa{|\cP_{K}(KM)|}$ can differentiate the rates.
 We observe that $\log\pa{|\cP_{K}(KM)|}\leq KM\log(K)$, while  $\log\pa{|(\mathcal{S}_K)^{M}|}\sim KM\log(K)$ for $K$ large, so both cardinalities are similar. While the constraint $|G_{k}\cap ([K]\times \{m\})|=1$ for every $m\in[M]$ and $k\in[K]$ reduces the number of admissible partitions, this reduction is not strong enough in order to significantly differentiate the minimax rates.

As for the LD threshold, we observe that the constraint $|G_{k}\cap ([K]\times \{m\})|=1$ for every $m\in[M]$ and $k\in[K]$ is complex and combinatorial in nature. \cite{Even25a} provides evidence that poly-time algorithms -- at least low-degree polynomials -- can struggle to fully exploit complex combinatorial structures, as for example in sparse clustering or biclustering. In light of this observation, it is not surprising that poly-time algorithms fail to exploit the  constraint $|G_{k}\cap ([K]\times \{m\})|=1$ for every $m\in[M]$ and $k\in[K]$, in order to perform significantly better than unconstrained clustering algorithms.

Finally, we mention that multiple feature matching can be viewed as a specific case of socially fair-clustering~\cite{FairClustering19,FairClustering21}. In fair-clustering, we observe $n$ data points $Y_{1},\ldots, Y_{n}$, each of them having an observed sensitive attribute (gender, social group, etc), say $m\in[M]$. One of the goal in fair-clustering is to provide a partition of  $Y_{1},\ldots, Y_{n}$ minimizing a criterion like $K$-means or $K$-median under the constraint that every demographic group is proportionally represented in each cluster~\cite{FairClustering19}.
Considering  $\big\{Y_{k}^{(m)}:(k,m)\in [K]\times [M]\big\}$ as data points to be clustered, and seeing the label $m$ as the sensitive attribute of $Y_{k}^{(m)}$, the multiple feature matching problem can be seen as a fair-clustering problem. Indeed, if we seek for a partition of $\big\{Y_{k}^{(m)}:(k,m)\in [K]\times [M]\big\}$ into $K$ clusters, each of them having an equal number of each label $m$, then, for each cluster, we are forced to peak one, and only one, observation from $\ac{Y_{k}^{(m)}:k\in [K]}$. Hence, a fair clustering of  $\big\{Y_{k}^{(m)}:(k,m)\in [K]\times [M]\big\}$  into $K$ clusters provide a multiple feature matching. 






\section{Background on cumulants}\label{sec:cumulant:background}

In this section, we summarize results on mixed  cumulants of random variables that we shall use in our proof.



\subsection{Classical results on cumulants}

Let $Y_1,\ldots, Y_l$ be random variables on the same space $\mathcal{Y}$. Their cumulant generating function is $$K(t_1,\ldots, t_l):=\log\E\cro{\exp\pa{\sum_{l'=1}^lt_{l'}Y_{l'}}}\enspace,$$
and their joint cumulant is the value of the partial derivative of $K(t_1,\ldots, t_l)$ at 0
 $$\cumul\pa{Y_1,\ldots,Y_l}:=\pa{\frac{\partial^l\, K}{\partial t_{1}\cdots\partial t_{l}}(t_1,\ldots,t_l)}_{t_1,\ldots, t_l=0}\enspace.$$
In the proof, we use standard results on cumulants that we state in Lemma \ref{lem:mobiusformula} and \ref{lem:independentcumulant}.  We refer e.g. to \cite{novak2014three} for proofs and more details. The first lemma is the Möbius formula that expresses joint cumulant of random variables as a linear combination of their mixed moments.

\begin{lem}\label{lem:mobiusformula}
Let $Y_1,\ldots, Y_l$ be random variables on the same space $\mathcal{Y}$. For $G$ a partition of $[l]$, we write $m(G)=(-1)^{|G|-1}(|G|-1)!$ the Möbius function. Then $$\cumul\pa{Y_1,\ldots, Y_l}=\sum_{G\in\mathcal{P}([l])}m(G)\prod_{R\in G}\E\cro{\prod_{i\in R}Y_i} \ ,$$
where $\cP([l])$ is the collection of all partitions of $[l]$. 
In particular, cumulants are multilinear. 
\end{lem}

The next lemma gives a sufficient condition for the nullity of cumulants.

\begin{lem}\label{lem:independentcumulant}
Let $Y_1,\ldots, Y_l$ be random variables on the same space $\mathcal{Y}$. Suppose that there exists disjoint sets $I_1$ and $I_2$, non-empty and covering $[l]$, such that $(Y_i)_{i\in I_1}$ and $(Y_i)_{i\in I_2}$ are independent. Then, we have  $\cumul\pa{Y_1,\ldots, Y_l}=0$.
\end{lem}



\subsection{Expansion of cumulants in latent variable  models}\label{sec:law_total_cumulantce}


In some latent models, as  considered in Sections~\ref{sec:clustering_constant} and \ref{sec:multiple_feature},
the cumulants $\kappa_{x,\alpha}$ arising in the control~\eqref{eq:SW22} of the $MMSE_{\leq D}$ have intricate forms.  In this subsection, we recall some formulas derived in~\cite{Even25a}. Assume that the signal matrix $X$ is of the form
\begin{equation}\label{eq:latent-model}
X_{ij}=\mu_{\pi^*(i)j},\quad \textrm{for}\quad (i,j)\in [n]\times [p], 
\end{equation}
where $\pi^*: [n]\mapsto [K]$ is possibly randomly generated and the $\mu_{kj}$'s are  generated independently according to $\mathcal{N}(0,\lambda^2)$ with $\lambda>0$. 
In particular, this encompasses the prior distributions in Definitions~\ref{def:prior} and~\ref{def:priorfeaturematching}. 


The following proposition is a corollary of Theorem 2.5 in~\cite{Even25a}. It shows that for bounding $\kappa_{x,\alpha}$, it  suffices to control mixed cumulants in terms of the latent variables $\pi^*(i)$. 
\begin{prop}\label{thm:LTC}[\cite{Even25a}]
Consider the model~\eqref{eq:latent-model}, and fix any $\alpha\in \N^{n\times p}$. If $|\alpha|$ is odd, then $\kappa_{x,\alpha}=0$. For $|\alpha|=2l$, suppose that, for all decomposition $\alpha=\beta_1+\ldots+\beta_l$, with $\beta_s$ of the form $\beta_s=\ac{(i_s, j_s), (i'_s, j_s)}$, we have $$\left|\cumul\left\{x,\1\ac{\pi^{*}(i_1)= \pi^{*}(i_2)},\ldots, \1\ac{\pi^{*}(i_l)= \pi^{*}(i'_l)} \right\}\right|\leq C_\alpha\enspace,$$
then, 
\begin{equation}\label{eq:LTCgeneral:thm}
|\kappa_{x,\alpha}|\leq \lambda^{|\alpha|}|\alpha|^{\frac{|\alpha|}{2}-1}C_\alpha\enspace.
\end{equation}
\end{prop}





\begin{proof}[Proof of Proposition \ref{thm:LTC}]
Let us remark that, in the model \eqref{eq:latent-model},  $(x,X)$ has the same law as $(x,-X)$. Thus, if $|\alpha|$ is odd, we deduce from the multilinearity of cumulants $$\kappa_{x,\alpha}=\cumul\pa{x, \pa{X_{ij}}_{ij\in \alpha}}=\cumul\pa{x, \pa{-X_{ij}}_{ij\in \alpha}}=\pa{-1}^{|\alpha|}\cumul\pa{x, \pa{X_{ij}}_{ij\in \alpha}}=-\kappa_{x,\alpha}\enspace,$$
and we directly have $\kappa_{x,\alpha}=0$. 
Suppose that $|\alpha|=2l$. We recall that we consider $\alpha\in \N^{n\times p}$ as a multiset containing $\alpha_{ij}$ copies of $(i,j)$. 
 Let $\mathcal{P}_2(\alpha)$ denote the set of all partitions of $\alpha$ into groups of size $2$. Given $G=\ac{G_1,\ldots,G_l}\in \cP_2\pa{\alpha}$ and $s\in [l]$, we define $\beta_s(G)\in \N^{n\times p}$ with entries $\pa{\beta_s(G)}_{ij}$ recording the number of copies of $(i,j)$ in $G_s$. Then, Theorem~2.5  in~\cite{Even25a} states that 
$$\kappa_{x,\alpha}=\lambda^{\alpha}\sum_{G\in \cP_2(\alpha)}\cumul\pa{x, \1_{\Omega_{\beta_1(G)}},\ldots, \1_{\Omega_{\beta_l(G)}}}\enspace,$$
where, for $\beta=\ac{(i,j), (i',j')}$, we write $\1_{\Omega_{\beta}}=\1\ac{j=j'}\1\ac{\pi^*(i)=\pi^*(i')}$. So, for $G\in \cP_2(\alpha)$, writing $\beta_s(G)=\ac{(i_s,j_s),(i'_s,j'_s)}$, if there exists $s$ such that $j_s\neq j'_s$, then $$\cumul\pa{x, \1_{\Omega_{\beta_1(G)}},\ldots, \1_{\Omega_{\beta_l(G)}}}=0\enspace,$$ and, if not, the hypothesis of the proposition leads to $$|\cumul\pa{x, \1_{\Omega_{\beta_1(G)}},\ldots, \1_{\Omega_{\beta_l(G)}}}|\leq C_\alpha\enspace.$$
Hence, $|\kappa_{x,\alpha}|\leq |\cP_2(\alpha)|\lambda^{|\alpha|}C_\alpha\leq \lambda^{|\alpha|}|\alpha|^{\frac{|\alpha|}{2}-1}C_\alpha$, where we use $|\cP_2(\alpha)|\leq |\alpha|^{\frac{|\alpha|}{2}-1}$.
\end{proof}





\subsection{Weighted dependency graph and cumulants}\label{sec:weighted-graph}


Our method for bounding cumulants builds upon the theory of weighted dependency graphs from \cite{feray2018}, on which we provide an account here. This section will be useful when we want to reduce random variables into product of random variables, as for example in Steps 1 and 3 of Section~\ref{sec:globalmethod}. For a set $S$, let  $(Y_i)_{i\in S}$ be random variables on the same space $\mathcal{Y}$, that are indexed by $S$. 



\begin{definition}[Weighted Graph]
A weighted graph $\cL=(S,E)$ is an undirected graph with vertex set $S$ such that any edge $e$ has a weight $w_e\in (0,1]$.
\end{definition}

\begin{definition}[Weight of a graph]
Let $\cL=(S,E)$ a weighted graph with vertex set $S$, and weights $w_e$ for $e\in E$. Given a spanning tree $\cT$ of $\cL$, its weight is the product of the weights of its edges, that is $weight(\cT)=\prod_{e\in \cT}w_e$. We define $\bbM(\cL)$ as the maximum weight over all  spanning tree of $\cL$. Here, we use the convention that $\bbM[\cL]=0$ if $\cL$ is not connected.
\end{definition}


For $\cL$ a weighted graph, we define $\cL\<1\>$ the graph induced by the edges of weight $1$. Given $S'\subseteq S$, we define $\cL[S]$ the restriction of $\cL$ to the vertex set $S'$.

In the following, we seek to bound cumulants of subfamilies of $(Y_i)_{i\in S}$ in terms of the maximal weight of a  weighted graph, that keeps track of the low-dependencies between the random variables $Y_i$. To do so, we need to consider super-multiplicative functions on subsets of $S$. 


\begin{definition}
Consider a non-negative function  $\psi$ mapping any subset of $S$ to $\mathbb{R}_+$. Then, $\psi$ is said to be super-multiplicative if for any  $S_1$,   $S_2\subseteq S$, we have $\psi\pa{S_1\cup S_2}\geq \psi(S_1)\psi(S_2)$.
\end{definition}



We are now in position to state Proposition~5.2 from \cite{feray2018}, that is very useful to reduce the problem of computing cumulants of random variables, to the problem of computing cumulants of products of random variables.


\begin{prop}\label{prop:feray}[Proposition 5.2 of \cite{feray2018}]
Let $\cL$ a weighted graph with vertex set $S$ and $\psi$ a super-multiplicative function on multisets of elements of $S$. Let $(D_r)_{r\geq 1}$ a sequence of positive numbers. Assume that, for any subset $B\subseteq S$, one has 
$$\left|\cumul\pa{\prod_{i\in B_1}Y_i,\ldots, \prod_{i\in B_l}Y_i}\right|\leq D_{|B|}\,\psi(B)\,\bbM\pa{\cL[B]}\enspace,$$
where $B_1,\ldots,B_l$ are the vertex sets of the connected components of $\cL\<1\>[B]$. Then, for all $B\subseteq S$, one has 
$$|\cumul\pa{(Y_i)_{i\in B}}|\leq C_{|B|}\psi(B)\bbM\pa{\cL[B]}\enspace,$$
with $C_r$ a sequence defined recursively by 
$$C_r=D_r+\underset{G\neq \{[r]\}}{\sum_{G\in\mathcal{P}([r])}}\prod_{R\in G}C_{|R|}\enspace ,$$
where  $\cP([r])$ stands for the collection of all partitions of $[r]$. 
\end{prop}

\medskip

\begin{rem}
 The proof of Proposition \ref{prop:feray} in \cite{feray2018} is a recursion on $B$. Thus, if one wants to upper-bound, for a specific subset $B\subseteq S$, the quantity $|\cumul\pa{(Y_i)_{i\in B}}|$, it is sufficient to upper-bound, for all subsets $B'\subseteq B$, the cumulants $|\cumul\pa{\prod_{i\in B'_1}Y_i,\ldots, \prod_{i\in B'_l}Y_i}|$, where  $B'_1,\ldots,B'_l$ are the vertex sets of the connected components of $L\<1\>[B']$. 
\end{rem}

To establish non-asymptotic bounds of cumulants, we provide the following upper bound on the sequence $|C_r|$ defined in Proposition \ref{prop:feray}. 


\begin{lem}\label{lem:subexponential}
In Proposition \ref{prop:feray}, if we suppose that the sequence $(D_r)_{r\geq 1}$ is upper-bounded by some constant $D_{\infty}>0$, then, for all $r\geq 1$, $C_r\leq D_{\infty}r^{6r}$.
\end{lem}



\begin{proof}[Proof of Lemma \ref{lem:subexponential}]


Without loss of generality, we can suppose that $D_{\infty}=1$. We shall prove by induction over $r\geq 0$ that $C_r\leq r^{6r}$. By definition, $C_0=1=0^0$.

We  now assume  that, for all $r'<r$, we have $C_{r'}\leq r'^{6r'}$, and we shall prove that $C_r\leq r^{6r}$. We begin by isolating one subset in the recursion formula 
\begin{align*}
C_r&=1+\sum_{\pi\neq \{[r]\}}\prod_{R\in\pi}C_{|R|}
=1+\sum_{\emptyset\subsetneq T\subsetneq [r]}C_{|T|}\pa{\sum_{\pi\in\mathcal{P}([r]\setminus T)}\prod_{R\in\pi}C_{|R|}}
=1+\sum_{\emptyset\subsetneq T\subsetneq [r]}C_{|T|}\pa{2C_{r-|T|}-1}\enspace .
\end{align*} 
Then, we apply the recursion hypothesis, 
\begin{align*}
C_r&\leq 1+\sum_{\emptyset\subsetneq T\subsetneq [r]}|T|^{6|T|}\pa{2(r-|T|)^{6(r-|T|)}-1}
\leq 2\sum_{\emptyset\subsetneq T\subsetneq [r]}|T|^{6|T|}(r-|T|)^{6(r-|T|)}\\
&\leq 2\sum_{l=1}^{r-1}\binom{r}{l}l^{6l}(r-l)^{6(r-l)}\enspace.
\end{align*}
For $l\in[1,r/2]$, we have $\binom{r}{l}l^{6l}(r-l)^{6(r-l)}\leq \binom{r}{l}l^{6l}r^{6(r-l)}\leq r^{6r}\pa{\frac{l}{r}}^{6l}\binom{r}{l}$. Then,  $\log\pa{\pa{\frac{l}{r}}^{6l}\binom{r}{l}}\leq 6l\log(l/r)+l\log(er/l)\leq -5l\log(r/l)+l\leq -5l\log(2)+l\leq -3l\log(2)$, where the last inequality comes from the fact that $\log(2)\geq \frac{1}{2}$. Hence, we arrive at
 \begin{align*}
C_r&\leq 4r^{6r}\sum_{l=1}^{r/2}2^{-3l}\leq \frac{1}{2}r^{6r}\frac{1-2^{-3r/2}}{1-2^{-3}}\leq r^{6r}\enspace , 
\end{align*}
which concludes the induction and the proof of Lemma \ref{lem:subexponential}.
\end{proof}



















\section{Proof of Theorem \ref{thm:lowdegreeconstantsizeclustering} -- pedagogical instantiation of Section~\ref{sec:globalmethod}}\label{app:clustering}
To prove Theorem \ref{thm:lowdegreeconstantsizeclustering}, we proceed in three steps:
\begin{enumerate}
\item We apply \cite{SchrammWein22} to reduce the derivation of LD bound to proving bounds on cumulants $\kappa_{x,\alpha}=\cumul\pa{x,X_{\alpha}}$;
\item We instantiate the methodology of Section~\ref{sec:globalmethod} to upper bound  $\kappa_{x,\alpha}$;
\item We conclude following similar reasoning as in \cite{SchrammWein22,Even25a}.
\end{enumerate}

\paragraph{1. From LD bound to cumulants with \cite{SchrammWein22}.}

With no loss of generality, we assume through this proof that $\sigma^2=1$.
Let $D\in \N$ such that $n\geq \max\pa{2(D+2)^2K, \pa{D+2}^4}$ and $K\geq D+2$. We suppose $p\geq \frac{n}{K^2}$ and 
$$\zeta:= \frac{\overline{\Delta}^{4}}{p}D^{22}(D+2)^2\max\left(1, \frac{n}{K^2}\right)<1\enspace.$$
Since the minimization problem defining $MMSE_{\leq D}$ in Equation (\ref{def:MMSE}) is separable, and since the random variables $M^*_{ij}$ are exchangeable, the $MMSE_{\leq D}$ can be reduced to
\begin{align*}
    MMSE_{\leq D}&:=\frac{1}{n(n-1)}\sum_{i\neq j=1}^{n}\inf_{f_{ij}\in \R_{D}(Y)}\E\cro{\pa{f_{ij}(Y)-\Gamma^*_{ij}}^2}\\
&=\inf_{f\in \R_{D}(Y)}\E\cro{\pa{f(Y)-\Gamma^*_{12}}^2}\enspace.
\end{align*}
In the remaining of the proof, we write $x=\Gamma^*_{12}=\1_{\pi^*(1)=\pi^*(2)}$. Then, our goal is to upper-bound 
$$MMSE_{\leq D}=\inf_{f\in \R_{D}(Y)}\E\cro{\pa{f(Y)-x}^2}\enspace.$$
The model of Definition \ref{def:prior} is a particular instance of the Additive Gaussian Noise Model considered in \cite{SchrammWein22}. 
Therefore, we can use Theorem 2.2 from \cite{SchrammWein22}, stated in Equation \eqref{eq:SW22}. For a matrix $\alpha\in\N^{n\times p}$, we define $|\alpha|=\sum_{i=1}^{n}\sum_{j=1}^{p}\alpha_{ij}$ and $\alpha!=\prod_{i=1}^{n}\prod_{j=1}^{p}\alpha_{ij}!$. We write $X\in \R^{n\times p}$ for the signal matrix, whose $i$-th row is the vector $\mu_{\pi^*(i)}$. Using Equation \eqref{eq:SW22}, we have the lower-bound
\begin{equation}
MMSE_{\leq D}\geq \frac{1}{K}-\frac{1}{K^2}-\underset{\alpha\neq 0}{\sum_{\alpha\in \N^{n\times p}}}\frac{\kappa_{x,\alpha}^2}{\alpha!}\enspace,
\end{equation}
where, for $\alpha\in \N^{n\times p}$, $\kappa_{x,\alpha}=\cumul(x,X^{\alpha}):=\cumul(x,X_{a_{1}},\ldots ,X_{a_{m}})$, with $\{a_{1},\ldots ,a_{m}\}$  the multiset that contains $\alpha_{ij}$ copies of $(i,j)$, for $i,j\in[1,n]\times [1,p]$.

Hence, in order to prove the theorem, it is enough to prove the bound
\begin{equation}\label{eq:SW22clustering}
    \underset{\alpha\neq 0}{\sum_{\alpha\in \N^{n\times p}}}\frac{\kappa_{x,\alpha}^2}{\alpha!}\leq \frac{18D^{21}}{K^2}\frac{\zeta}{1-\sqrt{\zeta}}\enspace.
\end{equation}
In light of Equation \eqref{eq:SW22clustering}, we shall identify the zero cumulant $\kappa_{x,\alpha}=0$ and
control $\kappa_{x,\alpha}$ for any $\alpha\in \N^{n\times p}$. For this purpose, it is convenient to represent $\alpha\in \N^{n\times p}$ as a bipartite multi-graph. 
More precisely, we define $\mathcal{G}_{\alpha}$ as the bipartite multi-graph on two disjoint sets of nodes $U=\{u_{i},i\in[1,n]\}$ and $V=\{v_{j}, j\in[1,p]\}$, with $\alpha_{ij}$ edges between $u_i$ and $v_j$, for $i,j\in [1,n]\times [1,p]$. We denote $\mathcal{G}_{\alpha}^-$ the restriction of $\mathcal{G}_{\alpha}$ to its non-isolated nodes and to $\ac{u_1,u_2}$. 
Henceforth, $\mathcal{G}_{\alpha}^-\cup \ac{(u_1,u_2)}$ stands for the multigraph $\cG_{\alpha}^{-}$ to which we have added an edge between $u_1$ and $u_2$. 
We write $cc(\alpha)$ the number of connected components of $\mathcal{G}_{\alpha}^-\cup \ac{(u_1,u_2)}$. We denote $supp(\alpha):=\ac{i\in [n], \alpha_{i:}\neq 0}$, $col(\alpha)=\ac{j\in [p], \alpha_{:j}\neq 0}$.

\paragraph{2. Bounding $\kappa_{x,\alpha}$ with the methodology outlined Section~\ref{sec:globalmethod}.}
The crux for deriving the lower bound of Theorem \ref{thm:lowdegreeconstantsizeclustering} lies in obtaining an upper-bound on the cumulant $\kappa_{x,\alpha}$.
Following our methodology outlined Section~\ref{sec:globalmethod}, we obtain the following upper-bound. 

\begin{lem}\label{lem:controlcumulantsconstantsizeclustering}
Let $\alpha\neq 0\in \N^{n\times p}$. If $n\geq 2\pa{|\alpha|+2}^2K$ and $K\geq |supp(\alpha)\cup\ac{1,2}|$, then, 
$$|\kappa_{x,\alpha}|\leq 4 \lambda^{|\alpha|}|\alpha|^{5|\alpha|+9}\pa{\frac{1}{K}}^{|supp(\alpha)\cup\ac{1,2}|-1}\pa{\frac{K(|supp(\alpha)\cup\ac{1,2}|)^2}{n}}^{cc(\alpha)-1}\enspace.$$
\end{lem}

For clarity and pedagogical purposes, the proof of this result is deferred to Appendix~\ref{prf:controlcumulantsconstantsizeclustering}.

\begin{rem} In the case where $cc(\alpha)=1$ and where $[1,2]\subseteq supp(\alpha)$, we recover, up to some $|\alpha|^{|\alpha|}$ terms, the bound obtained in~\cite{Even25a} for independent labels. 
\end{rem}

\paragraph{3. Concluding similarly as in \cite{SchrammWein22, Even25a}.}
It remains to characterize the set of $\alpha$'s such that $\kappa_{x,\alpha}\neq 0$ and to upper-bound the sum of the remaining cumulants in~\eqref{eq:SW22clustering}. 
\medskip 

\noindent{\bf 3.a. Identifying non zero $\kappa_{x,\alpha}$.} In the case where the labels are sampled independently, as in~\cite{Even25a}, it is possible to build upon the independence of the random variables involved in the cumulant $\kappa_{x,\alpha}$ and thereby to easily deduce that $\kappa_{x,\alpha}=0$ when $cc(\alpha)>1$ -- see~\cite{Even25a}. As no such independence holds in our case, the condition for having $\kappa_{x,\alpha}=0$ is more involved.
Suppose that there exists $j_0\in col(\alpha)$ such that $|\alpha_{:j_0}|=1$. Then, since $\pa{x,(X_{ij})_{ij\in [n]\times [p]}}$ has the same distribution as $\pa{x,((-1)^{j=j_0}X_{ij})_{ij\in [n]\times [p]}}$, we deduce from the multilinearity of cumulants that $\kappa_{x,\alpha}=-\cumul\pa{x, X_\alpha}=-\kappa_{x,\alpha}$, and so $\kappa_{x,\alpha}=0$. Hence, for having $\kappa_{x,\alpha}\neq 0$, we need $|\alpha|\geq 2|col(\alpha)|\geq 2$. Moreover, since $|\alpha|+1$ corresponds to the number of edges of $\cG_\alpha^-\cup\ac{(u_1,u_2)}$ and since $|supp(\alpha)\cup\ac{1,2}|+|col(\alpha)|$ corresponds to the number of nodes in $\cG_{\alpha}^{-}$, we deduce that $|\alpha|\geq |col(\alpha)|+|supp(\alpha)\cup\ac{1,2}|-cc(\alpha)-1$. Putting these two conditions together leads to the following condition on the $\alpha$'s such that $\kappa_{x,\alpha}\neq 0$
$$|\alpha|\geq \max\pa{2|col(\alpha)|, |col(\alpha)|+|supp(\alpha)\cup \ac{1,2}|-cc(\alpha)-1}\enspace.$$
Let us identify two other constraints satisfied by $supp(\alpha)$, $cc(\alpha)$ and $|\alpha|$. 
Each connected component of $\cG_\alpha^-\cup\ac{(u_1,u_2)}$ contains at least one point of $\pa{u_i}_{i\in supp(\alpha)\cup \ac{1,2}}$, with one of them containing both $u_1$ and $u_2$. Hence, $|supp(\alpha)\cup \ac{1,2}|\geq cc(\alpha)+1$. It is also clear that $|\alpha|+2\geq |supp(\alpha)\cup \ac{1,2}|$. 
\medskip

\noindent{\bf 3.b. Bounding the sum~\eqref{eq:SW22clustering}.}
Let $d,r,m,cc\geq 1$, with $d\geq \max\pa{2r,r+m-cc-1}$ and $d+2\geq m\geq cc+1$. There are at most $(rm)^{d}p^r n^{m-2}\leq \pa{d(d+2)}^{d}p^r n^{m-2}$ matrices $\alpha$ satisfying $|\alpha|=d$, $|supp(\alpha)\cup\ac{1,2}|=m$, $|col(\alpha)|=r$ and $cc(\alpha)=cc$. 
Since $|\alpha|\leq D$, $K\geq D+2$, and $n\geq 2(D+2)^2K$
by assumption of Theorem~\ref{thm:lowdegreeconstantsizeclustering},
we can apply Lemma~\ref{lem:controlcumulantsconstantsizeclustering}, and get 

\begin{align*}
\underset{\alpha\neq 0}{\sum_{\alpha\in \N^{n\times p}}}\frac{\kappa_{x,\alpha}^2}{\alpha!}\leq& \sum_{d=2}^{D}\sum_{\alpha: \ |\alpha|=d}\kappa_{x,\alpha}^2\\
\leq& \frac{16}{K^2}\sum_{d=2}^{D}\underset{d\geq \max\pa{2r,r+m-cc-1}}{\underset{d+2\geq m\geq cc+1}{\sum_{r,cc\geq1}}} \lambda^{2d}(d+2)^{d}d^{11d+18}p^r\pa{\frac{n}{K^2}}^{m-2}\pa{\frac{K^2m^4}{n^2}}^{cc-1}\\
\leq &\frac{16D^{18}}{K^2}\sum_{d=2}^{D}\underset{d\geq \max\pa{2r,r+m-cc-1}}{\underset{d+2\geq m\geq cc+1}{\sum_{r,cc\geq1}}} \lambda^{2d}\pa{D^{11}(D+2)}^{d}p^r\pa{\frac{n}{K^2}}^{m-cc-1}\pa{\frac{(D+2)^4}{n}}^{cc-1}\\
\leq &\frac{16D^{18}}{K^2}\sum_{d=2}^{D}\underset{d\geq \max\pa{2r,r+m-cc-1}}{\underset{d+2\geq m\geq cc+1}{\sum_{r,cc\geq1}}} \pa{D^{11}(D+2)\lambda^2}^{d}p^r\pa{\frac{n}{K^2}}^{m-cc-1}\enspace \ , 
\end{align*}
where we used in the last line that $n\geq (D+2)^4$. Let us fix $d,r,m,cc\geq 1$, with $d\geq \max\pa{2r,r+m-cc-1}$ and $d+2\geq m\geq cc+1$, and let us upper-bound the quantity $\Upsilon:= \pa{D^{11}(D+2)\lambda^2}^{d}p^r\pa{\frac{n}{K^2}}^{m-cc-1}$. 

First, let us consider the case $r\geq m-cc-1$. Leveraging the constraint $d\geq 2r$, we derive
\begin{align*}
\Upsilon\leq & \pa{D^{11}(D+2)\lambda^2}^{d-2r}\pa{\lambda^4 D^{22}(D+2)^2p}^{r-(m-cc-1)} \pa{\lambda^4 D^{22}(D+2)^2p\frac{n}{K^2}}^{m-cc-1}
\leq \zeta^{d/2}\enspace ,
\end{align*}
by definition of $\zeta$. 

Second, when $r<m-cc-1$, we use the constraint $d\geq r+m-cc-1$ to obtain
\begin{align*}
\Upsilon \leq &\pa{D^{11}(D+2)\lambda^2}^{d-r-m+cc+1}\pa{D^{11}(D+2)\lambda^2 p}^{r}\pa{D^{11}(D+2)\lambda^2\frac{n}{K^2}}^{m-cc-1}\\
\leq & \pa{D^{11}(D+2)\lambda^2}^{d-r-m+cc+1} \pa{D^{11}(D+2)\lambda^2\frac{n}{K^2}}^{m-cc-1-r}\pa{D^{22}(D+2)^2\lambda^4\frac{pn}{K^2}}^r\enspace.
\end{align*}

It is clear that $D^{11}(D+2)\lambda^2\leq \sqrt{\zeta}$ and $D^{22}(D+2)^2\lambda^4\frac{pn}{K^2}\leq \zeta$. For the remaining term, using $p\geq \frac{n}{K^2}$, we have $D^{11}(D+2)\lambda^2\frac{n}{K^2}=\frac{n}{K^2p}D^{11}(D+2)\bar{\Delta}^2\leq \sqrt{D^{22}(D+2)^2\frac{n}{K^2p}\bar{\Delta}^4}\leq \sqrt{\zeta}$. We end up with $\Upsilon \leq \zeta^{d/2}$.
Hence, we can conclude 
\begin{align*}
\underset{\alpha\neq 0}{\sum_{\alpha\in \N^{n\times p}}}\frac{\kappa_{x,\alpha}^2}{\alpha!}\leq&\frac{16D^{18}}{K^2}\sum_{d=2}^{D}\underset{d\geq \max\pa{2r,r+m-cc-1}}{\underset{d+2\geq m\geq cc+1}{\sum_{r,cc\geq1}}}\zeta^{d/2}\\
\leq &\frac{16D^{18}}{K^2} \sum_{d=2}^{D} \frac{d(d+1)(d+4)}{4}\zeta^{d/2}\\
\leq &\frac{18D^{21}}{K^2}\frac{\zeta}{1-\sqrt{\zeta}}\enspace,
\end{align*}
where we used, $d(d+1)(d+4)\leq 4.5d^3$ for $d\geq 2$, and the identity  $\sum_{d\geq 2}z^d=\frac{z^2}{1-z}$, for any $-1<z<1$. This concludes the proof of Theorem \ref{thm:lowdegreeconstantsizeclustering}.




\subsection{Proof of Lemma \ref{lem:controlcumulantsconstantsizeclustering} -- simple instantiation of Section~\ref{sec:globalmethod}}\label{prf:controlcumulantsconstantsizeclustering}

For proving Lemma \ref{lem:controlcumulantsconstantsizeclustering}, we instantiate the methodology outlined in Section~\ref{sec:globalmethod}.


\paragraph{Step 0: From $\kappa_{x,\alpha}$ to cumulants like \eqref{eq:generalformcumulant}.} 
A preliminary step is to apply  Proposition~\ref{thm:LTC} in order to reduce the problem of bounding $\kappa_{x,\alpha}$ to the problem of bounding cumulants like \eqref{eq:generalformcumulant}. 

Let $\alpha\neq 0\in \N^{n\times p}$. We recall the hypotheses $n\geq 2(|\alpha|+2)^2K$ and $K\geq |supp(\alpha)\cup \ac{1,2}|$. 
According to Proposition~\ref{thm:LTC}, all we need to upper-bound $\kappa_{x,\alpha}$ is to upper-bound,
 for any decomposition $(\beta_1,\ldots, \beta_l)$ of $\alpha$ with $|\beta_s|=2$ of the form $\beta_s=\ac{(i_s, j_s), (i'_s, j_s)}$, the cumulant 
$\cumul\pa{x, \pa{\1\ac{\pi^*(i_s)=\pi^*\pa{i'_s}}}}$.
Let us take the convention $i_0=1$, $i_0'=2$, so that we can write
\begin{equation}\label{eq:start:clustering}
\cumul\pa{x, \pa{\1\ac{\pi^*\pa{i_s}=\pi^*\pa{i'_s}}}}=\cumul\pa{\pa{\1\ac{\pi^*\pa{i_s}=\pi^*\pa{i'_s} }}_{s\in [0,l]}}\enspace, 
\end{equation}
which is of the form~\eqref{eq:generalformcumulant} of the cumulants that are dealt with in Section~\ref{sec:globalmethod}. We can now follow the general methodology described in Section~\ref{sec:globalmethod}. 


\paragraph{Step 1: Reduction.} 
As explained in Section~\ref{sec:globalmethod}, the first step is to reduce the control of the cumulant \eqref{eq:start:clustering}, to the control of cumulants of products of strongly dependent $\1\ac{\pi^*\pa{i_s}=\pi^*\pa{i'_s} }$.
We introduce a weighted graph $\cW$ to which we will apply Proposition \ref{prop:feray}. Let $\cW$ be the weighted graph on $[0,l]$ with weights $w_{s,s'}$ defined by;
\begin{itemize}
\item If $\ac{i_s, i'_s}\cap \ac{i_{s'}, i'_{s'}}\neq \emptyset$, then $w_{s,s'}=1$;
\item If $\ac{i_s, i'_s}\cap \ac{i_{s'}, i'_{s'}}=\emptyset$, then $w_{s,s'}=K(|supp(\alpha)\cup \ac{1,2}|)^2/n$.
\end{itemize}
We observe that when $w_{s,s'}=1$, there exists some strong dependencies within the variables  $\pi^*\pa{i_s},\pi^*\pa{i'_s},\pi^*\pa{i_{s'}},\pi^*\pa{i'_{s'}}$. As for the value $w_{s,s'}=K(|supp(\alpha)\cup \ac{1,2}|)^2/n$ for the second case, it is chosen based on forthcoming Lemma~\ref{lem:controlreductedcumulantsclusteringnew}.
Let us fix $S^{(0)}\subseteq [0,l]$. We recall that $\cW\<1\>[S^{(0)}]$ stands for the weighted graph induced by $S^{(0)}$, where we only keep the edges of weight one. Let us write $\bS=S_1,\ldots, S_{|\bS|}$ for the partition of $S^{(0)}$ induced by the connected components of $\cW\<1\>[S^{(0)}]$.   In order to apply Proposition \ref{prop:feray}, we shall upper-bound, for such an $S^{(0)}$, the cumulant 
$$C_{\bS}:=\cumul\pa{\pa{\prod_{s\in S}\1\ac{\pi^*\pa{i_s}=\pi^*\pa{i'_s}}}_{S\in\bS}}\enspace,$$
with respect to the maximal weight $\bbM\pa{\cW[S^{(0)}]}=\pa{\frac{K(|supp(\alpha)\cup\ac{1,2}|)^2}{n}}^{|\bS|-1}$. The next lemma (steps 2-4 of Section~\ref{sec:globalmethod}), proved in Section \ref{prf:controlreductedcumulantsclusteringnew}, provides such an upper-bound.



\begin{lem}\label{lem:controlreductedcumulantsclusteringnew}
Suppose $n\geq 2(|supp(\alpha)\cup \ac{1,2}|)^2K$ and $K\geq |supp(\alpha)\cup\ac{1,2}|$. Let $S^{(0)} \subset [0,l]$ and let $\bS=S_1,\ldots, S_{|\bS|}$ denote the connected components of $\cW\<1\>[S^{(0)}]$. Writing $supp(S^{(0)})=\cup_{s\in S^{(0)}}\ac{i_s,i'_s}$, we have
$$\left|C_{\bS}\right|\leq 4|\bS|^{3|\bS|+1}\pa{\frac{1}{K}}^{|supp(S^{(0)})|-1}\pa{\frac{K|supp(S^{(0)})|^2}{n}}^{|\bS|-1}\enspace.$$
\end{lem}
From Lemma \ref{lem:controlreductedcumulantsclusteringnew}, we deduce that for any $S^{(0)}\subseteq [0,l]$, with $\bS$ the set of connected components of $\cW\<1\>[S^{(0)}]$,
$$\left|C_{\bS}\right|\leq 4|\bS|^{3|\bS|+1}\pa{\frac{1}{K}}^{|supp(S^{(0)})|-1}\bbM\pa{\cW[S^{(0)}]}\enspace.$$
The function $S^{(0)}\to \pa{\frac{1}{K}}^{|supp(S^{(0)})|-1} $ is super-multiplicative. Moreover, $4|\bS|^{3|\bS|+1}\leq 4\pa{l+1}^{3l+4}$. Hence, applying Proposition \ref{prop:feray} and Lemma~\ref{lem:subexponential}, we get that 
$$\left|\cumul\pa{\pa{\1\ac{\pi^*\pa{i_s}=\pi^*\pa{i'_s}}}_{s\in [0,l]}} \right| \leq4\pa{l+1}^{9l+10} \pa{\frac{1}{K}}^{|supp(\alpha)\cup\ac{1,2}|-1}\bbM\pa{\cW}\enspace.$$
In other words, writing $cc(\cW)$ the number of connected components of $\cW\<1\>$, we have 
\begin{multline*}
\lefteqn{\left|\cumul\pa{\pa{\1\ac{\pi^*\pa{i_s}=\pi^*\pa{i'_s}}}_{s\in [0,l]}} \right|\leq}\\
4 \pa{l+1}^{9l+10}\pa{\frac{1}{K}}^{|supp(\alpha)\cup\ac{1,2}|-1}\pa{\frac{K(|supp(\alpha)\cup\ac{1,2}|)^2}{n}}^{cc(\cW)-1}\enspace.
\end{multline*}
We recall that $cc(\alpha)$ stands for the number of connected components of $\mathcal{G}_\alpha^-\cup \ac{(u_1,u_2)}$. For all $s\in [0,l]$, $u_{i_s}$ and $u_{i'_s}$ are in the same connected components of $\mathcal{G}_\alpha^-\cup \ac{(u_1,u_2)}$, since they are connected via $v_{j_{s}}$. Moreover, for $s\neq s'$,  $\{u_{i_s}, u_{i'_s}\}$ and $\{u_{i_{s'}}, u_{i'_{s'}}\}$ are in the same connected components of $\mathcal{G}_\alpha^-\cup \ac{(u_1,u_2)}$ if and only if $s$ and $s'$ are in the same connected component of $\cW\<1\>$. We deduce from these two claims that $cc(\alpha)=cc(\cW)$, and so 
\begin{multline*}
\lefteqn{\left|\cumul\pa{\pa{\1\ac{\pi^*\pa{i_s}=\pi^*\pa{i'_s}}}_{s\in [0,l]}} \right|\leq}\\ 4 \pa{l+1}^{9l+10}\pa{\frac{1}{K}}^{|supp(\alpha)\cup\ac{1,2}|-1}\pa{\frac{K(|supp(\alpha)\cup\ac{1,2}|)^2}{n}}^{cc(\alpha)-1}\enspace.
\end{multline*}
This being true for all decomposition $\beta_1,\ldots,\beta_l$ of $\alpha$,  we get from Proposition~\ref{thm:LTC} that 
$$|\kappa_{x,\alpha}|\leq 4 \lambda^{|\alpha|}|\alpha|^{5|\alpha|+9}\pa{\frac{1}{K}}^{|supp(\alpha)\cup\ac{1,2}|-1}\pa{\frac{K(|supp(\alpha)\cup\ac{1,2}|)^2}{n}}^{cc(\alpha)-1}\enspace.$$
This concludes the proof of Lemma \ref{lem:controlcumulantsconstantsizeclustering}.








\subsection{Proof of Lemma \ref{lem:controlreductedcumulantsclusteringnew}}\label{prf:controlreductedcumulantsclusteringnew}

\paragraph{Step 2: Expansion.} 
Let $S^{(0)}\subseteq [0,l]$ and let $\bS=S_1,\ldots, S_{|\bS|}$ be the connected components of $\cW\<1\>[S^{(0)}]$, which is the subgraph induced by $S^{(0)}$ obtained only keeping the edges of $\cW$ of weight $1$. 
The second step amounts to expand the cumulant 
$$|C_{\bS}|=\left|\cumul\pa{\pa{\prod_{s\in S}\1\ac{\pi^*\pa{i_s}=\pi^*\pa{i'_s}}}_{S\in \bS}}\right|\enspace,$$
over all possible values of $\pi^*$.
For any $S\subseteq [0,l]$, We write $supp(S)=\cup_{s\in S}\ac{i_s,i'_s}$. By definition of the graph $\cW$ and of $\bS$, the subsets $supp(S)$, for $S\in \bS$, are disjoint, and form a partition of $supp(S^{(0)})$. Moreover, for all $S\in \bS$, and for all $i,i'\in supp(S)$, there exists a path $s_1,\ldots, s_{h}\subseteq S$, such that $i\in \ac{i_{s_1}, i'_{s_1}}$, $i'\in \ac{i_{s_h}, i'_{s_h}}$, and such that $(s_{h'-1},s_{h'})$, for $h'\in [2,h]$, is an edge of weight $1$ of $\cW$. Thus, for $S\in\bS$, 
$\pi^*(i_{s})=\pi^*(i'_{s})$ if and only if $\pi^*$ is constant on $supp(S)$, and we have
$$\prod_{s\in S}\1\ac{\pi^*\pa{i_s}=\pi^*\pa{i'_s}}=\sum_{a \in [K]}\prod_{i\in supp(S)}\1\ac{\pi^*(i)= a }\enspace.$$
Hence, we are interested in configurations $\pi^*$ that are constant on each $S_l$ for $l=1,\ldots, |\bS|$. For that purpose, we focus on 
$\pi= (\pi(S_l))_{l=1,\ldots,|\bS|}\in  [K]^{|\bS|}$. Then, using the multilinearity of cumulants, we get
\begin{equation}\label{eq:multilinearityclustering}
C_{\bS}:=\cumul\pa{\pa{\prod_{s\in S}\1\ac{\pi^*\pa{i_s}=\pi^*\pa{i'_s}}}_{S\in \bS}}=\sum_{(\pi(S_l))_{l=1,\ldots,|\bS|}\in  [K]^{|\bS|}}
C_{\bS}(\pi)\enspace , 
\end{equation}
where 
\[
C_{\bS}(\pi):= \cumul\pa{\pa{\prod_{i\in supp(S)}\1\ac{\pi^*(i)=\pi(S)}}_{S\in \bS}}\enspace . 
\]

\paragraph{Step 3: Pruning incompatible configurations.} No pruning required in this case.

\paragraph{Step 4: Leveraging Lemma \ref{lem:upperboundgeneralcumulant}.}
The last step is to recognize some variables having mixed moment  of the form \eqref{eq:formula:general_momodent}.
In the following, for $S\in \bS$, we write $Z_{\pi,S}=\prod_{i\in supp(S)}\1\ac{\pi^*(i)=\pi\pa{S}}$. We denote  $B_1,\ldots, B_K$ the partition\footnote{Actually, this is not a partition as some of the $B_k$'s are empty; we only use that the $B_k$'s do not intersect and cover $supp(S^{(0)})$.} of $supp(S^{(0)})$ induced by $\pi$, i.e $B_k=\cup_{S\in \bS, \pi\pa{S}=k}supp(S)$. We recall that we write $\bS=S_1,\ldots, S_{|\bS|}$. Let $\Delta\subseteq [|\bS|]$ and let us denote $I_{\Delta}=\cup_{t\in \Delta}supp(S_t)$. Since $K\geq |supp(\alpha)\cup\ac{1,2}|$ by assumption, we have
\begin{align}\nonumber
\E\cro{\prod_{t\in \Delta}Z_{\pi,S_t}}=&\P\cro{\forall t\in \Delta, \forall i\in supp(S_t), \pi^*(i)=\pi\pa{S_t}}\\\nonumber
=&\frac{1}{n(n-1)\times \ldots\times (n-|I_\Delta|+1)}\prod_{k\in [K]}\frac{n}{K}\times \ldots\times \pa{\frac{n}{K}-|I_\Delta\cap B_k|+1}\\
=&\pa{\frac{1}{K}}^{|I_\Delta|}\frac{1}{1-\frac{1}{n}}\times \ldots\times \frac{1}{1-\frac{|I_\Delta|-1}{n}}\prod_{k\in [K]}\pa{1-\frac{K}{n}}\times \ldots\times \pa{1-\pa{|I_\Delta\cap B_k|-1}\frac{K}{n}}\enspace.\label{eq:leveragingclustering}
\end{align}
We recognize mixed moments of the form \eqref{eq:formula:general_momodent}.
Applying Lemma \ref{lem:upperboundgeneralcumulant} with $\eta=\frac{1}{K}$, $x_0=\frac{1}{n}$ and $y_0=\frac{K}{n}$, we get that, whenever $|supp(S^{(0)})|^2K/n\leq 0.5$ and $K\geq 2$, 
$$\left|C_{\bS}(\pi)\right|\leq 4|\bS|^{2|\bS|}\pa{\frac{1}{K}}^{|supp(S^{(0)})|}\pa{|supp(S^{(0)})|^2\frac{K}{n}}^{|\bS|-1}\pa{\frac{1}{K}}^{\#\pi -1}\enspace,  $$
where we denote $\#\pi=|\ac{\pi(S), S\in \bS}|$. 

\paragraph{Conclusion.}
Back to \eqref{eq:multilinearityclustering}, to upper-bound $|C_{\bS}|$, it remains to sum
 over all possible $\pi= (\pi(S_l))_{l=1,\ldots,|\bS|}\in  [K]^{|\bS|}$ $\pi\in [K]^{\bS}$
\begin{align*}
\left|C_{\bS}\right|\leq &\sum_{\pi=\pa{\pi(S)}_{S\in\bS}}4|\bS|^{2|\bS|}\pa{\frac{1}{K}}^{|supp(S^{(0)})|}\pa{\frac{K|supp(S^{(0)})|^2}{n}}^{|\bS|-1}\pa{\frac{1}{K}}^{\#\pi-1}\\
\leq&4|\bS|^{2|\bS|}\pa{\frac{1}{K}}^{|supp(S^{(0)})|}\pa{\frac{K|supp(S^{(0)})|^2}{n}}^{|\bS|-1}\sum_{k=1}^{|\bS|}\underset{|\pi|=k}{\sum_{\pi=\pa{\pi(S)}_{S\in \bS}}}\pa{\frac{1}{K}}^{k-1}\\
\leq&4|\bS|^{2|\bS|}\pa{\frac{1}{K}}^{|supp(S^{(0)})|}\pa{\frac{K|supp(S^{(0)})|^2}{n}}^{|\bS|-1}\sum_{k=1}^{|\bS|}\pa{\frac{1}{K}}^{k-1}K^k k^{|\bS|}\\
\leq& 4|\bS|^{3|\bS|+1}\pa{\frac{1}{K}}^{|supp(S^{(0)})|-1}\pa{\frac{K|supp(S^{(0)})|^2}{n}}^{|\bS|-1}\enspace,
\end{align*}
which concludes the proof of Lemma \ref{lem:controlreductedcumulantsclusteringnew}.






\section{Proof of Theorem \ref{thm:lowdegreefeature}}\label{prf:lowdegreefeature}

\begin{rem}
The observation $Y$ can either be seen as a matrix $Y\in \R^{KM\times p}$ or as a tensor $Y\in \R^{K\times M\times p}$. For clarity, we consider throughout the proof the tensor notation. But, we can still apply the framework for proving LD lower-bounds with latent structure from \cite{Even25a} which is written for the case where we observe a matrix $Y\in \R^{n\times p}$. 
\end{rem}










Without loss of generality, we assume in this proof that $\sigma^2=1$. Let $D\in \N$ such that $K\geq 2(D+2)^2$. We suppose
\begin{equation}\label{eq:def:zeta:feature}
\zeta:=64D^{40}\lambda^4p\max\pa{1, \frac{M}{K}}<1\enspace.
\end{equation}
Since the minimization problem defining $MMSE_{\leq D}$ in Equation (\ref{def:MMSE}) is separable, and since the random variables $\Gamma^*_{(k,m), (k',m')}$ are jointly exchangeable both with respect to $(k,k')$ and $(m,m')$, the $MMSE_{\leq D}$ can be reduced to
\begin{align*}
    MMSE_{\leq D}&:=\frac{1}{KMK(M-1)}\sum_{u=(k,m), u'=(k',m') \text{ with }m\neq m'} \inf_{f_{uu'}\in \R_{D}(Y)}\E\cro{\pa{f_{uu'}(Y)-\Gamma^*_{uu'}}^2}\\
&=\inf_{f\in \R_{D}(Y)}\E\cro{\pa{f(Y)-\Gamma^*_{(1,1),(1,2)}}^2}\enspace.
\end{align*}
For all $(k,m)\in [K]\times [M]$, in order to keep in line with the notation of Section \ref{sec:globalmethod}, we write $\pi^*(k,m)=\pi^*_m(k)$. In the remaining of the proof, we write $x=\Gamma^*_{(1,1),(1,2)}=\1\{\pi^*(1,1)=\pi^*(1,2)\}$. Then, our goal is to upper-bound 
$$MMSE_{\leq D}=\inf_{f\in \R_{D}(Y)}\E\cro{\pa{f(Y)-x}^2}\enspace.$$
 The model of Definition \ref{def:priorfeaturematching} is a particular case of the Gaussian Additive Model considered by \cite{SchrammWein22}. Therefore, we can use Theorem 2.2 from \cite{SchrammWein22}, stated in Equation \eqref{eq:SW22}. For a tensor $\alpha\in \N^{K\times M\times p}$, we define $|\alpha|=\sum_{k=1}^K\sum_{m=1}^{M}\sum_{j=1}^p \alpha_{k,m,j}$ and $\alpha!=\prod_{k,m,j}\alpha_{k,m,j}$. We write $X\in \R^{K\times M\times p}$ the signal matrix defined by $X_{k,m,j}=\pa{\mu_{\pi^*(k,m)}}_j$. Using Equation \eqref{eq:SW22}, we have the following lower-bound on the low-degree MMSE
 \begin{equation}\label{eq:SW22featurematching}
 MMSE_{\leq D}\geq \frac{1}{K}-\frac{1}{K^2}-\underset{0<|\alpha|\leq D}{\sum_{\alpha\in \N^{K\times M\times p}}}\frac{\kappa_{x,\alpha}^2}{\alpha!}\enspace,
 \end{equation}
where $\kappa_{x,\alpha}$ for $\alpha\in \N^{K\times M\times p}$ is the cumulant $\cumul(x,\ac{X_{k,m,j}}_{(k,m,j)\in \alpha})$, where $\ac{X_{k,m,j}}_{(k,m,j)\in \alpha}$ is the multiset that contains $\alpha_{k,m,j}$ copies of $X_{k,m,j}$, for $(k,m,j)\in[K]\times [M]\times [p]$.
Hence, in order to prove Theorem~\ref{thm:lowdegreefeature}, it is sufficient  to prove that
\begin{equation}\label{eq:objective_lower_bound_feature_matching}
   \underset{0<|\alpha|\leq D}{\sum_{\alpha\in \N^{K\times M\times p}}}\frac{\kappa_{x,\alpha}^2}{\alpha!} \leq 
   \frac{64(D+1)D^{36}}{K^2}\frac{\zeta}{1-\sqrt{\zeta}}\enspace . 
\end{equation}
The first step is to find necessary conditions for having $\kappa_{x,\alpha}\neq 0$. In the following, we define 
\begin{align*}
supp(\alpha)&:=\ac{(k,m)\in [K]\times [M],\enspace \sum_{j\in [p]}\alpha_{k,m,j}\neq 0}\enspace ;\\
sample(\alpha)&=\ac{m\in [M],\enspace \sum_{k\in [K]}\sum_{j\in [p]}\alpha_{k,m,j}\neq 0}\enspace ;\\
col(\alpha)&=\ac{j\in [p],\enspace \sum_{k\in [K]}\sum_{l\in [M]}\alpha_{k,m,j}\neq 0}\enspace\ ,
\end{align*}
where $col(\alpha)$ is the set of features involved in $\alpha$, $sample(\alpha)$ is the collection of data-sets involved in $\alpha$. 
The following lemma establishes some sufficient conditions for the nullity of the cumulant $\kappa_{x,\alpha}$. It is based on some independence properties together with Lemma~\ref{lem:independentcumulant}.

\begin{lem}\label{lem:nullitycumulantfeature}
Let $\alpha\in \N^{K\times M\times p}\neq0$ such that $\kappa_{x,\alpha}\neq 0$. Then, $|\alpha|\geq \max\pa{2|col(\alpha)|, 2|sample(\alpha)\cup\ac{1,2}|-2}$. In particular, we have $|\alpha|\geq 2$.
\end{lem}
The second step, which contains in fact the core of the arguments amounts to controlling the remaining $\kappa_{x,\alpha}$'s. 

\begin{lem}\label{lem:controlcumulantsfeature}
Let $\alpha\neq 0\in \N^{K\times M\times p}$ with $|\alpha|\geq 2$. Suppose that $K\geq 2\left|supp(\alpha)\cup \ac{(1,1), (1,2)}\right|^2$, then
$$|\kappa_{x,\alpha}|\leq \lambda^{|\alpha|}\pa{8|\alpha|^{18}}^{\frac{|\alpha|}{2}+1}\pa{\frac{1}{K}}^{\left|supp(\alpha)\cup\ac{(1,1),(1,2)}\right|-1}\enspace.$$
\end{lem}



For $d\in [2,D]$, $v\in [KM]$ and $l\in [M]$ satisfying $d\geq 2l$ and $v\geq l$, there exist at most $\pa{vd/2}^{d}K^{v-2}m^{l-2}p^{d/2}\leq \pa{d}^{2d}K^{v-2}M^{l-2}p^{d/2}$ matrices $\alpha$ with $d=|\alpha|$, $d\geq 2|col(\alpha)|$, $l=|sample(\alpha)\cup\ac{1,2}|$ and $v=|supp(\alpha)\cup \ac{(1,1), (1,2)}|$. Combining Lemma \ref{lem:nullitycumulantfeature} and Lemma \ref{lem:controlcumulantsfeature} leads us to 
\begin{align*}
\underset{0<|\alpha|\leq D}{\sum_{\alpha\in \N^{K\times m\times p}}}\frac{\kappa_{x,\alpha}^2}{\alpha!}\leq& 4\sum_{d=2}^{D}\sum_{v=2}^{d+2}\ \sum_{l=2}^{v\wedge (d/2+1)}D^{2d}K^{v-2}M^{l-2}p^{d/2}\pa{8D^{18}}^{d+2}\lambda^{2d}\pa{\frac{1}{K^2}}^{v-1}\\
\leq&\frac{64D^{36}}{K^2}\sum_{d=2}^{D}\sum_{v=2}^{d+2}\sum_{l=2}^{v\wedge (d/2+1)}\pa{\lambda^2\sqrt{p}8D^{20}}^{d}\pa{\frac{1}{K}}^{v-2}M^{l-2}\\
\leq& \frac{64D^{36}}{K^2}\sum_{d=2}^{D}\sum_{v=2}^{d+2}\sum_{l=2}^{v\wedge (d/2+1)}\pa{\lambda^2\sqrt{p}8D^{20}}^{d}\pa{\frac{M}{K}}^{l-2}\\
\leq &\frac{64(D+1)D^{36}}{K^2}\sum_{d=2}^{D}\sum_{l=0}^{d/2-1}\pa{\lambda^2\sqrt{p}8D^{20}}^{d-2l}\pa{64D^{40}\lambda^4p\frac{M}{K}}^{l}\\
\leq & \frac{64(D+1)D^{36}}{K^2}\sum_{d=2}^{+\infty}\sqrt{\zeta}^d\\
\leq & \frac{64(D+1)D^{36}}{K^2}\frac{\zeta}{1-\sqrt{\zeta}}\enspace,
\end{align*}
where we used the definition~\eqref{eq:def:zeta:feature} of $\zeta$ in the penultimate line. We have shown~\eqref{eq:objective_lower_bound_feature_matching}, which concludes the proof of Theorem \ref{thm:lowdegreefeature}.







\subsection{Proof of Lemma~\ref{lem:nullitycumulantfeature}}

Let $\alpha\in \N^{K\times M\times p}\neq 0$ such that $\kappa_{x,\alpha}\neq 0$. Let us first prove that $|\alpha|\geq 2|col(\alpha)|$. For that, it is sufficient to prove that, for all $j\in col(\alpha)$, $\sum_{k=1}^K\sum_{m=1}^M\alpha_{k,m,j}\geq 2$.

 Let us consider $\alpha$ such that there exists $j_0\in col(\alpha)$ with $\sum_{k=1}^K\sum_{m=1}^M\alpha_{k,m,j_0}=1$. The joint distribution of $(x, \pa{X_{k,m,j}}_{k,m,j\in [K]\times [M]\times [p]})$ and  $(x, \pa{\pa{-1}^{\1\ac{j=j_0}}X_{k,m,j}}_{k,m,j\in [K]\times [M]\times [p]})$ are the same, so we have 
\begin{align*}\kappa_{x,\alpha}=&\cumul\pa{x, (X_{k,m,j})_{k,m,j\in \alpha}}=\cumul\pa{x, (\pa{-1}^{\1\ac{j=j_0}}X_{k,m,j})_{k,m,j\in \alpha}}\\
=&-\cumul\pa{x, (X_{k,m,j})_{k,m,j\in \alpha}}=-\kappa_{x,\alpha}\enspace,
\end{align*}
which, in turn, implies $\kappa_{x,\alpha}=0$ for such an $\alpha$. As a consequence, if $\kappa_{x,\alpha}\neq 0$ then $|\alpha|\geq 2|col(\alpha)|$.



Let us now prove that $|\alpha|\geq 2|sample(\alpha)\cup \ac{1,2}|-2$. Using Proposition~\ref{thm:LTC}, we know that $|\alpha|$ is even and that there exists at least a decomposition $(\beta_1,\ldots,\beta_l)$ of $\alpha$, with $|\beta_s|=2$ of the form $\beta_s=\ac{(k_s, m_s, j_s), (k'_s, m'_s, j_s)}$, such that 
$$\cumul\pa{x, \pa{\1\ac{\pi^*(k_s,m_s)=\pi^*(k'_s,m'_s)}}_{s\in [1,l]}}\neq 0\enspace. $$
Let us take the convention $k_0=1$, $k'_0=1$, $m_0=1$ and $m'_0=2$. Hence, we get 
\begin{equation}\label{eq:cumulant:simplie:non_zero}
\cumul\pa{\pa{\1\ac{\pi^*(k_s,m_s)=\pi^*(k'_s,m'_s)}}_{s\in [0,l]}}\neq 0\enspace. 
\end{equation}
Let us prove the following claim: for all $m\in \cup_{s\in [0,l]}\ac{m_s, m'_s}$, we have $\sum_{s\in [0,l]}\1\ac{m_s=m}+\1\ac{m'_s=m}\geq 2$. To do so, we suppose that it is not the case and we shall find a contradiction. Let $m\in \cup_{s\in [0,l]}\ac{m_s, m'_s}$ with $\sum_{s\in [0,l]}\1\ac{m_s=m}+\1\ac{m'_s=m}= 1$. By symmetry, suppose that  $m=m_{s_0}$. Then, $\pi^*\pa{k_{s_0},m_{s_0}}$ is independent of $\pa{\pa{\pi^*(k_s,m_s)}_{s\in [0,l] \setminus s_0}, \pi^*\pa{k'_{s_0},m'_{s_0}}}$ and so $\1\ac{\pi^*(k_{s_0},m_{s_0})=\pi^*(k'_{s_0},m'_{s_0})}$ is a Bernoulli with parameter $1/K$ independent from the random variables $\pa{\1\ac{\pi^*(k_{s},m_{s})=\pi^*(k'_{s},m'_{s})}}_{s\in [0,l]\setminus \ac{s_0}}$. Using Lemma \ref{lem:independentcumulant}, we deduce that $\cumul\pa{\pa{\1\ac{\pi^*(k_s,m_s)=\pi^*(k'_s,m'_s)}}_{s\in [0,l]}}=0$, which contradicts~\eqref{eq:cumulant:simplie:non_zero}. We conclude that, for all $m\in \cup_{s\in [0,l]}\ac{m_s, m'_s}$, $\sum_{s\in [0,l]}\1\ac{m_s=m}+\1\ac{m'_s=m}\geq 2$. 

From this claim, we deduce that $2l+2\geq 2|sample(\alpha)\cup \ac{1,2}|$ which implies $|\alpha|\geq 2|sample(\alpha)\cup \ac{1,2}|-2$. This concludes the proof of Lemma~\ref{lem:nullitycumulantfeature}. 










\subsection{Proof of Lemma \ref{lem:controlcumulantsfeature}}\label{prf:controlcumulantsfeature}

Let $\alpha\neq 0\in \N^{K\times M\times p}$. We recall the hypothesis $K\geq 2\left|supp(\alpha)\cup \ac{(1,1), (1,2)}\right|^2$. Using Proposition~\ref{thm:LTC}, we are reduced to upper-bounding, for any decomposition $(\beta_1,\ldots,\beta_l)$ of $\alpha$, with $|\beta_s|=2$ of the form $\beta_s=\ac{(k_s, m_s, j_s), (k'_s, m'_s, j_s)}$, the cumulant 
$$\cumul\pa{x, \pa{\1\ac{\pi^*(k_s,m_s)=\pi^*(k'_s,m'_s)}}_{s\in [1,l]}}\enspace. $$
Let us take the convention $k_0=1$, $k'_0=1$, $m_0=1$ and $m'_0=2$. With this notation, we can write
\begin{equation}\label{eq:cumulant:feature:partition}
\cumul\pa{x, \pa{\1\ac{\pi^*(k_s,m_s)=\pi^*(k'_s,m'_s)}}_{s\in [1,l]}}=\cumul\pa{\pa{\1\ac{\pi^*(k_s,m_s)=\pi^*(k'_s,m'_s)}}_{s\in [0,l]}}\enspace. 
\end{equation}


\paragraph{Step 1: Reduction.}  As explained in Section~\ref{sec:globalmethod}, we first reduce the control of the cumulant \eqref{eq:cumulant:feature:partition} to the control of cumulants of products of strongly dependent $\1\ac{\pi^*\pa{k_s,m_s}=\pi^*\pa{k'_s,m'_s} }$. As previously, we introduce a weighted graph to which we will apply Proposition \ref{prop:feray}. Let $\cW$ be the weighted graph on $[0,l]$ with weights $w_{s,s'}$ defined by;
\begin{itemize}
\item If $\ac{(k_s, m_s), (k'_s, m'_s)}\cap \ac{(k_{s'}, m_{s'}), (k'_{s'}, m'_{s'})}\neq \emptyset$, then $w_{s,s'}=1$;
\item If $\ac{(k_s, m_s), (k'_s, m'_s)}\cap \ac{(k_{s'}, m_{s'}), (k'_{s'}, m'_{s'})}=\emptyset$, then $w_{s,s'}=w\in (0,1)$, 
\end{itemize}
where $w$ is to be fixed later. 


Let $S^{(0)}\subseteq [0,l]$. Denote by $\cW\<1\>[S^{(0)}]$ the subgraph induced by $S^{(0)}$ while only keeping the edges of weight 1, and by
$\bS=S_1,\ldots, S_{|\bS|}$ the partition of $S^{(0)}$  into the connected components of  $\cW\<1\>[S^{(0)}]$. In order to apply Proposition \ref{prop:feray}, we shall upper-bound, for such a $S^{(0)}$, the cumulant 
$$C_{\bS}:=\cumul\pa{\pa{\prod_{s\in S}\1\ac{\pi^*(k_s,m_s)=\pi^*(k'_s,m'_s)}}_{S\in \bS}}\enspace,$$
with respect to the maximum weight $\bbM\pa{\cW[S^{(0)}]}=\pa{w}^{|\bS|-1}$. The next lemma  (steps 2-4 of Section~\ref{sec:globalmethod}) provides such an upper-bound.

\begin{lem}\label{lem:controlreductedcumulantsfeature}
Let $S^{(0)}\subseteq [0,l]$ and let $\bS$ be its partition into the connected components of $\cW\<1\>[S^{(0)}]$. Writing $supp(S^{(0)})=\cup_{s\in S^{(0)}}\ac{(k_s, m_s), (k'_s, m'_s)}$, we have, whenever $K\geq 2|supp(S^{(0)})|^2$,
$$\left|C_{\bS}\right|\leq \pa{2|\bS|^{9}}^{|\bS|}|supp(S^{(0)})|^{2|\bS|}\pa{\frac{1}{K}}^{|supp(S^{(0)})|-1}\enspace.$$
\end{lem}


From Lemma \ref{lem:controlreductedcumulantsfeature}, we know that for any $S^{(0)}\subseteq [0,l]$ with $\bS$ the connected components of $\cW\<1\>[S^{(0)}]$,
$$\left|C_{\bS}\right|\leq \pa{2(l+1)^{9}}^{l+1}\pa{
2l+2}^{2(l+1)}\pa{\frac{1}{K}}^{|supp(S^{(0)})|-1}w^{-l-1}\bbM\pa{\cW[S^{(0)}]}\enspace.$$
The function $S\to \pa{\frac{1}{K}}^{|supp(S)|-1} $ is super-multiplicative. Hence, applying Proposition \ref{prop:feray} and Lemma~\ref{lem:subexponential} together with the fact that $\bbM\pa{\cW}\leq 1$, we get that 
$$\left|\cumul\pa{\pa{\1\ac{\pi^*(k_s,m_s)=\pi^*(k'_s,m'_s)}}_{s\in [0,l]}}\right| \leq w^{-l-1}\pa{8\pa{l+1}^{17}}^{l+1}\pa{\frac{1}{K}}^{|supp(\alpha)\cup\ac{(1,1), (1,2)}|-1}.$$
We also have $l=\frac{|\alpha|}{2}$ and so $l+1\leq |\alpha|$. Since the above bound is valid for any $w<1$, by taking $w$ arbitrarily close to one, we conclude that 
$$\left|\cumul\pa{\pa{\1\ac{\pi^*(k_s,m_s)=\pi^*(k'_s,m'_s)}}_{s\in [0,l]}}\right|\leq \pa{8|\alpha|^{17}}^{\frac{|\alpha|}{2}+1}\pa{\frac{1}{K}}^{\left|supp(\alpha)\cup\ac{(1,1),(1,2)}\right|-1}.$$
This bound of the cumulant~\eqref{eq:cumulant:feature:partition} is valid for for any decomposition $\beta_1,\ldots, \beta_l$ of $\alpha$ with $\beta_s=\ac{(k_s, m_s, j_s), (k'_s, m'_s, j_s)}$. Since the number of such decomposition is at most $|\alpha|^{\frac{|\alpha|}{2}-1}$, we deduce from Proposition~\ref{thm:LTC} that 
$$|\kappa_{x,\alpha}|\leq \lambda^{|\alpha|}\pa{8|\alpha|^{18}}^{\frac{|\alpha|}{2}+1}\pa{\frac{1}{K}}^{\left|supp(\alpha)\cup\ac{(1,1),(1,2)}\right|-1}\enspace.$$
This concludes the proof of Lemma \ref{lem:controlcumulantsfeature}.




\subsection{Proof of Lemma \ref{lem:controlreductedcumulantsfeature}}\label{prf:controlreductedcumulantsfeature}


\paragraph{Step 2: Expansion.} Let $S^{(0)}\subseteq [0,l]$ and let $\bS=S_1,\ldots, S_{|\bS|}$ the connected components of $\cW\<1\>[S^{(0)}]$. We seek to control 
$$C_{\bS}:=\cumul\pa{\pa{\prod_{s\in S}\1\ac{\pi^*(k_s,m_s)=\pi^*(k'_s,m'_s)}}_{S\in \bS}}\enspace.$$
For any $S\subseteq [0,l]$, we write $supp(S)=\cup_{s\in S}\ac{(k_{s}, m_s), (k'_s, m'_s)}$. For $R\subseteq [|\bS|]$, we write $I_{R}=\cup_{t\in R}supp(S_t)$. By definition of the graph $\cW$, the sets $supp(S_t)$ are disjoint and form a partition of $supp(S^{(0)})$. Moreover, for all $(k,m'),(k', m'')\in supp(S_t)$, there exists a path $s_1,\ldots, s_{h}\subseteq S_{t}$ such that $(k,m')\in \ac{(k_{s_1}, m_{s_1}), (k'_{s_1}, m'_{s_1})}$ and $(k', m'')\in \ac{(k_{s_h}, m_{s_h}), (k'_{s_h}, m'_{s_h})}$ and such that $\cW$ has an edge of weight $1$ between all $s_{h'}, s_{h'+1}$. Thus, for $t\in [|\bS|]$, $\prod_{s\in S_{t}}\1\ac{\pi^*(k_s,m_s)=\pi^*(k'_s,m'_s)}$ can be written 
$$\prod_{s\in S_{t}}\1\ac{\pi^*(k_s,m_s)=\pi^*(k'_s,m'_s)}=\sum_{a \in [K]}\prod_{(k,m)\in supp(S_t)}\1\ac{\pi^*(k,m)=a}\enspace.$$
Hence, we are interested in configurations $\pi^*$ that are constant on each $S_t$ for $t=1,\ldots, |\bS|$. For that purpose, we consider  $\pi= (\pi(S_t))_{t=1,\ldots,|\bS|}\in  [K]^{|\bS|}$. Then, using the multilinearity of cumulants, we get
\begin{equation}\label{eq:multilinearityfeature}
C_{\bS}=\sum_{\pi=\pa{\pi(S)}_{S\in \bS}\in [K]^{\bS}}\cumul\pa{\pa{\prod_{(k,m)\in supp(S)}\1\ac{\pi^*(k,m)=\pi(S)}}_{S\in \bS}}\enspace.
\end{equation}
Let us fix such a $\pi=\pa{\pi_S}_{S\in \bS}\in [K]^{\bS}$, and  for $S\in \bS$, let us define 
$$Z_{\pi,S}=\prod_{(k,m)\in supp(S)}\1\ac{\pi^*(k,m)=\pi(S)}.$$ 
  In the following, we shall control 
  $$C_{\bS}(\pi):=\cumul\pa{\pa{Z_{\pi,S}}_{S\in \bS}}=\cumul\pa{\pa{\prod_{(k,m)\in supp(S)}\1\ac{\pi^*(k,m)=\pi(S)}}_{S\in \bS}}.$$



\paragraph{Step 3: Pruning incompatible configurations.}
Note that $k\to \pi(k,m)$ defined by $\pi(k,m)=\pi(S)$ for $(k,m)\in supp(S)$ may not be injective, in which case it is impossible to have all the $Z_{\pi,S}$ non zero for $S\in\bS$. To cope with such cases,
we shall apply Proposition \ref{prop:feray} to a weighted dependency graph $\cV$  on $|\bS|$ defined by
\begin{itemize}
\item an edge of weight $1$ between $t$ and $t'$ if and only if $\pi(S_t)=\pi(S_{t'})$ and $\cup_{s\in S_t}\ac{m_{s}, m'_s}\cap \cup_{s\in S_{t'}}\ac{m_{s}, m'_s}\neq \emptyset$,
\item an edge of weight $\frac{|supp(S^{(0)})|^2}{K}$ otherwise.
\end{itemize}
We highlight the fact that, although this is not explicit, $\cV$ actually depends on the choice of $\pi=\pa{\pi(S)}_{S\in \bS}$. 
Weights 1 are attributed to connected components having the same value $\pi(S)$ and sharing some common datasets. 

Consider the case where  $R\subseteq [|\bS|]$ is such that $\cV$ has an edge of weight $1$ between two nodes of $R$. Then, writing $t$ and $t'$ two such nodes that are connected in $\cV$ be an edge of weight $1$, we observe that this implies that $\pi(S_t)= \pi(S_{t'})$ and there exists $m\in [M]$ such that $m$ belongs to both $\cup_{s\in S_t}\ac{m_{s}, m'_s}$ and $\cup_{s\in S_{t'}}\ac{m_{s}, m'_s}$. Hence, since $S_{t}$ and $S_{t'}$ are disjoint, having $Z_{\pi,S_t}=1$ and $Z_{\pi,S_{t'}}=1$ implies that there exists $k\neq k'$ such that $\pi^*(k,m)=\pi^*(k',m)$, the latter being impossible since $\pi^*(.,m)$ is a permutation of $[K]$. As a consequence, $Z_{\pi,S_{t}}Z_{\pi,S_{t'}}=0$ a.s. Denoting $\bR=R_1,\ldots, R_{|\bR|}$ the connected components of $\cV\<1\>[R]$,  we deduce from Lemma~\ref{lem:independentcumulant} that
\begin{equation}\label{eq:nullityfeaturereduced}
\cumul\pa{\pa{\prod_{t\in R_{h}}Z_{\pi,S_t}}_{h\in [|\bR|]}}=0\enspace.
\end{equation}
On the other hand, if $R\subseteq [|\bS|]$ is such that $\cV$ has no edges of weight $1$ between nodes in $R$, the partition $\bR$ of $R$ induced by the connected components of $\cV\<1\>[R]$ is made of singletons, and can be identified to $R$ itself. Thus, in order to apply Proposition \ref{prop:feray}, we only have to control the cumulants
$$C_{\bS[R]}(\pi):=\cumul\pa{\pa{Z_{\pi,S_t}}_{t\in R}}\enspace ,$$
for all subsets $R$ of $[|\bS|]$ such that $\cV[R]$ does not have any edge of weight $1$. In other words, we only have to control the cumulants for configurations $(\pi(S))_{S\in \bS}$ that are possibly compatible with $\pi^*$. 


\paragraph{Step 4: Leveraging Lemma \ref{lem:upperboundgeneralcumulant}.} 

\begin{lem}\label{lem:reducedcumulantfeature2}
Let $R\subseteq [|\bS|]$ such that $\cV[R]$ does not contain any edge of weight $1$. If $K\geq 2|I_R|^2$, with $I_R=\cup_{t\in R}supp(S_t)$,
$$\left|C_{\bS[R]}(\pi)\right|\leq 2|R|^{2|R|}\pa{\frac{1}{K}}^{|I_R|}\pa{\frac{|I_R|^2}{K}}^{|R|-1}\enspace.$$
\end{lem}

\begin{proof}[Proof of Lemma~\ref{lem:reducedcumulantfeature2}]
Let $R\subseteq [|\bS|]$ such that $\cV[R]$ does not have any edge of weight $1$. For $m\in [M]$, we denote $A_{m}$ the set $\ac{(k,m), k\in [K]}$. Let $\Delta\subseteq R$, $I_\Delta=\cup_{t\in \Delta}supp(S_t)$, and let us compute 
\begin{align}\nonumber
\E\cro{\prod_{t\in \Delta}Z_{\pi,S_t}}=&\P\cro{\forall t\in \Delta, \forall (k,m)\in supp(S_t), \pi^*(k,m)=\pi(S_t)}\\\nonumber
=& \prod_{m=1}^M \frac{1}{K(K-1)\times\ldots\times \pa{K-\pa{|I_{\Delta}\cap A_{m}|-1}}}\\
=& \pa{\frac{1}{K}}^{|I_{\Delta}|}\prod_{m=1}^M \frac{1}{\pa{1-\frac{1}{K}}\times\ldots\times \pa{1-\pa{|I_{\Delta}\cap A_{m}|-1}\frac{1}{K}}}\enspace.\label{eq:leveragingfeature}
\end{align}
We are therefore in position to apply Lemma~\ref{lem:upperboundgeneralcumulant} with $\eta=\frac{1}{K}$ and $x_0=\frac{1}{K}$. Hence, we deduce from \eqref{eq:upperboundgeneralcumulant2} that, whenever $K\geq 2|I_R|^2$, we have
$$\left|C_{\bS[R]}(\pi)\right|\leq2|R|^{2|R|}\pa{\frac{1}{K}}^{|I_R|}\pa{\frac{|I_R|^2}{K}}^{|R|-1}\enspace,$$
which concludes the proof of the lemma.
\end{proof}


The function $R\mapsto \pa{\frac{1}{K}}^{|I_R|}$ is super-multiplicative.  Combining Lemma~\ref{lem:reducedcumulantfeature2} with Proposition~\ref{prop:feray} and Lemma~\ref{lem:subexponential}, we end up with 
$$\left|C_{\bS}(\pi)\right|\leq 2|\bS|^{8|\bS|}\pa{\frac{1}{K}}^{|supp(S^{(0)})|}\bbM\pa{\cV}\enspace.$$



\paragraph{Conclusion.}
For $\pi=\pa{\pi(S)}_{S\in\bS}\in [K]^{\bS}$, we write $cc(\pi)$ the number of connected components of the induced graph $\cV\<1\>$ (we recall that the graph $\cV$ depends on the choice of $\pi$). In light of the definition of $\bbM\pa{\cV}$, we arrive at
$$\left|C_{\bS}(\pi)\right|\leq 2|\bS|^{8|\bS|}\pa{\frac{1}{K}}^{|supp(S^{(0)})|}\pa{\frac{|supp(S^{(0)})|^2}{K}}^{cc(\pi)-1}\enspace , $$
for any $\pi$. 
Plugging this inequality in \eqref{eq:multilinearityfeature} leads us to 
$$|C_{\bS}|\leq 2|\bS|^{8|\bS|}\pa{\frac{1}{K}}^{|supp(S^{(0)})|}\sum_{cc=1}^{|\bS|}\underset{cc(\pi)=cc}{\sum_{\pi\in [K]^{\bS}}}\pa{\frac{|supp(S^{(0)})|^2}{K}}^{cc-1}\enspace.$$
The following lemma bounds the number of configurations $\pi$ with a given number of $cc(\pi)$. 
\begin{lem}\label{lem:numberk}
For any $cc\in [|\bS|]$, we have 
\[
\left|\ac{\pi=\pa{\pi_S}_{S\in \bS}\in [K]^{\bS},\enspace cc(\pi)=cc}\right|\leq (2|\bS|)^{|\bS|}K^{cc}\enspace.
\]
\end{lem}


Putting everything together, we conclude that 
\begin{align*}
|C_{\bS}|\leq& 2|\bS|^{8|\bS|}\pa{\frac{1}{K}}^{|supp(S^{(0)})|}\sum_{cc=1}^{|\bS|}\underset{cc(\pi)=cc}{\sum_{\pi\in [K]^{\bS}}}\pa{\frac{|supp(S^{(0)})|^2}{K}}^{cc-1}\\
\leq & 2\pa{2|\bS|^9}^{\bS}\pa{\frac{1}{K}}^{|supp(S^{(0)})|-1}\sum_{cc=1}^{|\bS|}|supp(S^{(0)})|^{2cc-2}\\
\leq& \pa{2|\bS|^{9}}^{|\bS|}|supp(S^{(0)})|^{2|\bS|}\pa{\frac{1}{K}}^{|supp(S^{(0)})|-1}\enspace.
\end{align*}
The proof of Lemma \ref{lem:controlreductedcumulantsfeature} is complete










\subsection{Proof of Lemma \ref{lem:numberk}}\label{prf:numberk}

Let us fix $cc\in [|\bS|]$, and let us count the number of $\pi=\pa{\pi_S}_{S\in \bS}$ with $cc(\pi)=cc$. To do so, we fix a permutation $\psi\in \mathcal{S}([|\bS|])$ of $[|\bS|]$ and we fix $\cG$ a subgraph of the set of edges $\ac{(\psi(1), \psi(2)),(\psi(2), \psi(3)),\ldots, (\psi(|\bS|-1), \psi(|\bS|))}$ having exactly $cc$ connected components. We first seek to upper-bound the number of $\pi$'s such that the induced graph $\cV\<1\>$ has the same connected components as $\cG$. In order to highlight the dependency of $\cV$ with respect to $\pi$, we now write $\cG_{\pi}$ for $\cV\<1\>$. If $\cG$ has an edge between $t$, $t'\in [|\bS|]$, then we must choose $\pi$ satisfying $\pi_{S_t}=\pi_{S_t'}$. So, for $R$ a connected component of $\cG$, we must have $\pi_{S_{t}}=\pi_{S_{t'}}$ for all $t,t'\in R$. Hence, there are at most $K^{cc}$ possibilities for choosing $\pi$ such that $\cG_\pi$ has the same connected components as  $\cG$. 

In total, the number of $\pi\in [K]^{\bS}$ such that $cc(\pi)=cc$ is at most $ (2|\bS|)^{|\bS|}K^{cc}$. This concludes the proof of Lemma \ref{lem:numberk}.













\section{Proof of Theorem \ref{thm:lowdegreeseriation}}\label{prf:lowdegreeseriation}

Without loss of generality, we assume through the proof that $\sigma^2=1$. Let $D\in \N$ such that $n\geq 2(2D+2)^2$. We suppose
$$\zeta:=2^{12}\lambda^2\pa{D+1}^{42}\max\pa{1,\frac{4\rho^2}{n}}<1\enspace.$$
Denote $x=\1\ac{|\pi^*(1)-\pi^*(2)|\leq \rho}$. Since the minimization problem defining $MMSE_{\leq D}$ in Equation (\ref{def:MMSE:seriation}) is separable, and since the random variables $X_{ij}$ are jointly exchangeable, the $MMSE_{\leq D}$ can be reduced to
$$MMSE_{\leq D}=\lambda^2 \frac{n-1}{n}\inf_{f\in \R_D[Y]}\E\cro{\pa{f(Y)-x}^2}\enspace.$$
We can compute $\E\cro{x}= \frac{2\rho}{n-1}\pa{1- \frac{\rho+1}{2n}}$.
The model considered is a particular case of the Gaussian Additive model analyzed by \cite{SchrammWein22} and hence, we can use Equation \eqref{eq:SW22}
\begin{equation*}\label{eq:SW22seriation}
\frac{n}{n-1} MMSE_{\leq D}\geq  \lambda^2 \frac{2\rho}{n-1}\pa{1- \frac{\rho+1}{2n}}-\frac{4\lambda^2 \rho^2}{(n-1)^2}\pa{1- \frac{\rho+1}{2n}}^2-\lambda^2 \underset{D\geq |\alpha|> 0}{\sum_{\alpha\in \N^{n\times n}}}\frac{\kappa_{x,\alpha}^2}{\alpha!}\enspace,
\end{equation*}
where $\kappa_{x,\alpha}$ for $\alpha\in \N^{n\times n}$ is the cumulant $\kappa_{x,\alpha}=\cumul\pa{x,\pa{X_{ij}}_{ij\in \alpha}}$, where $\pa{X_{ij}}_{ij\in \alpha}$
 is the multiset that contains $\alpha_{ij}$ copies of $X_{ij}$, for $i,j\in[1,n]$. In light of Equation \eqref{eq:SW22seriation}, it is sufficient, for proving Theorem \ref{thm:lowdegreeseriation}, to establish that 
$$\underset{D\geq |\alpha|> 0}{\sum_{\alpha\in \N^{n\times n}}}\frac{\kappa_{x,\alpha}^2}{\alpha!}\leq 2^{18}\frac{\pa{D+1}^{44}\rho^2}{n^2}\frac{\zeta}{1-\zeta}\enspace.$$
In the proof of this theorem, for $\alpha\in \N^{n\times n}$, we denote $supp(\alpha)=\ac{i\in [n],\enspace \alpha_{i:}\neq 0}\bigcup \ac{i\in [n],\enspace \alpha_{:i}\neq 0}$. Let us define a multigraph $\mathcal{G}_\alpha$ on $[n]$ with $\alpha_{ij}$ edges between the nodes $i$ and $j$, for $i,j\in [n]$. We define $\mathcal{G}_\alpha^-$ the graph obtained after removing the isolated notes (except $1$ and $2$) and we denote $cc(\alpha)$ the number of connected components of $\mathcal{G}_\alpha^-\cup \ac{(1,2)}$, which is the graph $\cG_{\alpha}^{-}$ where we have added an edge between $1$ and $2$. 

The following lemma states the desired control of the cumulant. 
\begin{lem}\label{lem:controlcumulantseriation}
For any $\alpha\neq 0$ with $n\geq 2\pa{|supp(\alpha)\cup\ac{1,2}|}^2$, we have 
$$|\kappa_{x,\alpha}|\leq \lambda^{|\alpha|}2^{5|\alpha|+7 }\pa{|\alpha|+1}^{20|\alpha|+21}
\pa{\frac{2\rho}{n}}^{|supp(\alpha)\cup \ac{1,2}|-1}\pa{\frac{1}{2\rho}}^{cc(\alpha)-1}\enspace.$$
\end{lem}
Before showing this lemma, we first conclude the proof of the theorem. 



For $\alpha\neq 0$,  the number of edges of $\mathcal{G}_\alpha^-\cup \ac{(1,2)}$ is $|\alpha|+1$, and  the number of nodes is $|supp(\alpha)\cup \ac{1,2}|$. Since in $\cG_{\alpha}^{-}$,  no node except possibly $1$ and $2$ are isolated, one deduces from these definitions that  $$|\alpha|\geq \max\pa{|supp(\alpha)\cup\ac{1,2}|-cc(\alpha)-1,\frac{|supp(\alpha)\cup\ac{1,2}|-2}{2}} \ . $$ Moreover, the nodes $1$ and $2$ belong to the same connected component of $\mathcal{G}_\alpha^-\cup \ac{(1,2)}$, so we also have $$|supp(\alpha)\cup\ac{1,2}|\geq cc(\alpha)+1\enspace.$$ Moreover, given $d,cc\geq 1$ and $m\geq cc+1$, with $d\geq \max\pa{m-cc-1,\frac{m-2}{2}}$, there are at most $n^{m-2}m^{2d}\leq n^{m-2}(2d+2)^{2d}$  matrices $\alpha\in \N^{n\times n}$ satisfying $|\alpha|=d$, $|supp(\alpha)\cup \ac{1,2}|=m$ and $cc(\alpha)=cc$. Recall that we assume that $n\geq 2\pa{2D+2}^2$. Combining the last bound with Lemma~\ref{lem:controlcumulantseriation} leads us  to
\begin{align*}
\underset{D\geq |\alpha|> 0}{\sum_{\alpha\in \N^{n\times n}}}\frac{\kappa_{x,\alpha}^2}{\alpha!}\leq&2^{14}\pa{D+1}^{42}\hspace{-1cm}\underset{D\geq d\geq \max\pa{m-cc-1,\frac{m-2}{2}}}{\underset{m\geq cc+1}{\sum_{cc\geq 1}}}\hspace{-1cm}\pa{2D+2}^{2d}\lambda^{2d}\pa{2^{10}\pa{D+1}^{40}}^{d}\pa{\frac{4\rho^2}{n^2}}^{m-1}\pa{\frac{1}{4\rho^2}}^{cc-1}n^{m-2}\\
\leq&2^{16}\frac{\pa{D+1}^{42}\rho^2}{n^2}\underset{D\geq d\geq \max\pa{m-cc-1,\frac{m-2}{2}}}{\underset{m\geq cc+1}{\sum_{cc\geq 1}}}\pa{2^{12}\lambda^2\pa{D+1}^{42}}^d \pa{\frac{4\rho^2}{n}}^{m-2}\pa{\frac{1}{4\rho^2}}^{cc-1}.
\end{align*}
Let us fix $d,cc\geq 1$ and $m\geq cc+1$, with $d\geq \max\pa{m-cc-1,\frac{m-2}{2}}$, and let us upper-bound the term $\Upsilon:= \pa{2^{12}\lambda^2\pa{D+1}^{42}}^d \pa{\frac{4\rho^2}{n}}^{m-2}\pa{\frac{1}{4\rho^2}}^{cc-1}$. Using the hypothesis $d\geq m-cc-1$, we get 
\begin{align*}
\Upsilon\leq &\pa{2^{12}\lambda^2\pa{D+1}^{42}}^{d-m+cc+1}
\pa{\frac{4\rho^2}{n}2^{12}\lambda^2\pa{D+1}^{42}}^{m-cc-1}\pa{\frac{1}{n}}^{cc-1}
\leq \max(\zeta,1/n)^d\enspace 
\end{align*}
by definition of $\zeta$.
We end up with 
\begin{align*}
\underset{D\geq |\alpha|> 0}{\sum_{\alpha\in \N^{n\times n}}}\frac{\kappa_{x,\alpha}^2}{\alpha!}\leq& 2^{16}\frac{\pa{D+1}^{42}\rho^2}{n^2}\underset{D\geq d\geq \max\pa{m-cc-1,\frac{m-2}{2}}}{\underset{m\geq cc+1}{\sum_{cc\geq 1}}}\max(\zeta,1/n)^d\\
\leq & 2^{16}\frac{\pa{D+1}^{42}\rho^2}{n^2}\pa{2D+1}^{2}\sum_{d=1}^D \max(\zeta,1/n)^d\\
\leq& 2^{18}\frac{\pa{D+1}^{44}\rho^2}{n^2}\frac{\max(\zeta,1/n)}{1-\max(\zeta,1/n)}\enspace,
\end{align*}
which concludes the proof of Theorem \ref{thm:lowdegreeseriation}.









\subsection{Proof of Lemma \ref{lem:controlcumulantseriation}}\label{prf:controlcumulantseriation}


Let $\alpha\neq 0\in \N^{n\times n}$ and let us upper-bound the absolute value of $\kappa_{x,\alpha}=\cumul\pa{x,\pa{X_{ij}}_{ij\in \alpha}}$.
We recall that $X_{ij}=\lambda \1\ac{|\pi^*(i)-\pi^*(j)|\leq \rho}$. 
 From the multilinearity of cumulants, we know that $\kappa_{x,\alpha}$ is proportional to $\lambda^{|\alpha|}$. Without loss of generality, we suppose in the following that $\lambda=1$. Let $l=|\alpha|$ and let $(i_s,j_s)_{s\in [l]}$ such that $\alpha=\ac{(i_s, j_s), s\in [l]}$. We use  the convention $i_0=1$ and $j_0=2$. With those notation, $supp(\alpha)\cup \ac{1,2}=\cup_{s\in [0,l]}\ac{i_s, j_s}$, and we have 
\begin{equation}\label{eq:definition:cumulant:seriation}
\kappa_{x,\alpha}=\cumul\pa{\pa{\1\ac{|\pi^*(i_s)-\pi^*(j_s)|\leq \rho}}_{s\in [0,l]}}\enspace.
\end{equation}
This cumulant can be controlled using the general approach described in Section~\ref{sec:globalmethod}. 



\paragraph{Step 1: Reduction.}  As explained in Section~\ref{sec:globalmethod}, we first reduce the control of the cumulant \eqref{eq:definition:cumulant:seriation} to the control of cumulants of products of strongly dependent $\1\ac{\pi^*\pa{i_s}=\pi^*\pa{j_s} }$. We introduce a weighted graph to which we shall apply Proposition \ref{prop:feray}. Let $\cW$ be the weighted graph on $[0,l]$ with weights $w_{s,s'}$ defined by:
\begin{itemize}
\item if $\ac{i_s,j_s}\cap \ac{i_{s'},j_{s'}}\neq \emptyset$, then $w_{s,s'}=1$,
\item if $\ac{i_s,j_s}\cap \ac{i_{s'},j_{s'}}= \emptyset$, then $w_{s,s'}=\frac{1}{2\rho}$.
\end{itemize}
For any subset $S^{(0)}\subseteq [0,l]$, we denote by $\cW\<1\>[S^{(0)}]$   the subgraph of $\cW[S^{(0)}]$, where we only keep the edges with weight one, and we 
 denote by $\bS$ the partition of $S^{(0)}$  into connected components of $\cW\<1\>[S^{(0)}]$. In order to apply Proposition \ref{prop:feray}, we have to bound the cumulant
$$C_{\bS}:=\cumul \pa{\pa{\prod_{s\in S}\1\ac{|\pi^*(i_s)-\pi^*(j_s)|\leq \rho}}_{S\in \bS}}\enspace  .$$
Such a control is provided in the next lemma (steps 2-4 of Section~\ref{sec:globalmethod}), which is proved in Section \ref{prf:reducedcumulantseriation}. For any $S\subseteq [0,l]$, we write $supp(S)=\cup_{s\in S}\ac{i_s,j_s}$. In particular, we have $supp(\alpha)=supp([1,l])$ and $supp(\alpha)\cup \ac{1,2}=supp([0,l])$. 

\begin{lem}\label{lem:reducedcumulantseriation}
Let $S^{(0)}\subseteq [0,l]$ and suppose $n\geq 2\pa{|supp(S^{(0)})|}^2$. Let $\bS$ be the set of connected components of $\cW\<1\>[S^{(0)}]$. Then,
$$|C_{\bS}|\leq  4|\bS|\pa{2|\bS|^{10}|supp(S^{(0)})|^4}^{|\bS|} \pa{\frac{2\rho}{n}}^{|supp(S^{(0)})|-1}\pa{\frac{1}{2\rho}}^{|\bS|-1}\enspace.$$
\end{lem}

Since $\bbM\pa{\cW[S^{(0)}]}=\pa{\frac{1}{2\rho}}^{|\bS|-1}$,
Lemma \ref{lem:reducedcumulantseriation} implies that, for all $S^{(0)}\subseteq [0,l]$, 
$$\left|C_{\bS}\right|\leq 4\pa{l+1}\pa{2(l+1)^{10}|supp(\alpha)\cup\ac{1,2}|^4}^{l+1}\pa{\frac{2\rho}{n}}^{|supp(S^{(0)})|-1}\bbM\pa{\cW[S^{(0)}]}.$$
The function $S^{(0)}\mapsto \pa{\frac{2\rho}{n}}^{|supp(S^{(0)})|-1}$ being super-multiplicative,
applying Proposition \ref{prop:feray} and Lemma~\ref{lem:subexponential}, with the weighted dependency graph $\cW$, we get that, since $l=|\alpha|$ and $|supp(\alpha)\cup\ac{1,2}|\leq 2(|\alpha|+1)$, 
$$|\kappa_{x,\alpha}|\leq 4\pa{|\alpha|+1}\pa{2^5(|\alpha|+1)^{20}}^{|\alpha|+1}\pa{\frac{2\rho}{n}}^{|supp(\alpha)\cup \ac{1,2}|-1}\bbM\pa{\cW}\enspace.$$
The proof of Lemma \ref{lem:controlcumulantseriation} is complete since $\bbM\pa{\cW}=\pa{\frac{1}{2\rho}}^{cc(\alpha)-1}$.




\subsection{Proof of Lemma \ref{lem:reducedcumulantseriation}}\label{prf:reducedcumulantseriation}


\paragraph{Step 2: Expansion.} Let $S^{(0)}\subseteq [0,l]$ and let $\bS=S_1,\ldots, S_{|\bS|}$ the connected components $\cW\<1\>[S^{(0)}]$. Recall that we aim at bounding in absolute value the following cumulant
$$C_{\bS}=\cumul \pa{\pa{\prod_{s\in S}\1\ac{|\pi^*(i_s)-\pi^*(j_s)|\leq \rho}}_{S\in \bS}} \enspace.$$


For $S\in \bS$, we denote $\mathcal{A}_{S}$ the set of all injections $\pi_S:supp(S)\to [n]$ such that, for all $s\in S$, $|\pi_S(i_s)-\pi_S(j_s)|\leq \rho$. We have, for $S\in \bS$, 
$$\prod_{s\in S}\1\ac{|\pi^*(i_s)-\pi^*(j_s)|\leq \rho}=\sum_{\pi_S\in \mathcal{A}_{S}}\prod_{i\in supp(S)}\1\ac{\pi^*(i)=\pi_S(i)}\enspace.$$
By the multilinearity of cumulants, we deduce 
\begin{equation}\label{eq:multilinearityseriation}
C_{\bS}=\sum_{\pi=\pa{\pi_{S}}_{S\in \bS}\in \prod_{S\in \bS}\mathcal{A}_{S}}\cumul\pa{\pa{\prod_{i\in supp(S)}\1\ac{\pi^*(i)=\pi_{S}(i)}}_{S\in \bS}}\enspace.
\end{equation}




Let us fix $\pi=\pa{\pi_S}_{S\in \bS}\in \prod_{S\in \bS}\mathcal{A}_{S}$. For $S\in \bS$ and $i\in supp(S)$, we write $\pi(i)=\pi_S(i)$. For $S\in \bS$, let us write $Z_{\pi, S}=\prod_{i\in supp(S)}\1\ac{\pi^*(i)=\pi(i)}$. In light of~\eqref{eq:multilinearityseriation}, we need to control the cumulants
$$C_{\bS}(\pi):=\cumul\pa{\pa{Z_{\pi, S}}_{S\in \bS}}\enspace.$$
Note that the corresponding function  $\pi$ is possibly non-injective, in which case it is impossible that all $Z_{\pi, S}$ with $S\in \bS$ are simultaneously non-zero. Indeed, if there exists $i\in S$ and $i'\in S'$ such that $\pi(i)=\pi(i')$, it is impossible to have $\pi^*(i)=\pi(i)$ and $\pi^*(i')=\pi(i')$ since $\pi^*$ is permutation of $[n]$. 




\paragraph{Step 3: Pruning incompatible configurations.}  We recall that we write $\bS=S_1,\ldots, S_{|\bS|}$. We shall apply Proposition \ref{prop:feray} to some weighted graph $\cV$ with vertex set $[|\bS|]$ with:
\begin{itemize}
\item an edge of weight $1$ between $t,t'\in [|\bS|]$ if and only if $\ac{\pi(i), i\in supp(S_t)}\cap \ac{\pi(i), i\in supp(S_{t'})}\neq \emptyset$,
\item an edge of weight $\frac{|supp(S^{(0)})|^2}{n}$ between $t$ and $t'$ otherwise.
\end{itemize}
As argued above, if the graph $\cV$ contains at least an edge with weight $1$, then $\pi^*$ cannot be compatible with $\pi$. The graph $\cV$ depends on $\pi$ but we do not write explicitly this dependency for simplicity of notation. If $R\subseteq [|\bS|]$ is such that $\cV$ has an edge of weight $1$ between two nodes of $R$,  denote $\bR=R_1,\ldots,R_{|\bR|}$ the partition of $R$ into connected components of $\cV\<1\>[R]$. If such a connected component $R_h$ contains at least two nodes, this implies that $\prod_{t\in R_{h}}Z_{\pi, S_t}=0$ a.s. since $\prod_{t\in R_{h}}Z_{\pi, S_t}\neq 0$ would imply that, for some $i\neq i'$, $\pi^*(i)= \pi^*(i')$. It then follows from Lemma~\ref{lem:independentcumulant} that 
\begin{equation}\label{eq:nullityseriationreduced}
\cumul\pa{\pa{\prod_{t\in R_{h}}Z_{\pi, S_t}}_{h\in [|\bR|]}}=0\enspace.
\end{equation}


On the other hand, if $R\subseteq [|\bS|]$ is such that $\cV$ has no edges of weight $1$ between nodes in $R$, the partition $\bR$ of $R$ induced by the connected components of $\cV\<1\>[R]$ is made of singletons, and can be identified to $R$ itself. Thus, in order to apply Proposition \ref{prop:feray}, we only have  to control the cumulant $\left| \cumul\pa{\pa{Z_{\pi, S_t}}_{t\in R}}\right|$ for all subsets $R$ of $[|\bS|]$ such that $\cV[R]$ does not have any edge of weight $1$. 





\paragraph{Step 4: Leveraging Lemma \ref{lem:upperboundgeneralcumulant}.} For $R\subseteq [|\bS|]$, let us write $I_R=\cup_{t\in R}supp(S_t)$. 




\begin{lem}\label{lem:reducedcumulantseriation2}
Let $R\subseteq [|\bS|]$ such that $\cV[R]$ does not have any edge of weight $1$. If $n\geq 2|I_R|^2$, 
$$\left|\cumul\pa{\pa{Z_{\pi, S_t}}_{t\in R}}\right|\leq 2|R|^{2|R|}\pa{\frac{1}{n}}^{|I_R|}\pa{\frac{|I_R|^2}{n}}^{|R|-1}\enspace.$$
\end{lem}
\begin{proof}[Proof of Lemma~\ref{lem:reducedcumulantseriation2}]


Let $R\subseteq [|\bS|]$ such that $\cV[R]$ does not have any edge of weight $1$. We recall that  this corresponds to the case where the event such that $\pi^*(i)= \pi(i)$ for all $i\in S_t$ with $t\in R$ holds with positive probability. 
Equivalently, this implies that $\pi$ is an injection on $I_{R}$. We seek to upper-bound $\left| \cumul\pa{\pa{Z_{\pi, S_t}}_{t\in R}}\right|$, where, for $t\in R$, $Z_{\pi, S_t}=\prod_{i\in supp(S_t)}\1\ac{\pi^*(i)=\pi(i)}$. Let $\Delta\subseteq R$, and let us compute, writing $I_\Delta=\cup_{t\in \Delta}supp(S_t)$,
\begin{align}\nonumber
\E\cro{\prod_{t\in \Delta} Z_{\pi, S_t}}=&\P\cro{\forall t\in \Delta, \enspace \forall i\in supp(S_t),\enspace \pi^*(i)=\pi(i)}\\\nonumber
=&\frac{1}{n(n-1)\times \ldots\times (n-|I_\Delta|+1)}\\
=&\pa{\frac{1}{n}}^{|I_\Delta|}\frac{1}{1-\frac{1}{n}}\times \ldots\times \frac{1}{1-\frac{|I_\Delta|-1}{n}}\enspace.\label{eq:leveragingseriation}
\end{align}
We are in position to apply the general bound for cumulants  with weakly dependant random variables from Lemma~\ref{lem:upperboundgeneralcumulant}. Indeed, applying Equation \eqref{eq:upperboundgeneralcumulant2} with $x_0=\eta=\frac{1}{n}$, leads us to
$$\left| \cumul\pa{\pa{Z_{\pi, S_t}}_{t\in R}}\right|\leq 2|R|^{2|R|}\pa{\frac{1}{n}}^{|I_R|}\pa{\frac{|I_R|^2}{n}}^{|R|-1}\enspace.$$
whenever $n\geq 2|I_R|^2$.






\end{proof}

For all $R\subseteq [|\bS|]$, denoting $\bR=R_1,\ldots, R_{|\bR|}$ the connected components of $\cV\<1\>[R]$, we have 
$\bbM\pa{\cV[R]}=\pa{\frac{|I_R|^2}{n}}^{|R|-1}$.
Hence, when $n\geq 2\pa{supp(S^{(0)})}^2$, the identity \eqref{eq:nullityseriationreduced} and Lemma \ref{lem:reducedcumulantseriation2} imply that, 
$$\left|\cumul\pa{\pa{\prod_{t\in R_{h}}Z_{\pi, S_t}}_{h\in [|\bR|]}}\right|\leq 2|R|^{2|R|}\pa{\frac{1}{n}}^{|I_R|}\bbM\pa{\cV[R]}\enspace.$$
Since the function $R\to \pa{\frac{1}{n}}^{|I_R|}$ is super-multiplicative, we have all the ingredients to apply Proposition \ref{prop:feray} and Lemma~\ref{lem:subexponential},  leading to
$$\left|C_{\bS}(\pi)\right|= \left|\cumul\pa{\pa{Z_{\pi, S_t}}_{t\in [|\bS|]}}\right|\leq 2|\bS|^{8|\bS|}\pa{\frac{1}{n}}^{|supp(S^{(0)})|}\bbM\pa{\cV}\enspace.$$



\paragraph{Conclusion.} 
For $\pi=\pa{\pi_S}_{S\in \bS}\in \prod_{S\in \bS}\mathcal{A}_{S}$, we denote $cc(\pi)$ the number of connected components of $\cV\<1\>$ so that $\bbM\pa{\cV} = (|supp(S^{(0)})|^2/n)^{cc(\pi)-1}$. Hence, we have 
$$\left|C_{\bS}(\pi)\right|\leq 2|\bS|^{8|\bS|}\pa{\frac{1}{n}}^{|supp(S^{(0)})|}\pa{\frac{|supp(S^{(0)})|^2}{n}}^{cc(\pi)-1}\enspace.$$
Plugging this inequality in \eqref{eq:multilinearityseriation} leads us to 
\begin{equation}\label{eq:upper:C_bS}
|C_{\bS}|\leq 2|\bS|^{8|\bS|}\pa{\frac{1}{n}}^{|supp(S^{(0)})|}\sum_{cc=1}^{|\bS|}\left|\ac{\pi,\enspace cc(\pi)=cc}\right| \pa{\frac{|supp(S^{(0)})|^2}{n}}^{cc-1}\enspace.
\end{equation}


Let us fix $cc\in [|\bS|]$ and let us count the number of $\pi$'s with $cc(\pi)=cc$.  
\begin{lem}\label{lem:numbersigma}
For any $cc\in [|\bS|]$,
$$\left|\ac{\pi\in \prod_{S\in \bS}\cA_S,\enspace cc(\pi)=cc}\right|\leq (2|\bS|^2|supp(S^{(0)})|^2)^{|\bS|}n^{cc}\pa{2\rho}^{|supp(S^{(0)})|-|\bS|}\enspace.$$
\end{lem}

Combining Lemma \ref{lem:numbersigma} and Eq.~\eqref{eq:upper:C_bS} leads us to 
\begin{align*}
|C_{\bS}|\leq& 2|\bS|^{8|\bS|}\pa{\frac{1}{n}}^{|supp(S^{(0)})|}\sum_{cc=1}^{|\bS|}(2|\bS|^2|supp(S^{(0)})|^2)^{|\bS|}n^{cc}\pa{2\rho}^{|supp(S^{(0)})|-|\bS|} \pa{\frac{|supp(S^{(0)})|^2}{n}}^{cc-1}\\
\leq&2n\pa{2|\bS|^{10}|supp(S^{(0)})|^2}^{|\bS|} \pa{\frac{2\rho}{n}}^{|supp(S^{(0)})|}\pa{\frac{1}{2\rho}}^{|\bS|}\sum_{cc=1}^{|\bS|}|supp(S^{(0)})|^{2(cc-1)}\\
\leq& 4|\bS|\pa{2|\bS|^{10}|supp(S^{(0)})|^4}^{|\bS|} \pa{\frac{2\rho}{n}}^{|supp(S^{(0)})|-1}\pa{\frac{1}{2\rho}}^{|\bS|-1}\enspace.
\end{align*}
This concludes the proof of Lemma \ref{lem:reducedcumulantseriation}.








\subsection{Proof of Lemma \ref{lem:numbersigma}}\label{prf:numbersigma}





Let us fix $cc\in [|\bS|]$ and let us count the number of $\pi=\pa{\pi_S}_{S\in \bS}\in \prod_{S\in \bS}\mathcal{A}_S$'s with $cc(\pi)=cc$. To do so, we fix a permutation $\psi\in \mathcal{S}([|\bS|])$ of $|\bS|$ and we fix $\cG$ a subgraph of the set of edges $\ac{(\psi(1), \psi(2)),(\psi(2), \psi(3)),\ldots, (\psi(|\bS|-1), \psi(|\bS|))}$ having exactly $cc$ connected components. There are less than $|\bS|! 2^{|\bS|}\leq (2|\bS|)^{|\bS|}$ possible choices for $\cG$ and $\psi$. We first seek to upper-bound the number of $\pi$'s such that the induced weighted graph $\cV\<1\>$ with vertex set $[|\bS|]$ has the same connected components as $\cG$. We recall that $\cV\<1\>$ has an edge of weight $1$ between $t,t'\in [|\bS|]$ if and only if there exists $i\in S_t$ and $i'\in S_{t'}$ with $\pi(i)=\pi(i')$. In the following, we write $\cG_{\pi}$ for the graph $\cV\<1\>$ in order to emphasize the dependency with respect to $\pi$. Let us upper-bound the number of $\pi\in \prod_{S\in \bS}\mathcal{A}_S$ such that $\cG_{\pi}$ and $\cG$ have the same connected components. Without loss of generality, we suppose in the following that $\psi$ is the identity; in particular, the connected components of $\cG$ are intervals.

Let us fix $R\subseteq [|\bS|]$ a connected component of $\cG$ and we upper-bound the number of choices for $\pi^{(R)}=\pa{\pi_{S_t}}_{t\in R}\in \prod_{t\in R}\mathcal{A}_{S_t}$ connecting $R$, i.e such that the graph $\cG_{\pi^{(R)}}$ with vertex set $R$ is connected. By symmetry, we can suppose that $R=[|R|]$. Let us choose a permutation $\phi$ of $[|R|]$ and let us count the number of $\pi^{(R)}$ satisfying; for all $t\in [2,|R|]$, $\cG_{\pi^{(R)}}$ has an edge between $\phi(t)$ and $\ac{\phi(t'), t'\leq t-1}$. Without loss of generality, we now suppose that the chosen and fixed permutation $\phi$ is the identity. Let us choose for $t\in [2,|R|]$, an element $i^{t}_1\in supp(S_{t})$ and let us count the number of $\pi^{(R)}=\pa{\pi_{S_t}}_{t\in R}$ such that $\pi_{S_{t}}(i^{t})$ is in $\pa{\cup_{t'\leq t-1}\cup_{i\in S_{t'}}\pi_{S_{t'}}(i)}$. There are at most $\prod_{t\in [|R|]}|supp(S_{t})|$ possibilities for choosing the $i^{t}_1$'s. For $t\leq [|R|]$, let us order $S_{t}=\ac{s_1^{t},\ldots, s^{t}_{|S_{t}|}}$, with $i^{t}_1\in \ac{i_{s_1^{t}}, j_{s_1^{t}}}$, in such a way that, for all $j\in [2,|S_{t}|]$, $\ac{i_{s_j^{t}}, j_{s_j^{t}}}$ intersects $\bigcup_{j'\leq j-1}\ac{i_{s_{j'}^{t}}, j_{s_{j'}^{t}}}$. Then:

\begin{itemize}
\item For $S_{1}$, we choose a value in $[n]$ for $\pi_{S_1}(i_{s_1^{1}})$. That makes $n$ possibilities. Then, choosing the other labels for the elements $supp({S_{1}})$ in the order of appearance in the couples indexed by $\ac{s_1^{1},\ldots, s^1_{|S_{1}|}}$, we have at each time only $2\rho$ possibilities (each label must be at distance at most $\rho$ from the already chosen label of the point which is in the same $\ac{i_{s_j^{1}}, j_{s_j^{1}}}$ for some $j\leq |S_1|$). That makes at most $n(2\rho)^{|supp(S_1)|-1}$ possibilities.
\item For the other $S_{t}$'s, the same thing occurs except that the label of the first element $i^{t}_1$ must be in the labels already chosen previously. That makes at most $|I_R|\pa{2\rho}^{|supp\pa{S_{t}}|-1}$ possibilities, where we recall that $I_R=\cup_{t\leq |R|}supp(S_{t})$.
\end{itemize}
In total, counting the number of possibilities for choosing the $i^{t}_1$'s and for choosing the permutation $\phi$, we have $|R|^{|R|}n\pa{2\rho}^{|I_R|-|R|}|I_R|^{|R|-1}\prod_{t\in R}|supp(S_{t})|$ possibilities. Doing so for all the connected components of $\cG$, the number of $\pi$'s such that $\cG_{\pi}$ has the same connected components as $\cG$ is at most 
$$n^{cc}\pa{2\rho}^{|supp(S^{(0)})|-|\bS|}\pa{|\bS||supp(S^{(0)})|^2}^{|\bS|}\enspace.$$


Multiplying for the number of choices for the graph $G$ and for the permutation $\psi$, we deduce that the number of $\pi\in \prod_{S\in \bS}\mathcal{A}_{S}$ with $cc(\pi)=cc$ is at most 
$$(2|\bS|^2|supp(S^{(0)})|^2)^{\bS}n^{cc}\pa{2\rho}^{|supp(S^{(0)})|-|\bS|}\enspace,$$
which concludes the proof of the lemma.






\section{Proof of Lemma~\ref{lem:upperboundgeneralcumulant}}\label{sec:quazifactorizationseries}






This section is devoted to the proof of Lemma~\ref{lem:upperboundgeneralcumulant}. We first treat the first point of the lemma (case $r\geq 1$), postponing to Section \ref{ref:caser0} the proof for the particular case $r=0$. Assume that $Z_{1},\ldots,Z_{\ell}$ have mixed moments given by \eqref{eq:formula:general_momodent}: for all $\Delta\subseteq R$
\[
\E\cro{\prod_{t\in \Delta}Z_{t}}=\eta^{|I_\Delta|}\prod_{j=1}^q \frac{1}{1-x_0}\times\ldots\times \frac{1}{1-(|I_\Delta\cap A_{j}|-1)x_0}\times\prod_{i=1}^r (1-y_0)\times\ldots\times \pa{1-\pa{|I_\Delta \cap B_{i}|-1}y_0}. \nonumber\ 
\]
The random variables $\pa{Z_{t}}_{t\in [\ell]}$ have their moments that are close to be factorized. If instead of~\eqref{eq:formula:general_momodent}, we had considered random variables $\pa{\tilde{Z}_{t}}_{t\in [\ell]}$, such that, for any $\Delta\subseteq R$, we had 
\[
\E\cro{\prod_{t\in \Delta}\tilde{Z}_{t}}=\eta^{|I_\Delta|}\prod_{j=1}^q \left[\frac{1}{1-x_0}\right]^{|I_{\Delta}\cap A_j|}\prod_{i=1}^r (1-y_0)^{|I_\Delta \cap B_{i}|}\enspace , \nonumber\ 
\]
then, we would have $\E\cro{\prod_{t\in \Delta}\tilde{Z}_{t}}= \prod_{t\in \Delta}\E\cro{\tilde{Z}_{t}}$. Since the mixed moments of $\tilde{Z}_{t}$ are the same as if they were independent, it then follows from Lemmas~\ref{lem:independentcumulant} and~\ref{lem:mobiusformula} that $ \cumul\pa{\pa{\tilde{Z}_{t}}_{t\in [\ell]}}=0$.  The purpose of Lemma~\ref{lem:upperboundgeneralcumulant} is to quantify to what extent the fact that the moments of the $Z_{t}$'s  in~\eqref{eq:formula:general_momodent} are close to be factorized implies that their joint cumulant is small. 


\subsection{Small-cumulant and quasi-factorization}

A key result of F\'eray~\cite{feray2018} is Proposition~5.8 (in~\cite{feray2018}), that we recall here informally. Let $Z_{1},\ldots,Z_{\ell}$ be random variables, with a distribution depending on some parameter $n$, and let $\cL$ be a weighted graph with vertex set $[\ell]$. If for all $\Delta \subseteq [\ell]$ of size at least 2 we have the quasi-factorisation
\begin{equation} \label{eq:quasi-factor}
\prod_{\delta\subseteq \Delta}\E\cro{\prod_{t\in\delta}Z_{t}}^{(-1)^{|\Delta|-|\delta|}}=1+O_{n}(\bbM(\cL[\Delta])),
\end{equation}
then, we have the small cumulant property  for all $\Delta \subseteq [\ell]$ of size at least 2
\begin{equation} \label{eq:small-cumul}
\cumul\pa{\pa{Z_{t}}_{t\in \Delta}}=\prod_{t\in\Delta} \E\cro{Z_{t}} \times O_{n}(\bbM(\cL[\Delta])),
\end{equation}
where $O_{n}(\cdot)$ refers to the parameter $n$, and $\bbM(\cL[\Delta])$ is the weight of the graph $\cL$ restricted to the node set $\Delta$, see Section~\ref{sec:weighted-graph} for the definition of $\bbM$.

To prove Lemma~\ref{lem:upperboundgeneralcumulant}, we provide a non-asymptotic and quantitative version of this result.
Instead of considering moments $\E\cro{\prod_{t\in\delta}Z_{t}}$ as real numbers, our approach is to consider them as bivariates series in $(x_{0},y_{0})$. In this direction, 
for any subset $\Delta\subseteq [\ell]$, we introduce the multivariate series
\begin{align}\label{eq:definition_u_Delta}
u_\Delta(x,y):=&\eta^{|I_\Delta|}\prod_{j=1}^q \frac{1}{1-x}\times\ldots\times \frac{1}{1-(|I_\Delta\cap A_{j}|-1)x}\cdot \prod_{i=1}^{r}(1-y)\times\ldots\times \pa{1-\pa{|I_\Delta \cap B_{i}|-1}y}, 
\end{align}
with the convention that $u_{\emptyset}=1$. We have $\E\cro{\prod_{t\in \Delta}Z_{t}}= u_\Delta(x_0,y_0)$, and 
 $u_\Delta(x,y)$  is well-defined when $x<\frac{1}{L}$, where $L=|I_{[\ell]}|$. 


Having in mind the Möbius formula (Lemma~\ref{lem:mobiusformula}) for cumulants,  we define, for $\Delta\subseteq [\ell]$, the bivariate series
 \begin{equation}\label{eq:definition:kappa_Delta}
 \kappa_{\Delta}(x,y):=\sum_{G\in \mathcal{P}[\Delta]}m(G)\prod_{\delta\in G}u_{\delta}(x,y)\enspace ,
 \end{equation}
so that 
 \begin{equation}\label{eq:cumul:kappa}
    \cumul\pa{\pa{Z_{t}}_{t\in [\ell]}}=\kappa_{[\ell]}(x_0,y_0)\enspace.
    \end{equation}
 To derive a non asymptotic upper bound on $\kappa_{[\ell]}(x_0,y_0)$, we will first control the so-called \emph{order} (defined in Section~\ref{sec:order})  of the bivariate series $\kappa_{[\ell]}(x,y)$, by building on ideas from~\cite{feray2018}.  Then, this will allow us to work around the non-asymptotic bound by carefully bounding the terms. The counterpart of the 
 quasi-factorisation property \eqref{eq:quasi-factor} in our framework, will be some lower bound on the order of  the following bivariate rational function $P_{\Delta}[u]$.

 \begin{definition}\label{defi:P_delta}
Consider any family $(u_{\Delta}(x,y))$ with $\Delta\subseteq [\ell]$ of bivariate power series with an open domain of convergence.  
For $\Delta\subseteq  [\ell]$ non empty, we define the multivariate rational function 
\begin{equation}\label{eq:definition_P_Delta}
P_{\Delta}[u](x,y):=\prod_{\delta\subseteq \Delta}\pa{u_{\delta}(x,y)}^{(-1)^{|\Delta|-|\delta|}}\enspace. 
\end{equation}
\end{definition} 


A key property of the rational function $P_{\Delta}[v](x,y)$ is that when the power series $(v_\Delta(x,y))_{\Delta\subset[\ell]}$ can be factorized, as if they were mixed moments of variables with some independence, then $P_{\Delta}[v](x,y)=1$.



\begin{lem}\label{lem:independentquasifacto}
Let $\ell \geq 1$ and $v=(v_\Delta(x,y))_{\Delta\subseteq[\ell]}$ be a family of power series indexed by subsets of $[\ell]$. For some $(x,y)$ in the domain, we suppose that  for all $\Delta\subseteq [\ell]$, $v_\Delta(x,y)\neq 0$. Let $\Delta\subseteq[\ell]$, and let us suppose that there exist $I_1$ and $I_2$ forming a partition of $\Delta$ such that, for all $\delta\subseteq \Delta$, one has $v_\delta(x,y)=v_{\delta\cap I_1}(x,y)v_{\delta\cap I_2}(x,y)$. Then, $P_\Delta[v](x,y)=1$.
\end{lem} 


In the two following subsection, we provide a counterpart of the small cumulant property~\eqref{eq:small-cumul}, by proving that
the order of $\kappa_{[\ell]}(x,y)$ is at least that of $P_{[\ell]}[u](x,y)-1$.  Then, we will lower bound the latter  for $u$ defined in~\eqref{eq:definition_u_Delta}.



\subsection{Order of a power series}\label{sec:order}

For our purpose, we introduce a  specific notion of \emph{order} of a power series, which slightly differs from that in the literature. 
Let us first introduce a partial order relation on $\mathbb{N}^2$. 
\begin{definition}\label{def:orderrelation}
Let $s_0,s'_0\geq 0$ and $s_1,s'_1\geq 0$. We write that $(s_1,s'_1)\succcurlyeq (s_0,s'_0)$ if and only if $s_1\geq s_0$ and $s_1+s'_1\geq  s_0+s'_0$. The binary relation $\succcurlyeq$ is an order relation.
\end{definition}


\begin{lem}\label{lem:minimumexposant}
Any subset  $S\subseteq \N^2$ admits a unique infimum for the order relation $\succcurlyeq$. This infimum is not necessarily in $S$.
\end{lem}
We are now in position to define the \emph{order} of a multivariate series.
\begin{definition}\label{def:minimumexposant}
Let $f(x,y)=\sum_{s,s'\geq 0}f_{s,s'}x^sy^{s'}$ a multivariate series with positive radius. Let $\mathcal{D}(f)=\ac{(s,s')\in \N^2,\enspace f_{s,s'}\neq 0}$. We define the \textbf{order} of $f$ as the infimum of $\mathcal{D}(f)$ with respect to the partial order $\succcurlyeq$. It is referred as $\mathrm{ord}(f):=\inf \mathcal{D}(f)$.
\end{definition}


Our objective in this subsection is to control $\mathrm{ord}\pa{\kappa_{\Delta}}$ for the power series $\kappa_{\Delta}(x,y)$ defined by \eqref{eq:definition:kappa_Delta}.
For that purpose, we introduce a notion of {\it polynomial graph}, which are weighed graphs whose edges have weights $x$, $y$ or $1$. Consider such a polynomial graph $\mathcal{L}$ with edges $w_e\in \ac{x,y,1}$. Consider, if it exists (i.e if $\cL$ is connected), a spanning tree $\cT$ of $\cL$. We define the weight of $\cT$ as the monomial in $x$ and $y$ defined by $\prod_{e\in \cT}w_e$, and we write $deg(\cT)\in \N^2$ the \textit{degree} of this monomial, i.e. if $\prod_{e\in \cT}w_e=x^sy^{s'}$, then $deg(\cT):=(s,s')$. 



\begin{definition}\label{def:minimumexposantgraph}
For $\mathcal{L}$ a polynomial graph, we define the \textbf{order} of $\cL$, and we write $\mathrm{ord}(\cL)$ the infimum (w.r.t. $\succcurlyeq$) of $deg(\mathcal{T})$ over all spanning trees $\mathcal{T}$, with the convention that $\inf \emptyset = (+\infty, +\infty)$.
\end{definition}


It turns out that the order of $\cL$ is achieved by a spanning tree $\mathcal{T}$, its there exists any. 
\begin{lem}\label{lem:minimumexposantgraph}
Let $\cL$ be a connected   polynomial graph. There exists a spanning tree $\mathcal{T}$  such that $\mathrm{ord}(\cL)=deg(\mathcal{T})$.
\end{lem}



In the following lemma, we adapt a result from \cite{feray2018} to the setup of multivariate series, which enables us to lower-bound the \textit{order} of a polynomial graph $\cL$ by the \textit{order} of well-chosen sub-graphs. Given two partition $\bV$ and $\bW$ of a set $V$, we write $\mathbf{W}\vee \mathbf{V}$ as the finest partition which is coarser than $\bW$ and coarser than $\bW$. In other words, this partition is obtained by merging the groups of $\bW$ and $\bV$ whenever they intersect.

Given $\bold{\Delta}=\ac{\Delta_1,\ldots, \Delta_m}$ a family of subsets of $[\ell]$, we write, for $i\in [m]$, $\Pi\pa{\Delta_i}$ the partition of $[\ell]$ made of $\Delta_i$ and singletons. The partition $\Pi(\Delta_1)\vee\ldots\vee\Pi(\Delta_m)$ is defined as previously as the finest partition with is coarser than all $\Pi(\Delta_i)$.



\begin{lem}\label{lem:decompmimimumexposantgraph}
Let $\cL=(V,E)$ by a polynomial graph. Let $\mathbf{V}=(V_1,\ldots, V_{|CC|})$ be the partition of the vertices induced by the connected components of $\cL$ while only keeping the edges with weights one.  Let $\bold{\Delta}=\ac{\Delta_1,\ldots, \Delta_m}$ be another partition of $V$ that satisfies  $\mathbf{V}\vee \Pi\pa{\Delta_1}\vee \ldots\vee \Pi\pa{\Delta_m}=\{V\}$. Then, we have  
$$\sum_{i=1}^m \mathrm{ord}\pa{\cL[\Delta_i]}\succcurlyeq \mathrm{ord}\pa{\cL}\enspace.$$
\end{lem}




We gather in next lemma some properties of the \textit{order} of multivariate power series that we will use throughout the proofs. 

\begin{lem}\label{lem:basicpropertiesorder}
Let $f,g$ be multivariate series with positive radius. We have;
\begin{enumerate}
\item $\mathrm{ord}(fg)\succcurlyeq \mathrm{ord}(f)+\mathrm{ord}(g)$;
\item $\mathrm{ord}(f+g)\succcurlyeq \inf\pa{\mathrm{ord}(f), \mathrm{ord}(g)}$, where the infimum is taken for the order $\succcurlyeq$;
\item If $f(0,0)=0$, then $\frac{1}{1+f}-1$ is a multivariate series with positive radius and $\mathrm{ord}(\frac{1}{1+f}-1)=\mathrm{ord}(f)$.
\end{enumerate}
\end{lem}





\subsection{Control of the order of $\kappa_{_{[\ell]}}$}\label{sec:orderkappa}




We are now in position to introduce the polynomial graph $\cL^*$ that will be useful to lower-bound the  \textit{order} of $\kappa_{[\ell]}(x,y)$. 
We recall that $I_{1},\ldots,I_{\ell},A_{1},\ldots,A_{q},B_{1},\ldots,B_{r}$ are subsets of $[n]$ involved in the definition of the 
mixed moments~\eqref{eq:definition_u_Delta} of $Z_{1},\ldots,Z_{\ell}$. 

\begin{definition}\label{def:Lstar}
Let $\cL^*$ be the polynomial graph with vertex set $[\ell]$ whose edges are defined as follows. For $(t,t')\in [\ell]$: 
   \begin{itemize}
    \item there is an edge with weight $y$ between $t$ and $t'$ if there exists  $i \in [r]$ such that both $I_{t}$ and $I_{t'}$ intersect $B_{i}$.
    \item there is an edge with weight $x$ between $t$ and $t'$, if there does not exist $i\in [r]$ such that both $I_{t}$ and $I_{t'}$ intersect $B_{i}$ and if there exists $j\in [q]$ such that that both  $I_{t}$ and $I_{t'}$ intersect $A_{j}$.
    \item Otherwise, there is no edge between $t$ and $t'$. 
    \end{itemize}
\end{definition}


    We shall lower-bound the \textit{order} of $\kappa_{\ell}(x,y)$ in term of  the \textit{order} of $\cL^*$.
    The following lemma, which is the counterpart  in our setting of Proposition 5.8  of \cite{feray2018}, ensures that, if one is able to lower-bound the \textit{order} of $P_{\Delta}[u]$, for all $\Delta\subseteq [\ell]$ of size at least $2$, with respect to the \textit{order} of some well chosen polynomial graph, then one is able to lower-bound the \textit{order} of $\kappa_{\Delta}$ for all $\Delta\subseteq R$. The proof is postponed to the end of the section.


    \begin{lem}\label{lem:ferayseries}
    Let $\pa{u_\Delta(x,y)}_{\Delta\subseteq [\ell]}$ be a sequence of multivariate series indexed by subsets of $[\ell]$. Let $\cL$ be a polynomial graph on $[\ell]$ whose edges are equal either to $x$, $y$, $0$ or $1$. Let us suppose that, for all $\Delta\subseteq [\ell]$ of size at least $2$, one has $\mathrm{ord}\pa{P_{\Delta}[u]-1}\succcurlyeq \mathrm{ord}\pa{\cL[\Delta]}$. Then, for all $\Delta\subseteq [\ell]$, one also has $$\mathrm{ord}(\kappa_{\Delta})\succcurlyeq \mathrm{ord}\pa{\cL[\Delta]}+\sum_{i\in \Delta}\mathrm{ord}(u_{\{i\}})\enspace.$$
    \end{lem}

    Hence, to lower bound the order of $\kappa_{\Delta}$, we mostly have to lower bound the order of $P_{\Delta}[u]-1$ in terms of that of $\cL^*[\Delta]$, and then in turn to control the order of $\cL^*[\Delta]$. 
    The following lemma, proved in Section \ref{prf:quazifactogeneral}, lower-bounds the \textit{order} of $P_{\Delta}[u]-1$, for all $\Delta$ of size at least $2$.


    \begin{lem}\label{lem:quazifactogeneral}
    For all $\Delta\subseteq [\ell]$ of size at least $2$, one has 
    $$\mathrm{ord}\pa{P_{\Delta}[u]-1}\succcurlyeq \mathrm{ord}\pa{\cL^*[\Delta]}\enspace.$$
    \end{lem}


    Combining Lemma \ref{lem:ferayseries} and Lemma \ref{lem:quazifactogeneral}, we get that, for all $\Delta\subseteq [\ell]$ of size at least $2$, 
    $$\mathrm{ord}\pa{\kappa_{\Delta}}\succcurlyeq \mathrm{ord}\pa{\cL^*[\Delta]}+\sum_{i\in \Delta}\mathrm{ord}\pa{u_{\{i\}}}\enspace.$$
    When $\Delta$  is a singleton that is $\Delta=\ac{i}$, we directly have $\kappa_{\Delta}=u_{\{i\}}$ and so the above inequality still holds. 
    Since $\mathrm{ord}\pa{u_{\{i\}}}\in\N^2$, we have  for all non-empty $\Delta\subseteq R$, 
    \begin{equation}\label{eq:kappa2L}
    \mathrm{ord}\pa{\kappa_{\Delta}}\succcurlyeq \mathrm{ord}\pa{\cL^*[\Delta]}\enspace\enspace.
    \end{equation}
    It remains to lower-bound $\mathrm{ord}\pa{\cL^*}=\mathrm{ord}\pa{\cL^*[[\ell]]}$. We recall that the graph $\mathcal{B}$ defined in the statement of Lemma~\ref{lem:upperboundgeneralcumulant}, is a graph on the vertex set $[\ell]$ with an edge between $t$, $t'$ in $[\ell]$ if and only if there exists $i \in [r]$ such that both $I_{t}$ and $I_{t'}$ intersects $B_{i}$ and that $|cc(\cB)|$ stands for the number of connected components of this graph.

    \begin{lem}\label{lem:quasifactographgeneral}
    Writing $\mathrm{ord}\pa{\cL^*}=(d_{[\ell]}, d'_{[\ell]})$, we have 
    $$d_{[\ell]}\geq |cc\pa{\mathcal{B}}|-1\quad \quad \text{ and } d_{[\ell]}+d'_{[\ell]}\geq \ell-1\enspace.$$
    In particular, $\mathrm{ord}\pa{\cL^*}\succcurlyeq \pa{|cc\pa{\mathcal{B}}|-1, \ell-|cc\pa{\mathcal{B}}|}$.
    \end{lem}

Combining  \eqref{eq:kappa2L} with Lemma \ref{lem:quasifactographgeneral}  leads to o lower-bound on the order of $\kappa_{[\ell]}$
    \begin{equation}\label{eq:lower:bound:kappa_R}
    \mathrm{ord}\pa{\kappa_{[\ell]}}\succcurlyeq \pa{|cc\pa{\cB}|-1, \ell-|cc\pa{\cB}|}\enspace.
    \end{equation}

\subsection{Non-asymptotic control of the coefficients}\label{sec:controlcoeff}


 In order to deduce from \eqref{eq:lower:bound:kappa_R} a non-asymptotic upper-bound of $\kappa_{[\ell]}(x_0, y_0)$, it is sufficient to upper-bound the absolute value of the coefficients of the decomposition of $\kappa_{[\ell]}(x,y)$ as a multivariate series. We recall that, for $[\ell]\subseteq R$, we have 
    \begin{align*}
    u_\Delta(x,y)=&\eta^{|I_\Delta|}\prod_{j=1}^{q}\frac{1}{1-x}\times\ldots\times \frac{1}{1-(|I_\Delta\cap A_{j}|-1)x}
   \times\prod_{i=1}^{r}(1-y)\times\ldots\times \pa{1-\pa{|I_\Delta \cap B_{i}|-1}y}\enspace.
    \end{align*}
 In order to upper-bound the coefficients of the series $\kappa_{[\ell]}(x,y)$, we shall first do so for the $u_{\Delta}(x,y)$'s. In the following, given $f$ a multivariate series and $d,d'\geq 0$, we write $[d,d']_f$ the coefficient of $x^dy^{d'}$ in the decomposition of $f$. For any $d$ ,$d'\geq 0$, and $j=1,\ldots, q$, we define
\begin{align*}
g_{1,j}(x,y)&:= \frac{1}{1-x}\times\ldots\times \frac{1}{1-(|I_\Delta\cap A_{j}|-1)x}\ ;\\
g_{1}(x,y)&:= \prod_{j=1}^{q}g_{1,j}(x,y)  \ ; \\
g_{2}(x,y)&:= \prod_{i=1}^{r}(1-y)\times\ldots\times \pa{1-\pa{|I_\Delta \cap B_{i}|-1}y} \ ,
\end{align*}
so that  $ [d,d']_{u_{\Delta}} =\eta^{|I_\Delta|}[d,0]_{g_1} [0,d']_{g_2}$. One the one hand, for any $j=1,\ldots, q$ and any $d\geq 0$, we have 
    \begin{align*}
    [d,0]_{g_1,j}
    =&\underset{d_1+\ldots+d_{|I_\Delta\cap A_{j}|-1}=d}{\sum_{d_1,\ldots, d_{|I_\Delta\cap A_{j}|-1}\geq 0}}\prod_{a=1}^{|I_\Delta\cap A_{j}|-1}a^{d_a}
    \leq\pa{1+\ldots+(|I_\Delta\cap A_{j}|-1)}^d\\ 
    \leq& \pa{\frac{|I_\Delta\cap A_{j}|^2}{2}}^d\enspace .
    \end{align*}
We deduce that 
    \begin{align*}
    [d,0]_{g_1}=&\underset{d_1+\ldots+d_q=d}{\sum_{d_1,\ldots, d_q\geq 0}}\prod_{j=1}^{q}[d_{j}, 0]_{g_1,j}\\
    \leq&\underset{d_1+\ldots+d_q=d}{\sum_{d_1,\ldots, d_q\geq 0}}\prod_{j=1}^{q}\pa{\frac{|I_\Delta\cap A_{j}|^2}{2}}^{d_j}\\
    \leq& \pa{\sum_{j=1}^q\frac{|I_\Delta\cap A_{j}|^2}{2}}^d \leq  \pa{\frac{|I_\Delta|^2}{2}}^d \ ,
    \end{align*}
    where the last equality stems from the disjunction of the $A_{i}$.
Then, turning our attention to $g_2$, we have 
    \begin{align*}
    \left|[0,d']_{g_2}\right|\leq& \binom{\sum_{i=1,\ldots, r}|I_\Delta\cap B_{i}|-1}{d'}|I_{\Delta}|^{d'}
    \leq  |I_{\Delta}|^{2d'}\enspace . 
    \end{align*}
    We conclude that 
    \begin{equation}\label{eq:boundcoeffseriemomentclustering1}
    |[d,d']_{u_\Delta}|\leq \eta^{|I_\Delta|}|I_\Delta|^{2d+2d'}\enspace. 
    \end{equation}
    Then, we consider any partition $\boldsymbol{\Delta}=(\Delta_1,\ldots,\Delta_{|\boldsymbol{\Delta}|} )$ of $[\ell]$. Define $h_{\boldsymbol{\Delta}}= \prod_{a=1}^{{|\boldsymbol{\Delta}|}} u_{\Delta_a}$. 
    Recall that the $I_t$'s defined for \eqref{eq:formula:general_momodent} have disjoint support so that the $I_{\Delta_a}$'s are disjoint and $\sum_{a=1}^{|\boldsymbol{\Delta}|}|I_{\Delta_a}|= L$.  Hence, we deduce from \eqref{eq:boundcoeffseriemomentclustering1} that
    \begin{align*}
    \left|[d,d']_{h_{\boldsymbol{\Delta}}}\right|&=\left|\underset{d_1+\ldots+d_{|\boldsymbol{\Delta}|}=d}{\sum_{d_1,\ldots,d_{|\boldsymbol{\Delta}|}\geq 0}}\quad \underset{d'_1+\ldots+d'_{|\boldsymbol{\Delta}|}=d'}{\sum_{d'_1,\ldots,d'_{|\boldsymbol{\Delta}|}\geq 0}}\prod_{a=1}^{|\boldsymbol{\Delta}|}[d_a, d'_a]_{u_{\Delta_a}} \right|\\
    &\leq  \eta^{L}\underset{d_1+\ldots+d_{|\boldsymbol{\Delta}|}=d}{\sum_{d_1,\ldots,d_{|\boldsymbol{\Delta}|}\geq 0}}\quad \underset{d'_1+\ldots+d'_{|\boldsymbol{\Delta}|}=d'}{\sum_{d'_1,\ldots,d'_{|\boldsymbol{\Delta}|}\geq 0}}\prod_{a=1}^{|\boldsymbol{\Delta}|}|I_{\Delta_a}|^{2d_{a}+2d'_{a}}\\
    &\leq   \eta^{L}\pa{\sum_{a=1}^{|\boldsymbol{\Delta}|}|I_{\Delta_a}|}^{2d+2d'}=  \eta^{L}L^{2d+2d'}\enspace.
    \end{align*}
    Then, combining this with a triangular inequality and the Möbius formula (Lemma \ref{lem:mobiusformula}), we obtain the following bound for the coefficients of $\kappa_{[\ell]}$. 
    \begin{equation}\label{eq:boundcoeffseriemomentclustering2}
    \left|[d,d']_{\kappa_{[\ell]}}\right|\leq \eta^{L}L^{2d+2d'}\ell^{2\ell}\enspace.
    \end{equation}


 \subsection{Conclusion}
Combining Equation \eqref{eq:boundcoeffseriemomentclustering2} together with \eqref{eq:lower:bound:kappa_R} leads us to 
    \begin{align*}
    \left|\kappa_{[\ell]}\pa{x_0,y_0}\right|\leq&\ell^{2\ell}\eta^{L}\underset{d+d'\geq \ell-1}{\sum_{d\geq cc\pa{\cB}-1}}L^{2d+2d'}x_0^dy_0^{d'}\\
    &\leq  \ell^{2\ell}\eta^{L}\sum_{d\geq cc\pa{\cB}-1}\sum_{d'\geq \ell-1-d}\pa{L^2 x_0}^d\pa{L^2y_0}^{d'}\\
    &\leq 2\ell^{2\ell}\eta^{L}\sum_{d\geq cc\pa{\cB}-1}\pa{L^2 x_0}^d \pa{L^2y_0}^{\ell-1-d}\\
    &\leq 2\ell^{2\ell}\eta^{L}\pa{L^2y_0}^{\ell-1}\sum_{d\geq cc\pa{\cB}-1}\pa{x_0/y_0}^d\\
    &\leq  4\ell^{2\ell}\eta^{L}\pa{L^2y_0}^{\ell-1}\pa{\frac{x_0}{y_0}}^{cc\pa{\cB}-1}\enspace,
    \end{align*}
    where the third and fifth inequalities are satisfied whenever $L^2y_0\leq\frac{1}{2}$ and $x_0\leq\frac{1}{2}y_0$. We have shown
    $$\left|\cumul\pa{\pa{Z_t}_{t\in [\ell]}}\right|\leq 4\ell^{2\ell}\eta^{L}\pa{L^2y_0}^{\ell-1}\pa{\frac{x_0}{y_0}}^{cc\pa{\cB}-1}\enspace.$$
This concludes the proof of Lemma~\ref{lem:upperboundgeneralcumulant}.


























\subsection{Proof of Lemma \ref{lem:ferayseries}}\label{prf:ferayseries}


The proof of Lemma \ref{lem:ferayseries} build on the ideas of the proof of Proposition 5.8 of \cite{feray2018}, which are adapted to the framework of multivariate series. 


Let us first reduce the problem to the case where $u_{\{i\}}= 1$. Let us define the family of power series
$$w_\Delta(x,y)=\frac{u_\Delta (x,y)}{\prod_{i\in \Delta}u_{\{i\}}(x,y)}.$$ 
We have $P_\Delta[w]=P_{\Delta}[u]$, for all $\Delta\subseteq [\ell]$ of size at least $2$. Defining  $\kappa_{\Delta}[w]$ as the counterpart of $\kappa_{\Delta}$ when the function $u$ is replaced by $w$, we get  
$$\kappa_{\Delta}(x,y)=\pa{\prod_{i\in \Delta}u_{\{i\}}(x,y)}\kappa_{\Delta}[w](x,y)\enspace .$$
So, if we prove that $\mathrm{ord}(\kappa_{\Delta}[w])\succcurlyeq \mathrm{ord}(\cL[\Delta])$ (see Definition \ref{def:minimumexposantgraph} for the order of a power serie), then by Lemma~\ref{lem:basicpropertiesorder}
$$\mathrm{ord}(\kappa_{\Delta})\succcurlyeq \mathrm{ord}(\cL[\Delta])+\sum_{i\in\Delta}\mathrm{ord}(u_{\ac{i}}). $$
Hence, in the following, we assume that $u_{\{i\}}=1$ for all $i\in [\ell]$. By assumption,  for all $\Delta$ of size at least $2$, one has $\mathrm{ord}\pa{P_\Delta (u)-1}\succcurlyeq \mathrm{ord}\pa{\cL[\Delta]}$ and we shall lower-bound $\mathrm{ord}\pa{\kappa_{\Delta}}$ for all $\Delta\subseteq [\ell]$. Without loss of generality, it is sufficient to do so for $\Delta=[\ell]$.



For $\Delta\subseteq [\ell]$, define $R_\Delta(x,y)=P_\Delta (u)(x,y)-1$. By assumption, we have $\mathrm{ord}\pa{R_\Delta}\succcurlyeq \mathrm{ord}\pa{\cL[\Delta]}$. Let us fix a partition $\bW=(W_1,\ldots, W_s)$ of $[\ell]$, and let us consider $W\in \bW$. Since $u_\emptyset=1$, 
we have
\begin{align*}
\prod_{\Delta\subseteq W}P_{\Delta}[u](x,y)=&\prod_{\Delta\subseteq W}\prod_{\delta\subseteq \Delta}\pa{u_{\delta}(x,y)}^{\pa{-1}^{|\Delta|-|\delta|}}\\
=&\prod_{\delta\subseteq W}\pa{u_{\delta}(x,y)}^{\sum_{\delta\subseteq \Delta \subseteq W}(-1)^{|\Delta|-|\delta|}}\\
=&u_{W}(x,y)\enspace,
\end{align*}
where the last inequality comes from the fact that, whenever $\delta\subsetneq W$, $\sum_{\delta\subseteq \Delta \subseteq W}(-1)^{|\Delta|-|\delta|}=\pa{1-1}^{|W|-|\delta|}=0$. In turn,  expanding $P_{\Delta}(x,y)=1+R_{\Delta}(x,y)$ and using the fact that for all $\ac{i}$, $P_{\ac{i}}[u](x,y)=1$,
we get,
$$u_W(x,y)=\underset{|\Delta|\geq 2}{\prod_{\Delta\subseteq W}}\pa{1+R_\Delta(x,y)}=\sum_{\ac{\Delta_1,\ldots, \Delta_m}}R_{\Delta_1}(x,y)\ldots R_{\Delta_m}(x,y)\enspace,$$
where the sum runs over all finite sets of distinct subsets of $W$ of size at least $2$. Therefore, 
\begin{equation}\label{eq:prod-uWi}
\prod_{i=1}^su_{W_i}(x,y)=\sum_{\ac{\Delta_1,\ldots,\Delta_m}}R_{\Delta_1}(x,y)\ldots R_{\Delta_m}(x,y)\enspace,
\end{equation}
where the sum is taken over all finite sets of distinct subsets (but not necessarily disjoint) of $[\ell]$ of size at least $2$, such that each $\Delta_i$ is contained in a group of the partition $\bW$. Let us fix such a set $\bold{\Delta}=\ac{\Delta_1,\ldots,\Delta_m}$ and, for $i\in [m]$, let us write $\Pi\pa{\Delta_i}$ the partition of $[\ell]$ containing $\Delta_{i}$ and singletons. We recall that $\Pi\pa{\Delta_1}\vee\ldots \vee  \Pi\pa{\Delta_m}$ is the partition of $[\ell]$ defined by; for $t,t'\in [\ell]$, $t$ and $t'$ are in the same group of $\Pi\pa{\Delta_1}\vee\ldots \vee  \Pi\pa{\Delta_m}$ if and only if there exist $t_1,\ldots, t_h$ with $t_1=t$, $t_h=t'$ and, for all $h'\leq h-1$, there exists $i\in [m]$ such that $t_h$ and $t_{h+1}$ are in the same group of the partition $\Pi\pa{\Delta_i}$.  Since each $\Delta_i$ is contained in a group of $\bW$, we have that each group of $\Pi\pa{\Delta_1}\vee\ldots \vee  \Pi\pa{\Delta_m}$ must be contained in a group of $\bW$. Consequently, $\bW\vee\Pi\pa{\Delta_1}\vee\ldots \vee  \Pi\pa{\Delta_m}=\bW$. 

In the following, given $\bold{\Delta}=\ac{\Delta_1,\ldots,\Delta_m}$ a set of distinct subsets of $[\ell]$ of size at least $2$, we denote $\cP_{\bold{\Delta}}([\ell])$ the set of all partitions $\bW$ of $[\ell]$ satisfying that, for all $i\in [m]$, $\Delta_i$ is contained in a group of $\bW$. For all $\bW\in \cP_{\bold{\Delta}}([\ell])$, we have $\bW\vee\Pi\pa{\Delta_1}\vee\ldots \vee  \Pi\pa{\Delta_m}=\bW$.
Using the Möbius formula stated in Lemma \ref{lem:mobiusformula}, together with \eqref{eq:prod-uWi}, and after reversing the summation order, we get
\begin{equation}\label{eq:cumulantsumRDelta}
\kappa_{[\ell]}(x,y)=\underset{|\Delta_i|\geq 2}{\underset{\Delta_i\subseteq [\ell]}{\sum_{\bold{\Delta}=\ac{\Delta_1,\ldots, \Delta_m}}}}R_{\Delta_1}(x,y)\ldots R_{\Delta_m}(x,y)\pa{\sum_{\bW\in \mathcal{P}_{\bold{\Delta}}([\ell])}m(\bW)}\enspace,
\end{equation}
where $m(\bW)=(-1)^{|\bW|-1}(|\bW|-1)!$ is the Möbius function.
Next lemma prunes some of the terms of~\eqref{eq:cumulantsumRDelta}.

\begin{lem}\label{lem:cumulantsumRDelta}
Let $\bold{\Delta}=\ac{\Delta_1,\ldots, \Delta_m}$ a family of distinct subsets of $[\ell]$. If $\Pi(\Delta_1)\vee\ldots\vee \Pi(\Delta_m)\neq \ac{[\ell]}$, we have $$\sum_{\bW\in \mathcal{P}_{\bold{\Delta}}([\ell])}m(\bW)=0\enspace.$$
\end{lem}


\begin{proof}[Proof of Lemma \ref{lem:cumulantsumRDelta}]
Let us consider $\bW^{(0)}=\Pi(\Delta_1)\vee\ldots\vee \Pi(\Delta_m)$, and let us write  $\bW^{(0)}=W^{(0)}_1,\ldots, W^{(0)}_{|\bW^{(0)}|}$, with $|\bW^{(0)}|\geq 2$. By definition of $\bW^{(0)}$, we have $\mathcal{P}_{\bold{\Delta}}([\ell])=\mathcal{P}_{\bW^{(0)}}([\ell])$ and so it is sufficient to prove that $\sum_{\bW\in \mathcal{P}_{\cW^{(0)}}([\ell])}m(\bW)=0$, when $\bW^{(0)}$ is a partition of $[\ell]$ different from the trivial partition $\ac{[\ell]}$. We can construct a bijection $\phi$ from all partitions $\bG$ of $[|\bW^{(0)}|]$ to the set $\mathcal{P}_{\cW^{(0)}}([\ell])$ defined by $\phi(\bG)=\ac{\cup_{i\in G}W^{(0)}_i,\enspace G\in \bG}$. This bijection preserves the Möbius function in the sense that $m(\phi(\bG))=m(\bG)$ and so $$\sum_{\bW\in \mathcal{P}_{\cW^{(0)}}([\ell])}m(\bW)=\sum_{\bG\in \cP([|\bW^{(0)}|])}m(\bG)=\cumul\pa{1,\ldots,1}=0\enspace,$$
where the last cumulant is the cumulant of $|\bW^{(0)}|$ copies of the deterministic variable $1$, which is equal to $0$ as soon as $|\bW^{(0)}|\geq 2$ (see Lemma \ref{lem:independentcumulant}). This concludes the proof of Lemma \ref{lem:cumulantsumRDelta}.
\end{proof}


Combining Lemma \ref{lem:cumulantsumRDelta} and Equality \eqref{eq:cumulantsumRDelta}, we get 
\begin{equation}\label{eq:cumulantsumRDelta2}
\kappa_{[\ell]}(x,y)=\underset{|\Delta_i|\geq 2}{\underset{\Pi(\Delta_1)\vee\ldots\vee \Pi(\Delta_m)=\ac{[\ell]}}{\sum_{\bold{\Delta}=\ac{\Delta_1,\ldots, \Delta_m}}}}R_{\Delta_1}(x,y)\ldots R_{\Delta_m}(x,y)
\enspace.
\end{equation}
Let us now consider $\bold{\Delta}=\ac{\Delta_1,\ldots, \Delta_m}$ a set of subsets of $[\ell]$ such that $\Pi\pa{\Delta_1}\vee\ldots \vee  \Pi\pa{\Delta_m}=\ac{[\ell]}$. We consider $\bV$ the partition of $[\ell]$ induced by the connected components of $\cL\<1\>$, which is the graph keeping only the edges of weight $1$ of $\cL$. Since $\Pi\pa{\Delta_1}\vee\ldots \vee  \Pi\pa{\Delta_m}=\ac{[\ell]}$, one necessarily has $\bV\vee\Pi\pa{\Delta_1}\vee\ldots \vee  \Pi\pa{\Delta_m}=\ac{[\ell]}$. Hence, using Lemma \ref{lem:decompmimimumexposantgraph}, we get
$$\sum_{i=1}^m \mathrm{ord}(\cL[\Delta_i])\succcurlyeq \mathrm{ord}(\cL)\enspace.$$
We recall our assumption that  $\mathrm{ord}(R_{\Delta_i})\succcurlyeq \mathrm{ord}(\cL[\Delta_i])$. Lemma \ref{lem:basicpropertiesorder} ensures that, 
$$\mathrm{ord}\pa{R_{\Delta_{1}}\ldots R_{\Delta_m}}\succcurlyeq \sum_{i=1}^m \mathrm{ord}(\cL[\Delta_i])\succcurlyeq \mathrm{ord}(\cL)\enspace.$$
Thus, all the non-zero terms in the sum \eqref{eq:cumulantsumRDelta} have their \textit{order} higher than $\mathrm{ord}(\cL)$ with respect to the ordering $\succcurlyeq$. Invoquing a last time Lemma \ref{lem:basicpropertiesorder}, we get the claimed inequality
$$\mathrm{ord}(\kappa_{[\ell]})\succcurlyeq \mathrm{ord}(\cL)\enspace.$$






\subsection{Proof of Lemma \ref{lem:quazifactogeneral}}\label{prf:quazifactogeneral}


The power series $u_{\Delta}$ involves multiple terms that are alike factorial terms. For proving Lemma~\ref{lem:quasifactographgeneral}, we shall apply several times the following result which which is variation of Proposition 5.10 in~\cite{feray2018}. Its proof is postponed to the end of the subsection. 

\begin{lem}\label{lem:factorielseries}
Let $a_1, \ldots, a_\ell$ be non-negative integers, and, for $\Delta\subseteq [\ell]$, let us define 
\begin{align*}
v_\Delta(x,y)&:=\pa{1-x}\ldots \pa{1-\pa{\sum_{i\in \Delta}a_i-1}x}\enspace ;\\ w_\Delta(x,y)&:=\frac{1}{\pa{1-x}\ldots \pa{1-\pa{\sum_{i\in \Delta}a_i-1}x}}\enspace \ , 
\end{align*}
with the convention, if $\sum_{i\in \Delta} a_i =0$ or $\sum_{i\in \Delta} a_i =1$, $v_\Delta(x,y)=w_\Delta(x,y)=1$. Recall the operator $P_{\Delta}$ defined in~\eqref{eq:definition_P_Delta}.
 Then, for all $\Delta$ of size at least $2$, we have
$$\mathrm{ord}\pa{P_{\Delta}[v]-1}\succcurlyeq (|\Delta|-1, 0)\enspace\ ;\quad \quad  \mathrm{ord}\pa{P_\Delta[w]-1}\succcurlyeq (|\Delta|-1, 0)\enspace.$$
\end{lem}



We shall also use next lemma, whose proof is also postponed to the end of this subsection, and which enables us to decompose $u$ as a product of power series.

\begin{lem}\label{lem:decomppowerseries}
Let $\pa{v_\Delta}_{\Delta\subseteq [\ell]}$ and $\pa{w_\Delta}_{\Delta\subseteq [\ell]}$ to families of power series in $x$ and $y$ indexed by subsets of $[\ell]$. Suppose that there exists $(s,s')\in \N^2$ such that, for all $\Delta\subseteq [\ell]$, we have $\mathrm{ord}\pa{P_{\Delta}[v]-1}\succcurlyeq (s,s')$ and $\mathrm{ord}\pa{P_\Delta[w]-1}\succcurlyeq (s,s')$. Then, for all $\Delta\subseteq [\ell]$, $\mathrm{ord}\pa{P_{\Delta}[vw]-1}\succcurlyeq (s,s')$.
\end{lem}












Now, we have all the ingredients to prove Lemma \ref{lem:quazifactogeneral}. Let $\Delta\subseteq [\ell]$ of size at least $2$. We seek to lower bound $\mathrm{ord}\pa{P_{\Delta}[u]-1}$, where $$P_{\Delta}[u](x,y)=\prod_{\delta\subseteq \Delta}\pa{u_\delta(x,y)}^{(-1)^{|\Delta|-|\delta|}}\enspace,$$
where we recall that, for all $\Delta\subseteq [\ell]$,
\begin{align*}
u_\Delta(x,y)=&\eta^{|I_\Delta|}\prod_{j=1}^q\frac{1}{1-x}\times\ldots\times \frac{1}{1-(|I_\Delta\cap A_{j}|-1)x}\\
&\times\prod_{i=1}^r(1-y)\times\ldots\times \pa{1-\pa{|I_\Delta \cap B_{i}|-1}y}\enspace.
\end{align*}
Let us define, for $j=1,\ldots, q$, $$w^{(j)}_\Delta(x,y):=\frac{1}{1-x}\times\ldots\times \frac{1}{1-(|I_\Delta\cap A_{j}|-1)x}\enspace,$$
and, for $i\in [r]$,
$$v^{(i)}_\Delta(x,y):=(1-y)\times\ldots\times \pa{1-\pa{|I_\Delta \cap B_{i}|-1}y}\enspace,$$
and $z_{\Delta}(x,y):=\eta^{|I_\Delta|}$.


For all $\Delta\subseteq [\ell]$, we have $u_\Delta(x,y)=z_{\Delta}(x,y)\prod_{j=1}^qw^{(j)}_\Delta(x,y)\prod_{i=1}^r v^{(i)}_\Delta(x,y)$. In the light of Lemma \ref{lem:decomppowerseries}, in order to prove that $\mathrm{ord}\pa{P_{\Delta}[u]-1}\succcurlyeq \mathrm{ord}(\cL^*[\Delta])$, it is sufficient to prove that we have $\mathrm{ord}\pa{P_\Delta[w^{(j)}]-1}\succcurlyeq \mathrm{ord}(\cL^*[\Delta])$, for all $j=1,\ldots, q$, and $\mathrm{ord}\pa{P_\Delta[v^{(i)}]-1}\succcurlyeq \mathrm{ord}(\cL^*[\Delta])$, for all $i\in [r]$, and  $\mathrm{ord}\pa{P_\Delta[z]-1}\succcurlyeq \mathrm{ord}(\cL^*[\Delta])$.



\paragraph{The term z}. Let us first deal with the constant term $P_\Delta[z]$. It is clear that for all $\delta\subseteq \Delta$, we have $z_{\delta}=\prod_{t'\in \delta}z_{\ac{t'}}$. Therefore, using Lemma \ref{lem:independentquasifacto}, we deduce that as soon as $\Delta$ is of size at least $2$, $P_\Delta[z]=1$ and thus $\mathrm{ord}\pa{P_\Delta[z]-1}=+\infty$. Hence, it is clear that $\mathrm{ord}\pa{P_\Delta[z]-1}\succcurlyeq \mathrm{ord}\pa{\cL^*[\Delta]}$. 



\paragraph{The term $w^{(j)}$.} Let us now deal with the term $P_\Delta[w^{(j)}]$. If there exists $t\in \Delta$ such that $I_{t}\cap A_{j}=\emptyset$, we can easily check using Lemma \ref{lem:independentquasifacto} that $P_\Delta[w^{(j)}]=1$ and so $\mathrm{ord}\pa{P_\Delta[w^{(j)}]-1}\succcurlyeq \mathrm{ord}(\cL^*[\Delta])$. Let us now suppose that for all $t\in \Delta$, we have $I_{t}\cap A_{j}\neq \emptyset$. Note that this implies that $\cL^*[\Delta]$ is a complete graph, and is in particular connected (we recall that $\cL^*$ is defined in Definition~\ref{def:Lstar}, page~\pageref{def:Lstar}). Since any spanning tree of $\cL^*[\Delta]$ has exactly $|\Delta|-1$ edges, we derive that  $\mathrm{ord}(\cL^*[\Delta])\preccurlyeq \pa{|\Delta|-1, 0}$.

For all $\delta\subseteq \Delta$, we remark that
$$w^{(j)}_\delta(x,y)=\frac{1}{(1-x)\ldots (1-(\sum_{t\in \delta}|I_{\ac{t}}\cap A_{j}|-1)x)}\enspace.$$
 Lemma \ref{lem:factorielseries} then ensures that, for all $\Delta$ of size at least $2$,  $\mathrm{ord}\pa{P_\Delta[w^{(j)}]-1}\succcurlyeq \pa{|\Delta|-1, 0}$. We have proved that $\mathrm{ord}\pa{P_\Delta[w^{(j)}]-1}\succcurlyeq \mathrm{ord}(\cL^*[\Delta])$. 




\paragraph{The term $v^{(i)}$.} Finally, we shall prove that, for all $i \in [r]$, $\mathrm{ord}\pa{P_\Delta[v^{(i)}]-1}\succcurlyeq \mathrm{ord}\pa{\cL^*[\Delta]}$. If there exists $t\in \Delta$ such that $I_{t}\cap B_{i}=\emptyset$, then, using Lemma \ref{lem:independentquasifacto}, we deduce $P_\Delta[v^{(i)}]=1$ and so $\mathrm{ord}\pa{P_\Delta[v^{(i)}]-1}\succcurlyeq \mathrm{ord}(\cL^*[\Delta])$. Let us now suppose that all  $t \in \Delta$, we have $B_{i}\cap I_t\neq \emptyset$. In particular, this implies that $\cL^*[\Delta]$ is a complete graph with edges with weight $y$. Hence, $\mathrm{ord}(\cL^*[\Delta])=\pa{0, |\Delta|-1}$. For all $\delta\subseteq\Delta$, $v^{(i)}_\delta=\pa{1-y}\ldots \pa{1-\pa{\sum_{t'\in \delta}|I_{t'}\cap B_{i}|-1}y}$. So , using Lemma \ref{lem:factorielseries}, we deduce that $\mathrm{ord}\pa{P_{\Delta}[w]-1}\succcurlyeq (0,|\Delta|-1)=\mathrm{ord}\pa{\cL^*[\Delta]}$. 




Combining those three points together concludes the proof of Lemma~\ref{lem:quazifactogeneral}.




\begin{proof}[Proof of Lemma \ref{lem:factorielseries}]



Let $a_1,\ldots, a_\ell$ be a set of non-negative integers. We remark that $v_{\Delta}=1/w_{\Delta}$ for any subset $\Delta$, which in turn implies $P_{\Delta}[v]-1=\frac{1}{P_{\Delta}[w]}-1=\frac{1}{1+(P_{\Delta}[w]-1)}-1$. Since $\pa{P_{\Delta}[v]-1(0,0)}=\pa{P_{\Delta}[w]-1} (0,0)=0$, we get, using Lemma \ref{lem:basicpropertiesorder}, that $\mathrm{ord}\pa{P_{\Delta}[v]-1}\succcurlyeq \mathrm{ord}\pa{P_{\Delta}[w]-1}$ and, similarly, $\mathrm{ord}\pa{P_{\Delta}[w]-1}\succcurlyeq \mathrm{ord}\pa{P_{\Delta}[v]-1}$. We deduce $\mathrm{ord}\pa{P_{\Delta}[w]-1}=\mathrm{ord}\pa{P_{\Delta}[v]-1}$. Hence, for $\Delta\subseteq [\ell]$, having $\mathrm{ord}\pa{P_{\Delta}[v]-1}\succcurlyeq \pa{|\Delta|-1,0}$ is equivalent to having $\mathrm{ord}\pa{P_{\Delta}[w]-1}\succcurlyeq \pa{|\Delta|-1,0}$. Hence, we only need to prove the result for $P_{\Delta}[v]$.


We argue by induction on $\ell$ and then $a_\ell$ that this holds for all $\Delta\subseteq [\ell]$. For $\ell=1$, the result is trivial. Consider $\ell>1$, and assume that for all $\Delta\subsetneq [\ell]$, we have $\mathrm{ord}\pa{P_{\Delta}[v]-1}\succcurlyeq \pa{|\Delta|-1,0}$. Let us prove that $\mathrm{ord}\pa{P_{[\ell]}[v]-1}\succcurlyeq (\ell-1,0)$.



In the following, for $k\geq 0$, we define $v_{\Delta}[k]$  as 
$$v_\Delta[k](x,y):=\pa{1-x}\ldots \pa{1-\pa{\sum_{i\in \Delta\setminus \ac{\ell}}a_i+k\1\ac{\ell\in \Delta}-1}x}\enspace.$$
In particular, we have  $v_\Delta=v_\Delta[a_\ell]$. Hence, we only need to prove that $\mathrm{ord}\pa{P_{[\ell]}(v[k])-1}\succcurlyeq (\ell-1,0)$ for all non-negative integers $k$ and any $(a_1,\ldots, a_{\ell-1})$.


Let us first consider the case $k=0$. Then, for any $\Delta\subseteq [\ell-1]$, 
$$v_\Delta[k](x,y)=v_{\Delta\cup\ac{\ell}}[k](x,y)\enspace.$$
By definition~\eqref{eq:definition_P_Delta} of $P_{\Delta}$, this implies that for all $x,y$, $P_{[\ell]}(v[a_\ell])(x,y)=1$. Hence, we have $\mathrm{ord}\pa{P_{[\ell]}(v[a_\ell])-1}\succcurlyeq (\ell-1,0)$.


Now assume for some $k>0$, we have $\mathrm{ord}\pa{P_{[\ell]}(v[k])-1}\succcurlyeq (\ell-1,0)$ and let us prove that $\mathrm{ord}\pa{P_{[\ell]}(v[k+1])-1}\succcurlyeq (\ell-1,0)$. We observe that, for $\ell\in \Delta$, 
\begin{align*}
v_\Delta[k+1]=&(1-x)\ldots\pa{1-\pa{\sum_{i\in \Delta\setminus \ac{l}}a_i+k}x}\\
=&(1-x)\ldots\pa{1-\pa{\sum_{i\in \Delta\setminus \ac{\ell}}a_i+k-1}x}\times \pa{1-\pa{\sum_{i\in \Delta\setminus \ac{\ell}}a_i+k}x}\\
=&v_{\Delta}[k]\pa{1-\pa{\sum_{i\in \Delta\setminus \ac{\ell}}a_i+k}x} \enspace . 
\end{align*}
On the other hand, if $\ell\notin \Delta$, we have $v_\Delta[k+1]=v_{\Delta}[k]$.
Thus, we deduce that 
$$P_{[\ell]}[v[k+1]]=\pa{\underset{\ell\in \Delta}{\prod_{\Delta\subseteq [\ell]}}\pa{1-\pa{\sum_{i\in \Delta\setminus \ac{\ell}}a_i+k}x}^{(-1)^{\ell-|\Delta|}}}P_{[\ell]}[v[k]]\enspace . $$
Let us define the multivariate series
\begin{align*}
Q(x):=&\underset{\ell\in \Delta}{\prod_{\Delta\subseteq [\ell]}}\pa{1-\pa{\sum_{i\in \Delta\setminus \ac{\ell}}a_i+k}x}^{(-1)^{\ell-|\Delta|}}
=\underset{\ell\in \Delta}{\prod_{\Delta\subseteq [\ell]}}x^{(-1)^{\ell-|\Delta|}}\pa{\frac{1}{x}-\pa{\sum_{i\in \Delta\setminus \ac{\ell}}a_i+k}}^{(-1)^{\ell-|\Delta|}}\\
=&\underset{\ell\in \Delta}{\prod_{\Delta\subseteq [\ell]}}\pa{\frac{1}{x}-\pa{\sum_{i\in \Delta\setminus \ac{\ell}}a_i+k}}^{(-1)^{\ell-|\Delta|}}\ , 
\end{align*}
where we used that,  for $\ell\geq 2$, $\underset{\ell\in \Delta}{\prod_{\Delta\subseteq [\ell]}}x^{(-1)^{\ell-|\Delta|}}=1$.


For any $t\in \R$, define $F(t):=\prod_{\Delta\subseteq [\ell-1]}\pa{t-\sum_{i\in \Delta}a_i}^{(-1)^{|\Delta|+1}}$. Then, we have 
\[
Q(x)= \pa{F\pa{\frac{1}{x}-k}}
^{(-1)^\ell}\enspace . 
\]
From Lemma A.1 of \cite{feray2018}, we know that $F(t)-1$ is a rational function in $t$ of degree at most $-\ell+1$. Hence, $Q(x)-1$ is a multivariate series in $x$ of \textit{order} at least $\ell-1$. Combining this with the induction hypothesis, we deduce that $\mathrm{ord}\pa{P_{[\ell]}[v[k+1]]}\succcurlyeq (\ell-1, 0)$, which concludes the induction and the proof of Lemma~\ref{lem:factorielseries}. 

\end{proof}




\begin{proof}[Proof of Lemma \ref{lem:decomppowerseries}]
Let $\Delta\subseteq [\ell]$. We have 
$$P_{\Delta}[vw]-1=P_{\Delta}[v]-1+P_{\Delta}[w]-1+\pa{P_{\Delta}[v]-1}\pa{P_{\Delta}[w]-1}\enspace.$$
By hypothesis of the lemma, we both have $\mathrm{ord}\pa{P_{\Delta}[v]-1}\succcurlyeq (s,s')$ and $\mathrm{ord}\pa{P_\Delta[w]-1}\succcurlyeq (s,s')$. This also implies by Lemma \ref{lem:basicpropertiesorder} that $\mathrm{ord}\pa{\pa{P_{\Delta}[v]-1}\pa{P_\Delta[w]-1}}\succcurlyeq (s,s')$ and so, still using Lemma \ref{lem:basicpropertiesorder}, $\pa{P_{\Delta}[vw]-1}\succcurlyeq (s,s')$. This concludes the proof of Lemma~\ref{lem:decomppowerseries}.


\end{proof}


\subsection{Proof of the remaining  technical lemmas}


\begin{proof}[Proof of Lemma \ref{lem:independentquasifacto}]


For $\delta\subset \Delta$, we write $\delta_1=\delta\cap I_1$ and $ \delta_2= \delta\cap I_2$. By definition, one has
\begin{align*}
P_{\Delta}[v]=&\prod_{\delta\subseteq \Delta}v_\delta^{(-1)^{|\Delta|-|\delta|}}
=\prod_{\delta\subseteq \Delta}v_{\delta_1}^{(-1)^{|\Delta|-|\delta|}}v_{\delta_2}^{(-1)^{|\Delta|-|\delta|}}\\
=&\prod_{\delta_1\subseteq I_1}\prod_{\delta_2\subseteq I_2}v_{\delta_1}^{(-1)^{|I_1|-|\delta_1|}(-1)^{|I_2|-|\delta_2|}}v_{\delta_2}^{(-1)^{|I_2|-|\delta_2|}(-1)^{|I_1|-|\delta_1|}}\\
=&\prod_{\delta_1\subseteq I_1}\pa{v_{\delta_1}^{(-1)^{|I_1|-|\delta_1|}}}^{\sum_{\delta_2\subseteq I_2}(-1)^{|I_2|-|\delta_2|}}
\prod_{\delta_2\subseteq I_2}\pa{v_{\delta_2}^{(-1)^{|I_2|-|\delta_2|}}}^{\sum_{\delta_1\subseteq I_1}(-1)^{|I_1|-|\delta_1|}}\enspace.
\end{align*}
We have $\sum_{\delta_1\subseteq I_1}(-1)^{|I_1|-|\delta_1|}=\pa{-1}^{-|I_1|}\sum_{t=1}^{|I_1|}\binom{|I_1|}{t}(-1)^t=0^{|I_1|}=0$ since $I_1\neq \emptyset$. As a consequence, $$\prod_{\delta_2\subseteq I_2}\pa{v_{\delta_2}^{(-1)^{|I_2|-|\delta_2|}}}^{\sum_{\delta_1\subseteq I_1}(-1)^{|I_1|-|\delta_1|}}=1\enspace,$$
and, similarly,
$$\prod_{\delta_1\subseteq I_1}\pa{v_{\delta_1}^{(-1)^{|I_1|-|\delta_1|}}}^{\sum_{\delta_2\subseteq I_2}(-1)^{|I_2|-|\delta_2|}}=1\enspace.$$
We conclude that $P_{\Delta}[v]=1$.





\end{proof}



\begin{proof}[Proof of lemma \ref{lem:minimumexposant}]
Consider any  $S\subset \N^{2}$. Let
$$s_0=\min\ac{s\in\N, \enspace \exists s'\in \N\enspace s.t\enspace (s,s')\in S}\enspace,$$
and let $s_0'$ the maximal element in $\N$ such that for all $(s,s')\in S$, $s_0+s_0'\leq s+s'$, i.e. 
$$s_0+s'_0=s_{0}+\min_{(s,s')\in S} (s+s').$$ 
It is clear that  $(s,s')\succcurlyeq (s_0,s'_0)$ for all $(s,s')\in S$. It remains to prove that for all $(s_1,s'_1)$ satisfying $(s,s')\succcurlyeq (s_1,s'_1)$ for all $(s,s')\in S$, we have $(s_0,s'_0)\succcurlyeq (s_1,s'_1)$. First, for all $(s,s')\in S$, $s_1\leq s$, which implies that $s_0\geq s_1$. Then, for all $(s,s')\in S$, we have  $s+s'\geq s_1+s'_1$. Again, this readily implies that  $s_0+s'_0\geq s_1+s'_1$. We conclude that $(s_0,s'_0)\succcurlyeq (s_1,s'_1)$. Hence, $(s_0,s'_0)$ is the infimum of $S$, which is unique by definition
\end{proof}



\begin{proof}[Proof of Lemma \ref{lem:minimumexposantgraph}]
Let $\cL=(V,E)$ be a polynomial graph. We write $(V_1,\ldots, V_{|CC|})$ for the partition of the vertices corresponding to the connected components of a subgraph of $\cL$, where we only keep the edges with weight $1$. Let $\mathcal{T}$ denote a spanning tree of $\cL$ and let $(s,s')$ be its degree. By definition, $\mathcal{T}$ must span all the $V_{t}$'s.  Hence, it has at least $ |CC|-1$ edges of weight $x$ or $y$. We deduce that $s+s'\geq |CC|-1$. 

Let us construct a spanning tree $\mathcal{T}$, with degree  $(s,s')$, such that $s+s'=|CC|-1$. To do so, we consider $E_1$ the set of edges of $\mathcal{L}$ whose extremities are between two different connected components $V_{t}$ and $V_{t'}$. We denote $\cG_{CC}$ the induced polynomial multi-graph on $[|CC|]$. We extract from $\cG_{CC}$ a spanning tree $\mathcal{T}^{CC}$, and for all edges of $\mathcal{T}_{CC}$ between some $t$ and $t'$, we keep an edge of $E_1$ connecting $V_{t}$ and $V_{t'}$. We denote by $E_1'$, which is of size $|CC|-1$, the corresponding  subset of $E_1$. Let $\cG$ denote the polynomial graph obtained by the union of $E_1'$ with all the edges of weight $1$. It is clear that $\cG$ spans the vertex set $V$. We extract $\mathcal{T}$ a spanning tree of $\cG$. By definition, we have $s+s'= |CC|-1$. 

Let us now take $\mathcal{T}_0$ a spanning tree of $\cG_{CC}$ with $|CC|-1$ edges of weight $x$ or $y$ and that minimizes the number of edges of weight $x$. By constructing a spanning graph $\mathcal{T}^*$ of $\cG$ from $\mathcal{T}_0$ as above, we deduce that  its degree is the infimum of the degrees of all spanning trees. 
\end{proof}



\begin{proof}[Proof of Lemma \ref{lem:decompmimimumexposantgraph}]



We consider $\bold{\Delta}=\ac{\Delta_1,\ldots,\Delta_m}$ a set of subsets of $[\ell]$  such that $\bV\vee \Pi(\Delta_1)\vee\ldots\vee\Pi(\Delta_m)=\{V\}$. If there exists $i\in [m]$ such that $\cL[\Delta_i]$ is not connected, then $\mathrm{ord}\pa{\cL[\Delta_i]}=\pa{+\infty,+\infty}$ and the result is trivial. Let us now suppose that, for all $i\in [m]$,  $\cL[\Delta_i]$ is connected. For $i\in [m]$, consider $\cT_i$ a spanning tree of $\cL[\Delta_i]$ with $deg(\cT_i)=\mathrm{ord}\pa{\cL[\Delta_i]}$ --such a tree exists by Lemma \ref{lem:minimumexposantgraph}. Each $\cT_i$ can then be viewed as a subset of edges of the original graph $\cL$. Let $E_0$ be the union of all the edges  of $\cT_i$'s and of all edges of weight $1$ of $\cL$. Since $\bV\vee \Pi(\Delta_1)\vee\ldots\vee\Pi(\Delta_m)=\{V\}$, we know that $E_0$ spans $V$. We extract a spanning tree $\cT$ from $E_0$. Considering $E_0$ as a monomial in $x$ and $y$, we deduce that  
$$deg(\cT)\preccurlyeq deg(E_0)=\sum_{i=1}^m deg(\cT_i)=\sum_{i=1}^m \mathrm{ord}\pa{\cL[\Delta_i]} \enspace .$$
Since $\mathrm{ord}\pa{\cL}\preccurlyeq deg(\cT)$, we conclude that 
$$\mathrm{ord}\pa{\cL} \preccurlyeq\sum_{i=1}^m \mathrm{ord}\pa{\cL[\Delta_i]} \enspace. $$
\end{proof}





\begin{proof}[Proof of Lemma \ref{lem:basicpropertiesorder}]
Let us take $f(x,y)=\sum_{s,s'\geq 0}f_{s,s'}x^s y^{s'}$ and $g=\sum_{s,s'\geq 0}g_{s,s'}x^sy^{s'}$.
\begin{enumerate}
\item We have $(fg)(x,y)=\sum_{s_0,s_0'\geq 0}\pa{\sum_{s\leq s_0}\sum_{s'\leq s'_0}f_{s,s'}g_{s_0-s, s'_0-s'}}x^{s_0}y^{s'_0}$. We write $(fg)_{s_0,s'_0}=\sum_{s\leq s_0}\sum_{s'\leq s'_0}f_{s,s'}g_{s_0-s, s'_0-s'}$. For having $(fg)_{s_0,s'_0}\neq 0$, there must exists $s\leq s_0$ and $s'\leq s'_0$ such that $f_{s,s'}\neq 0$ and $g_{s_0-s, s'_0-s'}\neq 0$. In that case, by definition, we have $(s,s')\succcurlyeq \mathrm{ord}(f)$ and $(s_0-s, s'_0-s')\succcurlyeq \mathrm{ord}(g)$ so that $(s_0,s'_0)\succcurlyeq  \mathrm{ord}(f)+\mathrm{ord}(g)$. This being true for all $(s_0,s'_0)$ with $(fg)_{s_0,s'_0}\neq 0$, we deduce taking the infimum that $\mathrm{ord}(fg)\succcurlyeq \mathrm{ord}(f)+\mathrm{ord}(g)$.

\item We have $(f+g)(x,y)=\sum_{s,s'\geq 0}\pa{f_{s,s'}+g_{s,s'}}x^sy^{s'}$. Let us write $(f+g)_{s,s'}=f_{s,s'}+g_{s,s'}$. For having $(f+g)_{s,s'}\neq 0$, one needs that either $f_{s,s'}\neq 0$ or $g_{s,s'}\neq 0$ and so $(s,s')\succcurlyeq \inf \pa{\mathrm{ord}(f),\mathrm{ord}(g)}$. We conclude $\mathrm{ord}(f+g)\succcurlyeq \inf \pa{\mathrm{ord}(f),\mathrm{ord}(g)}$:

\item Let us suppose that $f(0,0)=0$. Then, on an open ball around $(0,0)$, $|f(x,y)|<1$, and so 
$$\frac{1}{1+f(x,y)}-1=\sum_{d\geq 1}(-f(x,y))^d:=\sum_{s,s'\geq 0}\pa{\frac{1}{1+f}-1}_{s,s'}x^sy^{s'}\enspace.$$
Using point 1., we know that for all $d\geq 1$, $\mathrm{ord}((-f)^d)\succcurlyeq d\cdot\mathrm{ord}(f)\succcurlyeq \mathrm{ord}(f)$. For $s,s'$ such that $\pa{\frac{1}{1+f}-1}_{s,s'}\neq 0$, there exists $d$ such that, wherenever $d'\geq d+1$, $d'\cdot\mathrm{ord}(f)\succcurlyeq (s,s')$. And so, using the second point of this proof generalized to finite sums of multivariate power series, we get that $(s,s')\succcurlyeq \mathrm{ord}(\sum_{d'\leq d}f^d)\succcurlyeq \mathrm{ord}(f)$. We conclude $\mathrm{ord}(\frac{1}{1+f}-1)\succcurlyeq \mathrm{ord}(f)$.
\end{enumerate}
\end{proof}



\begin{proof}[Proof of Lemma \ref{lem:quasifactographgeneral}]
Let us write $\mathrm{ord}\pa{\cL^*}=\pa{d_{[\ell]},d'_{[\ell]}}$. Suppose $\pa{d_{[\ell]},d'_{[\ell]}}$ is finite. From Lemma \ref{lem:minimumexposantgraph}, we know that there exists a spanning tree $\mathcal{T}$ of $\cL^*$ of degree $\pa{d_{[\ell]},d'_{[\ell]}}$. 


A spanning tree, if there exists one, has necessarily at least $|\ell|-1$ edges. All the edges in $\mathcal{L}^*$ are of weight $x$, $y$. Hence, $d_{[\ell]}+d'_{[\ell]}\geq \ell-1$.


We recall that $\mathcal{B}$ is the graph on $[\ell]$ with an edge between $t$ ,$t'$ if and only if there exists $i\in [r]$ such that both $I_{t}$ and $I_{t'}$ intersects $B_{i}$, and that $cc(\cB)$ stands for the number of connected components of this graph. We remark that $(t,t')$ is an edge of $\cB$ if and only if it is an edge of weight $y$ of $\cL^*$. Thus, $\mathcal{T}$ has at least $cc(\cB)-1$ edges of weight $x$ and so $d_{[\ell]}\geq cc(\cB)-1$. 

\end{proof}




\subsection{Case $r=0$.}\label{ref:caser0}


This section is devoted to proving the second point of Lemma \ref{lem:upperboundgeneralcumulant}. Assume that $Z_1, \ldots, Z_\ell$ have mixed moments given by 
$$\E\cro{\prod_{t\in \Delta}Z_{t}}=\eta^{|I_\Delta|}\prod_{j=1}^q \frac{1}{1-x_0}\times\ldots\times \frac{1}{1-(|I_\Delta\cap A_{j}|-1)x_0}\ ,\quad \text{for $\Delta\subseteq [R]$.}$$

This is a particular case of the cumulant dealt in the first point. We could use the result of the first point, but loose a factor $2$ compared to the result that we want to prove. However, let us explain in this section what simplifications we can make in the specific case $r=0$. We Define, for $\Delta\subseteq [\ell]$, $u_\Delta(x)=\eta^{|I_\Delta|}\prod_{j=1}^q \frac{1}{1-x}\times\ldots\times \frac{1}{1-(|I_\Delta\cap A_{j}|-1)x}$ which is a power series in $x$. We define the associated power series, for $\Delta\subseteq [\ell]$, $\kappa_{\Delta}(x)=\sum_{G\in \cP\pa{\Delta}}m(G)\prod_{\delta\in G}u_\delta(x)$. We remark that $\cumul\pa{Z_1,\ldots,Z_\ell}=\kappa_{[\ell]}(x_{0})$. The \textit{order} of this power series is of the form $(d_\Delta,0)$ and, using the results of Section \ref{sec:orderkappa}, we get that $d_{[\ell]}\geq \ell-1$. 
When $x$ is small enough, we can expand the power series $\kappa_{[\ell]}(x)=\sum_{d\geq  \ell-1}\kappa_{d}x^d$. We plug the results of Section \ref{sec:controlcoeff} and we get that, for all $d\geq  \ell-1$, $|\kappa_{d}|\leq \eta^L L^{2d}\ell^{2\ell}$, where we recall $L=|I_{[\ell]}|$. When $2Lx^2\leq 1$, we end up with, 
\begin{align*}
|\kappa_{[\ell]}(x)|&\leq \sum_{d\geq \ell-1}\ell^{2\ell} \eta^L L^{2d}x^d\\
&\leq 2\ell^{2\ell}\eta^L \pa{L^2 x}^{\ell-1}\enspace,
\end{align*}
and we conclude with $|\kappa_{[\ell]}(x_0)|=|\cumul\pa{Z_1,\ldots, Z_\ell}|\leq  2\ell^{2\ell}\eta^L \pa{L^2 x_{0}}^{\ell-1}$ when $2Lx_{0}^2\leq 1$. 





\section{Other losses for seriation}\label{sec:seriation:complementary}


In this section, we introduce the general T\oe plitz-Robinson seriation model. Given a vector $\theta = (\theta_0,\dots, \theta_{n-1})\in \bbR^n$, we write $T(\theta)$ for the T\oe plitz matrix in $\mathbb{R}^{n\times n}$ with entries $T(\theta)_{i,j} = \theta_{i-j}$, where we use the convention $\theta_k := \theta_{-k}$ for $k \leq 0$. 
The matrix $T(\theta)$ is  said to be T\oe plitz Robinson if the entries of $\theta$ are non-increasing. 

Given a permutation $\pi^*$ in $\cS_n$, we write $P(\pi^*)$ for the corresponding permutation matrix. In this seriation model, we observe a $Y\in \mathbb{R}^{n\times n}$ with $Y=X + E$ where  the matrix $E$ is made of independent standard normal entries and 
\begin{equation}\label{eq:model:seriation:Toeplitz}
X=P(\pi^*)T(\theta)P(\pi^*)
\end{equation}
with $T(\theta)$ is a possibly unknown T\oe plitz-Robinson matrix, and $P(\pi^*)$ is an unknown permutation matrix to be estimated. The permutation $P(\pi^*)$ is not identifiable: $P(\pi^*)$ and the corresponding reverse permutation $P(\pi^*)_{-}$ are such that $P(\pi^*)T(\theta)P(\pi^*)^T= P(\pi)_-^*T(\theta)P(\pi^*)_-^{T}$. Hence, the main goal  in seriation is to recover a permutation $\pi$ such that $X= P(\pi)T(\theta)P(\pi)^T$.


Given a positive integer $\rho$ and $\lambda>0$, we defined the vector $\theta_{\lambda,\rho}\in \mathbb{R}^n$ by $(\theta_{\lambda,\rho})_{i}= \lambda \1_{i\leq \rho}$. Note that the model~\eqref{eq:definition:model:seriation} introduced in Section~\ref{sec:seriation} corresponds to $X= P(\pi^*)T(\theta_{\lambda,k})P(\pi^*)$


One way of quantifying the error of a given permutation matrix $\Pi$ is the $\ell_2$ loss which quantifies to what extent 
$X$ is close in Frobenius distance to a Robinson matrix ordered by $\pi$.
$$
\ell_2(\pi) := \inf_{R \in \cR_n} \|  X  - P(\pi) RP(\pi)^T\|_F\enspace ,
$$
where $\cR_n$ is the collection of Robinson matrices, that is the collection of symmetric matrices $R$ such, for any $i< j$, we have  $R_{i,j} \leq R_{i+1,j}$ and $R_{i,j}\geq R_{i,j+1}$. Equivalently, $R$ is a Robinson matrix if its entries are non-increasing when one moves away from the diagonal. 

It is established in \cite{berenfeld2024seriation} that the minimax rate in $\ell^2_2$ for the seriation problem is of the order of $n$. In contrast, the best known polynomial-time procedures~\cite{berenfeld2024seriation} only achieves a rate of the order of $n^{3/2}$. To provide evidence of the optimality of the $n^{3/2}$ for polynomial-time procedures, \cite{berenfeld2024seriation} also provide  a nearly matching LD polynomial lower bound but their model was quite different as $\pi^*$ was not necessarily a permutation. Here, we strengthen this evidence by deriving a computational $n^{3/2}$ lower bound in the model~\eqref{eq:model:seriation:Toeplitz}.

As for clustering, the problem of estimating a permutation $\hat{\pi}$ is of combinatorial nature and in order to state a LD lower bounds, we reduce it to the problem of estimating the matrix $X=P(\pi^*) T(\lambda,\rho)P(\pi^*)^T$. 

The following lemma is a slight adaptation of Lemma 8 in~\cite{berenfeld2024seriation} --see Section~\ref{sec:proof:reminaining:seriation} for a proof. 
\begin{lem}[Reduction to matrix estimation]\label{lem:reduction}
Consider any $\lambda>0$, positive integer $\rho$ and any estimator $\widehat{\pi}$. 
Define the matrix $\hat{X}$ by $\hat{X}_{i,j}= \lambda/2$ if $|\hat{\pi}^{-1}(i)-\hat{\pi}^{-1}(j)|\leq \rho$ and $\hat{X}_{i,j}= 0$ otherwise. Then, we have 
\begin{equation}\label{eq:lower_bound_risk}
\ell^2_2(\hat{\pi})\geq \frac{1}{4}\left[\left[\|\hat{X}-X\|_F^2\right]- \lambda^2\rho n \right]  
\end{equation}
\end{lem}
As a consequence of this lemma, if all polynomial-time estimators $\hat{X}$ of $X$ satisfy $\mathbb{E}[\|\hat{X}-X\|_F^2]\geq \frac{3}{2} \lambda^2 \rho n$, then no polynomial-time estimators of $\hat{\pi}$ satisfy 
$\mathbb{E}[\ell^2_2(\hat{\pi})]\geq c  \lambda^2 \rho n$ for some $c>0$. Hence, to establish the hardness of achieving $\mathbb{E}[\ell^2_2(\hat{\pi})] \preccurlyeq_{\log(n)} n^{3/2}$, it suffices to prove that, for $\rho=\lceil \sqrt{n} \rceil$ and $\lambda$ such that $1/\lambda$ is a polylogarithmic  term, one has $\mathbb{E}[\|\hat{X}-X\|_F^2]\geq \frac{3}{2} \lambda^2 \rho n$. The latter precisely corresponding to LD lower bound in Theorem~\ref{thm:lowdegreeseriation}.

In particular, taking $D\asymp \log(n)$, $\rho\asymp \sqrt{n}$, $\lambda$ as the inverse of a polylogarithmic term, we deduce from  that theorem that 
\[
MMSE_{\leq \log(n)}\geq \lambda^2 \frac{3\rho}{2}n  \succcurlyeq_{\log(n)} n^{3/2}\ . 
\] 
Together with Lemma~\ref{lem:reduction}, this suggests the hardness of achieving seriation with a $\ell_2^2$ rate smaller than $n^{3/2}$. 






