\begin{proof}[Proof of Proposition~\ref{prp:upper:polynomial:seriation}]

The first result straightforwardly derives from the proof of Theorem 4 in~\cite{berenfeld2024seriation}. Translating the third line of that proof with our notation, we deduce that there exists an event $\cA$ of probability higher than $1-4/n$ such that 
\[
\|X_{\hat{\pi}} - X\|_F^2 \leq \lambda^2 n + \lambda n^{3/2} \sqrt{\log(n)}
\]
Since $\|X_{\hat{\pi}} - X\|_F^2\leq \lambda^2 n^2$, we deduce that 
\[
\mathbb{E}\left[\|X_{\hat{\pi}} - X\|_F^2\right]\leq 5\lambda^2 n + \lambda n^{3/2} \sqrt{\log(n)}\ . 
\]
Let us turn to the second result. For a fixed $(i,j)$, it follows from a standard control of the Gaussian tail distribution that  $(\hat{X}_{th})_{ij}= X_{ij}$ with probability at least $1-1/n^2$. Hence, $\mathbb{E}[((\hat{X}_{th})_{ij}- X_{ij})^2]=\lambda^2/n^2$. The result follows by linearity. 
\end{proof}



\begin{proof}[Proof of Proposition~\ref{prp:upper:IT:seriation}]
$\|Y - \hat{X}_{\hat{\pi}}\|_F^2 \leq \|Y- X\|^2_F$ implies that $\|X - \hat{X}_{\hat{\pi}}\|_F^2+ 2 \langle E , X - \hat{X}_{\hat{\pi}}\rangle\leq 0$. Let us apply an union bound of the random variable $\langle E ,\hat{X}_{\pi}-X\rangle$  over all $n!$ matrices of the form $X_{\pi}$. 
Hence, with probability higher than $1-e^{-x}$, we have $-\langle E , X - \hat{X}_{\hat{\pi}}\rangle\leq \sqrt{2[n\log(n)+x]}\|X -\hat{X}_{\hat{pi}}\|_F$. On this event, we have $\|X - \hat{X}_{\hat{\pi}}\|^2_F\leq 8[n\log(n) + x]$. The result follows by integrating with respect to $x$. 
\end{proof}






\begin{proof}[Proof of Lemma~\ref{lem:reduction}]
The proof closely follows that of Lemma 8 in~\cite{berenfeld2024seriation}. Still, we provide here a complete proof as 
the notation and the conventions slightly differ from~\cite{berenfeld2024seriation}. 
Without loss of generality, we assume that $\pi^*$ is the identity permutation. 
If $|\hat{\pi}(i)- \hat{\pi}(j)|\leq 2\rho$, we have $|\hat{X}_{ij}-X_{ij}|= \lambda/2$. Hence, it follows that 
\begin{equation}\label{eq:upper_bound_l2_pi3}
\|\hat{X}-X\|_F^2\leq \lambda^2 \rho n + \lambda^2 \left|\{(i,j): X_{ij}= \lambda \text{ and } |\hat{\pi}(i)- \hat{\pi}(j)|>2\rho\}\right| 
\end{equation}
We bound the RHS of \eqref{eq:lower_bound_risk} using the loss $\ell^2_2(\hat{\pi})$. For that purpose, let us introduce $\mathcal{R}'_n$ the collection of $n\times n$ matrices whose rows are unimodal and achieve their maximum on the diagonal. Obviously $\mathcal{R}_n\subset \mathcal{R}'_n$ and so $\ell^2_2(\hat{\pi})\geq \inf_{R\in \mathcal{R}'_n}\| X - P(\hat{\pi}) R P(\hat{\pi})^{T} \|_F^2$. Besides, we introduce $\mathcal{R}'_n(\lambda)$ as the subset of $\mathcal{R}'_n$ that only take its values in $\{0,\lambda\}$ outside the diagonal. For $R\in \cR_n'$, let us introduce $R_0\in \cR_n(\lambda)$ defined by $\cro{R_0}_{ij}=\lambda\1\ac{R_{ij}\leq \lambda/2}$. Since $X$ takes its values on $\ac{0,\lambda}$, we have that $\| X - P(\hat{\pi}) R P(\hat{\pi})^{T} \|_F^2\geq \frac{1}{4}\| X - P(\hat{\pi}) R_0 P(\hat{\pi})^{T} \|_F^2$. We deduce
\begin{equation}\label{eq:lower_bound_l2_pi}
\ell^2_2(\hat{\pi})\geq  \inf_{R\in \mathcal{R}'_n}\| X - P(\hat{\pi}) R P(\hat{\pi})^{T} \|_F^2 \geq  \frac{1}{4}\inf_{R\in \mathcal{R}'_n(\lambda)}\| X - P(\hat{\pi})R P(\hat{\pi})^{T}\|_F^2 .
\end{equation}
Let  $R$ denote any matrix in $\mathcal{R}'_n(\lambda)$ that achieves the above infimum.  Fix any $i\in [n]$. We claim that  
\begin{align}
\frac{\|[ X - P(\hat{\pi}) RP(\hat{\pi})^T ]_{i}\|^2}{\lambda^2}&  \geq  \left|\{j: |i-j|\leq \rho \text{ and } |\hat{\pi}(i)-\hat{\pi}(j)|> 2\rho \}\right|   , \label{eq:lower_row}  
\end{align}
where $[ X - P(\hat{\pi}) RP(\hat{\pi})^T ]_{i}$ stands for the $i$-th row ot the matrix. Before showing this claim, let us conclude the proof. Since $$\left|\{j: |i-j|\leq \rho \text{ and } |\hat{\pi}(i)-\hat{\pi}(j)|> 2\rho \}\right|= \left|\{j: X_{i,j}= \lambda \text{ and } |\hat{\pi}(i)- \hat{\pi}(j)|> 2\rho\}\right|\enspace,$$ it follows from 
\eqref{eq:upper_bound_l2_pi3} and~\eqref{eq:lower_row} that 
\[
\|\hat{X}-X\|_F^2\leq \lambda^2 \rho n + 4\ell^2_2(P(\hat{\pi}))\ , 
\]
which is precisely the desired bound.

Let us now show~\eqref{eq:lower_row}. Without loss of generality, we can assume that  the $j$'s such that $|i-j|\leq  \rho$ and $ |\hat{\pi}(i)-\hat{\pi}(j)|> 2\rho $ are such that $\hat{\pi}(j)> \hat{\pi}(i)+ 2\rho$. We consider two cases: (i)
$R_{\hat{\pi}(i), \hat{\pi}(i) + 2\rho + 1 }=0$.  For all $j$ such that $|i-j|\leq  \rho$ and $ |\hat{\pi}(i)-\hat{\pi}(j)|> 2\rho$, we have $[ X - P(\hat{\pi}) RP(\hat{\pi})^T ]_{ij}=\lambda$. Then, this straightforwardly implies~\eqref{eq:lower_bound_l2_pi}. Now, suppose (ii) that  $R_{\hat{\pi}(i), \hat{\pi}(i) + 2\rho + 1 }=\lambda$. There exists at least $\left|\{j: |i-j|\leq \rho \text{ and } |\hat{\pi}(i)-\hat{\pi}(j)|\geq 2\rho \}\right|$ indices $j$ such that $\hat{\pi}(j)\in (\hat{\pi}(i), \hat{\pi}(i)+2\rho]$ and $|i-j|>\rho$. Since, for a such a $j$, we have  $X_{i,j}=0$ and $R_{\hat{\pi}(i),\hat{\pi}(j)}= \lambda$ , we again derive~\eqref{eq:lower_row}.
\end{proof}


\subsection{Proof of Proposition \ref{prop:hardnessclustering}}\label{prf:hardnessclustering}

This proof is adapted from the proof of Proposition A.3 of \cite{Even25a}. Let us consider a regime where $n,K$ go to infinity (and possibly $p$) and where $K=o(n)$. Given a partition $G=G_1,\ldots, G_K$ such that $|G_k|=n/K$ for all $k\in [K]$, we define the partnership matrix $\Gamma^G\in \R^{n\times n}$ by $\Gamma^G_{i,j}=\sum_{k\in [K]}\1\ac{i,j\in G_k}$. We write $\Gamma^*$ for $G^*$. Then, 
\begin{equation*}
n(n-1) MMSE_{poly}=\E\cro{\|\Gamma^*\|^2_F}-corr_{poly}^2=n^2/K-corr_{poly}^2,
\end{equation*}
where we define $$corr_{poly}^2:= \sup_{\hat \Gamma\ poly-time,\ \E\cro{\|\hat \Gamma\|^2_{F}}=1} \E\cro{\langle \Gamma^*,\hat \Gamma\rangle_{F}}^2\enspace.$$ 
Since $MMSE_{poly}= 1/K(1+o(1))$, it follows that   $corr_{poly}^2=o(n^2/K)$. For $\hat G$ a polynomial time estimator of $G^*$ with prescribed group size $n/K$, we have 
$$\E\left[\<\Gamma^{\hat G}, \Gamma^*\>\right]\leq \sqrt{\E\cro{\|\Gamma^{\hat{G}}\|^2_F}}\ corr_{poly}=\sqrt{n^2\over K}\ corr_{poly}$$ 
since $\|\Gamma^{\hat{G}}\|^2_F=n^2/K$ almost surely. We deduce 
\begin{align*}
\E\cro{\|\Gamma^{\hat{G}}-\Gamma^*\|^2_F}=&2n^2/K-2\mathbb{E}\left[\<\Gamma^{\hat{G}}, \Gamma^*\>\right]\\
\geq& 2n^2/K-\sqrt{n^2/K}\ corr_{poly}\\
\geq& 2n^2/K(1+o(1))\enspace.
\end{align*}
We conclude the proof of the proposition with the following lemma.
\begin{lem}\label{lem:clusteringhardness} For any $G$ with prescribed group size $n/K$, we have 
$\cro{1-err(G,G^*)}^2\leq 1-\frac{K\|\Gamma^G-\Gamma^*\|_F^2}{2n^2}$.
\end{lem}





\begin{proof}[Proof of Lemma \ref{lem:clusteringhardness}]
With no loss of generality, we assume that the permutation $\psi$ in the definition of $err(G,G^*)$ is the identity. Thus,
\[
err(G,G^*)= \frac{1}{2n}\sum_{k=1}^K |G_k \Delta G^*_k|= 1 - \frac{1}{n}\sum_{k=1}^K
|G_k\cap G^*_k|\ , 
\]
which implies that $\sum_{k=1}^K|G_k\cap G^*_k| = n[1- err(G,G^*)]$. We have, for $G,G^*$ with group size $n/K$,  that 
\begin{equation*}
\|\Gamma^G-\Gamma^*\|_F^2=  \|\Gamma^G\|^2_F+\|\Gamma^*\|_F^2-2\<\Gamma^G, \Gamma^*\>_F = 2n^2/K-2\<\Gamma^G, \Gamma^*\>_F \ .
\end{equation*}
Furthermore,
$$\<\Gamma^G, \Gamma^*\>_F=\sum_{ij\in [n]}\sum_{k,k'\in [K]}\1\ac{i,j\in G_k}\1\ac{i,j\in G_k^*} \enspace.$$
For $k\in [K]$, let us denote $N_k=\left|G_k\cap G^*_k\right|$. Then,
\begin{equation*}
\<\Gamma^G, \Gamma^*\>_F\geq\sum_{k\in [K]}N_k^2\geq \frac{1}{K}\cro{\sum_{k\in [K]}N_k}^2\geq n^2\cro{1-err(G,G^*)}^2/K\enspace,
\end{equation*}
where we used the Cauchy-Schwarz inequality for the second inequality. We conclude that $$\|\Gamma^G-\Gamma^*\|_F^2\leq 2{n^2\over K}\pa{1-\cro{1-err(G,G^*)}^2}\enspace.$$
\end{proof}






\subsection{Proof of Proposition \ref{prop:featurematchinghardness}}\label{prf:featurematchinghardness}


This proof is also adapted from the proof of Proposition A.3 of \cite{Even25a} and is similar to the proof of Proposition \ref{prop:hardnessclustering}. Let us consider a regime where $M,K$ go to infinity (and possibly $p$). Given a $M$-tuple of permutations $\pi=\pi_1,\ldots, \pi_M$, we define the partnership matrix $\Gamma^\pi\in \R^{(K\times M)^2}$ by $\Gamma^\pi_{(k,m), (k',m')}=\1\ac{\pi_m(k)=\pi_{m'}(k')}$. We write $\Gamma^*$ for $\pi^*$. Then, 
\begin{equation*}
(M(M-1))K^2 MMSE_{poly}=\E\cro{\|\Gamma^*\|^2_F}-corr_{poly}^2=KM^2-corr_{poly}^2,
\end{equation*}
where we define $$corr_{poly}^2:= \sup_{\hat \Gamma\ poly-time,\ \E\cro{\|\hat \Gamma\|^2_{F}}=1} \E\cro{\langle \Gamma^*,\hat \Gamma\rangle_{F}}^2\enspace.$$ 
Since $MMSE_{poly}= 1/K(1+o(1))$, it follows that   $corr_{poly}^2=o(M^2K)$. For $\hat{\pi}\in \pa{\mathcal{S}_K}^M$ a polynomial time estimator of $\pi^*$, we have 
$$\E\left[\<\Gamma^{\hat{\pi}}, \Gamma^*\>\right]\leq \sqrt{\E\cro{\|\Gamma^{\hat{\pi}}\|^2_F}}\ corr_{poly}=\sqrt{KM^2}\ corr_{poly}$$ 
since $\|\Gamma^{\hat{\pi}}\|^2_F=KM^2$ almost surely. We deduce \begin{align*}
\E\cro{\|\Gamma^{\hat{\pi}}-\Gamma^*\|^2_F}=&2KM^2-2\mathbb{E}\left[\<\Gamma^{\hat{\pi}}, \Gamma^*\>\right]\\
\geq& 2KM^2-\sqrt{KM^2}\ corr_{poly}\\
\geq& 2KM^2(1+o(1))\enspace.
\end{align*}
We conclude the proof of the proposition with the following lemma.
\begin{lem}\label{lem:featurematchinghardness} For any $\pi\in\pa{\mathcal{S}_{K}}^M$, we have 
$\cro{1-err(\pi,\pi^*)}^2\leq 1-\frac{\|\Gamma^\pi-\Gamma^*\|_F^2}{2KM^2}$.
\end{lem}





\begin{proof}[Proof of Lemma \ref{lem:featurematchinghardness}]
With no loss of generality, we can suppose that the permutation $\psi$ minimizing the definition of the error $err(\pi,\pi^*)$ is the identity and thus $$err(\pi,\pi^*)=\frac{1}{KM}\sum_{k,m}\1\ac{\pi_m(k)\neq \pi^*_m(k)}=1-\frac{1}{KM}\sum_{k,m}\1\ac{\pi_m(k)= \pi^*_m(k)}\enspace.$$
And, we also have $$\|\Gamma^\pi-\Gamma^*\|_F^2=\|\Gamma^\pi\|_F^2+\|\Gamma^*\|_F^2-2\<\Gamma^\pi, \Gamma^*\>\enspace.$$ We can directly compute $\|\Gamma^\pi\|_F^2=\|\Gamma^*\|_F^2=KM^2$. For the crossed-product term, we expand $$\<\Gamma^\pi, \Gamma^*\>=\sum_{(k,m), (k',m')}\1\ac{\pi_m(k)=\pi_{m'}(k')}\1\ac{\pi^*_m(k)=\pi^*_{m'}(k')}\enspace.$$
For $k\in [K]$, let us denote $N_k=\left|\ac{(k',m)\in [K]\times [M], \pi_m(k')=k\\ \quad\text{and}\quad \pi^*_m(k')=k}\right|$. We get \begin{align*}
\<\Gamma^\pi, \Gamma^*\>\geq&\sum_{k\in [K]}N_k^2
\geq \frac{1}{K}\cro{\sum_{k\in [K]}N_k}^2\geq KM^2\cro{1-err(\pi,\pi^*)}^2\enspace,
\end{align*}
where we used Cauchy-Schwarz inequality for the second inequality. We conclude that $$\|\Gamma^\pi-\Gamma^*\|^2_F\leq 2KM^2-2KM^2\cro{1-err(\pi,\pi^*)}^2\enspace.$$
\end{proof}



\subsection{Proof of Corollary \ref{cor:featurematchingupperbound}}\label{prf:featurematchingupperbound}




We write $G^*$ the partition of $[K]\times [M]$ defined by $G_{k}^*=\ac{(k',m)\in [K]\times [M],\enspace \pi^*_m(k')=k}$. We remark that $G^*$ is a balanced partition of $[K]\times [M]$ into $K$ groups and that $Y^{(m)}_{k'}\sim \cN\pa{\mu_k, \sigma^2I_p}$. 

\begin{enumerate}
\item Using Proposition 4 of \cite{Even24}, we know that a single linkage hierarchical procedure is able to recover exactly $G^*$ with high probability as soon as $\Delta^2\gtrsim \log(KM)+\sqrt{p\log(KM)}$;
\item Using Theorem 1 of \cite{giraud2019partial}, we know that a SDP relaxation procedure is able to recover exactly $G^*$ in high dimension $p\geq MK$ as soon as $\Delta^2\geq_{\log}\sqrt{\frac{pK}{M}}$;
\item Using Proposition 3.2 of \cite{Even25a}, we deduce that, with a method based on spectral projections together with the low-dimensional clustering procedure from \cite{LiuLi2022}, we are able to recover exactly $G^*$ with high probability when $M\geq K^c$, for some numerical constant $c$, and $\Delta^2\geq_{\log}1+\sqrt{\frac{pK}{M}}$;
\item Still using Proposition 3.2 of \cite{Even25a}, we know that, with a method based on spectral projections together with a single linkage hierarchical procedure, we are able to recover exactly $G^*$ with high probability when $M\gtrsim K$, $MK\geq p\geq M$ and $\Delta^2\geq_{\log}1+\sqrt{\frac{pK}{M}}$.
\end{enumerate}

All the methods that are used for these four points are computable in polynomial time. Hence, combining those results, we deduce that, except when both $M\in [K,K^c]$ and $p\in [\log(KM), \frac{p}{KM}]$, there exists an efficient algorithm $\hat{G}$ which recovers exactly with high probability $G^*$ as soon as $\Delta^2\geq_{\log} 1 +\min\pa{\sqrt{p}, \sqrt{\frac{pK}{M}}}$. We define the estimator $\hat{\pi}$ by $\hat{\pi}_m(k')=k$ if $(k',m)\in \hat{G}_k$. On the event where $\hat{G}=G^*$, $\hat{\pi}$ is a $M$-tuple of permutations on $[K]$ which satisfies $err(\hat{\pi}, \pi^*)=err(\hat{G},G^*)=0$. This concludes the proof of the corollary. 





 \subsection{Sketch of proof of Proposition \ref{prop:upperboundinformationalfeature}}\label{prf:upperboundinformationalfeature}



This proof is directly adapted from the proof of Theorem 2 of \cite{Even24} for exact $K$-means and we mainly explain the key steps.  We view $Y$ as a matrix in $\R^{KM\times p}$. Given $\pi\in \pa{\cS_K}^M$, let $B(\pi)$ the normalized partnership matrix $B(\pi)\in \R^{KM\times KM}$ defined $\pa{B(\pi)}_{(k,m),(k',m')}=\frac{1}{M}\1\ac{\pi_m(k)=\pi_{m'}(k')}$. As noticed by \cite{PengWei07}, minimizing Criterion \eqref{eq:critpi} is equivalent to maximizing the quantity $\<YY^T, B(\pi)\>$. Let $\cB:=\{B(\pi), \pi\in \pa{\cS_K}^M\}$ and let $$\hat{B}:=\argmax_{B\in \cB}\<YY^T, B\>\enspace.$$
$\cB$ is a subset of the set $\cC=\{ B\in S_{n}(\mathbb{R})^{+}:\ B_{ij}\geq 0, \tr(B)=K, B1=1, B^{2}=B \}$ which is the set of normalized partnership matrices associated to partitions $G$ of $[KM]$ into $K$ groups. In particular, all the inequalities from \cite{Even24} which are valid on $\cC$ are in fact valid on $\cB$. In the following, we write $B^*$ for $B(\pi^*)$. Let us consider;\begin{itemize}
\item $A\in\R^{KM\times K}$ the membership matrix defined by $A_{(k',m),k}=\1_{\pi^*_m(k')=k}$, 
\item $E\in\R^{KM\times p}=Y-\E[Y]$ the noise matrix,
\item $\mu \in\R^{K\times p}$ whose $k$-th row is $\mu_{k}$.
\end{itemize}
By definition of $\hat{B}$, we have $\<YY^T, \hat{B}-B^*\>\geq 0$. Decomposing $Y$ with the relation $Y=A\mu +E$, we get
$$\<A\mu(A\mu)^{T},B^{*}-\hat{B}\>\leq \<A\mu E^{T}+E(A\mu)^{T},\hat{B}-B^{*}\>+\<EE^{T}-pI_{MK},\hat{B}-B^{*}\>\enspace.$$
Given a matrix $A$, we write $\|A\|_1$ for the sum of the absolute values of its entries. 
For any $M$-tuple of permutation, the error $err(\pi,\pi^*)$ is linked to the norm $\|B^*-B^*B(\pi)\|_1$ 
through the inequality $err(\pi,\pi^*)\lesssim \frac{\|B^*-B^*B(\pi)\|_1}{KM}$ (see Lemma 9 of \cite{Even24}). Building on this bound;\begin{enumerate}
\item One can lower-bound the signal term $\<A\mu(A\mu)^{T},B^{*}-B\>$ with respect to $\frac{\|B^*-B^*B\|_1}{KM}$. Using Lemma 4 from \cite{giraud2019partial} which is valid on a set containing $\cC$ and thus $\cB$, we get that, for all $\pi\in \pa{\cS_K}^M$, $\<A\mu(A\mu)^{T},B^{*}-B(\pi)\>\gtrsim \Delta^2\|B^*-B^*B(\pi)\|_1\gtrsim KM\Delta^2err(\pi,\pi^*)$.
\item Directly plugging Lemma 11 of \cite{Even24}, we deduce that with high probability, simultaneously on all $B\in \cB$, \begin{align*}
    |\<EE^T-pI_{KM}, B^*-B\>|\lesssim& \|B^*-B^*B\|_{1}\pa{\log(K)+\sqrt{\frac{p}{M}\log(K)}}\\
    &+\|B^*-B^*B\|_{1}\pa{\sqrt{\frac{p}{M}\log(\frac{MK^4}{ \|B^*-B^*B\|_{1}})}+\log(\frac{MK^4}{ \|B^*-B^*B\|_{1}})}\enspace.
\end{align*}
In particular, the first term of this some is smaller than one half of the signal term when $\Delta^2\gtrsim \log(K)+\sqrt{\frac{p}{M}\log(K)}$. 
\item Finally, using Lemma 12 of \cite{Even24}, we get that, with high probability, simultaneously on all $B\in \cB$, $$\langle A\mu E^T +E(A\mu)^T  ,B-B^{*}\rangle \lesssim \sqrt{\<A\mu(A\mu)^{T},B^{*}-B\>}\sqrt{ \|B^*-B^*B\|_{1}\log(\frac{MK^4}{\|B^*-B^*B\|_{1}})}\enspace . $$
\end{enumerate}
In the following, let us denote $\hat{\delta}=\|B^*-B^*\hat{B}\|_{1}$. Combining those three points together, we get that, whenever $\Delta^2\gtrsim \log(K)+\sqrt{\frac{p}{M}\log(K)}$, with high probability,
\begin{align*}
\<A\mu(A\mu)^{T},B^{*}-\hat{B}\>\lesssim& \hat{\delta}\pa{\sqrt{\frac{p}{M}\log(\frac{MK^4}{ \hat{\delta}})}+\log(\frac{MK^4}{ \hat{\delta}})}+\sqrt{\<A\mu(A\mu)^{T},B^{*}-\hat{B}\>}\sqrt{ \hat\delta\log(\frac{MK^4}{\hat\delta})}\enspace,
\end{align*}
which, in turn, implies,
\begin{align*}
\Delta^2\hat{\delta}\lesssim&\hat\delta\pa{\log(\frac{MK^4}{\hat\delta})+\sqrt{\frac{p}{M}\log(\frac{MK^4}{\hat\delta})}}\enspace,
\end{align*}
and so 
$$\hat{\delta}\lesssim MK^4\exp\pa{-c\pa{\Delta^2\wedge\frac{M\Delta^4}{p}}}\enspace,$$
with $c$ some numerical constant. Finally, we end up with 
$$err(\hat{\pi}, \pi^*)\lesssim \frac{\hat{\delta}}{KM}\lesssim K^3\exp\pa{-c\pa{\Delta^2\wedge\frac{M\Delta^4}{p}}}\leq  \exp\pa{-c'\pa{\Delta^2\wedge \frac{\Delta^4 M}{p}}}\enspace, $$ where the last inequality holds for some numerical constant $c'$ if $\Delta^2\gtrsim \log(K)+\sqrt{\frac{p\log(K)}{M}}$. This concludes the (sketch of) proof. 















\subsection{Proof of Theorem \ref{thm:lowerboundinformationalfeature}; Perfect Recovery}\label{prf:lowerboundexact}





This section is dedicated to proving the first point of Theorem \ref{thm:lowerboundinformationalfeature}. Without loss of generality, we suppose throughout this proof that $\sigma=1$. We suppose that $K\geq K_{0}$ with $K_{0}$ a constant that we will choose large enough. 

To prove the first point of Theorem \ref{thm:lowerboundinformationalfeature}, we will distinguish two cases. First, we will prove that there exist positive numerical constants $c_{1}$ and $C$ such that, when $\Bar{\Delta}^{2}\leq c_{1}\log(KM)$, we have $$\inf_{\hat{\pi}:\R^{K\times M\times p}\to (\mathcal{S}_{K})^{M}} \sup_{\mu\in\Theta_{\bar{\Delta}}}\sup_{\pi\in (\mathcal{S}_{K})^{M}}\P_{\mu,\pi}(err(\hat{\pi}, \pi)\neq 0)>C\enspace.$$
Second, we will show that there exists a numerical constant $c_{2}$ such that this still holds when $c_{1}\log(KM)\leq \bar{\Delta}^{2}\leq c_{2}\sqrt{\frac{p}{M}\log(KM)}.$


\subsubsection{Case $\bar{\Delta}^{2}\leq c_{1}\log(KM)$.}




Let us suppose that $\bar{\Delta}^{2}\leq c_{1}\log(KM)$ for $c_{1}$ a positive numerical constant that we will choose small enough later. Let $e$ be a unit vector of $\R^{p}$ and define $\mu_{k}=\sqrt{2}k\Bar{\Delta} e$ for $k\in[1,K]$. To prove our statement, we will use Fano's Lemma that we recall here (see e.g p 57 of \cite{HDS2}).
\begin{lem}[Fano's Lemma]\label{lem:fano}
    Let $(\P_{s})_{s\in[\ell]}$ be a set of probability distributions on some set $\mathcal{Y}$. For any probability distribution $\mathbb{Q}$ such that for all $s\in[\ell]$, $\P_{s}<<\mathbb{Q}$, $$\min_{\hat{J}:\mathcal{Y}\to [\ell]}\frac{1}{\ell}\sum_{s=1}^{\ell}\P_{s}\pa{\hat{J}(Y)\neq s}\geq 1-\frac{1+\frac{1}{\ell}\sum_{s=1}^{\ell}KL(\P_{s},\mathbb{Q})}{\log(\ell)}\enspace , $$ where we recall that $KL(\P,\mathbb{Q})=\int \log\pa{\frac{d\P}{d\mathbb{Q}}}d\P$ stands for the Kullback-Leibler divergence between $\P$ and $\mathbb{Q}$. 
\end{lem}

\medskip

Let us consider the distribution $\P_{\mu,id}$ as reference distribution for applying Lemma \ref{lem:fano}. Our goal will be to find different $M$-tuples of permutations $\pi^{(1)},...,\pi^{(\ell)}$, with $\ell$ as large as possible, such that $KL(\P_{\mu, \pi^{(s)}},\P_{\mu,id})$ remains small for all $s\in[\ell]$. To do so, for $s\leq \lfloor \frac{K}{2}\rfloor$ and $m\in[M]$, we define $\pi^{(s,m)}$ the $M$-tuple of permutations defined as follows. If $m'\neq m$, then $\pi^{(s,m)}_{m'}=id$, and $\pi^{(s,m)}_{m}=(2s-1,2s)$ where $(2s-1,2s)$ stands for the transposition of $2s-1$ and $2s$.  

For $s\leq \lfloor \frac{K}{2}\rfloor$ and $m\in[M]$, let us compute $KL(\P_{\mu, \pi^{(s,m)}}, \P_{\mu,id})$. Given $m'\in[M]$ and $k\in[K]$, we denote $\P_{\mu, \pi^{(s,m)};k,m'}$ the marginal distribution of the vector $Y_{k}^{(m')}$ under  $\P_{\mu, \pi^{(s,m)}}$. Using the independence of the $Y_{k}^{(m')}$'s for $k\in[K]$ and $m'\in[M]$, we get 

\begin{align*}
    KL(\P_{\mu, \pi^{(s,m)}}, \P_{\mu,id})=&\sum_{k=1}^{i=K}\sum_{m'=1}^{M}KL(\P_{\mu, \pi^{(s,m)};k,m'}, \P_{\mu,id;k,m'})\\
    =& KL\pa{\P_{\mu, \pi^{(s,m)};2s-1,m},\P_{\mu, id;2s-1,m}}+KL\pa{\P_{\mu, \pi^{(s,m)};2s,m},\P_{\mu, id;2s,m}}\\
    =&KL\pa{\mathcal{N}(\mu_{2s-1},I_p),\mathcal{N}(\mu_{2s},I_{p})}+KL\pa{\mathcal{N}(\mu_{2s},I_p),\mathcal{N}(\mu_{2s-1},I_{p})}\\
    =& 2\bar{\Delta}^2   \leq 2c_1 \log(KM)\enspace .
\end{align*}

For any estimator $\hat{\pi}$, we associate $\hat{j}$ the estimator that gives $(s,m)$ if $\hat{\pi}=\pi^{(s,m)}$ and $(1,1)$ otherwise. Fano's Lemma (Lemma~\ref{lem:fano}) implies that, for all estimators $\hat{\pi}$, the corresponding estimator $\hat{j}$ satisfies $$\frac{1}{M\lfloor \frac{K}{2}\rfloor}\sum_{(s,m)}\P_{\mu,\pi^{(s,m)}}(\hat{j}\neq (s,m))\geq 1-\frac{1+2c_{1} \log(KM)}{\log(M\lfloor \frac{K}{2}\rfloor)}\enspace.$$ If $c_{1}$ is small enough and $K_{0}$ large enough, there exists a constant $C>0$ such that, for all integers $K\geq K_{0}$ and $M\geq 2$, we have $1-\frac{1+2c_{1} \log(KM)}{\log(M\lfloor \frac{K}{2}\rfloor)}\geq C.$

Since, for any estimator $\hat{\pi}$ and its corresponding estimator $\hat{j}$, for any $s\leq \lfloor K/2\rfloor$ and $m\leq M$, we have $\P_{\mu,\pi^{(s,m)}}(\hat{\pi}=\pi^{(s,m)})\leq \P_{\mu,\pi^{(s,m)}}(\hat{j}=(s,m))$, we get $$\frac{1}{M\lfloor \frac{K}{2}\rfloor}\sum_{(s,m)}\P_{\mu,\pi^{(s,m)}}(\hat{\pi}\neq \pi^{(s,m)})\geq C\enspace .$$
This, with the fact that, for all estimator $\hat{\pi}$, $$\sup_{\mu\in\Theta_{\bar{\Delta}}}\sup_{\pi\in(\mathcal{S}_{K})^{M}}\P_{\mu,\pi}(\hat{\pi}\neq \pi)\geq \frac{1}{M\lfloor \frac{K}{2}\rfloor}\sum_{(s,m)}\P_{\mu,\pi^{(s,m)}}(\hat{\pi}\neq \pi^{(s,m)})$$ concludes the proof of our statement in the regime where $\bar{\Delta}^{2}\leq c_{1}\log(KM)$.



















\subsubsection{Case $c_{1}\log(KM)\leq \bar{\Delta}^{2}\leq c_{2}\sqrt{\frac{p}{M}\log(KM)}$.}

We suppose that 
\begin{equation}\label{eq:constraint:delta_bar}
c_{1}\log(KM)\leq \bar{\Delta}^{2}\leq c_{2}\sqrt{\frac{p}{M}\log(KM)}\enspace ,
\end{equation}
with $c_{1}$ defined just above and $c_{2}$ that we will choose small enough. Given $\rho$ a probability distribution on $(\R^{p})^{K}$ and a $M$-tuple of permutations $\pi\in(\mathcal{S}_{K})^{M}$, we define the probability distribution on $\R^{K\times M\times p}$ by $$\P_{\rho,\pi}(A)=\int \P_{\mu,\pi}(A)d\rho(\mu)\enspace.$$ In this regime, we shall use the following lemma.

\begin{lem}\label{lem:reductionfano}
    We suppose that there exists a probability distribution $\rho$ on $(\R^{p})^{K}$ and $a>0$ such that $$\inf_{\hat{\pi}:\R^{K\times M\times p}\to (\mathcal{S}_{K})^{M}}\sup_{\pi\in(\mathcal{S}_{K})^{M}}\P_{\rho,\pi}(err(\hat{\pi}, \pi)\neq 0)-\rho(\R^{p}\setminus\Theta_{\bar{\Delta}})>a\enspace.$$
    Then, we have $$\inf_{\hat{\pi}:\R^{K\times M\times p}\to (\mathcal{S}_{K})^{M}}\sup_{\mu\in\Theta_{\Bar{\Delta}}}\sup_{\pi\in(\mathcal{S}_{K})^{M}}\P_{\mu,\pi}(err(\hat{\pi}, \pi)\neq 0)>a\enspace.$$
\end{lem}



We refer to Section \ref{prf:reductionfano} for a proof of this lemma. We will consider the following distribution on $(\R^{p})^{K}$. Define $\eps=2\sqrt{\frac{1}{p}}\bar{\Delta}$ and define $\rho$ the uniform distribution on the hypercube $\mathcal{E}=\{-\eps,\eps\}^{p\times K}$. We will use Fano's Lemma to lower bound $\inf_{\hat{\pi}:\R^{K\times M\times p}\to (\mathcal{S}_{K})^{M}}\sup_{\pi\in(\mathcal{S}_{K})^{M}}\P_{\rho,\pi}(err(\hat{\pi}, \pi)\neq 0)$. To do so, we need to find many $M$-tuple of permutations $\pi^{(1)},\ldots,\pi^{(\ell)}\in(\mathcal{S}_{K})^{M}$, with $\ell$ large, such that $KL(\P_{\rho,\pi^{(s)}},\P_{\rho,id})$ remains small for all $s\in [\ell]$. 

Given $m\in[M]$, $k< k'\in [K]$, we define $\pi^{(m,k,k')}$ the $M$-tuple of permutations that satisfies; for all $m'\neq m$, $\pi^{(m,k,k')}_{m'}=id$, and $\pi^{(m,k,k')}_{m}$ is the transposition $(k,k')$. We denote $V$ the set of all these $M$-tuple of permutation; $V=\{\pi^{(m,k,k')},\enspace m\in[M-1],\enspace k< k'\in [K]\}$. For a $M$-tuple of permutations $\pi\in V$, let us compute the quantity $KL(\P_{\rho,\pi},\P_{\rho,id})=\int\log (\frac{d\P_{\rho,\pi}}{d\P_{\rho,id}})d\P_{\rho,\pi}$. We refer to Section \ref{prf:calculcompliquéexactrecovery} for a proof of the next lemma. 


\begin{lem}\label{lem:calculcompliquéexactrecovery}
We suppose that  the numerical constant $c_2$ is small enough with respect to $c_1$, where both $c_1$ and $c_2$ arise in~\eqref{eq:constraint:delta_bar}. Then, there exists a numerical constant $c>0$ such that, for all $m,k,k'$ with $m\in [M]$, $k<k'\in [K]$, we have  
\[
KL(\P_{\rho,\pi},\P_{\rho,id})=\int\log (\frac{d\P_{\rho,\pi^{(m,k,k')}}}{d\P_{\rho,id}})d\P_{\rho,\pi^{(m,k,k')}}\leq cc_2^2\log(KM)\enspace . 
\]
\end{lem}


This inequality combined with Lemma \ref{lem:fano} applied to the set $V$ of all the $M$-tuple of permutations $\pi^{(m,k,k')}$ leads to $$\inf_{\hat{\pi}:\R^{^{K\times M\times p}}\to (\mathcal{S}_{K})^{M}}\frac{1}{|V|}\sum_{\pi\in V}\P_{\rho,\pi}[\hat{\pi}\neq \pi]\geq 1-\frac{1+cc_{2}^{2}\log(Km)}{\log(|V|)}\enspace.$$ For all estimator $\hat{\pi}:\R^{K\times M\times p}\to (\mathcal{S}_{K})^{M}$, let us define $\psi_{\hat{\pi}}\in \mathcal{S}_K$ the permutation on $[K]$ such that $\psi_{\hat{\pi}}\circ \hat{\pi}_M=id$. We remark that, for any $\pi\in V$, having $err(\hat{\pi}, \pi)=0$ is equivalent to having $\pi=\psi_{\hat{\pi}}$. Thus, $$\inf_{\hat{\pi}:\R^{K\times M\times p}\to (\mathcal{S}_{K})^{M}}\frac{1}{|V|}\sum_{\pi\in V}\P_{\rho,\pi}[err(\hat{\pi}, \pi)\neq 0]\geq 1-\frac{1+cc_{2}^{2}\log(Km)}{\log(|V|)}\enspace,$$
and so
$$\inf_{\hat{\pi}:\R^{K\times M\times p}\to (\mathcal{S}_{K})^{M}}\sup_{\pi\in(\mathcal{S}_{K})^{M}}\P_{\pi,\rho}[err(\hat{\pi}, \pi)\neq 0]\geq 1-\frac{1+cc_{2}^{2}\log(Km)}{\log(|V|)}\enspace.$$
Finally, the fact that $\log(|V|)= \log(K(K-1)M/2)$ implies that, if we choose $c_{2}$ small enough and if $K_{0}$ is large enough, we will dispose of a numerical constant $b>0$ satisfying $$\inf_{\hat{\pi}:\R^{K\times M\times p}\to (\mathcal{S}_{K})^{M}}\frac{1}{|V|}\sum_{\pi\in V}\P_{\rho,\pi}[err(\hat{\pi}, \pi)\neq 0]\geq b\enspace.$$ In order to apply Lemma \ref{lem:reduction}, it remains to control $\rho(\pa{\R^{p}}^K\setminus \Theta_{\bar{\Delta}})$. From Lemma 14 of \cite{Collier16}, we get that $\rho(\pa{\R^{p}}^K\setminus \Theta_{\Bar{\Delta}})\leq \frac{K(K-1)}{2}e^{\frac{-p}{8}}$. Moreover, $c_{1}\log(KM)\leq c_{2}\sqrt{\frac{p}{M}\log(KM)}$ implies $p\geq \frac{c_{1}^{2}}{c_{2}^{2}}\log(KM)$. Thus, $\rho(\R^{p}\setminus \Theta_{\Bar{\Delta}})\leq \frac{b}{2}$, provided $c_{2}$ is small enough compared to $c_{1}$. Hence, Lemma \ref{lem:reductionfano} gives $$\inf_{\hat{\pi}:\R^{K\times M\times p}\to (\mathcal{S}_{K})^{M}}\sup_{\pi\in(\mathcal{S}_{K})^{M}}\P_{\rho,\pi}[\hat{\pi}\neq \pi]\geq \frac{b}{2}\enspace.$$ This concludes the proof of the first point of Theorem \ref{thm:lowerboundinformationalfeature} (perfect recovery).







\subsubsection{Proof of Lemma \ref{lem:calculcompliquéexactrecovery}}\label{prf:calculcompliquéexactrecovery}



By symmetry, it is sufficient to bound the Kullback-Leibler discrepansy for $\pi=\pi^{(1,1,2)}=\pa{(1,2), id,\ldots,id}$. In the following, we denote $\rho'$ the probability distribution on $(\R)^{p\times K}$ that satisfies; if $(\mu_{1},\ldots,\mu_{K})\sim \rho'$, all the $\mu_{i}$'s are independent, $\mu_{1}=\mu_{2}=0$ and all the other $\mu_{i}$'s are drawn uniformly on the set $\{\eps,-\eps\}^{p}$. 

First, we will compute the quantity \begin{equation}\label{eq:vraisemblance}
    \frac{d\P_{\rho,\pi}}{d\P_{\rho,id}}=\frac{\frac{d\P_{\rho,\pi}}{d\P_{\rho',\pi}}}{\frac{d\P_{\rho,id}}{d\P_{\rho',\pi}}}=\frac{\frac{d\P_{\rho,\pi}}{d\P_{\rho',\pi}}}{\frac{d\P_{\rho,id}}{d\P_{\rho',id}}}\enspace,
\end{equation} where the second equality comes from the fact that $\P_{\rho',id}=\P_{\rho',\pi}$. Given a probability law $\P$ on some Euclidean space, we denote $d\P$ the density of this law with respect to the Lebesgue measure on this space (when $\P$ is absolutely continuous with respect to the Lebesgue measure).  For the numerator in \eqref{eq:vraisemblance}, we have,
\begin{align*}
    \frac{d\P_{\rho,\pi}}{d\P_{\rho',\pi}}(Y)=&\frac{\E_{\rho}\cro{d\P_{\mu,\pi}(Y)}}{\E_{\rho'}\cro{d\P_{\mu,\pi}(Y)}}\\
    =&\frac{\E_{\rho}\cro{\prod_{k\in[1,K]}\prod_{m\in[M]}\exp\pa{-\frac{1}{2}\|Y^{(m)}_{\pi_{m}^{-1}(k)}-\mu_{k}\|^{2}}}}{\E_{\rho'}\cro{\prod_{k\in[1,K]}\prod_{m\in[M]}\exp\pa{-\frac{1}{2}\|Y^{(m)}_{\pi_{m}^{-1}(k)}-\mu_{k}\|^{2}}}}\\
    =&\frac{\E_{\rho}\cro{\prod_{d\in[1,p]}\prod_{k\in[K]}\prod_{m\in[M]}\exp\pa{-\frac{1}{2}\|X^{(m)}_{\pi_{m}^{-1}(k),d}-\mu_{k,d}\|^{2}}}}{\E_{\rho'}\cro{\prod_{d\in[1,p]}\prod_{k\in[K]}\prod_{m\in[M]}\exp\pa{-\frac{1}{2}\|Y^{(m)}_{\pi_{m}^{-1}(k),d}-\mu_{k,d}\|^{2}}}}\enspace.
\end{align*}
Using the independence of the $\mu_{k,d}$'s both for the law $\rho$ and $\rho'$ together with the fact that, when $k>3$, $\mu_{k,d}$ has the same law under $\rho$ and $\rho'$, we get that 
\begin{align*}
    \frac{d\P_{\rho,\pi}}{d\P_{\rho',\pi}}(Y)=&\prod_{d\in[p]}\prod_{k\in[K]}\frac{\E_{\rho}\cro{\prod_{m\in[M]}\exp\pa{-\frac{1}{2}(Y^{(m)}_{\pi_{m}^{-1}(k),d}-\mu_{k,d})^{2}}}}{\E_{\rho'}\cro{\prod_{m\in[M]}\exp\pa{-\frac{1}{2}(Y^{(m)}_{\pi_{m}^{-1}(k),d}-\mu_{k,d})^{2}}}}\\
    =&\prod_{d\in[p]}\prod_{k\in\{1,2\}}\frac{\E_{\rho}\cro{\prod_{m\in[M]}\exp\pa{-\frac{1}{2}(Y^{(m)}_{\pi_{m}^{-1}(k),d}-\mu_{k,d})^{2}}}}{\E_{\rho'}\cro{\prod_{m\in[M]}\exp\pa{-\frac{1}{2}(Y^{(m)}_{\pi_{m}^{-1}(k),d}-\mu_{k,d})^{2}}}}\\
    =&\prod_{d\in[p]}\prod_{k\in\{1,2\}}\E_{\rho}\cro{\prod_{m\in[M]}\exp{\pa{-\frac{1}{2}\pa{(Y^{(m)}_{\pi_{m}^{-1}(k),d}-\mu_{k,d})^{2}-(Y^{(m)}_{\pi_{k}^{-1}(k),d})^{2}}}}}\\
    =&\prod_{d\in[p]}\prod_{k\in\{1,2\}}\E_{\rho}\cro{\prod_{m\in[M]}\exp{\pa{Y^{(m)}_{\pi_{m}^{-1}(k),d}\mu_{k,d}-\frac{\eps^{2}}{2}}}}\\
    =&\prod_{d\in[p]}e^{\frac{-M\eps^{2}}{2}}\cosh\left[\eps \left(Y^{(1)}_{2,d}+ \sum_{m\in[2,M]} Y^{(m)}_{1,d} \right)\right]
    \cdot \prod_{d\in[p]}e^{\frac{-M\eps^{2}}{2}}\cosh\left[\eps \left(Y^{(1)}_{1,d}+ \sum_{m\in[2,M]} Y^{(m)}_{2,d} \right)\right]\enspace,\\
\end{align*}
where the third equality comes from the fact that, for all $d\in[1,p]$ and when $k\leq2$, $\mu_{k,d}=0$ almost surely under the law $\rho'$. Similarly, we get that 
\begin{align*}
    \frac{d\P_{\rho,id}}{d\P_{\rho',id}}(Y)=&\prod_{d\in[p]}e^{\frac{-M\eps^{2}}{2}}\cosh{\pa{\sum_{m\in[M]}\eps Y^{(m)}_{1,d}}}\cdot  \prod_{d\in[p]}e^{\frac{-M\eps^{2}}{2}}\cosh{\pa{\sum_{m\in[M]}\eps Y^{(m)}_{2,d}}}\enspace.\\
\end{align*}
Combining these two equalities in \eqref{eq:vraisemblance} leads to 
$$\frac{d\P_{\rho,\pi}}{d\P_{\rho,id}}=\frac{\prod_{d\in[p]}\cosh{\pa{\eps\sum_{m\in[2,M]}Y^{(m)}_{1,d}+\eps Y^{(1)}_{2,d}}}\cosh{\pa{\eps\sum_{m\in[2,M]}Y^{(m)}_{2,d}+\eps Y^{(1)}_{1,d}}}}{\prod_{d\in[p]}\cosh{\pa{\eps\sum_{m\in[M]}Y^{(m)}_{1,d}}}\cosh{\pa{\eps\sum_{m\in[M]}Y^{(m)}_{2,d}}}}\enspace.$$
We denote $\phi$ the standard Gaussian density $\phi(x)=\frac{1}{\sqrt{2\pi}}e^{\frac{-x^{2}}{2}}$. Under the law $\P_{\rho,\pi}$, conditionally on $\mu\sim\rho$, we have that: 
\begin{itemize}
    \item $\sum_{m\in[M]}Y^{(M)}_{1,d}\sim \mathcal{N}((M-1)\mu_{1,d}+\mu_{2,d},M)$,
    \item $\sum_{M\in[M]}Y^{(M)}_{2,d}\sim \mathcal{N}((M-1)\mu_{2,d}+\mu_{1,d},M)$,
    \item $\sum_{m\in[2,M]}Y^{(m)}_{1,d}+Y^{(1)}_{2,d}\sim \mathcal{N}(M\mu_{1,d},M)$,
    \item $\sum_{m\in[2,M]}Y^{(m)}_{2,d}+Y^{(1)}_{1,d}\sim \mathcal{N}(M\mu_{2,d},M)$.
\end{itemize}
This leads to 
\begin{align*}
    KL(\P_{\rho, \pi}, \P_{\rho,id})=&\E_{\rho,\pi}\cro{\log\pa{\frac{d\P_{\rho,\pi}}{d\P_{\rho,id}}}}\\
    =&\sum_{d\in[p]}\E_{\rho,\pi}\cro{\log\cosh\pa{\eps\sum_{m\in[2,M]}Y^{(m)}_{2,d}+\eps Y^{(1)}_{1,d}}}\\
    &+\sum_{d\in[p]}\E_{\rho,\pi}\cro{\log\cosh\pa{\eps\sum_{m\in[2,M]}Y^{(m)}_{1,d}+\eps Y^{(1)}_{2,d}}}\\
    &-\sum_{d\in[p]}\E_{\rho,\pi}\cro{\log\cosh\pa{\eps\sum_{m\in[M]}Y^{(m)}_{1,d}}}\\
    &-\sum_{d\in[p]}\E_{\rho,\pi}\cro{\log\cosh\pa{\eps\sum_{m\in[M]}Y^{(m)}_{2,d}}}\\
    =& 2p \E_{\rho,\pi}\cro{\log\cosh\pa{\eps \sum_{m\in[2,M]}Y^{(m)}_{1,1}+Y^{(1)}_{2,1}}}-2p \E_{\rho,\pi}\cro{\log\cosh\pa{\eps \sum_{m\in[M]}Y^{(m)}_{1,1}}}\\
    =&2p \E_{\rho}\cro{\int \log\cosh(\eps(M\mu_{1,1}+\sqrt{M}x))\phi(x)dx}\\
    &-2p \E_{\rho}\cro{\int \log\cosh(\eps((M-1)\mu_{1,1}+\mu_{2,1}+\sqrt{M}x))\phi(x)dx}\enspace.    
\end{align*}
First, let us upper-bound the term $$A:=\E_{\rho}\cro{\int \log\cosh(\eps(M\mu_{1,1}+\sqrt{M}x))\phi(x)dx}\enspace.$$ We denote $u=\eps\pa{ (M-1) \mu_{1,1}+\sqrt{M}x}$ and $h=\eps \mu_{1,1}$. Then, $A=\E_{\rho}\cro{\int \log\cosh(u+h)\phi(x)dx}\enspace.$ We will use the Taylor expansion of the function $\log\cosh$ around $u$. We compute the following derivatives: \begin{itemize}
    \item For all $x\in \R$, $\log\cosh'(x)=\tanh(x)$,
    \item For all $x\in\R$, $\log\cosh ''(x)=1-\tanh^{2}(x)$ which is bounded by $2$ in absolute value.
\end{itemize}
Hence, Taylor-Lagrange inequality implies \begin{equation}\label{eq:Taylor}
    |\log\cosh(x+y)- \log\cosh(x)- \tanh(x)y|\leq y^{2}, \enspace \forall (x,y)\in\R^{2}\enspace.
\end{equation}
Plugging this inequality leads to \begin{equation}\label{eq:Taylor_1}
    A=\E_{\rho}\cro{\int \log\cosh(u+h)\phi(x)dx}\leq \E_{\rho}\cro{\log\cosh(u)}+\E_{\rho}\cro{\int\tanh{(u)}h\phi(x)dx}+ \E_{\rho}(h^{2})\enspace.
\end{equation}

First, since $h^{2}=\eps^{4}$, we have $\E_{\rho}(h^{2})=\eps^{4}$. Now, we need to upper bound $\E_{\rho}\cro{\int\tanh{(u)}h\phi(x)dx}$. For any $y\in\R$, we have $\tanh'(y)=1-tanh^{2}(y)$ and $\tanh''(y)=-2\tanh(y)(1-\tanh(y)^{2})$, which is bounded by $4$ in absolute value. Hence, Taylor-Lagrange inequality taken at $0$ leads to $$ |\tanh(y)-y|\leq 2y^{2}\enspace, \forall y\in\R\enspace.$$

This leads us to $\E_{\rho}\cro{\int \tanh{(u)}h\phi(x)dx}\leq \E_{\rho}\cro{\int uh\phi(x)dx}+2\E_{\rho}\cro{\int u^{2}|h|\phi(x)dx}$. On the one hand, 
\begin{align*}
    \E_{\rho}\cro{\int uh\phi(x)dx}=&\eps^{2}\E_{\rho}\cro{\int((M-1)\mu_{1,1}+\sqrt{M}x)\mu_{1,1}\phi(x)dx}\\
    =&\eps^{2}\E_{\rho}\cro{(M-1)\mu_{1,1}^{2}}\\
    =&(M-1)\eps^{4}\enspace.    
\end{align*}
On the other hand, we have 
\begin{align*}
    \E_{\rho}[\int u^{2}|h|\phi(x)dx]=&\eps^{4}\E_{\rho}[\int((M-1)\mu_{1,1}+\sqrt{M}x)^{2}\phi(x)dx]\\
    =&\eps^{4}\pa{(M-1)^{2}\eps^{2}+M}\enspace.
\end{align*}
Plugging all these inequalities in \eqref{eq:Taylor_1} leads us to 
\begin{equation}\label{eq:KL_2}
   A\leq \E_{\rho}\cro{\log\cosh(u)}+(M-1)\eps^{4}+2\eps^{4}\pa{(M-1)^{2}\eps^{2}+M}+ \eps^{4}\enspace.
\end{equation}
Now, let us lower-bound the term $$B:=\E_{\rho}\cro{\int \log\cosh(\eps(m\mu_{1,1}+\mu_{2,1}+\sqrt{m+1}x))\phi(x)dx}=\E_{\rho}\cro{\int \log\cosh(u+h')\phi(x)dx}\enspace,$$
where we define $h'=\eps \mu_{2,1}$ which is independent of $u$. Using inequality \eqref{eq:Taylor} together with the independence of $u$ and $h'$ leads to $$\E_{\rho}\cro{\int \log\cosh(u+h')\phi(x)dx}\geq \E_{\rho}\cro{\log\cosh{u}}+\E_{\rho}\cro{\int \tanh{(u)}\phi(x)dx}\E_{\rho}\cro{h'}- \E_{\rho}\cro{h'^{2}}\enspace.$$
Since $\E_{\rho}\cro{h'}=0$ and $\E_{\rho}\cro{h'^{2}}=\eps^{4}$, we have \begin{equation}\label{eq:KL_1}
    \E_{\rho}\cro{\int \log\cosh(u+h')\phi(x)dx}\geq \E_{\rho}\cro{\log\cosh{u}}-\eps^{4}\enspace.
\end{equation} 
Hence, plugging inequalities \eqref{eq:KL_2} and \eqref{eq:KL_1} in the expression of $KL(\P_{\rho, \pi}, \P_{\rho,id})$ leads us to 
\begin{align*}
    KL(\P_{\rho, \pi}, \P_{\rho,id})=&2p(A-B)\leq 2\pa{2\eps^{4}+(M-1)\eps^{4}+2\eps^{4}((M-1)^{2}\eps^{2}+M)}\\
    \leq& c\pa{pM\eps^{4}\pa{1+M\eps^{2}}}\enspace,
\end{align*}
for some numerical constant $c$. Since $\eps^{2}=\frac{4}{p}\bar{\Delta}^{2}$, for some numerical constant $c$ that may differ, we have $$KL(\P_{\rho, \pi}, \P_{\rho,id})\leq c\pa{ \bar{\Delta}^{4}\frac{M}{p}(1+\frac{M}{p}\bar{\Delta}^{2})}\enspace.$$ 
The hypothesis $c_{1}\log(KM)\leq\bar{\Delta}^{2}\leq c_{2}\sqrt{\frac{p}{M}\log(KM)}$ gives us 
$$\bar{\Delta}^{4}\frac{M}{p}\leq c_{2}^{2}\log(Km)\enspace ,$$ and  $$\frac{M}{p}\bar{\Delta}^{2}=\frac{M}{p}\bar{\Delta}^{4}\frac{1}{\bar{\Delta}^{2}}\leq \frac{c_{2}^{2}\log(KM)}{c_{1}\log(KM)}\leq 1\enspace ,$$ 
provide that we chose $c_{2}\leq \sqrt{c_1}$. Thus, there exists a numerical constant $c$ such that for all $\pi\in V$, we have $$KL(\P_{\rho, \pi}, \P_{\rho,id})\leq c c_{2}^{2}\log(Km)\enspace.$$ 









\subsubsection{Proof of Lemma \ref{lem:reductionfano}}\label{prf:reductionfano}


Let us suppose that there exists a probability distribution $\rho$ on $\R^{K\times M\times p}$ and $a>0$ such that $$\inf_{\hat{\pi}:R^{K\times M\times p}\to (\mathcal{S}_{K})^{M}}\sup_{\pi\in(\mathcal{S}_{K})^{M}}\P_{\rho,\pi}(err(\hat{\pi}, \pi)\neq 0)-\rho(\pa{\R^{p}}^K\setminus\Theta_{\bar{\Delta}})\geq a\enspace.$$
Given an estimator $\hat{\pi}:\R^{K\times M\times p}\to (\mathcal{S}_{K})^{M} $, the previous hypothesis directly implies that there exists $\pi\in(\mathcal{S}_{K})^{M}$ such that $\P_{\rho,\pi}(err(\hat{\pi}, \pi)\neq 0)-\rho(\pa{\R^{p}}^K\setminus\Theta_{\bar{\Delta}})\geq a.$ 

By definition, $\P_{\rho,\pi}(err(\hat{\pi}, \pi)\neq 0)=\int \P_{\mu, \pi}(err(\hat{\pi}, \pi)\neq 0)d\rho(\mu).$ The quantity $\P_{\mu, \pi}(err(\hat{\pi}, \pi)\neq 0)$ being bounded by $1$, we have $\P_{\rho,\pi}(err(\hat{\pi}, \pi)\neq 0)\leq \int_{\Theta_{\bar{\Delta}}} \P_{\mu, \pi}(err(\hat{\pi}, \pi)\neq 0)d\rho(\mu)+\rho((\R^{p})^{K}\setminus \Theta_{\bar{\Delta}}).$ Therefore, $\int_{\Theta_{\bar{\Delta}}} \P_{\mu, \pi}(err(\hat{\pi}, \pi)\neq 0)d\rho(\mu)\geq a.$ This implies the existence of $\mu\in\Theta_{\bar{\Delta}}$ such that $\P_{\mu, \pi}(\hat{\pi}\neq \pi)\geq a$. This being true for all estimator $\hat{\pi}$, we get the following inequality that concludes the Lemma $$\inf_{\hat{\pi}:\R^{K\times M\times p}\to (\mathcal{S}_{K})^{M}}\sup_{\mu\in\Theta_{\bar{\Delta}}}\sup_{\pi\in(\mathcal{S}_{K})^{M}}\P_{\mu,\pi}(err(\hat{\pi}, \pi)\neq 0)\geq a\enspace.$$









\subsection{Proof of Theorem \ref{thm:lowerboundinformationalfeature}; Partial Recovery}
\label{prf:lowerboundpartial}

In this section, we prove the second point of Theorem \ref{thm:lowerboundinformationalfeature}. Let us suppose that $p\geq c \log(K)$ and $K\geq K_{0}$, with $c$ and $K_{0}$ two numerical constants that we will choose large enough later. Without loss of generality, we suppose throughout this proof that $\sigma=1$.

To prove our result, we will apply the following lemma that we prove in Section \ref{prf:numberpermutations} together with a reduction lemma.

\begin{lem}\label{lem:numberpermutations}
    Suppose that $K\geq K_0$ where $K_0$ is a numerical constant large enough. There exists $V$ a set of $M$-tuple of permutations such that the following properties hold.
    \begin{itemize}
        \item For all $\pi\in V$ and $M\leq \lceil \frac{M}{2}\rceil$, $\pi_{m}=id$,
        \item There exists a numerical constant $a$ such that for any two different $M$-tuple of permutations $\pi$ and $\pi'$ in $V$, $\frac{1}{MK}\sum_{m=1}^{M}\sum_{k=1}^{K}\1_{\pi'_{m}(k)\neq \pi_{m}(k)}\geq a$,
        \item There exists a numerical constant $c$ such that $\log(|S|)\geq cMK\log(K)$.
    \end{itemize}
\end{lem}

In the following, we suppose that $K_{0}\geq 4$ and we recall that we consider $K\geq K_0$. Here is the reduction lemma that we will apply in this proof. This lemma plays the same role in this proof as does Lemma \ref{lem:reductionfano} in Section \ref{prf:lowerboundexact}.

\begin{lem}\label{lem:reductionfano2}
    Suppose that there exists a probability distribution $\rho$ on $(\R^{p})^K$ and $C>0$ satisfying $$\inf_{\hat{\pi}:\R^{K\times M\times p}\to (\mathcal{S}_{K})^{M}}\sup_{\pi\in(\mathcal{S}_{K})^{M}}\E_{\rho,\pi}\cro{err(\hat{\pi},\pi)}-\rho((\R^{p})^{K}\setminus \Theta_{\bar{\Delta}})\geq C\enspace.$$ Then, we have $$\inf_{\hat{\pi}:\R^{K\times M\times p}\to (\mathcal{S}_{K})^{M}}\sup_{\mu\in\Theta_{\bar{\Delta}}}\sup_{\pi\in(\mathcal{S}_{K})^{M}}\E_{\mu,\pi}\cro{err(\hat{\pi},\pi)}\geq C\enspace.$$
\end{lem}

We will also need the following lemma which is a consequence of Fano's lemma. We refer to Section \ref{sec:prfFano2} for its proof.

\begin{lem}\label{lem:Fano2}
    Let $\rho$ be a probability distribution on $(\R^{p})^{K}$. For any finite set $A$ of $(\mathcal{S}_{K})^{M}$, we have the following inequality $$\inf_{\hat{\pi}:\R^{K\times M\times p}\to (\mathcal{S}_{K})^{M}}\frac{2}{|A|}\sum_{\pi\in A}\E_{\rho,\pi}\cro{err(\hat{\pi},\pi)}\geq \min_{\pi\neq \pi'\in A}err(\pi,\pi')\pa{1-\frac{1+\frac{1}{|A|}\sup_{\pi\in A}KL(\P_{\rho,\pi},\P_{\rho,id})}{\log(|A|)}}\enspace.$$
\end{lem}
As in Section \ref{prf:lowerboundexact}, we distinguish two cases. In the first one, we suppose that there exists a constant $c_{1}$ that we will choose small enough such that $\bar{\Delta}^{2}\leq c_{1}\log(K)$. In the second one, we will suppose that $c_{1}\log(K)\leq \bar{\Delta}^{2}\leq c_{2}\sqrt{\frac{p}{M}\log(K)}$, for $c_{2}$ a numerical constant that we will also choose small enough.



\subsection{Case $\bar{\Delta}^{2}\leq c_{1}\log(K)$}


In this section, we suppose that $\bar{\Delta}^{2}\leq c_{1}\log(K)$. We suppose that the constant $c$ such that $p\geq c\log(K)$ is large enough for having $\frac{p}{4}\log(2)\geq \log(K)$. Our choice of the centers $\mu_{1},\ldots, \mu_{K}$ relies on the following lemma, proved in Section \ref{sec:prfchoicepoints}.

\begin{lem}\label{lem:choicepoints}
    If $\frac{p}{4}\log(2)\geq \log(K)$, there exists $\mu_{1},\ldots ,\mu_{K}$ in $\R^{p}$ such that $\frac{1}{2}\min_{k\neq l}\|\mu_{k}-\mu_{l}\|^2\geq \bar{\Delta}^2$ and $\frac{1}{2}\max_{k\neq l}\|\mu_{k}-\mu_{l}\|^2\leq 4\bar{\Delta}^2$.
\end{lem}



We consider $\mu=(\mu_{1},\ldots ,\mu_{K})$ in $(\R^{p})^{K}$ that satisfies the conditions of this lemma. Given $\pi$ taken in the set $V$ defined in Lemma \ref{lem:numberpermutations}, let us compute $KL(\P_{\mu,\pi},\P_{\mu,id})$. We denote $\P_{\mu,\pi;k,m}$ the marginal distribution of $Y_{k}^{(m)}$ under the joint law $\P_{\mu,\pi}$. By independance of all the features, we have that $$KL(\P_{\mu,\pi},\P_{\mu,id})=\sum_{k=1}^{K}\sum_{m=1}^{M}KL(\P_{\mu,\pi;k,m},\P_{\mu,id;k,m})\enspace.$$ Given $k\in[K]$ and $m\in[M]$, $KL(\P_{\mu,\pi;k,m},\P_{\mu,id;k,m})=\frac{\|\mu_{k}-\mu_{\pi_{m}(k)}\|^{2}}{2}$. Hence, we have $$KL(\P_{\mu,\pi},\P_{\mu,id})\leq 4KM \bar{\Delta}^{2}\leq 4c_{1} KM\log(K)\enspace.$$ Combining this with Lemma \ref{lem:Fano2} and Lemma \ref{lem:numberpermutations} leads us to $$\inf_{\hat{\pi}:\R^{K\times M\times p}\to (\mathcal{S}_{K})^{M}}\frac{2}{|V|}\sum_{\pi\in V}\E_{\mu,\pi}\cro{err(\hat{\pi},\pi)}\geq a\pa{1-\frac{1+2c_{1}^{2}KM\log(K)}{cKM\log(K)}}\enspace,$$ where $a$ and $c$ are positive numerical constants. The quantity $a\pa{1-\frac{1+2c_{1}^{2}KM\log(K)}{cM\log(K)}}$ being larger than $\frac{a}{2}$ if $c_{1}$ is small enough and $K_{0}$ large enough, we conclude that there exists a constant $C$ such that $$\inf_{\hat{\pi}:\R^{K\times M\times p}\to(\mathcal{S}_{K})^{M}}\sup_{\mu\in\Theta_{\bar{\Delta}}}\sup_{\pi\in(\mathcal{S}_{K})^{M}}\E_{\mu,\pi}(err(\hat{\pi},\pi))\geq C\enspace.$$ 




\subsection{Case $c_{1}\log(K)\leq \bar{\Delta}^{2}\leq c_{2}\sqrt{\frac{p}{M}\log(K)}$}


In this section, we suppose that $c_{1}\log(K)\leq \bar{\Delta}^{2}\leq c_{2}\sqrt{\frac{p}{M}\log(K)}$ with $c_{2}$ a numerical constant that we will suppose small enough compared $c_1$ --$c_1$ now being considered as fixed. We still suppose that $K\geq K_0$, for $K_0$ a large enough numerical constant. As in Section \ref{prf:lowerboundexact}, we denote $\rho$ the uniform distribution on $\mathcal{E}=\{\eps, -\eps\}^{pK}$, where $\eps=2\sqrt{\frac{1}{p}}\bar{\Delta}$. 


\begin{lem}\label{lem:calculcompliquépartialrecovery}
We suppose that $c_2$ is small with respect to $c_1$ and that $c_{1}\log(K)\leq \bar{\Delta}^{2}\leq c_{2}\sqrt{\frac{p}{M}\log(K)}$. Then, there exists a numerical constant $c>0$ such that, for all $\pi\in V$, we have $$KL\pa{\P_{\rho, \pi},\P_{\rho,id}}\leq cc_2^2KM\log(K)$$
\end{lem}



We refer to Section \ref{prf:calculcompliquépartialrecovery} for a proof of this lemma. Combining Lemma \ref{lem:calculcompliquépartialrecovery} and Lemma \ref{lem:Fano2} implies that 
$$\inf_{\hat{\pi}:\R^{K\times M\times p}\to (\mathcal{S}_{K})^{M}}\frac{2}{|V|}\sum_{\pi\in V}\E_{\rho,\pi}\cro{err(\hat{\pi},\pi)}\geq \min_{\pi\neq \pi'\in V}err(\pi,\pi')\pa{1-\frac{1+c c_{2}^{2}KM\log(K)}{c'Km\log(K)}}\enspace,$$ 
where $c$ and $c'$ are two numerical constants. Given $\pi\neq \pi'\in V$, for $m\in[1,\lceil \frac{M}{2}\rceil]$, $\pi_{m}=\pi'_{m}$. Let $\psi$ be a permutation of $[K]$. Then, for $k\in[K]$, if $\psi(k)\neq k$, we get $\sum_{m=1}^{M}\1_{\psi(\pi_{m}(k))\neq \pi'_{m}(k)}\geq \lceil M/2\rceil \geq \sum_{m=1}^{M}\1_{\pi_{m}(k)\neq \pi'_{m}(k)}$. Hence, from the definition \eqref{eq:errorperm}, we have $err(\pi,\pi')=\frac{1}{MK}\sum_{i=1}^{K}\sum_{j=1}^{m}\1_{\pi_{j}(i)\neq \pi'_{j}(i)}$. From the definition of $V$ in Lemma \ref{lem:numberpermutations}, we deduce that $err(\pi,\pi')\geq a$, where $a$ is a numerical constant. Hence, $$\inf_{\hat{\pi}:\R^{K\times M\times p}\to (\mathcal{S}_{K})^{M}}\frac{2}{|V|}\sum_{\pi\in V}\E_{\rho,\pi}\cro{err(\hat{\pi},\pi)}\geq a\pa{1-\frac{1+cc_{2}^{2}Km\log(K)}{c'KM\log(K)}}\enspace.$$

This last quantity is larger than $\frac{a}{2}$ provided $c_{2}$ is small enough and $K_0$ large enough. We can conclude using Lemma \ref{lem:reductionfano2} together with the fact that $\rho(\pa{\R^{p}}^K\setminus \theta_{\Delta})\leq \frac{K(K-1)}{2}e^{\frac{-p}{8}} \leq \frac{a}{4}$ provided the constant $c$ such that $p\geq c\log(K)$ is large enough. We refer to Lemma 14 of \cite{Collier16} for the inequality $\rho(\R^{p}\setminus \theta_{\Delta})\leq \frac{K(K-1)}{2}e^{\frac{-p}{8}}$.







\subsection{Proof of Lemma \ref{lem:calculcompliquépartialrecovery}}\label{prf:calculcompliquépartialrecovery}


For $\pi\in V$, let us compute $KL(\P_{\rho, \pi},\P_{\rho,id})$. We recall that $KL(\P_{\rho, \pi},\P_{\rho,id})=\int \log\pa{\frac{d\P_{\rho,G}}{d\P_{\rho,\overline{G}}}}d\P_{\rho,G}$. We write $\P_{0,\pi}$, or equivalently $\P_{0,id}$, the distribution of $Y\in \R^{p\times [K]\times [M]}$ when $\mu_{1}=\ldots=\mu_{K}=0$ almost surely. Under this distribution, the entries of $Y$ are drawn independently according $\cN\pa{0,I_p}$. First, we will compute the quantity 
\begin{equation}\label{eq:vraisemblancepartial}
    \frac{d\P_{\rho,\pi}}{d\P_{\rho,id}}=\frac{\frac{d\P_{\rho,\pi}}{d\P_{0,\pi}}}{\frac{d\P_{\rho,id}}{d\P_{0,\pi}}}=\frac{\frac{d\P_{\rho,\pi}}{d\P_{0,\pi}}}{\frac{d\P_{\rho,id}}{d\P_{0,id}}}\enspace,
\end{equation} 
where the second equality comes from the fact that $\P_{0,\pi}=\P_{0,id}$. Given a probability distribution  $\P$ on some Euclidean space, which is absolutely continuous with respect to the Lebesgue measure, we write $d\P$ for the density of this distribution with respect to the Lebesgue measure.
  For the numerator in \eqref{eq:vraisemblancepartial}, we have
\begin{align*}
    \frac{d\P_{\rho,\pi}}{d\P_{0,\pi}}(Y)=&\frac{\E_{\rho}\cro{d\P_{\mu,\pi}(Y)}}{\E_{0}\cro{d\P_{\mu,\pi}(Y)}}\\
    =&\frac{\E_{\rho}\cro{\prod_{k\in[K]}\prod_{m\in [M]}\exp\pa{-\frac{1}{2}\|Y_{k}^{(m)}-\mu_{\pi_m(k)}\|^{2}}}}{\E_{0}\cro{\prod_{k\in[K]}\prod_{m\in [M]}\exp\pa{-\frac{1}{2}\|Y_{k}^{(m)}-\mu_{\pi_m(k)}\|^{2}}}}\\
    =&\frac{\E_{\rho}\cro{\prod_{d\in[p]}\prod_{k\in[K]}\prod_{m\in [M]}\exp\pa{-\frac{1}{2}\pa{Y_{k,d}^{(m)}-\mu_{\pi_m(k),d}}^{2}}}}{\prod_{d\in[p]}\prod_{k\in[K]}\prod_{m\in [M]}\exp\pa{-\frac{1}{2}\pa{Y_{k,d}^{(m)}}^2}}\enspace.
\end{align*}
Using the independence of the $\mu_{k,d}$'s under the law $\rho$, we get that 
\begin{align*}
     \frac{d\P_{\rho,\pi}}{d\P_{0,\pi}}(Y)=&\prod_{d\in[p]}\prod_{k\in[K]}\frac{\E_{\rho}\cro{\prod_{m\in [M]}\exp\pa{-\frac{1}{2}\pa{Y_{\pi^{-1}(k),d}^{(m)}-\mu_{k,d}}^{2}}}}{\prod_{m\in [M]}\exp\pa{-\frac{1}{2}\pa{Y_{\pi^{-1}(k),d}^{(m)}}^2}}\\
    =&\prod_{d\in[p]}\prod_{k\in[K]}\E_{\rho}\cro{\prod_{m\in [M]}\exp{\pa{-\frac{1}{2}\pa{(Y_{\pi^{-1}(k),d}^{(m)}-\mu_{k,d})^{2}-(Y_{\pi^{-1}(k),d}^{(m)})^{2}}}}}\\
    =&\prod_{d\in[p]}\prod_{k\in[K]}\E_{\rho}\cro{\prod_{m\in [M]}\exp{\pa{Y_{\pi^{-1}(k),d}^{(m)}\mu_{k,d}-\frac{\eps^{2}}{2}}}}\\
    =&\prod_{d\in[p]}\prod_{k\in[K]}e^{\frac{-M\eps^{2}}{2}}\cosh{\pa{\sum_{m\in [M]}\eps Y_{\pi^{-1}(k),d}^{(m)}}}\enspace.
\end{align*}
Similarly, we have
\begin{equation*}
    \frac{d\P_{\rho,id}}{d\P_{0,id}}(Y)=\prod_{d\in[p]}\prod_{k\in[K]}e^{\frac{-M\eps^{2}}{2}}\cosh{\pa{\sum_{m\in [M]}\eps Y_{k,d}^{(m)}}}\enspace.
\end{equation*}
Combining these two equalities in \eqref{eq:vraisemblancepartial}, we end up with
\begin{equation}\label{eq:vraisemblance2partial}
    \frac{d\P_{\rho,\pi}}{d\P_{\rho,id}}(Y)=\prod_{d=1}^{p}\prod_{k=1}^{K}\frac{\cosh{\pa{\sum_{m\in [M]}\eps Y_{\pi_m^{-1}(k), d}^{(m)}}}}{\cosh{\pa{\sum_{m\in [M]}\eps Y_{k,d}^{(m)}}}}\enspace.
\end{equation}
We denote $\phi$ the standard Gaussian density $\phi(x)=\frac{1}{\sqrt{2\pi}}e^{\frac{-x^{2}}{2}}$. Under the law $\P_{\rho, \pi}$, conditionally on $\mu_{1},\ldots \mu_{K}\sim\rho$, we have that: 
\begin{itemize}
    \item $\sum_{m\in [M]}\eps Y_{\pi_m^{-1}(k), d}^{(m)}\sim \mathcal{N}(M\mu_{k,d},M)$,
    \item $\sum_{m\in [M]}\eps Y_{k, d}^{(m)}\sim \mathcal{N}(\sum_{m\in[M]}\mu_{\pi_m(k),d}, M)$.
\end{itemize}
Plugging these two points, together with equality \eqref{eq:vraisemblance2partial}, in the definition of the Kullback-Leibler divergence leads to
\begin{align}\nonumber
    \frac{1}{p}KL(\P_{\rho, \pi},\P_{\rho,id})=&\sum_{k\in[K]}\E_{\rho}\cro{\int\log\cosh(\eps(M \mu_{k,1}+\sqrt{M}x))\phi(x)dx}\\
    &-\sum_{k\in[K]}\E_{\rho}\cro{\int\log\cosh(\eps(\sum_{m\in [M]} \mu_{\pi_{m}(k),1}+\sqrt{M}x))\phi(x)dx}\enspace.\label{eq:KLpartial}
\end{align}
By symmetry, it is sufficient to upper-bound the term corresponding to $k=1$ in the sum above. We call $S_1=S_{11}-S_{12}$ the corresponding terms with 
$S_1=S_{11}-S_{12}$, with 
\begin{align*}
    S_{11}&=\E_{\rho}\cro{\int\log\cosh(\eps(M \mu_{1,1}+\sqrt{M}x))\phi(x)dx},\\
     \text{and}\quad S_{12}&=\E_{\rho}\cro{\int\log\cosh(\eps(\sum_{m\in [M]} \mu_{\pi_{m}(1),1}+\sqrt{M}x))\phi(x)dx}.
\end{align*}
First, we upper-bound the term $S_{11}$. We will use the following inequality 
\begin{equation}\label{eq:Taylor2}
    \frac{x^{2}}{2}-\frac{x^4}{12}\leq  \log\cosh(x)\leq \frac{x^2}{2},\enspace \forall x\in\R\enspace.
\end{equation}
\begin{proof} [Proof of inequality \eqref{eq:Taylor2}]
    Let us first prove the upper-bound $\log\cosh(x)\leq \frac{x^{2}}{2}$. For $x\in\R$, $\cosh(x)=\sum_{t\in\N}\frac{x^{2t}}{(2t)!}\leq \sum_{t\in\N}\frac{x^{2t}}{t!2^{t}}=\exp\pa{\frac{t^{2}}{2}}$. Applying the logarithmic function leads us to $\log\cosh(x)\leq \frac{x^2}{2}$.

    Let us now prove the lower-bound $\log\cosh(x)\geq \frac{x^{2}}{2}-\frac{x^{4}}{12}$. To do so, we write, for $x\geq 0$, $f(x)=\tanh(x)$ and $g(x)=x-\frac{x^{3}}{3}$. We have $f'(x)=1-(f(x))^{2}$. Besides, $g'(x)=1-x^{2}\leq 1-(g(x))^{2}$. Together with the fact that $f(0)=g(0)=0$, this implies 
    $$f(x)\geq g(x),\enspace \forall x\geq 0\enspace.$$ 
    Integrating these function leads to $$\log\cosh(x)\geq \frac{x^{2}}{2}-\frac{x^{4}}{12},\enspace \forall x\geq 0\enspace.$$ By parity of these functions, this last inequality is satisfied for all $x\in\R$. 
\end{proof}
Inequality \eqref{eq:Taylor2}, together with the independence of $x$ and $\mu_{1,1}$, imply that 
\begin{equation}
    S_{11}\leq\frac{1}{2} \E_{\rho}\cro{\int(\eps(M\mu_{1,1}+\sqrt{M}x))^{2}\phi(x)dx}\leq \frac{1}{2}\eps^{2}\pa{M+M^{2}\eps^{2}}\enspace.
\end{equation}
We arrive at 
\begin{equation}\label{eq:S11}
    S_{11}\leq \frac{1}{2}M\eps^{2}(1+M \eps^{2})\enspace.
\end{equation}
Let us now lower-bound $S_{12}$. For $k\in [K]$, let us write $m_k=|\ac{m\in [M], \pi_m(1)=k}|$. Inequality \eqref{eq:Taylor2} induces
\begin{align*}
    S_{12}\geq&\frac{1}{2}\E_{\rho}\cro{\int\eps^2\bigg(\sum_{k\in[K]} m_{k}\mu_{k,1}+\sqrt{M}x\bigg)^{2}\phi(x)dx}\\
    &-\frac{1}{12}\E_{\rho}\cro{\int\eps^4\bigg(\sum_{k\in[K]} m_{k}\mu_{k,1}+\sqrt{M}x\bigg)^{4}\phi(x)dx}\\
    \geq & \frac{1}{2}\eps^{2}\pa{\sum_{k\in [K]}m_{k}^{2}\eps^{2}+M}
    -\frac{1}{12}\eps^{4}\E_{\rho}\left[\bigg(\sum_{k\in[K]}m_{k}\mu_{k,1}\bigg)^4\right]-\frac{1}{12}\eps^{4}3M^{2}\\
    &-\frac{1}{2}\eps^{4}M\E_{\rho}[(\sum_{k\in[K]}m_{k}\mu_{k,1})^2]\\
    \geq & \frac{1}{2}\eps^{2}\pa{\sum_{k\in [K]}m_{k}^{2}\eps^{2}+M}
    -\frac{1}{12}\eps^{8}\pa{\sum_{k\in[K]}m_{k}^{4}+6\pa{\sum_{k\in[K]}m_{k}^{2}}^{2}}-\frac{1}{4}\eps^{4}M^{2}\\
    &-\frac{1}{2}\eps^{6}M\sum_{k\in[K]}m_{k}^2\enspace.
\end{align*}
We end up with
\begin{equation}\label{eq:S12}
    S_{12}\geq \frac{1}{2}M\eps^{2}-\frac{1}{4}M^{2}\eps^{4}-\frac{1}{2}\eps^{6}M\sum_{k\in [K]}m_{k}^{2}-\frac{1}{12}\eps^{8}\pa{\sum_{k\in [K]}m_{k}^{4}+6\pa{\sum_{k\in [K]}m_{k}^{2}}^{2}}\enspace.
\end{equation}
Combining inequalities \eqref{eq:S11} and \eqref{eq:S12}, together with $M=\sum_{k\in [K]}m_{k}$, we get
\begin{align*}
    S_{1}\leq &\frac{1}{2}M\eps^{2}(1+M\eps^{2})-\frac{1}{2}M\eps^{2}
    +\frac{1}{4}M^{2}\eps^{4}+\frac{1}{2}\eps^{6}M\sum_{k\in [K]}m_{k}^{2}
    +\frac{1}{12}\eps^{8}\pa{\sum_{k\in[K]}m_{k}^{4}+6\pa{\sum_{k\in[K]}m_{k}^{2}}^{2}}\\
    \leq &\frac{3}{4}M^{2}\eps^{4}+\frac{7}{12}\eps^{8}M^{4}+\frac{1}{2}\eps^{6}M^{3}\\
    \leq &cM^2\eps^{4}\pa{1+\eps^{2}M+\eps^{4}M^2}\enspace,
\end{align*}
where $c$ is a numerical constant. Summing over $k\in[K]$ in \eqref{eq:KLpartial} leads to 
$$KL(\P_{\rho, \pi},\P_{\rho,id})\leq cpKM^2\eps^{4}\pa{1+\eps^{2}M+\eps^{4}M^2}\enspace.$$
From the definition of $\eps$, we deduce that $pM^2K\eps^{4}=\frac{16M^2K}{p}\Bar{\Delta}^{4}$. The hypothesis $\Bar{\Delta}^{2}\leq c_2\sqrt{\frac{p}{M}\log(K)}$ leads to $pMK\eps^{4}\leq 16c_{2}^{2}MK\log(K)$. Moreover, the hypothesis $c_{1}\log(K)\leq\Bar{\Delta}^{2}\leq c_2\sqrt{\frac{p}{M}\log(K)}$ implies $\eps^{2}M=\frac{4M}{p}\frac{\Bar{\Delta}^{4}}{\Bar{\Delta}^{2}}\leq 4\frac{c_{2}^{2}}{c_{1}}\leq 1$ provided that  $c_{2}$ is chosen small enough so that $c_2\leq \sqrt{c_1}$. Thus, there exists a numerical constant $c>0$ such that, when $c_2$ is small enough with respect to $c_1$, 
$$KL(\P_{\rho, \pi},\P_{\rho,id})\leq cc_{2}^2MK\log(K)\enspace.$$
This concludes the proof of the lemma.

\subsection{Proof of Lemma \ref{lem:numberpermutations}}\label{prf:numberpermutations}



To prove Lemma \ref{lem:numberpermutations}, we will use Lemma 16 from \cite{Collier16} that we recall here.
\begin{lem}
    For any $K\geq 4$. There exists $\psi^{(1)},\ldots ,\psi^{(\ell)}\in\mathcal{S}_{K}$ such that the following points hold: \begin{enumerate}
        \item $\ell\geq (\frac{K}{24})^{\frac{K}{6}}$, 
        \item For any $t\neq t'\in[\ell]$, $\frac{1}{K}\sum_{k\in[K]}\1_{\psi^{(t)}(k)\neq \psi^{(t')}(k)}\geq \frac{3}{8}$.
    \end{enumerate}
\end{lem}
If $M\leq 3$, we simply define $V$ of size $\ell$ made of $\pi$'s of the form $\pi_1=\pi_2=id$ and $\pi_3= \psi^{(l)}$ for some $l=1,\ldots, \ell$. Obviously, this set $V$ satisfies the desired properties of Lemma~\ref{lem:numberpermutations}. 


Let us now consider the general case where $M\geq 4$. We construct $V$ as follows. Denote $\overline{V}$ the subset of $(\mathcal{S}_{K})^{M}$ made from the $M$-tuples $\pi$ satisfying the two conditions; \begin{enumerate}
    \item if $m\leq \lceil \frac{M}{2}\rceil$, $\pi_{m}=id$;
    \item if $m> \lceil \frac{M}{2}\rceil$, $\pi_{m}$ is one of the $\psi^{(1)},\ldots ,\psi^{(\ell)}$. 
\end{enumerate}
We take for $V$ a maximal family in $\overline{V}$ such that for $\pi$ and $\pi'$ in $V$, there are at least $\frac{M}{4}$ index such that $\pi_{m}\neq \pi'_{m}$. Since for $t\neq t'\in[\ell]$, $\frac{1}{K}\sum_{k\in[K]}\1_{\psi^{(t)}(k)\neq \psi^{(t')}(k)}\geq \frac{3}{8}$, we have that, for $\pi\neq\pi'\in V$, $\frac{1}{KM}\sum_{k\in [K]}\sum_{m\in [M]}\1\ac{\pi_m(k)\neq \pi'_m(k)}\geq \frac{3}{32}.$

It remains to lower-bound the cardinality of $V$. First, we know that $|\overline{V}|= \ell^{\lfloor\frac{M}{2}\rfloor}$. For $\pi\in V$, denote by $B_{\pi}$ the subset of $\overline{V}$ made from all the $M$-tuple $\pi'\in |\overline{V}|$ that have less than $\frac{M}{4}$ indices such that $\pi_{m}\neq \pi'_{m}$. The definition of $V$ implies that $\overline{V}\subset \bigcup_{\pi\in V}B_{\pi}$. A fortiori, since the cardinality of $B_{\pi}$ is constant over $V$, we have $\ell^{\lfloor\frac{M}{2}\rfloor}\leq |V||B_{\pi}|$ for any $\pi \in V$. 

Let us upper-bound $|B_{\pi}|$ for some $\pi \in V$. Any $\pi'\in B_{\pi}$ has at least $\frac{M}{4}$ indice such that $\pi_{m}=\pi'_{m}$ among the indices $m> \lceil\frac{M}{2}\rceil$. Fixing $\lceil\frac{M}{4}\rceil$ indices where the permutations are equal, there are at most $\ell^{\frac{M}{4}}$ possibilities for choosing an element in $\overline{V}$ that is equal to $\pi'$ on these index. Thus, we get that $|B_{\pi}|\leq \binom{\lfloor\frac{M}{2}\rfloor}{\lceil \frac{M}{4}\rceil}\ell^{\frac{M}{4}}$. Since $\binom{x}{y}\leq (xe/y)^y$. 
 We end up with \begin{align*}
    \log|V|\geq& \log(\ell^{\lfloor\frac{m}{2}\rfloor})-\log|B_{\pi}|\\
    \geq&\lfloor\frac{M}{2}\rfloor\log(\ell)-\frac{M}{4}\log(\ell)-\lceil \frac{M}{4}\rceil \log(e\frac{\lfloor\frac{M}{2}\rfloor}{\lceil \frac{M}{4}\rceil})\\
    \geq& \frac{KM}{18}\log(\frac{K}{24})-\frac{KM}{24}\log(\frac{K}{24})-\lceil \frac{M}{4}\rceil \log(\frac{e\lfloor\frac{M}{2}\rfloor}{\lceil \frac{M}{4}\rceil})\enspace.
\end{align*} 
When $K_{0}$ is large enough, these inequalities imply $\log|V|\gtrsim MK\log(K)$ whenever $K\geq K_0$. This concludes the proof of the Lemma.

\subsection{Proof of Lemma \ref{lem:reductionfano2}}\label{prf:reductionfano2}



We suppose that there exists a probability distribution $\rho$ on $(\R^{p})^{K}$ and $C>0$ satisfying $$\inf_{\hat{\pi}:\R^{K\times M\times p}\to (\mathcal{S}_{K})^{M}}\sup_{\pi\in(\mathcal{S}_{K})^{M}}\E_{\rho,\pi}\cro{err(\hat{\pi},\pi)}-\rho((\R^{p})^{K}\setminus \Theta_{\bar{\Delta}})\geq C\enspace.$$
Given $\hat{\pi}:(\R^{p})^{KM}\to (\mathcal{S}_{K})^{M}$, there exists a $M$-tuple of permutation $\pi$ such that $\E_{\rho,\pi}\cro{err(\hat{\pi}\neq \pi)}-\rho((\R^{p})^{K}\setminus \Theta_{\bar{\Delta}})\geq C$. Since $\E_{\rho,\pi}\cro{err(\hat{\pi}, \pi)}=\int_{(\R^{p})^{K}}\E_{\mu,\pi}\cro{err(\hat{\pi}, \pi)}d\rho(\mu)$ and $\E_{\mu,\pi}\cro{err(\hat{\pi}, \pi)}$ is upper bounded by $1$, we end up with $\int_{\Theta_{\Delta}}\E_{\mu,\pi}\cro{err(\hat{\pi}, \pi)}d\rho(\mu)\geq C$.

This implies the existence of $\mu\in\Theta_{\Delta}$ such that $\E_{\mu,\pi}\cro{err(\hat{\pi}, \pi)}\geq C$. A fortiori, $$\sup_{\mu\in\Theta_{\Delta}}\sup_{\pi\in(\mathcal{S}_K)^M}\E_{\mu,\pi}\cro{err(\hat{\pi}, \pi)}\geq C\enspace .$$ 
This last inequality being true for all estimator $\hat{\pi}$, we get the desired result $$\inf_{\hat{\pi}:\R^{K\times M\times p}\to (\mathcal{S}_{K})^{M}}\sup_{\mu\in\Theta_{\bar{\Delta}}}\sup_{\pi\in(\mathcal{S}_{K})^{M}}\E_{\mu,\pi}\cro{err(\hat{\pi},\pi)}\geq C\enspace.$$





\subsection{Proof of Lemma \ref{lem:Fano2}}\label{sec:prfFano2}


Let $A$ be a subset of $(\mathcal{S}_K)^M$. Denote $\pi^{(1)},\ldots ,\pi^{(|A|)}$ the elements of $A$. Given any estimator $\hat{\pi}:\R^{K\times M\times p}\to (\mathcal{S}_{K})^{M}$, we denote $\hat{j}$ an index that minimises $err(\hat{\pi},\pi^{(j)})$.

For any $j\in[1,|A|]$, using the definition of $\hat{j}$ together with the fact that the function $err$ satisfies the triangular inequality, we have \begin{align*}
    min_{j\neq j'}err(\pi^{(j)},\pi^{(j')})\1_{\hat{j}\neq j}&\leq err(\pi^{(\hat{j})},\pi^{(j)})\\
    &\leq err(\hat{\pi},\pi^{(\hat{j})})+err(\hat{\pi},\pi^{(j)})\\
    &\leq 2err(\hat{\pi},\pi^{(j)})\enspace.
\end{align*}
Taking the expectation over this last inequality, we get, for $j\in[1,|A|]$, $$2\E_{\rho,\pi^{(j)}}\cro{err(\hat{\pi},\pi^{(j)})}\geq min_{\pi\neq \pi'\in A}err(\pi,\pi') \P_{\rho,\pi^{(j)}}\cro{\hat{j}\neq j}\enspace. $$ Summing over $\pi\in A$ leads to $$\frac{2}{|A|}\sum_{\pi\in A}\E_{\rho,\pi}\cro{err(\hat{\pi},\pi)}\geq \min_{\pi,\pi'\in A}err(\pi,\pi')\min_{\hat{\pi}:\R^{K\times M\times p}\to A}\frac{1}{|A|}\sum_{\pi\in A} \P_{\rho,\pi}\cro{\hat{\pi}\neq \pi}.$$Applying Lemma \ref{lem:fano}, we arrive at the desired conclusion $$\inf_{\hat{\pi}:\R^{K\times M\times p}\to (\mathcal{S}_{K})^{M}}\frac{2}{|A|}\sum_{\pi\in A}\E_{\rho,\pi}\cro{err(\hat{\pi},\pi)}\geq \min_{\pi,\pi'\in A}err(\pi,\pi')\pa{1-\frac{1+\frac{1}{|A|}\sum_{\pi\in A}KL(\P_{\rho,\pi},\P_{\rho,id})}{\log(|A|)}}\enspace.$$





\subsection{Proof of Lemma \ref{lem:choicepoints}}\label{sec:prfchoicepoints}


We suppose that $\frac{p}{4}\log(2)\geq \log(K)$ and we want to find vectors $\mu_{1},\ldots ,\mu_{K}$ in $\R^{p}$ such that $\frac{1}{2}\min_{k\neq l}\|\mu_{k}-\mu_{l}\|^2\geq \bar{\Delta}^2$ and $\frac{1}{2}\max_{k\neq l}\|\mu_{k}-\mu_{l}\|\leq 4\bar{\Delta}^2.$ Denote $\mathcal{H}=\bar{\Delta} \sqrt{\frac{2}{p}}\{-1,1\}^{p}$. There are $2^{p}$ elements in $\mathcal{H}$. Consider $H$ a maximal subset of $\mathcal{H}$ such that the following holds. For $\mu$ and $\mu'$ two distinct elements of $H$, there exist at least $p/4$ indices such that $\mu_{i}\neq \mu'_{i}$.

If $\mu$ and $\mu'$ are two distinct elements of $H$, we have from the definitions of $\mathcal{H}$ and $H$ that $$\bar{\Delta}^2\leq \frac{1}{2}\|\mu-\mu'\|^2\leq 4\bar{\Delta}^2\enspace.$$
It remains to lower-bound the cardinality of $H$ and to prove $|H|\geq K$. Given $\mu\in H$, denote $B_{\mu}$ the subset of $\mathcal{H}$ made of the elements $\mu'$ that have at least $\lfloor\frac{3p}{4}\rfloor$ indices such that $\mu_{i}=\mu'_{i}$. From the definition of $H$, we deduce that $\mathcal{H}\subseteq\bigcup_{\mu\in H}B_{\mu}$.

Let us upper-bound $|B_{\mu}|$ for any $\mu\in H$. Given a fixed set of index of cardinal $\lfloor\frac{3p}{4}\rfloor$, there are at most $2^{\frac{p}{4}}$ points in $\mathcal{H}$ that are equal to $\mu$ on these indices. Hence, the cardinal of $B_{\mu}$ is upper-bounded by $\binom{p}{\lfloor \frac{3p}{4}\rfloor}2^{\frac{p}{4}}$. 

Combining this with $\mathcal{H}\subseteq \bigcup_{\mu\in H}B_{\mu}$, we arrive at $\log(|H|)\geq p\log(2)-\log\binom{p}{\lfloor \frac{3p}{4}\rfloor}-\frac{p}{4}\log(2)$. We have  
\[
\log\binom{p}{\lfloor \frac{3p}{4}\rfloor}\leq \lceil \frac{p}{4}\rceil \log(ep/\lfloor \frac{3p}{4}\rfloor)\leq  \frac{p}{2}\log(2)
\ ,
\]
since $p\log(2)/4\geq \log(K)\geq \log(K_0)$ is large enough. Thus, we end up with $\log(|H|)\geq \frac{p}{4}\log(2)\geq \log(K)$. This concludes the proof. 








