\title{New types of convergence for unbounded star-shaped sets}
\author{Luisa F. Higueras-Montaño}
\address{Departamento de  Matem\'aticas,
Facultad de Ciencias, Universidad Nacional Aut\'onoma de M\'exico, 04510 Ciudad de M\'exico, M\'exico.}

