The next remark collects the basic properties of the radial distance. For each pair $A_1,A_2\in\mathcal{S}_{rc}^{d}$, the \textit{radial excess} of $A_1$ over $A_2$ is given by
$$
e_r(A_1,A_2):=\sup\left\{
d_r(a_1,A_2):a_1\in A_1
\right\}.
$$
It is worth noticing that the radial excess is not  symmetric with respect to $A_1$ and $A_2$, and that it takes values in $[0,\infty]$.  
\begin{remark}\label{rem:properties-d-r}
The following properties hold for all $A_1,A_2\in\mathcal{S}_{rc}^{d}$:
    \begin{itemize}
        \item [(P1)]$d_r(x,A_1)=\begin{cases}
            0 &\text{ if }x\in A_1,\\
            \|x\|-\rho_{A_1}\left(
            \theta_x\right) &\text{ if }x\notin A_1.
        \end{cases}$
        \item [(P2)] $d_r(x,A_1)=0$ if and only if $x\in A_1$. 
        \item [(P3)] $A_1=A_2$ if and only if  $d_r(x,A_1)=d_r(x,A_2)$ for all $x\in\mathbb{R}^d$.
        \item [(P4)] $d(x,A_1)\leq d_r(x,A_1)$ for all $x\in\mathbb{R}^d$.
        \item [(P5)] $e(A_1,A_2)\leq e_r(A_1,A_2)$.
        %[(P4)]  For $x\neq0$, $d_r(x,A)=\inf\left\{\|x-a\|:0,x,a\text{ are collinear and }  a\in A\right\}$.
        \item [(P6)] $e_r(A_1,A_2)=\sup_{x\in\mathbb{R}^d}\left\{d_r(x,A_2)-d_r(x,A_1)\right\}$.
    \end{itemize}
\end{remark}
\begin{proof}
(P1) If $x\in A_1$, then $x\in A_1\tilde{+}\varepsilon B_2^d$ for every $\varepsilon>0$. Thus $d_r(x,A_1)\leq\varepsilon$, and therefore $d_r(x,A_1)=0$.
If $x\notin A_1$, then $x\neq0$ and $\rho_{A_1}\left(\theta_x\right)<\|x\|$. Moreover, 
$$
x=\rho_{A_1}\left(\theta_x\right)\theta_x+\left(\|x\|-\rho_{A_1}\left(\theta_x\right)\right)\theta_x. 
$$
Thus $d_r(x,A_1)\leq\|x\|-\rho_{A_1}\left(\theta_x\right)$. To prove the reverse inequality, let $\alpha>0$ be such that $x\in A_1\tilde{+}\alpha B_2^d$. Clearly
$\|x\|\leq\rho_{A_1\tilde{+}\alpha B_2^d}\left(\theta_x\right)=\rho_{A_1}\left(\theta_x\right)+\alpha$. Hence 
$\alpha\geq\|x\|-\rho_{A_1}\left(\theta_x\right)$, which yields to 
$d_r(x,A_1)\geq\|x\|-\rho_{A_1}\left(\theta_x\right)$.

(P2) By (P1), we only need to check the only if part. Indeed, let $x\in\mathbb{R}^d$ be such that $d_r(x;A_1)=0$. Suppose by contradiction that $x\notin A_1$. Then 
$$
0=d_r(x,A)=\|x\|-\rho_{A_1}\left(\theta_x\right),
$$ 
and $\rho_{A_1}\left(\theta_x\right)=\|x\|$. Since $A_1\in\mathcal{S}_{rc}^{d}$,  we know that $x=\rho_{A_1}\left(\theta_x\right)\theta_x\in A_1$, which is a contradiction. Therefore $x\in A_1.$

(P3) Follows from (P2).

(P4) If $x\in A_1$, then $d_r(x,A_1)=d(x,A_1)=0$. If $x\notin A_1$, then $d(x,A)\leq\|x-\rho_{A_1}\left(\theta_x\right)\theta_x\|=d_r(x,A)$.

(P5) Follows from (P4).

(P6) Let us denote by $\lambda$ the supreme $\sup_{x\in\mathbb{R}^d}\left(d_r\left(x,A_2\right)-d_r\left(x,A_1\right)\right)$. By (P1), 
$d_r(a_1,A_2)=d_r(a_1,A_2)-d_r(a_1,A_1)\leq\lambda$ for all $a_1\in A_1$. Hence,
$e_r(A_1,A_2)\leq\lambda$. 
To prove the reverse inequality, notice that for every $x\in A_1$, we have that
$$
d_r(x,A_2)-d_r(x,A_1)=d_r(x,A_2)\leq e_r(A_1,A_2).
$$ 
Similarly, for every $x'\in A_2\setminus A_1$, 
$d_r(x',A_2)-d_r(x',A_1)=-d_r(x',A_1)\leq e_r(A_1,A_2)$. Finally, by (P1), for each $x''\notin A_1\cup A_2$, we have that
$$
d_r(x'',A_2)-d_r(x'',A_1)=\rho_{A_1}(\theta_{x''})-\rho_{A_2}(\theta_{x''}).
$$
Thus, if $\rho_{A_1}(\theta_{x''})\leq\rho_{A_2}(\theta_{x''})$, trivially $d_r(x'',A_2)-d_r(x'',A_1)\leq e_r(A_1,A_2)$. Otherwise, 
$
d_r\left(\rho_{A_1}\left(\theta_{x''}\right)\theta_{x''},A_2\right)=
\rho_{A_1}(\theta_{x''})-\rho_{A_2}(\theta_{x''})
$
and 
$$
d_r(x'',A_2)-d_r(x'',A_1)= d_r(\rho_{A_1}(\theta_{x''})\theta_{x''},A_2)\leq e_r(A_1,A_2).
$$ 
From this, it follows that $\lambda\leq e_r(A_1,A_2)$ as desired.
\end{proof}

