\begin{proposition}\label{prop:completez-sec-d_r}
    Let $(A_n)_n\subseteq\mathcal{S}_{rc}^d$ be a sequence. If $(d_r(\cdot,A_n))_n$ converges pointwise to $f:\mathbb{R}^d\rightarrow\mathbb{R}$, then $f=d_r(\cdot,A)$ for some $A\in\mathcal{S}_{rc}^d$.
\end{proposition}
\begin{proof}
    First, let us notice that for every $x\in\mathbb{R}^d$ with $f(x)>0$, there is $n_x\in\mathbb{N}$ such that $d_r(x,A_n)>0$ for all $n>n_x$. Hence, by (P1)-(P2), $x\notin A_n$ and $d_r(x,A_n)=\|x\|-\rho_{A_n}(\theta_x)$. Thus $\rho_{A_n}(\theta_x)<\infty$ for every $n>n_x$, and
    $$
    f(x)=\lim_{n}\left(\|x\|-\rho_{A_n}(\theta_x)\right),
    $$
    So, $\lim_{n}\rho_{A_n}(\theta_x)$ must be finite. Now, let $\alpha:\mathbb{S}^{d-1}\rightarrow[0,\infty]$ be given by
    \begin{equation*}
        \alpha(\theta)=\begin{cases}
        \lim_{n}\rho_{A_n}(\theta)&\text{ if }f(\lambda\theta)>0\text{ for some }\lambda>0,\\
        \infty&\text{ if }f(\lambda\theta)=0\text{ for all }\lambda\geq0.      \end{cases}
    \end{equation*}
    Observe that $\alpha$ is a well defined non-negative map. Consequently, there is $A\in\mathcal{S}_{rc}^d$ such that $\rho_A=\alpha$.
    Below, we shall prove that $f(\cdot)=d_r(\cdot,A)$.

    Suppose that $y\notin A$. Then
    $\rho_A(\theta_y)$ is finite, and $\rho_A(\theta_y)=\alpha(\theta_y)= \lim_{n}\rho_{A_n}(\theta_y)$. Moreover, by (P1), $d_r(y,A)=\|y\|-\lim_{n}\rho_{A_n}(\theta_y)>0$. Consequently, there is $n'_y\in\mathbb{N}$ such that $\rho_{A_n}(\theta_y)<\|y\|$ for all $n>n'_y$. Hence, from (P1) again, $d_r(y,A_n)=\|y\|-\rho_{A_n}(\theta_y)$ for all $n>n'_y$, and
    $$
    f(y)=\lim_{n}d_r(y,A_n)=\lim_{n}(\|y\|-\rho_{A_n}(\theta_y))=d_r(y,A).
    $$
    On the other hand, suppose that $y\in A$, i.e.,  $d_r(y,A)=0$. Notice that $f(y)=d_r(y,A)=0$ holds for $y=0$. For $y\neq 0$, we will consider separately two cases: $\liminf_n\rho_{A_n}(\theta_y)=\infty$ and $\liminf_n\rho_{A_n}(\theta_y)<\infty$. If $\liminf_n\rho_{A_n}(\theta_y)=\infty$, then $\lim_n\rho_{A_n}(\theta_y)=\infty$ and there is $N_y\in\mathbb{N}$ such that  $y\in A_n$
    %$\|y\|<\rho_{A_n}(\theta_y)$ 
    for all $n>N_y$. Hence $d_r(y,A_n)=0$ for all $n>N_y$, and  $f(y)=0$.

    If $R:=\liminf_n\rho_{A_n}(\theta_y)<\infty$, then, for every $k\in\mathbb{N}$, there is $n_k>k$ such that 
    $\rho_{A_{n_k}}(\theta_y)<R+1$. Thus $(R+2)\theta_y\notin A_{n_k}$ for all $k$, and by (P1), 
    $$
    d_r((R+2)\theta_y,A_{n_k})=R+2-\rho_{A_{n_k}}(\theta_y)>1.
    $$
    It then follows that $f((R+2)\theta_y)>1$, which implies that $\alpha(\theta_y)=\lim_n\rho_{A_n}(\theta_y)$. Moreover, since $y\in A$ and $\alpha(\theta_y)=\rho_A(\theta_y)$, then $\|y\|\leq\lim_n\rho_{A_n}(\theta_y)$.

    Now, observe that if the last inequality is strict, then there exist $N'_y\in\mathbb{N}$ such that  $\|y\|<\rho_{A_n}(\theta_y)$ for all $n>N'_y$. Consequently $y\in A_n$
    for all $n>N'_y$, and $f(y)=0$ as required. Otherwise, if $\|y\|=\lim_n\rho_{A_n}(\theta_y)$, then one of the following options holds: (1) there is $M_y\in\mathbb{N}$ such that $\|y\|>\rho_{A_n}(\theta_y)$ for all $n>M_y$, or  (2) there exists a subsequence $(A_{n_j})_j$ such that 
    $\|y\|\leq\rho_{A_{n_j}}(\theta_y)$ for all $j$. In the first case, $d_r(y,A_n)=\|y\|-\rho_{A_n}(\theta_y)$  for all $n>M_y$. Hence
    $$
    f(y)=\lim_{n}(\|y\|-\rho_{A_n}(\theta_y))=0.
    $$
    In the second case,
    $d_r(y,A_{n_j})=0$ for all $j$. Thus, $f(y)=\lim_{j}d_r(y,A_{n_j})=0$.
    This shows that $f(\cdot)=d_r(\cdot,A)$, as desired.
    %If $\|y\|>\rho_{A_n}(\theta_y)$ for every $n>M_y$, then,
 \end{proof}

Below, we show that the radial distance functional provides a new way to calculate the radial metric between bounded star bodies. 
% Below, we exhibit the relationship between the radial metric and the radial distance functional. 

\begin{proposition}\label{prop:caract-dHr-distanciaradial}
    For every $A_1,A_2\in\mathcal{S}_{rc}^{d}$ bounded, 
    \begin{equation}\label{eq:radialHauss-radialdist}
        \delta(A_1,A_2)=
    \sup_{x\in\mathbb{R}^d}\left|d_r(x,A_1)-d_r(x,A_2)\right|
    =\max\left\{e_r(A_1,A_2),e_r(A_2,A_1)\right\}.
    \end{equation}
\end{proposition}
\begin{proof} 
    Observe that the second equality follows directly from (P6). 
    Consequently, to prove the result, it is enough to show that
    $$
    \delta(A_1,A_2)=\max\left\{e_r(A_1,A_2),e_r(A_2,A_1)\right\}.
    $$
    Let us define $\eta:=\max\left\{
    e_r(A_1,A_2),e_r(A_2,A_1)\right\}$. Note that, by (P2), $\eta=0$ if and only if $A_1=A_2$, which is equivalent to $\delta(A_1,A_2)=0$. 

    For the case $\eta>0$, let $\alpha>0$ be such that $A_i\subseteq A_j\tilde{+}\alpha B_2^d$ for $i,j\in\{1,2\}$ with $i\neq j$. Then, 
    for every $x\in A_1$, we have that $x\in A_2\tilde{+}\alpha B_2^d$ and $d_r(x,A_2)\leq\alpha.$ Thus $e_r(A_1,A_2)\leq\alpha$. Analogously, it follows that $e_r(A_2,A_1)\leq\alpha$. Consequently
    $\eta\leq\alpha$, which implies that $\eta\leq\delta(A_1,A_2)$.

    To establish the reverse inequality, observe that $d_r(x,A_2)\leq\eta$ for all $x\in A_1$. Hence, $A_1\subseteq A_2\tilde{+}\eta B_2^d$. Similarly, $A_2\subseteq A_1\tilde{+}\eta B_2^d$. Therefore $\delta(A_1,A_2)\leq\eta$, completing the proof.
\end{proof}



\subsection{Inclusions into vector spaces of real-valued functions}
\label{sec:encajes-sin-estruct}
Let us denote by $F(\mathbb{R}^d,\mathbb{R})$ the vector space of functions $f:\mathbb{R}^d\rightarrow\mathbb{R}$, and 
by $C(\mathbb{R}^d,\mathbb{R})$ the linear subspace of continuous functions.
% Observe that for every $A\in\mathcal{S}_{rc}^{d}$, the radial distance to $A$ determines a real-valued map which is defined as 
% \begin{align*}
