Notice that from (P3) in Remark \ref{rem:properties-d-r}, it follows that the map 
%sending a star body $A\subseteq\mathbb{R}^d$ to $d_r(\cdot,A)$ is injective. As a consequence,
\begin{align}\label{eq:encaje1}
     \mathcal{S}_{rc}^{d}&\longrightarrow F(\mathbb{R}^d,\mathbb{R})\\
     A&\longrightarrow d_r(\cdot,A)\nonumber
\end{align}
is injective. In particular, the identification $A\leftrightarrow d_r(\cdot,A)$ allows us to consider the family of star bodies as a subset of $F(\mathbb{R}^d,\mathbb{R})$ consisting of non-negative functions. 

It is then natural to ask for the relationship between $\mathcal{S}_{rc}^{d}$ and $C(\mathbb{R}^d,\mathbb{R})$, under the identification (\ref{eq:encaje1}). We highlight that $d_r(\cdot,A)$ is not always continuous for $A\in\mathcal{S}_{rc}^{d}$. In fact, consider a segment $[0,a]$, with $a\in\mathbb{R}^{d}\setminus\{0\}$, then
\begin{align*}
    d_r(x,[0,a])=\begin{cases}
        0,\text{ if }x\in [0,a];\\
        \|x\|-\|a\|,\text{ if } x=\lambda a\text{ and }\lambda>1;\\
        \|x\|, \text{ otherwise}.
    \end{cases}
\end{align*}
is discontinuous at any  non-zero $x\in[0,a]$. This is a notably difference with the case of closed sets in $\mathbb{R}^d$ and the 
usual distance functional. In the next proposition, we describe all star bodies $A$ for which $d_r(\cdot,A)$ is continuous.

Recall that $\mathcal{S}_{1}^{d}$ denote the family of star bodies $A\subseteq\mathbb{R}^d$ with continuous radial function $\rho_A$. We define the following subfamilies of $\mathcal{S}_{1}^{d}$:
 $\mathcal{S}_{1,b}^{d}$, consisting of bounded star bodies; $\mathcal{S}_{1,(0)}^{d}$, composed by 
  star bodies containing the origin in the interior; and $\mathcal{S}_{1, b (0)}^{d}:=\mathcal{S}_{1,(0)}^{d}\cap\mathcal{S}_{1,b}^{d}$.

 % let $\mathcal{S}_{1,b}^{d}$, $\mathcal{S}_{1,(0)}^{d}$ and $\mathcal{S}_{1, b (0)}^{d}$ denote the sub-classes of $\mathcal{S}_{1}^{d}$ consisting of compact star bodies, of star bodies containing the origin in the interior, and of compact star bodies with the origin in the interior, respectively.

\begin{proposition}\label{prop:car-starb-conti-distance}
Let $A\in \mathcal{S}_{rc}^{d}$. Then, the following hold
\begin{itemize} 
    \item [(1)] If $\rho_A:\mathbb{S}^{d-1}\rightarrow[0,\infty]$ is continuous, then $A$ is closed.
    \item [(2)] $d_r(\cdot,A)$ is continuous if and only if $\rho_A$ is continuous. Particularly, $d_r(\cdot,A)$ is continuous if and only if $A\in\mathcal{S}_{1}^{d}$.
\end{itemize}
\end{proposition} 
\begin{proof} (1) Let $x\in\overline{A}$. Clearly, for $x=0$, $x\in A$. Now consider $x\neq0$, and let $(a_n)_n\subseteq A\setminus\{0\}$ be a sequence converging to $x$. Note that if $\rho_{A}(\theta_{a_n})=\infty$ for all $n>n_0$, then, by continuity of $\rho_A$, $\rho_A(\theta_x)=\infty$. Hence $x\in A$. 

On the other hand, if there is a subsequence $(a_{n_k})_k$ with $\rho_{A}(\theta_{n_k})<\infty$ for all $k$, then $\|a_{n_k}\|\leq\rho_{A}\left(\theta_{a_{n_k}}\right)$. Thus, again by continuity of $\rho_{A}$, $\|x\|\leq\rho_{A}\left(\theta_x\right)$, which yields to $x\in A$. Therefore $A$ is closed.

% $\|a_n\|\leq\rho_{A}\left(\theta_{a_n}\right)$ and, by the continuity of $\rho_{A}$, $\|x\|\leq\rho_{A}\left(\theta_x\right)$. Hence $x\in A$ and $A$ is closed. 

(2) Let us suppose that $\rho_A$ is continuous and let $x\in\mathbb{R}^d$  be arbitrary. Consider a sequence $(x_n)_n\subseteq\mathbb{R}^d$ converging to $x$. Notice that
\begin{equation}\label{eq:aux-continuity-drA-radial-map2}
    d_r(x_n,A)\leq\|x_n\|\leq\|x_n-x\|+ \|x\|
\end{equation}
holds for every $n\in\mathbb{N}$ and $x$. 
%Particularly, there is $n_x\in\mathbb{N}$ such that $d_r(x_n,A)\leq 1+\|x\|$
% \begin{equation*}\label{eq:aux-continuity drA-radial-map}
%     d_r(x_n,A)\leq 1+\|x\|,
% \end{equation*}
%for all $n\geq n_x$. 
Therefore, $(d_r(x_n,A))_n$ is bounded. 
We begin by proving continuity of $d_r(\cdot,A)$ when $d_r(x,A)=0$, i.e., $x\in A$. If $x=0$, then  (\ref{eq:aux-continuity-drA-radial-map2}) implies directly that $\lim_n d_r(x_n,A)=0$. 

For $x\neq 0$, we may suppose without lost of generality that there is $n_x\in\mathbb{N}$ such that $x_n\neq0$ for all $n>n_x$. 
% Thus, by continuity of $\rho_{A}$, 
% \begin{equation}\label{eq:aux-continuity drA-radial-map3}
%  \|x\|\leq\rho_{A}(\theta_x)=\lim_{n\to\infty}\rho_A(\theta_{x_n}).
% \end{equation}
In this case, we proceed by contradiction and suppose that $\limsup_n{d_r(x_n,A)}>0$. Then, there exist $\eta_0>0$ and a subsequence $(x_{n_k})$ such that $d_r(x_{n_k},A)>\eta_0$ for all $k$. Consequently $x_{n_k}\notin A$ and $\rho_A(\theta_{x_{n_k}})<\|x_{n_k}\|$. Since $x\in A$, $\|x\|\leq\rho_{A}(\theta_x)$. Thus, by continuity of $\rho_A$, 
$$
\|x\|\leq\rho_{A}(\theta_x)=\lim_{k\to\infty}\rho_A(\theta_{x_{n_k}})\leq\|x\|.
$$
The later in combination with (P1) proves that
% Moreover, from (P1), (\ref{eq:aux-continuity drA-radial-map3}), and the continuity of $\rho_A$, we also have that
$$
\eta_0\leq\lim_{k\to\infty}d_r(x_{n_k},A)=
\lim_{k\to\infty}\left\|x_{n_k}\right\|-\rho_{A}\left(\theta_{x_{n_k}}\right)
=\left\|x\right\|-\rho_{A}(\theta_{x})=0,
$$

which is a contradiction. This shows that $\limsup_n{d_r(x_n,A)}=0$, and therefore $\lim_n d_r(x_n,A)=0$ as required.

For the case $d_r(x,A)>0$, let us suppose without lost of generality that $x_n\neq0$ for all $n$.  Also notice that, by (P1)-(P2), $x\notin A$ and
$$
d_r(x,A)=\|x\|-\rho_{A}\left(\theta_x\right).
$$
By continuity of $\rho_A$, there exists $n'_x\in\mathbb{N}$ such that
$x_n\notin A$ for all $n>n'_x$. Otherwise, there is a subsequence $(x_{n_i})_{i}\subseteq A$. Particularly $\|x_{n_i}\|\leq\rho_{A}\left(\theta_{x_{n_i}}\right)$, and 
$\|x\|\leq\rho_{A}\left(\theta_{x}\right)<\|x\|$. which is a contradiction. Therefore, by (P2), 
$$
d_r(x_n,A)=\|x_n\|-\rho_{A}\left(\theta_{x_n}\right)\text{ for all }n\geq n'_x.
$$
Hence, again by continuity of $\rho_{A}$, $\lim_{n}d_r(x_n,A)=\|x\|-\rho_{A}\left(\theta_{x}\right)$. This proves that $d_r(\cdot,A)$ is continuous.

To prove the reverse implication, suppose that $d_r(\cdot,A)$ is continuous, and let $\theta\in\mathbb{S}^{d-1}$ and $(\theta_n)_n\subseteq\mathbb{S}^{d-1}$ be such that $(\theta_n)_n$ converges to $\theta$. Suppose that $\rho_A(\theta)$ is finite. By (P1), 
$$
d_r\left((\rho_A(\theta)+\varepsilon)\theta,A\right)=\varepsilon,
\text{ for every }\varepsilon>0.
$$
From the continuity of $d_r(\cdot,A)$,  it follows that $\lim_{n}d_r\left((\rho_A(\theta)+\varepsilon)
\theta_n,A\right)=\varepsilon$. Therefore, there exists $M\in\mathbb{N}$ such that $d_r\left((\rho_A(\theta)+\varepsilon)\theta_n,A\right)>0$ for all $n\geq M$. By (P1)-(P2), we have that 
$$
d_r\left((\rho_A(\theta)+\varepsilon)\theta_n,A\right)=\rho_A(\theta)+\varepsilon-\rho_A(\theta_n),
$$
%Thus, by using the continuity of $d_r(\cdot,A)$, we have that 
and the sequence $\left(\rho_A(\theta)+\varepsilon-\rho_A(\theta_n)\right)_n$ goes to $\varepsilon$. 
Since $\varepsilon>0$ is arbitrary, then $\lim_{n}\rho_A(\theta_n)=\rho_A(\theta)$.

For the case $\rho_A(\theta)=\infty$, we shall prove that 
$\liminf\rho_A(\theta_n)=\infty$. From this, it follows that $(\rho_A(\theta_n))_n$ converges to $\infty$. Indeed,
since $\lambda\theta\in A$ for every $\lambda>0$, then
$d_r(\lambda\theta,A)=0$. Hence, by continuity of $d_r(\cdot,A)$, 
\begin{equation}\label{eq:auxprop-car-starb-conti-distance}
    \lim_{n\rightarrow\infty}d_r(\lambda\theta_n,A)=0\text{ for all } \lambda>0.
\end{equation}
We will proceed by contradiction and suppose that $\liminf\rho_A(\theta_n)<\infty$. In this case, there is a sub-sequence $(\theta_{n_i})_i$ such that $\sup_{i}\rho_A(\theta_{n_i})<R$, for some $R>0$. Then, by (P1),
$$
d_r\left(R\theta_{n_i},A\right)=R-\rho_A\left(\theta_{n_i}\right)> 
R-\sup_{i}\rho_A(\theta_{n_i})>0.
$$
Hence $\lim_{i}d_r\left(R\theta_{n_i},A\right)>0$,
which is a contradiction with equality (\ref{eq:auxprop-car-starb-conti-distance}).
%However, from equality (\ref{eq:auxprop-car-starb-conti-distance}), we have that
% $$
% 0=\lim_{n\rightarrow\infty}d_r\left(R\theta_{n_i},A\right)>0
% $$
% which is a contradiction. 
This proves that $\rho_A$ is continuous. 

To finish the proof, observe that the fact that $d_r(\cdot,A)$ is continuous iff $A\in\mathcal{S}_{1}^{d}$ follows directly from what we have just proved and from (1) of this proposition.
\end{proof}

\section{A Wijsman type topology}
\label{sec:WijsmanTop}

In Section  \ref{sec:encajes-sin-estruct}, we 
% use the radial distance between points in $\mathbb{R}^d$ and  star bodies to 
established an identification of  $\mathcal{S}_{rc}^d$ as a subset of $F(\mathbb{R}^d,\mathbb{R})$, see (\ref{eq:encaje1}). Here, we further explore this relationship by introducing a weak topology on $\mathcal{S}_{rc}^d$, generated by 
the family of radial distance functionals. 

For every $x\in\mathbb{R}^d$, let $d_r(x,\cdot)$ be the map defined by 
\begin{align}\label{eq:functionalsradialWijsmantop}
    d_r(x,\cdot):\mathcal{S}_{rc}^d&\longrightarrow\mathbb{R}\\
    A&\longrightarrow d_r(x,A).\nonumber
\end{align}
%Then the radial Wijsman topology on $\mathcal{S}_{rc}^d$ is given by:

%the radial distance between star bodies and points.
% and establish its relation with the pointwise convergence topology on $F(\mathbb{R}^d,\mathbb{R})$. 
% To this end, for every $x\in\mathbb{R}^d$, let  $d_r(x,\cdot):\mathcal{S}_{rc}^d\rightarrow\mathbb{R}$  be the map sending $A\in\mathcal{S}_{rc}^d$ to $d_r(x,A)$.

\begin{definition}\label{defn:radial-WijsmanTop}
 The radial Wijsman topology $\tau_{W^r}$ on $\mathcal{S}_{rc}^d$ is the weak topology generated by the family $\left\{ d_r(x,\cdot):x\in\mathbb{R}^d\right\}$. That is, $\tau_{W^r}$ is the weakest topology on $\mathcal{S}_{rc}^d$ such that each $d_r(x,\cdot):\mathcal{S}_{rc}^d\rightarrow\mathbb{R}$ is continuous.
\end{definition}

In a similar way, we define \textit{the radial Wijsman topology on}  $\mathcal{S}_1^d$ and $\mathcal{S}_{1,b}^d$ as the weak topology on $\mathcal{S}_1^d$ (resp. $\mathcal{S}_{1,b}^d$) generated by the family 
$\{d_r(x,\cdot):\mathcal{S}_1^d\rightarrow\mathbb{R}\}_{x\in\mathbb{R}^d}$ (resp. $\mathcal{S}_{1,b}^d$).
%$\subseteq C(\mathbb{R}^d,\mathbb{R})$ (see Proposition \ref{prop:car-starb-conti-distance}-(2)). 
It can be directly verified that this topology coincides with the subspace topology that  $\mathcal{S}_1^d$ and $\mathcal{S}_{1,b}^d$ inherit from 
$(\mathcal{S}_{rc}^d,\tau_{W^r})$.  Clearly, it also agrees with the topology that $\mathcal{S}_{1,b}^d$ inherits from $(\mathcal{S}_{1}^d,\tau_{W^r})$.

% Naturally, the \textit{radial Wijsman topology on $\mathcal{S}_{1,b}^d$} is the weak topology generated 
% $\{d_r(x,\cdot):\mathcal{S}_{1,b}^d\rightarrow\mathbb{R}\}_{x\in\mathbb{R}^d}$. It also agrees with the subspace topology that $\mathcal{S}_{1,b}^d$ inherits from $(\mathcal{S}_{1}^d,\tau_{W^r})$.

It is well-known that the convergence in a weak topology amounts to the pointwise convergence of the defining family of functions. Particularly, for the radial Wijsman topology, a net $(A_i)_{i\in I}\subset\mathcal{S}_{rc}^d$ converges to some $A\in\mathcal{S}_{rc}^d$ if and only if $(d_r(\cdot,A_i)_i)_{i\in I}$ converges pointwise to $d_r(\cdot,A)$. That is,
\begin{equation}\label{eq:pointwise-convergence-rdistance}
 \tau_{W^r}\text{-}\lim_{i}A_i=A\textit{ iff }\lim_{i}d_r(x,A_i)=d_r(x,A),\textit{ for every }x\in\mathbb{R}^d.
\end{equation}

Notice that, under the identification  (\ref{eq:encaje1}), 
the radial Wijsman topology  is the topology that $\mathcal{S}_{rc}^d$ inherits from $F(\mathbb{R}^d,\mathbb{R})$, when the latter is equipped with the topology of pointwise convergence (see e.g., \cite[Definition VII.1]{Nagatabook}). 




Below, we establish a characterization of convergence in the radial Wijsman topology, formulated in terms of the pointwise convergence of the associated radial functions. As we will see throughout this work, this characterization plays a crucial role in simplifying proofs related to $\tau_{W^r}$.

