\section{An Attouch-Wets type distance}
\label{sec:radial Attouch-Wets topology}


Let $F_{ucb}(\mathbb{R}^d,\mathbb{R})$ denote the space of maps $f:\mathbb{R}^d\rightarrow\mathbb{R}$ equipped 
with the topology $\tau_{ucb}$ of the uniform convergence on bounded sets of $\mathbb{R}^d$. See for instance \cite[Example VII.3]{Nagatabook}).


\begin{definition}\label{def:radialAW}
    The radial Attouch-Wets topology  $\tau_{AW^r}$ on $\mathcal{S}_{rc}^d$ is the topology that $\mathcal{S}_{rc}^d$ inherits from $F_{ucb}(\mathbb{R}^d,\mathbb{R})$, under the identification given by $A\rightarrow d_r(\cdot,A).$ 
\end{definition}

We can make use of Proposition \ref{prop:car-starb-conti-distance} to define the \textit{radial Attouch-Wets topology $\tau_{AW^r}$ on $\mathcal{S}_{1}^d$}. In this case, it is the topology that $\mathcal{S}_{1}^d$ inherits from $C(\mathbb{R}^d,\mathbb{R})$, endowed with $\tau_{ucb}$, under the usual identification $A\rightarrow d_r(\cdot,A)$.
It is not difficult to prove that this topology coincides with the subspace topology that $\mathcal{S}_{1}^d$ obtain from $(\mathcal{S}_{rc}^d,\tau_{AW^r})$.

As in the case of the Hausdorff, Wijsman and Attouch-Wets topologies on $CL(d)$, there is a basic relation between the metric topology $\delta$, and the topologies $\tau_{W^r}$ and $\tau_{AW^r}$ on the family of star bodies:

\begin{remark}\label{rem:dAWR-stronger-than-Wr}
   $\tau_{W^r}\subseteq\tau_{AW^r}$ on $\mathcal{S}_{rc}^d$. Additionally, on $\mathcal{S}_{rc,b}^d$,  $\tau_{W^r}\subseteq\tau_{AW^r}\subseteq\tau_{\delta}$. 
\end{remark}
The previous remark follows directly from the definition of the topologies.


Below, we show that the map $d_{AW^r}$, defined in (\ref{defn:rd-AW}), is a metric on $\mathcal{S}_{rc}^d$ that generates the radial Attouch-Wets topology on $\mathcal{S}_{rc}^d$.
%that generates for the space $(\mathcal{S}_{rc}^d,\tau_{AW^r})$. 
\begin{theorem}\label{thm:rAW-complete-metrizable} 
$d_{AW^r}$
% The map $d_{AW^r}:\mathcal{S}_{rc}^d\times\mathcal{S}_{rc}^d\rightarrow[0,\infty)$, defined by
% $$
% d_{AW^r}(A_1,A_2):=\sup_{j\in\mathbb{N}}\min\left\{\frac{1}{j}, 
% \sup_{\|x\|\leq j}\left|d_{r}(x,A_1)-d_r(x,A_2)\right|\right\},
% $$
is a metric on $\mathcal{S}_{rc}^d$ that is compatible with $\tau_{AW^r}$. Furthermore, $(\mathcal{S}_{rc}^d,d_{AW^r})$ is a complete metric space. 
\end{theorem}
\begin{proof}
    Let $A_1, A_2, A_3\in \mathcal{S}_{rc}^d$  and $j\in\mathbb{N}$. The fact that $d_{AW^r}$ is a metric follows from (P3) and the following inequality 
    % $$
    % \left|d_{r}(x,A_1)-d_r(x,A_2)\right|\leq\left|d_{r}(x,A_1)-d_r(x,A_3)\right|+\left|d_{r}(x,A_3)-d_r(x,A_2)\right|.
    % $$ 
    % Consequently, for every $j\in\mathbb{N}$, we have
    \begin{align*}
    \min\left\{\frac{1}{j},\sup_{\|x\|\leq j}\left|d_{r}(x,A_1)-d_r(x,A_2)\right|\right\}\leq\min\left\{\frac{1}{j},\sup_{\|x\|\leq j}\left|d_{r}(x,A_1)-d_r(x,A_3)\right|\right\}\\+
    \min\left\{\frac{1}{j},\sup_{\|x\|\leq j}\left|d_{r}(x,A_3)-d_r(x,A_2)\right|\right\},
    \end{align*}
    which is a consequence of the triangle inequality. 
    %applied to the maps $d_{r}(\cdot,A_i)$ for $i=1,2,3.$ 
    %This yields to $d_{AW^r}(A_1,A_2)\leq d_{AW^r}(A_1,A_3)+d_{AW^r}(A_3,A_2)$.

    To prove that $d_{AW^r}$ and $\tau_{AW^r}$ generate the same topology, we will check that they have the same convergent nets. Let
    $(Y_i)_{i\in I}\subseteq\mathcal{S}_{rc}^d$ be a net converging in $\tau_{AW^r}$ to $Y\in\mathcal{S}_{rc}^d$. We shall see that $(Y_i)_i$ is $d_{AW^r}$-convergent to $Y$. Indeed, let $\eta>0$ and pick $j_0\in\mathbb{N}$ such that $\eta\in\left(\frac{1}{j_0+1},\frac{1}{j_0}\right]$. Since $(d_r(\cdot,Y_i))_i$ converges uniformly on $j_0B_2^d$ to $d_r(\cdot,Y)$, then there is $i_0\in I$ such that for all $i\geq i_0$, 
    $$
    \sup_{x\in j_0B_2^d}\left|d_{r}(x,Y)-d_r(x,Y_i)\right|<
    \eta\leq\frac{1}{j_0}.
    $$
    % $$
    % \sup_{x\in jB_2^d}\left|d_{r}(x,Y)-d_r(x,Y_i)\right|\leq
    % \sup_{x\in j_0B_2^d}\left|d_{r}(x,Y)-d_r(x,Y_i)\right|<
    % \eta\leq\frac{1}{j_0}.
    % $$
    Hence, 
    $$
    \sup_{j\leq j_0}\min\left\{\frac{1}{j}, 
    \sup_{\|x\|\leq j}\left|d_{r}(x,A_1)-d_r(x,A_2)\right|\right\}<\eta.
    $$ 
    This inequality and the fact that $\eta>\frac{1}{j_0+1}$ imply that $d_{AW^r}(Y,Y_i)<\eta$ for all $i\geq i_0$. Therefore,
    $Y=d_{AW^r}\text{-}\lim Y_i$ as desired. 

    On the other hand, consider a sequence $(X_n)_n\subseteq\mathcal{S}_{rc}^d$ converging in $d_{AW^r}$ to $X\in\mathcal{S}_{rc}^d$. Below we prove that $(X_n)_n$ is $\tau_{AW^r}$-convergent to $X$. Let $C\subseteq\mathbb{R}^d$ be a bounded set, and let $R_0\in\mathbb{N}$ be such that $\overline{C}\subseteq R_{0}B_2^d$. Then, for every $0<\varepsilon<\frac{1}{R_0+1}$, there is $n_0\in\mathbb{N}$ such that
    $d_{AW^r}(X,X_n)<\varepsilon$ for all $n>n_0$. Hence 
    $$
    \sup_{x\in C}\left|d_{r}(x,X)-d_r(x,X_n)\right|\leq\sup_{\|x\|\leq R_0+1}\left|d_{r}(x,X)-d_r(x,X_n)\right|<\varepsilon.
    $$
    Therefore $(d_r(\cdot,X_n))_n$ converges uniformly on $C$ to $d_r(\cdot,X)$. Since $C$ is arbitrary, $(X_n)_n$ is $\tau_{AW^r}$-convergent to $X$.

    To prove that $(\mathcal{S}_{rc}^d,d_{AW^r})$ is complete, let $(A_n)_n\subseteq\mathcal{S}_{rc}^d$ be a Cauchy sequence. Then, for every $x\in\mathbb{R}^d$, $(d_r(x,A_n))_n$ is also a Cauchy sequence and we can define $f:\mathbb{R}^d\rightarrow[0,\infty)$ as 
    $$
    f(x)=\lim_{n}d_r(x,A_n).
    $$
    From Proposition \ref{prop:completez-sec-d_r}, $f=d_r(\cdot, A)$ for some $A\in\mathcal{S}_{rc}^d$. We shall show that $(A_n)_n$ is  $d_{AW^r}$-convergent to $A$.  In fact, let $\gamma>0$ be such that $\gamma\in\left(\frac{1}{j+1},\frac{1}{j}\right]$  for some $j\in\mathbb{N}$. Since $(A_n)_n$ is a Cauchy sequence, there is $M\in\mathbb{N}$ such that $d_{AW^r}(A_n,A_m)<\frac{\gamma}{2}$ for all $n,m>M$. Particularly, for all $n,m>M$,
    $$
    \sup_{\|x\|\leq j}\left|d_{r}(x,A_n)-d_r(x,A_m)\right|<\frac{\gamma}{2}.
    $$
    Thus, if we fix $n>M$ and consider an arbitrary $x\in jB_2^d$, we have that
    $$
    |d_r(x,A)-d_r(x,A_n)|=\lim_{m}|d_r(x,A_m)-d_r(x,A_n)|\leq\frac{\gamma}{2}.
    $$
    Hence, $\sup_{\|x\|\leq j}\left|d_{r}(x,A_n)-d_r(x,A_m)\right|<\gamma$ and $d_{AW^r}(A,A_n)<\gamma$ for all $n>M$. This proves that 
    $A$ is the $d_{AW^r}$-limit of $(A_n)_n$ as desired.
\end{proof}

The next lemma can be understood as a generalization of \cite[Lemma 2.1]{NataliaLuisa2} to the context of the radial Attouch-Wets distance. It significantly eases the treatment of this distance and will be used frequently through the work.  

\begin{lemma}\label{lemm:axu-calcular-rdAW}
    Let $A_1, A_2\in\mathcal{S}_{rc}^d$ and $\eta>0$. Then the following statements hold:
    \begin{enumerate}
        \item $d_r(x,A_1)=d_r(x,A_1\cap\eta B_2^d)$ for all $x\in \eta B_2^d$.

        \item $\delta(A_1\cap\eta B_2^d,A_2\cap\eta B_2^d)=\sup_{\|x\|\leq \eta}\left|d_{r}(x,A_1)-d_r(x,A_2)\right|$.

        \item $d_{AW^r}(A_1,A_2)=\sup_{j\in\mathbb{N}}\min\left\{\frac{1}{j}, 
        \delta(A_1\cap jB_2^d,A_2\cap jB_2^d)\right\}$.

        \item For every integer $j\geq 1$ and $\varepsilon\in\left(\frac{1}{j+1},\frac{1}{j}\right]$, $d_{AW^r}(A_1, A_2)<\varepsilon$ if and only if $\delta(A_1\cap jB_2^d,A_2\cap jB_2^d)<\varepsilon$.
    \end{enumerate}
\end{lemma}
\begin{proof}
    (1) The result holds easily for $x\in A_1$. For 
    $x\in\eta B_2^d\setminus A_1$, we have that
    \begin{align*}
        d_{r}(x,A_1)=\|x\|-\rho_{A_1}(\theta_x)&=\|x\|-\min\{\rho_{A_1}(\theta_x),\eta\}\\
        &=\|x\|-\rho_{A_1\cap\eta B_2^d}(\theta_x)\\
        &=d_r(x,A_1\cap\eta B_2^d).
    \end{align*}

    (2) From (1) of this proposition and Proposition \ref{prop:caract-dHr-distanciaradial}, it follows that
    \begin{align*}
    \delta(A_1\cap\eta B_2^d,A_2\cap\eta B_2^d)&=\sup_{x\in\mathbb{R}^d}|d_r(x,A_1\cap\eta B_2^d)-d_r(x,A_2\cap\eta B_2^d)|\\
    &\geq\sup_{\|x\|\leq \eta}\left|d_{r}(x,A_1\cap\eta B_2^d)-d_r(x,A_2\cap\eta B_2^d)\right|\\
    &=\sup_{\|x\|\leq \eta}\left|d_{r}(x,A_1)-d_r(x,A_2)\right|.
    \end{align*}
    To show the reverse inequality, notice that if $x_0\in A_1\cap\eta B_2^d$, then 
    \begin{align*}
     d_r(x_0,A_2\cap\eta B_2^d)&=|d_r(x_0,A_1\cap\eta B_2^d)-d_r(x_0,A_2\cap\eta B_2^d)|\\
     &\leq\sup_{\|x\|\leq \eta}\left|d_{r}(x,A_1\cap\eta B_2^d)-d_r(x,A_2\cap\eta B_2^d)\right|\\
    &=\sup_{\|x\|\leq \eta}\left|d_{r}(x,A_1)-d_r(x,A_2)\right|.
    \end{align*}
    Similarly, for every $y_0\in A_2\cap\eta B_2^d$, we have that 
    $$
    d_r(y_0,A_1\cap\eta B_2^d)\leq\sup_{\|x\|\leq \eta}\left|d_{r}(x,A_1)-d_r(x,A_2)\right|.
    $$
    Finally, by using Proposition \ref{prop:caract-dHr-distanciaradial} again, we get that
    \begin{align*}
    \delta(A_1\cap\eta B_2^d,A_2\cap\eta B_2^d)&=\max\{e_r(A_1\cap\eta B_2^d,A_2\cap\eta B_2^d),e_r(A_2\cap\eta B_2^d,A_1\cap\eta B_2^d)\}\\
    &\leq\sup_{\|x\|\leq \eta}\left|d_{r}(x,A_1)-d_r(x,A_2)\right|.
    \end{align*}

    (3) Follows from (2) of this proposition.

    (4) Follows from (2) and (3) of this Proposition, and the definition of $d_{AW^r}$.
\end{proof}

\begin{proposition} \label{prop:subspaces-rdAW}The following statements hold:
    \begin{enumerate}
        \item $\mathcal{S}_1^d$ is a closed subset of $(\mathcal{S}_{rc}^d,d_{AW^r})$. Particularly, $(\mathcal{S}_{1}^d,d_{AW^r})$ is complete.

        \item $\mathcal{S}_{rc,b}^d$ is an open subset of $(\mathcal{S}_{rc}^d,d_{AW^r})$.

        \item $d_{AW^r}$ and $\delta$ generate the same topology on $\mathcal{S}_{rc,b}^d$.
    \end{enumerate}
\end{proposition}
\begin{proof}

(1)   % It follows directly from Proposition \ref{prop:car-starb-conti-distance} and the fact that limits $C(\mathbb{R}^d,\mathbb{R})$ 
    % % equipped with $d_{ucb}$ (REF) is complete.
Let $A\in\mathcal{S}_{rc}^d$ be such that $A=d_{AW^r}\text{-}\lim A_n$, for some $(A_n)_n\subseteq\mathcal{S}_1^d$. By Proposition \ref{prop:car-starb-conti-distance}, $(d_{r}(\cdot,A_n))_n\subseteq C(\mathbb{R}^d,\mathbb{R})$. Since $(d_{r}(\cdot,A_n))_n$ converges uniformly on compact sets to  $d_r(\cdot,A)$,  $d_r(\cdot,A)$ must be a continuous function. Therefore, by Proposition \ref{prop:car-starb-conti-distance}, $A\in\mathcal{S}_{1}^d$. The completeness of $(\mathcal{S}_{1}^d,d_{AW^r})$ follows from the fact that it is a closed subset of a complete metric space (Theorem \ref{thm:rAW-complete-metrizable}).

(2) Let $A\in\mathcal{S}_{rc,b}^d$ and let $j_0\geq1$ be an integer such that $A\subseteq j_0B_2^d$. We shall see that if $0<\varepsilon<\frac{1}{2j_0}$, then, for every $X\in\mathcal{S}_{rc}^d$ with $d_{AW^r}(A,X)<\varepsilon$, 
\begin{equation}\label{eq:Src-bouded}
    X\subseteq2j_0B_2^d.
\end{equation}
Suppose that there is $x\in X$ such that $\|x\|>2j_0$. Then $2j_0\theta_{x}\in X\cap 2j_0B_2^d$. This, in combination with Lemma \ref{lemm:axu-calcular-rdAW}-(1)-(3), yields to
$$
d_r(2j_0\theta_{x},A)=d_r(2j_0\theta_{x},A\cap2j_0B_2^d)\leq\delta(A\cap2j_0B_2^d,X\cap2j_0B_2^d)<\varepsilon<\frac{1}{2j_0}.
$$
Thus, there is $a\in A$ such that $0$, $2j_0\theta_x$ and $a$ are collinear and $\|a-2j_0\theta_{x}\|<\frac{1}{2j_0}$. This yields to $\|a\|>j_0$ which is a contradiction, since $A\subseteq j_0B_2^d$. 

(3) We shall show that the identity 
$I:(\mathcal{S}_{rc,b}^d,\delta)\rightarrow(\mathcal{S}_{rc,b}^d,d_{AW^r})$  is a homeomorphism. From Proposition \ref{prop:caract-dHr-distanciaradial}, $d_{AW^r}(A_1,A_2)\leq\delta(A_1,A_2)$ for all $A_1,A_2\in\mathcal{S}_{rc,b}^d$. Hence, $I$
is continuous. To prove that it is a homeomorphism, let $A\in\mathcal{S}_{rc,b}^d$  be such that 
$A\subseteq j_0B_2^d$ for some $j_0\geq1$ integer, and consider $0<\varepsilon<\frac{1}{2j_0}$. From (\ref{eq:Src-bouded}), it follows that $X\subseteq2j_0B_2^d$, for every $X\in\mathcal{S}_{rc}^d$ with $d_{AW^r}(A,X)<\varepsilon$. Thus, from Lemma \ref{lemm:axu-calcular-rdAW}-(3), if $d_{AW^r}(A,X)<\varepsilon$, then
$$
\delta(A,X)=\delta(X\cap2j_0B_2^d,A\cap2j_0B_2^d)<\varepsilon.
$$
Therefore $I$ is a homeomorphism.
\end{proof}

\subsection{On the relation with the  Attouch-Wets topology}
\label{sec:rel-AWr-AW}
Recall that the \textit{Attouch-Wets topology $\tau_{AW}$} on $CL(d)$ is the topology that $CL(d)$ inherits from the space of continuous functions $C(\mathbb{R}^d,\mathbb{R})$, equipped with the topology of the uniform convergence on bounded sets of $\mathbb{R}^d$, under the identification $C\rightarrow d(\cdot,C)$ given by the distance functional (see e.g., \cite[Definition 3.1.2]{Beer1993}).

It is well-known that $\tau_{AW}$ is a metrizable topology. In fact, the following distance, which is called \textit{the Attouch-Wets distance $d_{AW}$}, is an admissible distance for $\left(CL(d),\tau_{AW}\right)$. For $C_1,C_2\in CL(d)$, we define
\begin{equation}
\label{eq:dAW}
d_{AW}(C_1,C_2):=\sup_{j\in\mathbb{N}}\left\{\min\left\{\frac{1}{j},\sup_{\|x\|<j}|d(x,C_1)-d(x,C_2)|\right\}\right\}.
\end{equation}
This definition is the one used in \cite{SakaiYaguchi2006}. However it is equivalent to the Attouch-Wets distance defined in \cite[Definition 3.1.2]{Beer1993}. We refer \cite{Beer1993} for a thorough treatment of $\tau_{AW}$.

Below we exhibit the relation between $d_{AW}$ and $d_{AW^r}$ on the families of closed star bodies and of closed convex sets $\mathcal{K}_0^d$. We begin by showing 
%in Lemma \ref{lem:extension-resultado-Natalia}  
that \cite[Lemma 2.1]{NataliaLuisa2} holds not only for $\mathcal{K}_0^d$ but for all closed star bodies. This result allows to prove that convergence in the radial Attouch-Wets topology implies convergence in the Attouch-Wets topology (see Proposition \ref{prop:rdAW-es-top-strnger-than-rdAW}).

% $d_{AW^r}$ on the families of closed star bodies and of closed convex sets $\mathcal{K}_0^d$. We begin by showing 
% %in Lemma \ref{lem:extension-resultado-Natalia}  
% that LEMMAREF holds not only for the class $\mathcal{K}_0^d$ but for all closed star bodies. This result allows us to prove that the convergence in the radial Attouch-Wets topology is stronger than in the Attouch-Wets topology (see Proposition \ref{prop:rdAW-es-top-strnger-than-rdAW}).
% \textcolor{blue}{Introducir un poco lo que vamos a hacer y despues si señalar que es importante deicr aquí que este resultado en realidad esta mostrando que el Lema de natalia también es válido en la clase de conjuntos estrellados y no sólo en la clase convexos.}

\begin{lemma}\label{lem:extension-resultado-Natalia}
    Let $\eta>0$ and let $A\in\mathcal{S}_{rc}^d$ be closed. Then, for all $x\in\eta B_2^d$,
    \begin{equation}\label{eq:Aux-extension-lema-estrellados}
          d(x,A)=d(x,A\cap\eta B_2^d). 
    \end{equation}
    Particularly, for every $A_1,A_2\in\mathcal{S}_{rc}^d$, the following hold:
    \begin{enumerate}
         \item $d_{AW}(A_1,A_2)=\sup_{j\in\mathbb{N}}\min\left\{\frac{1}{j}, 
        d_H(A_1\cap jB_2^d,A_2\cap jB_2^d)\right\}$.

        \item For every integer $j\geq 1$ and $\varepsilon\in\left(\frac{1}{j+1},\frac{1}{j}\right]$, $d_{AW}(A_1, A_2)<\varepsilon$ if and only if $d_{H}(A_1\cap jB_2^d,A_2\cap jB_2^d)<\varepsilon$.
    \end{enumerate}
\end{lemma}
\begin{proof}
    Let $x\in\eta B_2^d$ and consider the set $W=\left\{a\in A: d(x,A)=\|x-a\|\right\}$. Notice that $W\neq\emptyset$, since $A$ is closed. We
    shall show that $W\subseteq\eta B_2^d$. From this, it follows that
    $d(x,A)\leq d(x,A\cap\eta B_2^d)\leq\|x-a\|=d(x,A)$ for any $a\in W$, which proves the equality.

    We proceed by contradiction. Suppose that there is $a\in W$ such that $\|a\|>\eta$. Let $p$ denote the orthogonal projection $\frac{\langle x,a\rangle}{\|a\|^2}a$. Observe that $\|p\|\leq \eta$ and that $\frac{|\langle x,a\rangle|}{\|a\|^2}<1$. Thus, 
    $p\in(-a,a)\cap\eta B_2^d$. If $p\in(-a,0]\cap\eta B_2^d$, then $\|p\|<\|p-a\|$ and
    \begin{equation*}
           \|x\|^2=\|x-p\|^2+\|p\|^2<\|x-p\|^2+\|p-a\|^2=\|x-a\|^2=d(x,A)^2
    \leq\|x\|^2
    \end{equation*}
    which is a contradiction. On the other hand, if $p\in[0,a)\cap\eta B_2^d$, then $p\in A$ because $A\in\mathcal{S}_{rc}^d$. Moreover, 
    let us denote by $\mathbb{R}^{+}a$ the ray $\left\{ta: t\geq0\right\}$. Then, since $\mathbb{R}^{+}a$ is a closed convex set and $p\neq a$, we must have that
    $$
    d(x,\mathbb{R}_{+}a)=\|x-p\|<\|x-a\|.
    $$ 
    However, $\|x-a\|=d(x,A)\leq\|x-p\|$ which leads to a contradiction with the previous inequality. This yields to $W\subseteq\eta B_2^d$ as desired.

    To finish the proof, notice that (1) and (2) follow directly from the equality in  (\ref{eq:Aux-extension-lema-estrellados}) and the definition of the Hausdorff and the Attouch-Wets metrics.
\end{proof}

The following relation between $d_{AW}$ and $d_{AW^r}$ can be understood as an extension of (\ref{eq:d-H-menor-rd-H}) to the context of unbounded star bodies.

\begin{proposition}\label{prop:rdAW-es-top-strnger-than-rdAW}
    For every pair $A_1,A_2\subseteq\mathbb{R}^d$ of closed star bodies, inequality in (\ref{eq:dAW-es-menor-rdAW}) holds.
\end{proposition}
\begin{proof}
    %Inequality (\ref{eq:dAW-es-menor-rdAW}) 
    Follows from inequality in (\ref{eq:d-H-menor-rd-H}), Lemma \ref{lemm:axu-calcular-rdAW}-(3) and Lemma \ref{lem:extension-resultado-Natalia}-(1).
