    %For proving the second affirmation, observe that if $A\in\mathcal{S}_{rc}^d$ is the $d_{AW^r}$-limit of a sequence $(A_n)_n\subseteq \mathcal{S}_{rc}^d\cap CL(d)$, then, by (\ref{eq:dAW-es-menor-rdAW}),..... is such that $A=d_{AW^r}\text{-}\lim_n$
\end{proof}

% \textcolor{red}{Comentario con respecto a la siguiente proposicion, pero para escribirlo me gustaría primero saber qué va a pasar con los resultados sobre las preservación de la propiedad de ser cerrados bajo la radial Attouch-Wets topology}


\begin{proposition} The following statements hold:
\begin{enumerate}
    \item If $(A_n)_n\subseteq\mathbb{R}^d$ is a sequence of closed star bodies converging in $d_{AW^r}$ to $A\in\mathcal{S}_{rc}^d$, then $\overline{A}=d_{AW}\text{-}\lim_{n}A_n$.

    \item On $\mathcal{S}_{1}^d$, $\tau_{AW}\subsetneq\tau_{AW^r}$.
\end{enumerate}
\end{proposition}
\begin{proof}
    (1) By Proposition \ref{prop:rdAW-es-top-strnger-than-rdAW}, $(A_n)_n$ is a Cauchy sequence in $(CL(d),d_{AW})$. Since the later is a complete metric space (see e.g., \cite[Theorem 3.1.3]{Beer1993}), there is $Z\in CL(d)$ such that $Z=d_{AW}\text{-}\lim_{n}A_n$. We shall see that $Z=\overline{A}$. Indeed, by (P4), for every $a\in A$ we have that
    $$
    d(a,Z)=\lim_{n}d(a,A_n)\leq\lim_{n}d_r(a,A_n)=d_r(a,A)=0.
    $$
    Therefore $A\subseteq Z$, and $\overline{A}\subseteq Z$. To show the reverse inclusion, let $z\in Z$ and consider a sequence $(x_n)_n\subseteq\mathbb{R}^d$ such that $x_n\in A_n$ and $d(z,A_n)=\|z-x_n\|$ for all $n$. Clearly, $(x_n)_n$ converges to $z$. Moreover, there are $j_0, n_0\in\mathbb{N}$ such that $\|z\|<j_0$ and $\|x_n\|<j_0$ for all $n>n_0$. Now, consider $0<\varepsilon<\frac{1}{j_0}$. Then, there is $n_1>n_0$ such that $d_{AW^r}(A,A_n)<\varepsilon$. Hence for all $n>n_1$,
    $$
    d_r(x_n,A)=|d_r(x_n,A)-d_r(x_n,A_n)|\leq\sup_{\|x\|\leq j_0}\left|d_{r}(x,A)-d_r(x,A_n)\right|<\varepsilon,
    $$
    which proves that $\lim_{n}d_r(x_n,A)=0$. By (P4), for every $n$, we have that
    $$
    d(x_n,\overline{A})=d(x_n,A)\leq d_r(x_n,A),
    $$ 
    which yields to $d(z,\overline{A})=0$. Therefore $z\in\overline{A}$, and thus $Z\subseteq\overline{A}$ as desired.

    (2) The inclusion follows directly from inequality (\ref{eq:dAW-es-menor-rdAW}). To check that
    $\tau_{AW}\neq\tau_{AW^r}$, recall that Example \ref{exam:ejemploMoszynska} exhibits a sequence in $\mathcal{S}_{1,b}^d$ 
    %$(A_n)_n\subseteq\mathcal{S}_{1,b}^d$ 
    converging in $d_H$ (and thus in $d_{AW}$) to $B_2^d$, but such that it is not $\delta$-convergent to $B_2^d$. Thus, by
    Proposition \ref{prop:subspaces-rdAW}-(3), this sequence is not $d_{AW^r}$-convergent to $B_2^d$ either. This proves the result.
\end{proof}

In the next remark we detail some basic properties of the radial Attouch-Wets topology on $\mathcal{K}_0^d$.

\begin{remark}\label{rem:d_AWr de convexos}
\begin{enumerate}
    \item On $\mathcal{K}_0^d$, $\tau_{AW}\subsetneq\tau_{AW^r}$. 
    %$d_{AW^r}$ is  \textcolor{red}{topologically stronger} than $d_{AW}$.

    \item On $\mathcal{K}_{0,b}^d$, $\delta$ and $d_{AW^r}$ generate the same topology. 
    \item The metric $d_H$, $d_{AW}$, $\delta$, and $d_{AW^r}$ generate the same topology on $\mathcal{K}_{(0),b}^d$.
\end{enumerate}

\end{remark}
\begin{proof}
    (1) By inequality (\ref{eq:dAW-es-menor-rdAW}), $\tau_{AW}\subseteq\tau_{AW^r}$. To prove that the inclusion is strict, let $(\theta_{n})_n\subseteq\mathbb{S}^{d-1}\setminus\{e_1\}$ be a sequence converging to $e_1$. Then, it is not difficult to check that the sequence of segments $\left([0,\theta_n]\right)_n$   converges in $d_H$ (and therefore in $d_{AW}$) to $[0,e_1]$. However, for all $n$,
    $$
    \delta\left([0,e_1],[0,\theta_n]\right)\geq\left|\rho_{[0,e_1]}(\theta_n)-\rho_{[0,\theta_n]}(\theta_n)\right|=1.
    $$
    Hence, $\left([0,\theta_n]\right)_n$ does not converge in $\delta$ to $[0,e_1]$. By Proposition \ref{prop:subspaces-rdAW}-(3),  $\left([0,\theta_n]\right)_n$ does not converge in $d_{AW^r}$ to $[0,e_1]$ either.  

    (2) Follows from Proposition \ref{prop:subspaces-rdAW}-(3).

    (3) Follows from Proposition \ref{prop:subspaces-rdAW}-(3) and the well-known fact that on $\mathcal{K}_{(0),b}^d$, the metrics $\delta$ and $d_{H}$ generate the same topology.
\end{proof}

\section{Dualities}
\label{sec:dualities}

% Dualities on the family of star sets have already been studied in \cite{Moszynska1999}, and more recently in \cite{ZooDualities} and \cite{MMilmanRotem}. The first work addresses the case of compact star sets with non-empty interior, while the latter two consider the more general setting of radially closed star sets.

A \textit{duality} for the family $\mathcal{S}_{rc}^d$ (resp. $\mathcal{S}_{1}^d$, $\mathcal{S}_{1,b}^d$ or $\mathcal{S}_{1,(0),b}^d$) is a map $\mathcal{T}:\mathcal{S}_{rc}^d\rightarrow\mathcal{S}_{rc}^d$ (resp. $\mathcal{S}_{1}^d$, $\mathcal{S}_{1,b}^d$ or $\mathcal{S}_{1,(0),b}^d$) with the following properties:
\begin{itemize}
    \item [(D1)] $\mathcal{T}\circ\mathcal{T}$ is the identity map.
    \item [(D2)] For every $A_1,A_2\in\mathcal{S}_{rc}^d$, if $A_1\subseteq A_2$, then
    $\mathcal{T}(A_2)\subseteq\mathcal{T}(A_1)$.
\end{itemize}
This definition as well as basic results and recent developments regarding dualities can be consulted in \cite{ArtsteinMilman2007,ArtsteinMilman2008,ZooDualities,Slomka2011}.


% Clearly, in the previous definition, we can consider other classes of star bodies such that $\mathcal{S}_{1}^d$, $\mathcal{S}_{1,b}^d$ or $\mathcal{S}_{1,(0),b}^d$ instead of $\mathcal{S}_{rc}^d$.


The star duality $\Phi$, defined in (\ref{eq:duality-Src}), was introduced in \cite[Definition 9.11]{MMilmanRotem}. However, as it is pointed out there, this duality was originally studied in \cite{Moszynska1999} for the  family of compact star bodies $\mathcal{S}_{1,(0),b}^d$. Indeed,  \cite[Definition 3.2]{Moszynska1999} introduces the duality $\phi:\mathcal{S}_{1,(0),b}^d\rightarrow\mathcal{S}_{1,(0),b}^d$ defined, for every $A\in\mathcal{S}_{1,(0),b}^d$, as
\begin{equation}\label{eq:duality-Moszynska}
\phi(A)=\overline{\mathbb{R}^d\setminus i(A)}. 
\end{equation}
Here $i(A)$ is the image of $A$ under the spherical inversion $i:\mathbb{R}^d\setminus\{0\}\rightarrow\mathbb{R}^d\setminus\{0\}$, given by $i(x)=\frac{x}{\|x\|^2}$. 
% In \cite[Definition 9.11]{MMilmanRotem}, the duality $\Phi$ is introduced. It is defined as the map $\Phi:\mathcal{S}_{rc}^d\rightarrow\mathcal{S}_{rc}^d$ sending $A\in\mathcal{S}_{rc}^d$ to the star body $\Phi(A)$ given by
% \begin{equation}\label{eq:duality-Src}
% \rho_{\Phi(A)}=\frac{1}{\rho_{A}}.    
% \end{equation}
% Here, we follow the convention that $\frac{1}{0}=\infty$ and $\frac{1}{\infty}=0$. 
% Earlier, \cite[Definition 3.2]{Moszynska1999} introduces a duality $\phi$ for the family $\mathcal{S}_{1,(0),b}^d$. It is defined as the map $\phi:\mathcal{S}_{1,(0),b}^d\rightarrow\mathcal{S}_{1,(0),b}^d$ sending each $A\in\mathcal{S}_{1,(0),b}^d$ to
% \begin{equation}\label{eq:duality-Moszynska}
% \phi(A)=\overline{\mathbb{R}^d\setminus i(A)}. 
% \end{equation}
% Here, $i(A)$ is the image of $A$ under the spherical inversion $i:\mathbb{R}^d\setminus\{0\}\rightarrow\mathbb{R}^d\setminus\{0\}$ given by $i(x)=\frac{x}{\|x\|^2}$. 
As highlighted in \cite{MMilmanRotem}, both of the dualities $\Phi$ and $\phi$ agree on $\mathcal{S}_{1,(0),b}^d$. That is,
\begin{equation}\label{eq:dualitiesMosz-and-Milman}
\Phi(A)=\overline{\mathbb{R}^d\setminus i(A)}\text{ for every }A\in\mathcal{S}_{1,(0),b}^d,
\end{equation}
see \cite{Moszynska1999} or \cite[$\mathsection$15.4]{MoszynskaBook}. 

It is worth noticing that equality (\ref{eq:dualitiesMosz-and-Milman}) does not hold on $\mathcal{S}_{rc}^d$. In fact, for every $u\in\mathbb{S}^{d-1}$,  $\Phi([0,u])=\mathbb{R}^{d}\setminus\{tu:t>1\}$ and $\overline{\mathbb{R}^d\setminus i([0,u])}=\mathbb{R}^d$. 
The next proposition exhibits the relation between $\Phi$ and the expression in the right side of (\ref{eq:dualitiesMosz-and-Milman}) on the family $\mathcal{S}_{rc}^d$.




\begin{proposition}\label{prop:duality-S1}
    For every $A\in\mathcal{S}_{rc}^d$, 
    $\Phi(A)=rc(\mathbb{R}^d\setminus i(A)).$ 
    Particularly, if $X\in\mathcal{S}_{1}^{d}$, then $\Phi(X)\in\mathcal{S}_{1}^{d}$ and
    $$
    \Phi(X)=\overline{\mathbb{R}^d\setminus i(X)}\textit{ for every }X\in\mathcal{S}_{1}^{d}.
    $$ 
\end{proposition}
\begin{proof}
Let us notice that for every $A\in\mathcal{S}_{rc}^d$, $\mathbb{R}^d\setminus i(A)$ is a star. Indeed, $0\in\mathbb{R}^d\setminus i(A)$ and, for each  non-zero $x\in\mathbb{R}^d\setminus i(A)$, we have that $\rho_{A}(\theta_x)<\frac{1}{\|x\|}$. Thus, if $\lambda x\notin\mathbb{R}^d\setminus i(A)$  for some $\lambda\in(0,1)$, then $\lambda x\in i(A)$ and $\rho_{A}(\theta_x)\geq\frac{1}{\lambda\|x\|}$ which is a contradiction. Hence $\lambda x\in\mathbb{R}^d\setminus i(A)$ for every $\lambda\in[0,1]$.

By  the previous observation, in order to prove that $\Phi(A)=rc(\mathbb{R}^d\setminus i(A))$, it is enough to show that 
\begin{equation}\label{eq:radial-map-of-a-duality}
    \rho_{\mathbb{R}^d\setminus i(A)}=\frac{1}{\rho_A}\textit{ for every }A\in\mathcal{S}_{rc}^d.
\end{equation}
% Notice that $0\in\mathbb{R}^d\setminus i(A)$ holds immediately. Now, suppose that $x\neq0$ belongs to $\mathbb{R}^d\setminus i(A)$. Then, $\rho_{A}(\theta_x)<\frac{1}{\|x\|}$. Moreover, if $\lambda x\notin\mathbb{R}^d\setminus i(A)$  for some $\lambda\in(0,1)$, then $\lambda x\in i(A)$ and thus $\rho_{A}(\theta_x)\geq\frac{1}{\lambda\|x\|}$ which is a contradiction. Therefore $\lambda x\in\mathbb{R}^d\setminus i(A)$ for every $\lambda\in[0,1]$, and $\mathbb{R}^d\setminus i(A)$ is a star set.

% We turn to prove that $\Phi(A)=rc(\mathbb{R}^d\setminus i(A))$. 
%it is enough to check that $\rho_{\mathbb{R}^d\setminus i(A)}=\frac{1}{\rho_A}$. Indeed, 
Let $\theta\in\mathbb{S}^{d-1}$ be such that $\rho_A(\theta)\in(0,\infty)$. Then
$\frac{1}{\rho_A(\theta)}\theta\in i(A)$ and 
%$\frac{1}{\rho_A(\theta)}\theta\notin\mathbb{R}^d\setminus i(A)$. Hence
$\rho_{\mathbb{R}^d\setminus i(A)}(\theta)\leq\frac{1}{\rho_A(\theta)}$. To prove the reverse inequality, consider an arbitrary $\alpha>\rho_A(\theta)$. Clearly, $\alpha\theta\notin A$ and
$\frac{1}{\alpha}\theta\notin i(A)$. Thus $\rho_{\mathbb{R}^d\setminus i(A)}(\theta)\geq\frac{1}{\alpha}$, and $\rho_{\mathbb{R}^d\setminus i(A)}(\theta)\geq\frac{1}{\rho_A(\theta)}$.  %\textcolor{red}{Similarly, it can be proved that if $\rho_{\mathbb{R}^d\setminus i(A)}(\theta)\in(0,\infty)$, then $\rho_{A}(\theta)=\frac{1}{\rho_{\mathbb{R}^d\setminus i(A)}(\theta)}$.}

For $\theta\in\mathbb{S}^{d-1}$ with $\rho_A(\theta)=0$. Let $\alpha>0$ be arbitrary and notice that $\alpha\theta\notin A$ iff
$\frac{1}{\alpha}\theta\notin i(A)$ iff $\rho_{\mathbb{R}^d\setminus i(A)}(\theta)\geq\frac{1}{\alpha}$ iff $\rho_{\mathbb{R}^d\setminus i(A)}(\theta)=\infty$.

For $\theta\in\mathbb{S}^{d-1}$ such that $\rho_A(\theta)=\infty$, we have that $t\theta\in A$ for all $t>0$. Hence, $\frac{1}{t}\theta\in i(A)$ and 
$\rho_{\mathbb{R}^d\setminus i(A)}(\theta)\leq\frac{1}{t}$. Therefore $\rho_{\mathbb{R}^d\setminus i(A)}(\theta)=0$. 
%Similarly, we have that if $\rho_{\mathbb{R}^d\setminus i(A)}(\theta)=0$, then $\rho_{A}(\theta)=\infty$. 
This proves (\ref{eq:radial-map-of-a-duality}). 

To finish the proof, observe that the map $\frac{1}{\rho_X}:\mathbb{S}^{d-1}\rightarrow[0,\infty]$ is continuous for every $X\in\mathcal{S}_{1}^{d}$. Hence, by Proposition \ref{prop:car-starb-conti-distance}-(1), $\Phi(X)$ is closed. Consequently, $\Phi(X)\in\mathcal{S}_{1}^{d}$ and   $\Phi(X)=\overline{\mathbb{R}^d\setminus i(X)}$. 
\end{proof}

Below, we examine the continuity of the star duality with respect to the radial metric, the Wijsman topology and the radial Attouch-Wets topology, respectively.

\begin{remark}\label{rem:dualidad-continua-acotados}
    The duality map $\Phi:\mathcal{S}_{1,(0),b}^d\rightarrow\mathcal{S}_{1,(0),b}^d$ is continuous with respect to the radial metric. %Moreover, the map $\clubsuit:\left(\mathcal{K}_{(0),b}^d,d_H\right)\rightarrow\left(\mathcal{F}_{(0),b}^d,\delta\right)$ sending $K$ to its associated flower $K^\clubsuit$ is an isometric isomorphism. 
\end{remark}
\begin{proof}
    Consider any $A\in\mathcal{S}_{1,(0),b}^d$. Let $\varepsilon>0$ and set $r_0=\min_{\theta\in\mathbb{S}^{d-1}}|\rho_A(\theta)|>0$. Then, for every $X\in\mathcal{S}_{1,(0),b}^d$ with $\delta(A,X)<\min\left\{\frac{r_0}{2},\frac{r_{0}^2\varepsilon}{2}\right\}$, we have that
    $$
    \delta\left(\Phi(A),\Phi(X)\right)\leq
    \frac{2\delta\left(A,X\right)}{r_0^2}<\varepsilon.
    $$
    This proves the continuity of $\Phi$.
\end{proof}

\begin{remark} The duality $\Phi:\mathcal{S}_{1,(0),b}^d\rightarrow\mathcal{S}_{1,(0),b}^d$ is discontinuous with respect to the Hausdorff metric $d_H$. 
\end{remark}

To verify the remark, notice that the sequence $(A_n)_n\subseteq\mathcal{S}_{1, (0),b}^d$ from Example \ref{exam:ejemploMoszynska} converges in $d_H$ to $B_2^d$, however 
$d_H\left(\Phi(A_n),B_2^d\right)\geq3$ for every $n$.

\begin{theorem}\label{thm:duality-Wr-continuous}
    The duality $\Phi:\mathcal{S}_{rc}^d\rightarrow\mathcal{S}_{rc}^d$ is continuous with respect to $\tau_{W^r}.$
\end{theorem}
\begin{proof} 
    Let $A\in\mathcal{S}_{rc}^d$. We shall prove that for every net $(A_i)_{i\in I}\subseteq\mathcal{S}_{rc}^d$ that is $\tau_{W^r}$-convergent to $A$, the net $(\Phi(A_i))_{i\in I}$ converges to $\Phi(A)$ in $\tau_{W^r}$.  By Theorem \ref{thm:caract-rWijsmanTopology}, the convergence in $\tau_{W^r}$ amounts to the pointwise convergence of the radial maps $(\rho_{A_i})_{i}$ to $(\rho_{\Phi(A_i)})_{i}$. Consequently, we only need to prove that for every $\theta\in\mathbb{S}^{d-1}$, the net $\left(\rho_{\Phi(A_i)}(\theta)\right)_{i}$ converges to $\rho_{\Phi(A)}(\theta)$. 

    We consider separately the cases when $\rho_{A}(\theta)$ strictly positive, $0$ and $\infty$. For the first case, notice that $\rho_{A}(\theta)\in(0,\infty)$ if and only if $\rho_{\Phi(A)}(\theta)=\frac{1}{\rho_{A}(\theta)}\in(0,\infty)$. Since $(\rho_{A_i}(\theta))_{i}$ converges to $\rho_{A}(\theta)$, there is $i_0\in I$ such that $\rho_{A_i}(\theta)\in(0,\infty)$ for all $i>i_0$. Then, it is a straightforward matter to prove that $\left(\rho_{\Phi(A_i)}(\theta)\right)_i$
    %$\left(\frac{1}{\rho_{A_i}(\theta)}\right)_i$ 
    approaches to $\rho_{\Phi(A)}(\theta)$. For the case $\rho_{A}(\theta)=0$ (resp. $\rho_{A}(\theta)=\infty$), observe that 
    $\rho_{\Phi(A)}(\theta)=\infty$ 
    (resp. $\rho_{\Phi(A)}(\theta)=0$). It then follows that the net $\left(\rho_{\Phi(A_i)}(\theta)\right)_i$ converges to $\infty$ (resp. $0$) when $(\rho_{A_i}(\theta))_{i}$ approaches to $0$ (resp. to $\infty$).
\end{proof}



\begin{lemma}\label{lem:Src(0)-is-open}
     Let $A\in\mathcal{S}_{rc}^d$ be such that $\frac{1}{j_0}B_2^d\subseteq A$ for some integer $j_0\geq1$, and let $X\in\mathcal{S}_{rc}^d$ be such that  $d_{AW^r}(X,A)<\frac{1}{2j_0}$. Then $\frac{1}{2j_0}B_2^d\subseteq X$. Particularly, $\mathcal{S}_{rc,(0)}^d$ is an open set in $\left(\mathcal{S}_{rc}^d,d_{AW^r}\right)$.  
\end{lemma}
\begin{proof}
    Since $A\in\mathcal{S}_{rc}^d$ is such that $\inf_{\theta\in\mathbb{S}^{d-1}}\rho_A(\theta)\geq\frac{1}{j_0}$ and $d_{AW^r}(A,X)<\frac{1}{2j_0}$, then,
    %Let $X\in\mathcal{S}_{rc}^d$ be such that $d_{AW^r}(A,X)<\frac{1}{2j_0}$. 
    % We shall see that if 
    % $X\in\mathcal{S}_{rc}^d$ and $d_{AW^r}(A,X)<\frac{1}{2j_0}$, then  $\frac{1}{2j_0}B_2^d\subseteq X$
    % %$\inf_{\theta\in\mathbb{S}^{d-1}}\rho_A(\theta)\geq\frac{1}{2j_0}$. , 
    by Lemma \ref{lemm:axu-calcular-rdAW}-(3), we have that for every $\theta\in\mathbb{S}^{d-1}$, 
    $$
    \left|\min{\{\rho_X(\theta),2j_0\}}-\min\{\rho_A(\theta),2j_0\}\right|<\frac{1}{2j_0}.
    $$
    Hence,  $\min{\{\rho_X(\theta),2j_0\}}>\frac{1}{2j_0}$ and
    $\rho_X(\theta)>\frac{1}{2j_0}$ for all $\theta\in\mathbb{S}^{d-1}$. Therefore, $\frac{1}{2j_0}B_2^d\subseteq X$ as required.
\end{proof}

\begin{theorem}\label{thm:duality-awr-continua}
    The duality $\Phi:\mathcal{S}_{rc}^d\rightarrow\mathcal{S}_{rc}^d$ is continuous with respect to $d_{AW^r}$.
\end{theorem}
\begin{proof}
    We will consider three separate cases: (1) $A\in\mathcal{S}_{rc}^d$ is bounded; (2) $A\in\mathcal{S}_{rc}^d$ contains the origin in the interior; and (3) $A\in\mathcal{S}_{rc}^d$ satisfies $\inf_{\theta\in\mathbb{S}^{d-1}}\rho_{A}(\theta)=0$ and
    $\sup_{\theta\in\mathbb{S}^{d-1}}\rho_{A}(\theta)=\infty$.

    We begin by proving the continuity of $\Phi$ for the third case. The remaining cases will follow from minor modifications in the proof of this case. 

    Let $\varepsilon\in\left(\frac{1}{j+1},\frac{1}{j}\right]$ with $j\geq2$ an integer, and 
    consider  $A\in\mathcal{S}_{rc}^d$ as in (3) of this proof.  We shall prove that if
    $$
    0<\eta<\min\left\{\frac{1}{2j+3},\frac{\varepsilon}{j^2+j\varepsilon} \right\},
    $$ 
    then, for every $X\in\mathcal{S}_{rc}^d$ with 
    $d_{AW^r}(A,X)<\eta$, 
    $d_{AW^r}(\Phi(X),\Phi(A))<\varepsilon$. To this end, we consider the following regions of $\mathbb{S}^{d-1}$:
    \begin{table}[h]
    \begin{tabular}{ll}
          $\mathcal{R}_1:=\left\{\theta\in\mathbb{S}^{d-1}:\rho_A(\theta)\leq\frac{1}{j} 
          \right\}$ & $\mathcal{R}_3:=\left\{\theta\in\mathbb{S}^{d-1}:j<\rho_A(\theta)<2j+3
          \right\}$ \\
          $\mathcal{R}_2:=\left\{\theta\in\mathbb{S}^{d-1}:\frac{1}{j}<\rho_A(\theta)\leq j 
          \right\}$ & $\mathcal{R}_4:=\left\{\theta\in\mathbb{S}^{d-1}:\rho_A(\theta)\geq 2j+3 
          \right\}$
    \end{tabular}
    \end{table}\\
    Observe that $\mathcal{R}_1$ and $\mathcal{R}_4$ are always non-empty, while $\mathcal{R}_2$ and $\mathcal{R}_3$ may be empty, depending on $A$. 

    Consider $\theta\in\mathcal{R}_1$. Since $d_{AW^r}(A,X)<\eta$, then by Lemma \ref{lemm:axu-calcular-rdAW}-(3), we have that  $\delta(A\cap(2j+3)B^d_2,X\cap(2j+3)B^d_2)<\eta$. Hence, 
    $$
    \rho_A(\theta)-\eta<\min\left\{\rho_{X}(\theta),2j+3\right\}<\rho_A(\theta)+\eta<\frac{1}{j}+\frac{1}{2j+3}<j,
    $$
    which yields to $\rho_{X}(\theta)<\frac{1}{j}+\eta$. Consequently, $\rho_{\Phi(X)}(\theta)=\infty$  or $\rho_{\Phi(X)}(\theta)>\frac{j}{1+j\eta}$. For the latter, notice that we actually have $\rho_{\Phi(X)}(\theta)>\frac{j}{1+j\eta}>j-\varepsilon$
    because of
    $\eta<\frac{\varepsilon}{j(j+\varepsilon)}<\frac{\varepsilon}{j(j-\varepsilon)}$. Particularly, for every $\theta\in\mathcal{R}_1$, we  have that
    $$
    \min\left\{\rho_{\Phi(X)}(\theta), j\right\}
    >\frac{j}{1+j\eta}>j-\varepsilon.
    $$
    Since $\min\left\{\rho_{\Phi(A)}(\theta),j\right\}=j$ on $\mathcal{R}_1$, then
    % \begin{align}\label{eq:Region1}
    %        \sup_{\theta\in\mathcal{R}_1}\left|\min\left\{\rho_{\Phi(A)}(\theta),j\right\}-\min\left\{\rho_{\Phi(X)}(\theta), j\right\}\right|&=
    %        \sup_{\theta\in\mathcal{R}_1}\left(j-\min\left\{\rho_{\Phi(X)}(\theta), j\right\}\right)\\
    %        &\leq j-\frac{j}{1+j\eta}\nonumber
    %        <\varepsilon.
    % \end{align}
    \begin{align}\label{eq:Region1}
           \sup_{\theta\in\mathcal{R}_1}\left|\min\left\{\rho_{\Phi(A)}(\theta),j\right\}-\min\left\{\rho_{\Phi(X)}(\theta), j\right\}\right|
           \leq j-\frac{j}{1+j\eta}
           <\varepsilon.
    \end{align}
    Now, suppose that $\mathcal{R}_2\neq\emptyset$ and let $\theta\in\mathcal{R}_2$ be arbitrary. First, let us suppose that $\rho_X(\theta)\leq\frac{1}{j}$. Then, by Lemma \ref{lemm:axu-calcular-rdAW}-(3), we know that
    \begin{equation}\label{eq:auxprovecontPhi1}
         \left|\rho_{A}(\theta)-\rho_{X}(\theta)\right|=
    \left|\min\left\{\rho_{A}(\theta),2j+3\right\}-\min\left\{\rho_{X}(\theta), 2j+3\right\}\right|<\eta.
    \end{equation}
    Particularly, $\rho_X(\theta)>\rho_A(\theta)-\eta>\frac{1}{j}-\eta>0$. Hence $j\leq\rho_{\Phi(X)}(\theta)<\frac{j}{1-j\eta}$, and
    \begin{align*}
        \left|\min\left\{\rho_{\Phi(A)}(\theta),j\right\}-\min\left\{\rho_{\Phi(X)}(\theta), j\right\}\right|&\leq\left|\rho_{\Phi(A)}(\theta)-\rho_{\Phi(X)}(\theta)\right|\\
        &\leq\eta\rho_{\Phi(A)}(\theta)\rho_{\Phi(X)}(\theta)\\
        &<\frac{j^2\eta }{1-j\eta}.
    \end{align*}
    Since $\eta<\frac{\varepsilon}{j^2+j\varepsilon}$,
    then,
    for every $\theta\in\mathcal{R}_2$ such that $\rho_X(\theta)\leq\frac{1}{j}$, we have that
    $$
    \left|\min\left\{\rho_{\Phi(A)}(\theta),j\right\}-\min\left\{\rho_{\Phi(X)}(\theta), j\right\}\right|<\frac{j^2\eta }{1-j\eta}<\varepsilon.
    $$
    Now, let us suppose that $\theta\in\mathcal{R}_2$ is such that $\frac{1}{j}<\rho_X(\theta)\leq j$. In this case, by Lemma \ref{lemm:axu-calcular-rdAW}-(3), the inequality in (\ref{eq:auxprovecontPhi1}) also holds. 
    % Therefore
    % $$
    % \left|\rho_{A}(\theta)-\rho_{X}(\theta)\right|=\left|\min\left\{\rho_{A}(\theta),(2j+3)\right\}-\min\left\{\rho_{X}(\theta), (2j+3)\right\}\right|<\eta
    % $$
    Thus,
    \begin{align*}
        \left|\min\left\{\rho_{\Phi(A)}(\theta),j\right\}-\min\left\{\rho_{\Phi(X)}(\theta), j\right\}\right|&=
        \left|\rho_{\Phi(A)}(\theta)-\rho_{\Phi(X)}(\theta) \right|\\
        &<j^2\left|\rho_{A}(\theta)-\rho_{X}(\theta) \right|\\
        &<j^2\eta\\
        &<\varepsilon.
    \end{align*}

    Now, suppose that $\theta\in\mathcal{R}_2$ is such that $\rho_X(\theta)>j$. Notice that $\rho_X(\theta)$ must be finite. Otherwise $\rho_X(\theta)=\infty$ and, from Lemma \ref{lemm:axu-calcular-rdAW}-(3), it follows that
    $$
    \left|\rho_A(\theta)-(2j+3)\right|=\left|\min\left\{\rho_{A}(\theta),(2j+3)\right\}-\min\left\{\rho_{X}(\theta), (2j+3)\right\}\right|<\eta.
    $$
    Hence $\rho_{A}(\theta)>2j+3-\eta>2j+2$, which is a contradiction. Thus  $j<\rho_X(\theta)<\infty$ and, since $\frac{1}{j}<\rho_A(\theta)\leq j$, we have:
    \begin{align*}
        \left|\min\left\{\rho_{\Phi(A)}(\theta),j\right\}-\min\left\{\rho_{\Phi(X)}(\theta), j\right\}\right|&\leq
        \left|\rho_{\Phi(A)}(\theta)-\rho_{\Phi(X)}(\theta) \right|\\
        &<\left|\rho_{A}(\theta)-\rho_{X}(\theta) \right|\\
        &<\eta<\varepsilon,
    \end{align*}
    for every $\theta\in\mathcal{R}_2$ such that $\rho_X(\theta)>j$.  By putting together the previous inequalities, we have just proved that if $\mathcal{R}_2\neq\emptyset$, then
    \begin{equation}\label{eq:Region2}
        \sup_{\theta\in\mathcal{R}_2}\left|\min\left\{\rho_{\Phi(A)}(\theta),j\right\}-\min\left\{\rho_{\Phi(X)}(\theta), j\right\}\right|\leq\max\left\{\frac{j^2\eta }{1-j\eta}, j^2\eta, \eta\right\}<\varepsilon.
    \end{equation}
    Next, assume that $\mathcal{R}_3\neq\emptyset$ and let $\theta\in \mathcal{R}_3$ be arbitrary. If $\theta\in\mathcal{R}_3$ is such that $\rho_X(\theta)\leq j$, then by Lemma \ref{lemm:axu-calcular-rdAW}-(3), the inequality in (\ref{eq:auxprovecontPhi1}) holds. Hence $\left|\rho_{A}(\theta)-\rho_{X}(\theta)\right|<\eta$ and $\rho_X(\theta)>j-\eta$. Thus $\frac{1}{j}\leq\rho_{\Phi(X)}(\theta)<\frac{1}{j-\eta}<j$, and
    \begin{align*}
        \left|\min\left\{\rho_{\Phi(A)}(\theta),j\right\}-\min\left\{\rho_{\Phi(X)}(\theta), j\right\}\right|&=
        \left|\rho_{\Phi(A)}(\theta)-\rho_{\Phi(X)}(\theta) \right|\\
        &<\frac{1}{j(j-\eta)}\left|\rho_{A}(\theta)-\rho_{X}(\theta) \right|\\
        &<\frac{\eta}{j(j-\eta)}\\
        &<\varepsilon.
    \end{align*}
    The last inequality follows from the fact that $\eta<\frac{\varepsilon}{j^2+j\varepsilon}<\frac{j^2\varepsilon}{1+j\varepsilon}$. 

    For $\theta\in\mathcal{R}_3$ such that $j<\rho_X(\theta)<2j+3$, observe that the inequality (\ref{eq:auxprovecontPhi1}) holds again. Therefore,
    \begin{align*}
        \left|\min\left\{\rho_{\Phi(A)}(\theta),j\right\}-\min\left\{\rho_{\Phi(X)}(\theta), j\right\}\right|&=
        \left|\rho_{\Phi(A)}(\theta)-\rho_{\Phi(X)}(\theta) \right|\\
        &<\frac{1}{j^2}\left|\rho_{A}(\theta)-\rho_{X}(\theta) \right|\\
        &<\frac{\eta}{j^2}<\frac{\varepsilon}{(1+j\varepsilon)}.
    \end{align*}

    Finally, if $\theta\in\mathcal{R}_3$ and $\rho_{X}(\theta)\geq2j+3$, then again by Lemma \ref{lemm:axu-calcular-rdAW}-(3), we have that:
    $$
        \left|\rho_{A}(\theta)-(2j+3)\right|=\left|\min\left\{\rho_{A}(\theta),2j+3\right\}-\min\left\{\rho_{X}(\theta), (2j+3\right\}\right|<\eta
    $$
    Thus $\rho_{A}(\theta)>2j+3-\eta>2j+2$, which yields to:
    \begin{align*}
        \left|\min\left\{\rho_{\Phi(A)}(\theta),j\right\}-\min\left\{\rho_{\Phi(X)}(\theta), j\right\}\right|&=
        \left|\rho_{\Phi(A)}(\theta)-\rho_{\Phi(X)}(\theta) \right|\\
        &<\frac{1}{2j+2}+\frac{1}{2j+3}\\
        &<\frac{1}{j+1}.
    \end{align*}
    By putting together the previous inequalities, we have shown that if $\mathcal{R}_3\neq\emptyset$, then
    \begin{equation}\label{eq:Region3}
        \sup_{\theta\in\mathcal{R}_3}\left|\min\left\{\rho_{\Phi(A)}(\theta),j\right\}-\min\left\{\rho_{\Phi(X)}(\theta), j\right\}\right|\leq\max\left\{\frac{\eta}{j(j-\eta)}, \frac{\eta}{j^2}, \frac{1}{j+1}\right\}
        <\varepsilon.
    \end{equation}    
    For the last region $\mathcal{R}_4$. Notice that from Lemma \ref{lemm:axu-calcular-rdAW}-(3), it follows that:
    $$
    \min\left\{\rho_X(\theta),2j+3\right\}>\min\left\{\rho_A(\theta),2j+3\right\}-\eta=2j+3-\eta>2j+2. 
    $$
    Hence $\rho_X(\theta)>2j+2$ and,
     \begin{align*}
        \left|\min\left\{\rho_{\Phi(A)}(\theta),j\right\}-\min\left\{\rho_{\Phi(X)}(\theta), j\right\}\right|=
        \left|\rho_{\Phi(A)}(\theta)-\rho_{\Phi(X)}(\theta) \right|
        <\frac{1}{j+1}.
    \end{align*}
    Consequently,
    \begin{equation}\label{eq:Region4}
        \sup_{\theta\in\mathcal{R}_4}\left|\min\left\{\rho_{\Phi(A)}(\theta),j\right\}-\min\left\{\rho_{\Phi(X)}(\theta), j\right\}\right|\leq \frac{1}{j+1}
        <\varepsilon.
    \end{equation}
    From Lemma \ref{lemm:axu-calcular-rdAW}-(4) and inequalities  (\ref{eq:Region1}), (\ref{eq:Region2}), (\ref{eq:Region3}) and (\ref{eq:Region4}), we have that  $\delta\left(\Phi(A)\cap jB_2^n,\Phi(X)\cap jB_2^n\right)<\varepsilon$ which is equivalent to 
    $$d_{AW^r}(\Phi(A),\Phi(X))<\varepsilon.$$  
    This proves the continuity of the duality at each $A\in\mathcal{S}_{rc}^d$ as in (3) of this proof.

    To prove continuity of $\Phi$ at each bounded $A\in\mathcal{S}_{rc}^d$. Let $j_A\geq1$ be the smallest integer such that $A\subseteq j_AB_2^d$ and consider  $\varepsilon_1\in\left(\frac{1}{j+1},\frac{1}{j}\right]$, for some integer $j$ such that $j>j_A$. Observe that if we take 
    $$
    0<\eta_1<\min\left\{\frac{1}{2j+3},\frac{\varepsilon_1}{j^2+j\varepsilon_1} \right\},
    $$ 
    then, by (\ref{eq:Src-bouded})), for each $X\in\mathcal{S}_{rc}^d$ with 
    $d_{AW^r}(A,X)<\eta_1$, $X\subseteq2j_AB_2^d$. Hence,
    $\mathcal{R}_4$ and the corresponding subset 
    $$
    \left\{\theta\in\mathbb{S}^{d-1}:\rho_X(\theta)\geq 2j+3 \right\}
    $$ 
    must be empty. Thus, we can proceed as in the proof of the previous case to show that $\delta\left(\Phi(A)\cap jB_2^2,\Phi(X)\cap jB_2^2\right)<\varepsilon_1$. Consequently $d_{AW^r}(\Phi(A),\Phi(X))<\varepsilon_1$, and $\Phi$ is continuous at each $A\in\mathcal{S}_{rc}^d$ bounded.

    % $\mathcal{R}_1,$ $\mathcal{R}_2,$ $\mathcal{R}_3,$ and $\mathcal{R}_4$ as above
    % $d_{AW^r}(\Phi(A),\Phi(X))<\varepsilon_1$. Indeed, by Proposition \ref{prop:subspaces-rdAW}-(3) (see also equation  (\ref{eq:Src-bouded})), we know that $X\in\mathcal{S}_{rc}^d$ must be bounded and that $X\subseteq2j_AB_2^d$. 
