\begin{proposition}\label{prop:flore-discontinuous-dAWr}\begin{enumerate}
    \item The spaces $\left(\mathcal{K}_{0}^d,d_{AW^r}\right)$ and $\left(\mathcal{F}^d,d_{AW^r}\right)$ are homeomorphic.
    \item The flower map $\clubsuit:\left(\mathcal{K}_{0}^d,d_{AW}\right)\rightarrow\left(\mathcal{F}^d,d_{AW^r}\right)$ is not continuous.
\end{enumerate}

\end{proposition}
\begin{proof}
    (1) It follows directly from Theorem \ref{thm:duality-awr-continua}, and the fact that  
    $\Phi\left(\mathcal{F}^d\right)=\mathcal{K}_0^d$ (see \cite[Theorem 9.4]{MMilmanRotem}).

    (2) Let $K,K_n\subseteq\mathbb{R}^2$, $n\in\mathbb{N}$, be defined as $K=[0,1]\times[0,\infty)$ and
    $$
    K_n=K\cup\left\{(x,y)\in\mathbb{R}^2:x\geq1\text{ and } y\geq n(x-1)\right\}.
    $$
    We shall prove that the sequence $(K_n)_n$ converges in $d_{AW}$ to $K$, but $(K^\clubsuit_n)_n$ does not converges to $K^\clubsuit$ in $d_{AW^r}$. The result for an arbitrary dimension will be obtained by considering the embedding $i:\mathbb{R}^2\rightarrow\mathbb{R}^d$, given by $i(x,y)=(x,y,0,\ldots,0)$,  the convex set $i(K)$, and the sequence $(i(K_n))_n$. 

    To prove the $d_{AW}$-convergence of $(K_n)_n$ to $K$, observe that the sequence of distance functionals $(d(\cdot,K_n))_n$ converges pointwise to $d(\cdot,K)$. Since $\tau_W$ and the metric topology induced by $d_{AW}$ agree on $\mathcal{K}_0^d$ (see e.g. \cite[Theorem 3.1.4]{Beer1993}), then $(K_n)_n$ is $d_{AW}$-convergent to $K$. 

    On the other hand, notice that $\rho_{K^\clubsuit}(e_1)=h_K(e_1)=1$. Also, for any $t\geq1$ and $n\geq1$, $(t,nt)\in K_n$. Hence
    $\rho_{K_{n}^\clubsuit}(e_1)\geq t$, which yields to  $\rho_{K_{n}^\clubsuit}(e_1)=\infty$ for all $n$. The latter, in combination with Theorem \ref{thm:caract-rWijsmanTopology}, proves that $(K_{n}^\clubsuit)_n$ does not converge in $\tau_{W^r}$ to $K^\clubsuit$. By Remark \ref{rem:dAWR-stronger-than-Wr}, the sequence $(K_{n}^\clubsuit)_n$ is not $d_{AW^r}$-convergent to $K^\clubsuit$ either. 

    To prove the discontinuity of $\clubsuit:\left(\mathcal{K}_{0}^d,d_{AW}\right)\rightarrow\left(\mathcal{F}^d,d_{AW^r}\right)$ for $d>2$. Notice that $\rho_{(i(K))^\clubsuit}(e_1)=1$ and that $\rho_{(i(K_n))^\clubsuit}(e_1)=\infty$ for all $n$. Moreover, for every integer $j\geq1$, we have that:
    \begin{align*}
    d_H\left(i(K)\cap jB_2^d,i(K_n)\cap jB_2^d\right)&=d_H\left(i\left(K\cap jB_2^2\right),i\left(K_n\cap jB_2^2\right)\right)\\
    &\leq d_H(K\cap jB_2^2,K_n\cap jB_2^2).
    \end{align*}
    Thus,  $d_{AW}\left(i(K),i(K_n)\right)\leq d_{AW}(K,K_n).$
    % \begin{align*}
    % d_{AW}\left(i(K),i(K_n)\right)
    % &=\sup_{j\in\mathbb{N}}\min\left\{\frac{1}{j},d_H\left(i(K)\cap jB_2^d,i(K_n)\cap jB_2^d\right)
    % \right\}\\
    % &\leq\sup_{j\in\mathbb{N}}\min\left\{\frac{1}{j},d_H\left(K\cap jB_2^2,K_n\cap jB_2^2\right)\right\}\\
    % &=d_{AW}(K,K_n).
    % \end{align*}
    Therefore $(i(K_n))_n$ converges, in $d_{AW}$, to $i(K)$, while $\left((i(K_n))^\clubsuit\right)_n$ does not converges to $(i(K))^\clubsuit$ in $d_{AW^r}$. This finishes the proof.     
\end{proof}

