\section{Groups with large elliptic sets}\label{se:gp.lg.ell}

Separation (i.e. being \emph{Hausdorff}, or \emph{$T_2$} \cite[Definition 13.5]{wil_top}) is always assumed for topological groups. The vast majority of the Lie groups of interest below are modeled on finite-dimensional manifolds (as opposed to the \emph{Banach} Lie groups of \cite[\S III.1.1, Definition 1]{bourb_lie_1-3}, \cite[\S VI.5]{lang-fund}, \cite[Definition IV.1]{neeb-inf}, etc.), so finite dimensionality is taken for granted and all departures from it (as far as Lie groups are concerned) will be made explicit.

\begin{remark}\label{re:dense.tors}
  In reference to \cite[Lemma 2]{zbMATH03510594} (recalled in the Introduction), to the effect that torsion subgroups $\Gamma\le \bG$ of connected Lie groups are relatively compact, it is crucial that $\Gamma\le \bG$ be a sub\emph{group} rather than just a sub\emph{set}. It is perfectly possible for a connected, non-compact, Lie group to have dense torsion: \Cref{ex:dns.ell.set}.
\end{remark}

\begin{example}\label{ex:dns.ell.set}
  Consider the semidirect product $\bG:=V\rtimes \bK$ afforded by a representation $\rho:\bK\circlearrowright V$ (which notation refers to a continuous morphism $\bK\xrightarrow{\rho} GL(V)$) of a compact connected Lie group $\bK$ on a f.d. real vector space $V$.

  An element $(v,s)\in V\rtimes \bK$ will be conjugate to one of $\bK$ (and hence elliptic) as soon as $v$ is in the image of $\rho(s)-1\in \End(V)$. It follows that
  \begin{itemize}[wide]
  \item the set of elliptic elements is dense in $\bG$ whenever the trivial weight does not feature in $\rho$.

  \item so the same goes for the set of torsion elements: every elliptic element topologically generates a compact Lie group; all such, in turn, are products of tori and finite abelian groups \cite[Corollary 4.2.6]{de}, so have dense torsion. 
  \end{itemize}
  For the more glib assertions we refer to \Cref{th:no.triv.wt}.
\end{example}

\Cref{ex:dns.ell.set} can in fact be turned into a \emph{characterization} result for representations giving rise to semidirect products with ``large'' sets of elliptic elements. 

\begin{theorem}\label{th:no.triv.wt}
  Let
  \begin{equation}\label{eq:k.by.v}
    \{1\}
    \to
    \left(V\cong \bR^d\right)
    \lhook\joinrel\xrightarrow{\quad}
    \bG
    \xrightarrowdbl{\quad}
    \bK
    \to
    \{1\}
  \end{equation}
  be an extension of a compact connected group $\bK$ by a vector group $V\cong \bR^d$ and denote by $\rho:\bK \circlearrowright V$ the underlying $\bK$-representation. The following conditions are equivalent

  \begin{enumerate}[(a)]

  \item\label{item:th:no.triv.wt:kfr.dns} The subset
    \begin{equation*}
      \bK_{\rho,fr}
      :=
      \left\{s\in \bK\ :\ \rho(s)-1\in GL(V)\text{ is invertible}\right\}
      \subseteq \bK
    \end{equation*}
    of elements acting freely on $V^{\times}:=V\setminus \{0\}$ is dense.

  \item\label{item:th:no.triv.wt:kfr.clstr} $1\in \bK$ is a \emph{cluster point} \cite[Definition 4.9]{wil_top} of $K_{\rho,fr}$.

    % % \item\label{item:th:no.triv.wt:k0fr.dns} The set $\bK_{0,\rho,fr}\subseteq \bK_0$ of the identity component is dense.
    % %   
    % % \item\label{item:th:no.triv.wt:k0fr.clstr} $1\in \bK_0$ is a cluster point for $\bK_{0,\rho,fr}$.
    % %   

  \item\label{item:th:no.triv.wt:tfr.dns} The set $\bT_{\rho,fr}\subseteq \bT$ is dense for every (equivalently, any one) maximal pro-torus $\bT\le \bK$.

  \item\label{item:th:no.triv.wt:tfr.clstr} $1\in \bT$ is a cluster point for $\bT_{\rho,fr}$ for every (any) maximal pro-torus $\bT\le \bK$.

  \item\label{item:th:no.triv.wt:ntw} The weights of $\rho$ with respect to every (any) maximal pro-torus $\bT\le \bK$ are all non-trivial. 

  \item\label{item:th:no.triv.wt:dns.ell} $\bG$ is almost-elliptic in the sense of \Cref{def:ell}\Cref{item:def:ell:alm.ell.set}.

  \item\label{item:th:no.triv.wt:op.dns.ell} $\bG$ is openly almost-elliptic in the sense of \Cref{def:ell}\Cref{item:def:ell:op.alm.ell.set}.
  \end{enumerate}  
\end{theorem}
\begin{proof}
  The statement's groups $\bG$ are precisely the semidirect products $\bG\cong V\rtimes_{\rho}\bK$, since \Cref{eq:k.by.v} always splits (\cite[Th\'eor\`eme 1]{SSL_1954-1955__1__A24_0}, \cite[Exercise 19 for \S III.9]{bourb_lie_1-3}, etc.)

  Observe that all conditions hold vacuously when $V=\{0\}$: everything in sight is elliptic and acts freely on the empty set $V^{\times}$, $\rho$ has no weights at all, etc. We can thus safely henceforth ignore that trivial case and assume $V$ non-zero. Nor is there any harm in assuming $\bK$ Lie whenever convenient, substituting for it the Lie \cite[Theorem I.3.11]{btd_lie_1995} image of $\bK\xrightarrow{\rho}GL(V)$.

  We relegate the purely representation-theoretic mutual equivalence of \Cref{item:th:no.triv.wt:kfr.dns}-\Cref{item:th:no.triv.wt:ntw} to \Cref{pr:rep.content}. To relate those conditions to \Cref{item:th:no.triv.wt:dns.ell} observe first that the subgroup $\bK\le \bG:=V\rtimes_{\rho} \bK$ is maximal compact and conjugate to all such by \cite[\S VII.3, Proposition 3]{bourb_int_7-9_en} (connectedness is irrelevant here), so $(v,s)\in \bG$ is elliptic precisely when conjugate to an element of $\bK\le \bG$. A straightforward computation shows that this translates precisely to
  \begin{equation}\label{eq:v.in.im}
    v\in \im (\rho(s)-1)\le V;
  \end{equation}
  condition \Cref{item:th:no.triv.wt:dns.ell}, then, translates to
  \begin{equation}\label{eq:dns.in.vk}
    \left\{(v,s)\in V\rtimes \bK\ :\ \text{\Cref{eq:v.in.im} holds}\right\}
    \quad
    \overset{\text{dense}}{\subseteq}
    \quad
    V\rtimes \bK.
  \end{equation}
  \begin{enumerate}[label={},wide]
  \item \textbf{\Cref{item:th:no.triv.wt:ntw} $\xRightarrow{\quad}$ \Cref{item:th:no.triv.wt:dns.ell}.} Simply observe that
    \begin{equation*}
      \left\{s\in \bK\ :\ \rho(s)-1\text{ invertible}\right\}
      \subseteq
      \bK
    \end{equation*}
    is dense. For such an $s\in \bK$ \emph{all} $v\in V$ will satisfy \Cref{eq:v.in.im}, hence the conclusion. 

    % % OLD: WRONG CONDITION (NO TRIVIAL SUMMANDS RATHER THAN NO TRIVIAL WEIGHTS)
    % % 
    % % The set of pairs $(v,s)$ satisfying \Cref{eq:v.in.im} is dense if and only if there are $s\in \bK$ for which $\rho(s)-1\in \End(V)$ is onto (in which case this holds for a dense set of $s\in \bK$). Denoting by $V^{\bK}$ denoting the space of $\bK$-invariants in $V$, the conclusion follows from the decomposition
    % % \begin{equation*}
    % %   V
    % %   =
    % %   \left(\sum_{s\in \bK}\im \left(\rho(s)-1\right)\right)
    % %   \bigoplus
    % %   V^{\bK}
    % % \end{equation*}
    % % of \cite[Theorem 3.36(vi)]{hm5}.

  \item \textbf{\Cref{item:th:no.triv.wt:dns.ell} $\xRightarrow{\quad}$ \Cref{item:th:no.triv.wt:ntw}.} We will argue for the contrapositive. The assumption that $\rho$ admits the trivial character of $\bT$ as a weight amounts to saying that all elements of $\bT$ (hence also of $\bK=\bigcup_s s\bT s^{-1}$ \cite[Theorem 9.32(ii)]{hm5}) have 1 as an eigenvalue on $V$.

    Consider an element $s\in \bK$ whose 1-eigenspace on $V$ has minimal dimension, yielding an orthogonal decomposition
    \begin{equation}\label{eq:v.decomp}
      V=\ker\left(1-\rho(s)\right)\oplus \im\left(1-\rho(s)\right)
    \end{equation}
    with respect to a $\bK$-invariant inner product on $V$ fixed beforehand. As noted in \cite[Remark post Proposition 13.4]{salt_divalg}, rank is \emph{lower semicontinuous} \cite[Problem 7K]{wil_top} in families of operators. The assumed maximality of the second-summand dimension in \Cref{eq:v.decomp} then implies (by a version of \cite[Proposition 13.4]{salt_divalg}, say) that the trivial $V$-fibered \emph{bundle} \cite[Definition 4.7.2]{hus_fib} over some small neighborhood $\bK\supseteq U\ni s$ decomposes as a direct sum (or \emph{Whitney sum} \cite[Definition 2.4.2]{hus_fib}) 
    \begin{equation}\label{eq:bdl.split.u}
      U\times V\cong E_{\ker}\oplus E_{\im}
      ,\quad
      \text{fibers}
      \left\{
        \begin{aligned}
          E_{\ker,s'}&=\ker\left(1-\rho(s')\right)\\         
          E_{\im,s'}&=\im\left(1-\rho(s')\right)
        \end{aligned}
      \right.
      ,\quad
      s'\in U
    \end{equation}
    of again trivial bundles. For $s'\in U$ the element
    \begin{equation*}
      \im\left(1-\rho\left(s'\right)\right)
      \in
      \text{\emph{Grassmannian} \cite[\S 15.4]{fh_rep-th} of }V
    \end{equation*}    
    will thus be close to $\im\left(1-\rho\left(s\right)\right)$. Consequently, no element
    \begin{equation*}
      (v,s)\in V\rtimes \bK
      ,\quad
      0\ne v\in \ker\left(1-\rho(s)\right)
    \end{equation*}
    can lie in the closure of the set of elliptic elements.

  \item \textbf{\Cref{item:th:no.triv.wt:op.dns.ell} $\xRightarrow{\quad}$ \Cref{item:th:no.triv.wt:dns.ell}} is obvious.  

  \item \textbf{\Cref{item:th:no.triv.wt:ntw} $\xRightarrow{\quad}$ \Cref{item:th:no.triv.wt:op.dns.ell}.} If $\rho$ carries only non-trivial weights then $\bK_{\rho,fr}\subseteq \bK$ is in fact \emph{open} dense, and for $s\in \bK_{\rho,fr}$ all $(v,s)\in V\rtimes \bK$ are elliptic.
  \end{enumerate}
\end{proof}

\begin{proposition}\label{pr:rep.content}
  Conditions \Cref{item:th:no.triv.wt:kfr.dns}-\Cref{item:th:no.triv.wt:ntw} of \Cref{th:no.triv.wt} are mutually equivalent for any finite-dimensional representation $\rho:\bK\circlearrowright V$ of a compact connected group $\bK$. 
\end{proposition}
\begin{proof}
  Maximal pro-tori are conjugate in $\bK$ \cite[Theorem 9.32(i)]{hm5}, so any of the statements above valid for one will indeed be valid for all; the split-quantifier sentences can thus indeed be treated as single units. 

  The mutual equivalence of conditions \Cref{item:th:no.triv.wt:kfr.dns,item:th:no.triv.wt:kfr.clstr,item:th:no.triv.wt:tfr.dns,item:th:no.triv.wt:tfr.clstr} is summarized in
  \begin{equation*}
    \begin{tikzpicture}[>=stealth,auto,baseline=(current  bounding  box.center)]
      \path[anchor=base] 
      (0,0) node (l) {\Cref{item:th:no.triv.wt:kfr.dns}}
      +(4,1) node (u) {\Cref{item:th:no.triv.wt:kfr.clstr}}
      +(4,-1) node (d) {\Cref{item:th:no.triv.wt:tfr.dns}}
      +(8,0) node (r) {\Cref{item:th:no.triv.wt:tfr.clstr}}
      ;
      \draw[-implies,double equal sign distance] (l) to[bend left=6] node[pos=.5,auto] {$\scriptstyle \text{obvious}$} (u);
      \draw[-implies,double equal sign distance] (u) to[bend left=6] node[pos=.5,auto] {$\scriptstyle \bK=\bigcup_s s\bT s^{-1}$ \cite[Theorem 9.32(ii)]{hm5}} (r);
      \draw[-implies,double equal sign distance] (r) to[bend left=6] node[pos=.5,auto] {$\scriptstyle \text{obvious}$} (u);
      \draw[implies-,double equal sign distance] (l) to[bend right=6] node[pos=.5,auto,swap] {$\scriptstyle  \bK=\bigcup_s s\bT s^{-1}$ \cite[Theorem 9.32(ii)]{hm5}} (d);
      \draw[-implies,double equal sign distance] (d) to[bend right=6] node[pos=.5,auto] {$\scriptstyle \text{obvious}$} (r);
      \draw[-implies,double equal sign distance] (r) to[bend left=60] node[pos=.5,auto,swap] {$\scriptstyle \text{\Cref{eq:sml.ne1.eigs}}$} (d);
    \end{tikzpicture}
  \end{equation*}
  given
  \begin{equation}\label{eq:sml.ne1.eigs}
    \forall\left(T\in U(n)\right)
    \exists\left(\varepsilon>0\right)
    \quad:\quad
    \left.
      \begin{aligned}
        \|S&-1\|<\varepsilon\\
        ST&=TS\\
        S-1&\text{ invertible}
      \end{aligned}
    \right\}
    \xRightarrow{\quad}
    ST-1\text{ invertible}.
  \end{equation}
  The equivalence \Cref{item:th:no.triv.wt:tfr.clstr} $\iff$ \Cref{item:th:no.triv.wt:ntw} is also self-evident: the elements of $\bT$ where any one of the finitely many non-trivial $\bT$-weights of $\rho$ is non-trivial constitute an open dense subset, so their intersection is dense as well.
\end{proof}

Dropping the connectedness assumption on $\bK$ in \Cref{th:no.triv.wt} will render the implication \Cref{item:th:no.triv.wt:ntw} $\Rightarrow$ \Cref{item:th:no.triv.wt:dns.ell} generally invalid.

\begin{example}\label{ex:z2.act.inv}
  Take for $\bK$ a semidirect product $\bT\rtimes \left(\bZ/2\right)$ for a torus $\bT$ acted upon by $\bZ/2$ by inversion: the generator $\sigma\in \bZ/2$ interchanges $z^{\pm 1}\in \bT$.

  One can easily arrange for $\rho|_{\bT}$ to have no trivial summands (so that \Cref{item:th:no.triv.wt:ntw} holds). $\rho(\sigma)\in GL(V)$ is a non-scalar reflection, and $\rho\left(\bT\sigma\right)$ consists entirely of conjugates thereof. It follows that no
  \begin{equation*}
    (v,\sigma)
    ,\quad
    0\ne v\in V
    ,\quad
    \rho(\sigma)v=v
  \end{equation*}
  can be approximated arbitrarily by elements $(v,s)$ satisfying \Cref{eq:v.in.im}.
\end{example}

\begin{remark}\label{re:g0.not.enough}
  \Cref{ex:z2.act.inv} also shows that the property of having a dense set of elliptic elements, for a Lie group with finitely many components, cannot be checked only on the identity component. Or again: said property is not invariant under finite extensions.
\end{remark}

In part, the proof of \Cref{th:no.triv.wt} does go through for disconnected $\bK$; we isolate the statement for future use. 

\begin{lemma}\label{le:alm.surj.cbd}
  Let \Cref{eq:k.by.l} be an extension of a compact group $\bK$ by solvable Lie, connected, simply-connected $\bL$.

  \begin{enumerate}[(1)]
  \item\label{item:le:alm.surj.cbd:set} For any maximal compact $\bM\le \bG$, the elliptic elements in $\bG$ are 
    \begin{equation}\label{eq:vxx}
      \left\{(v,s)\in \bL\rtimes \bM\cong \bL\cdot \bM\subseteq \bG\ :\ \exists \left(x\in \bL\right)\left(x^{-1}\cdot \Ad_s x=v\right)\right\}.
    \end{equation}

  \item\label{item:le:alm.surj.cbd:dns} In particular, $\bG$ is almost-elliptic if and only if for any (equivalently, all) maximal compact $\bM\le \bG$ the set \Cref{eq:vxx} is dense in $\bG$.
  \end{enumerate}
\end{lemma}
\begin{proof}
  The extension \Cref{eq:k.by.l} splits \cite[Exercise 19 for \S III.9]{bourb_lie_1-3} as $\bG\cong \bL\rtimes \bK$, so the maximal compact subgroups of $\bG$ are the conjugates \cite[Theorems A, B and C]{zbMATH00540631} of any such semidirect factor $\bK$. The conclusion thus follows by the argument casting condition \Cref{item:th:no.triv.wt:dns.ell} of \Cref{th:no.triv.wt} as \Cref{eq:dns.in.vk}. 
\end{proof}

\Cref{re:g0.not.enough} notwithstanding, there are some simple permanence results for almost-ellipticity which we record for whatever use they possess; we omit the proofs and henceforth take them for granted.

\begin{lemma}\label{le:alm.ell.perm}
  \begin{enumerate}[(1)]
  \item\label{item:le:alm.ell.perm:quot.opn} For any topological group $\bG$, quotients and open subgroups are (openly) almost-elliptic as soon as $\bG$ is respectively so.

  \item\label{item:le:alm.ell.perm:ell.in.quot} An element of $\bG$ is elliptic if and only if its image in any (some) quotient $\bG/\bK$ by a compact normal subgroup is elliptic. 

  \item\label{item:le:alm.ell.perm:quot.by.cpct} In particular, if $\bK\trianglelefteq \bG$ is compact and normal then $\bG$ is (openly) almost-elliptic if and only if $\bG/\bK$ is respectively so.  \qedhere
  \end{enumerate}
\end{lemma}

We record the following immediate consequence, reducing almost-ellipticity for sufficiently well-behaved locally compact groups to the Lie-group setup. We remind the reader that a topological group $\bG$ is \emph{almost-connected} (e.g. \cite[Preface, p.xvii, Definition 34]{hm5}) is the quotient $\bG/\bG_0$ by its identity connected component is compact.

\begin{corollary}\label{cor:lie.enough}
  An almost-connected locally compact group is (openly) almost elliptic if and only if any one of the following mutually-equivalent conditions holds respectively. 
  \begin{itemize}[wide]
  \item It is a \emph{cofiltered limit} \spr{04AY} of (openly) almost-elliptic Lie groups.

  \item Every compact-kernel Lie quotient of $\bG$ is (openly) almost-elliptic. 

  \item At least one compact-kernel Lie quotient of $\bG$ is (openly) almost-elliptic. 
  \end{itemize}
\end{corollary}
\begin{proof}
  This follows from \Cref{le:alm.ell.perm}\Cref{item:le:alm.ell.perm:quot.by.cpct}, given that almost-connected locally compact groups are the cofiltered limits of their Lie quotients with compact kernels (\cite[\S 4.6, Theorem]{mz} and \cite[Theorem 3.39]{hm_pro-lie-bk}, say). 
\end{proof}

Another sufficient condition for almost-ellipticity inheritance is as follows.

\begin{proposition}\label{pr:gmodl2g}
  Let $\bG$ be an almost-connected locally compact group and $\bL\trianglelefteq \bG$ normal closed.

  $\bG$ is almost elliptic provided $\bG/\bL$ is, along with all (equivalently, any one) subgroup of $\bG$ of the form
    \begin{equation}\label{eq:preim.max.cpct}
      \pi^{-1}\left(\bK\right)
      ,\quad
      \bG\xrightarrowdbl{\quad\pi\quad}\bG/\bL
      ,\quad
      \bK\le \bG/\bL\text{ maximal compact}.
    \end{equation}
\end{proposition}
\begin{proof}
  Almost-connected locally compact groups have maximal compact subgroups, all mutually conjugate, and automatically connected (\cite[\S 4.13, first Theorem]{mz}, \cite[Theorems A, B and C]{zbMATH00540631}. etc.); it follows that `any' and `every' are indeed interchangeable in \Cref{eq:preim.max.cpct}.

  The image $\overline{x}\in \bG/\bL$ of any $x\in \bG$ is by assumption arbitrarily approximable by elements belonging to compact $\bK\le \bG/\bL$, which subgroups may as well be assumed maximal. This means that $x$ is arbitrarily close to elements belonging to subgroups $\pi^{-1}\left(\bK\right)$; in turn, those elements are close to compact subgroups of $\pi^{-1}(\bK)$ (hence also of $\bG$).
\end{proof}

In the much same spirit, the implication of \Cref{pr:gmodl2g} can occasionally be reversed.

\begin{theorem}\label{th:ext.by.rd.perm}
  Let $\bG$ be a connected locally compact group and $\bL\trianglelefteq \bG$ a normal closed vector subgroup.

  $\bG$ is almost elliptic if and only if $\bG/\bL$ is, along with all (equivalently, any one) subgroup of $\bG$ of the form \Cref{eq:preim.max.cpct}. 
\end{theorem}
\begin{proof}
  It will be harmless (\Cref{cor:lie.enough}) to assume $\bG$ Lie. The backward implication is covered by \Cref{pr:gmodl2g}, and by \Cref{le:alm.ell.perm}\Cref{item:le:alm.ell.perm:quot.by.cpct} the quotient $\bG/\bL$ certainly is almost-elliptic whenever $\bG$ is; the more substantive claim is the almost-ellipticity of all (equivalently, at least one, by mutual conjugacy) $\pi^{-1}(\bK)$, assuming that of $\bG$.

  We have a splitting
 \begin{equation*}
   \pi^{-1}(\bK)
   \cong
   \bL\rtimes \bK
   \quad
   \left(\text{\cite[Th\'eor\`eme 1]{SSL_1954-1955__1__A24_0}, \cite[Exercise 19 for \S III.9]{bourb_lie_1-3}, etc.}\right),
 \end{equation*}
 so \Cref{th:no.triv.wt} applies: the claim is that $\bK$ operates on $\bL\cong \bR^d$ with no trivial weights. Assume otherwise, and (as in the proof of \Cref{th:no.triv.wt}) consider an element
 \begin{equation*}
   (v,s)\in \pi^{-1}(\bK)\cong \bL\rtimes \bK
   ,\quad
   v\ne 0
   ,\quad
   sv=v
 \end{equation*}
 with $s\in \bK$ having minimal-dimensional 1-eigenspace and a convergent \emph{net} \cite[Definition 11.2]{wil_top}
 \begin{equation*}
   \bG\ni
   \text{ elliptic }
   t_{\alpha}
   \xrightarrow[\quad\alpha\quad]{\quad}
   (v,s)
   \in \pi^{-1}(\bK)\le \bG.
 \end{equation*}
 The quotient $\bG/\bL$ operates on $\bL$ (for the latter is abelian), and we conflate the elements $\pi(t)$, $t\in \bG$ with the operators they induce on $\bL$. Moreover, by \Cref{th:sel.cj}\Cref{item:th:sel.cj:prx.el} below, $t_{\alpha}$ can be assumed respectively conjugate by $u_{\alpha}\xrightarrow[\alpha]{}1$ to elements in $\pi^{-1}(\bK)\cong \bL\rtimes \bK$; we thus assume $t_{\alpha}\in \pi^{-1}(\bK)$.

 The elliptic $\pi(t_{\alpha})$ are all semisimple and hence
 \begin{equation}\label{eq:im.t}
   \im\left(1-\pi(t_{\alpha})\right)|_{\bL_{\bC}:=\bL\otimes_{\bR}\bC}
   =
   \bigoplus_{\lambda\ne 1} \ker\left(\lambda-\pi(t_{\alpha})\right). 
 \end{equation}
 The convergence $\pi(t_{\alpha})\xrightarrow[\alpha]{}s$ entails \cite[Theorem 3]{Newburgh} spectrum convergence, so for the $\lambda\ne 1$ of \Cref{eq:im.t} we have
 \begin{equation}\label{eq:ll0}
   \forall\left(\varepsilon>0\right)
   \ 
   \exists\left(1\ne \lambda_0\in\text{spectrum of }s\right)
   \quad:\quad
   |\lambda-\lambda_0|<\varepsilon
   \text{ for large $\alpha$}.
 \end{equation}
 The assumed ellipticity of $t_{\alpha}$ implies
 \begin{equation*}
   v_{\alpha}\overset{\text{cf. \Cref{eq:v.in.im}}}{\in} \im\left(1-t_{\alpha}\right)
   \xRightarrow[\quad]{\quad\text{\Cref{eq:ll0}}\quad}
   \pi(t_{\alpha})v_{\alpha}-v_{\alpha}
   \text{ bounded away from 0}.
 \end{equation*}
 This contradicts the convergence $t_{\alpha}\xrightarrow[\alpha]{}(v,s)$, given that $sv=v$.
\end{proof}

An \emph{almost-containment} $V\succeq U$ in a topological space means that $V$ contains an open dense subset of $U$. Denoting interiors by `$\circ$' decorations, $V=\overset{\circ}{V}\succeq U$ then says that $V$ is an open \emph{almost-neighborhood} of $U$.  

\begin{theorem}\label{th:sel.cj}
  Let $\bK\le \bG$ be a maximal compact subgroup of a connected locally compact group. 

  \begin{enumerate}[(1)]

  \item\label{item:th:sel.cj:prx.gp} We have
    \begin{equation*}
      \forall\left(V=\overset{\circ}{V}\supseteq \bK\right)
      \exists\left(U=\overset{\circ}{U}\succeq \bK\right)
      \forall\left(\text{elliptic }t\in U\right)
      \quad:\quad
      \Braket{t}\subseteq V,
    \end{equation*}
    with $\Braket{\bullet}$ denoting generated subgroups. 

  \item\label{item:th:sel.cj:prx.el} There is a function
    \begin{equation*}
      \left(U=\overset{\circ}{U}\succeq \bK\right)
      \xrightarrow[\quad\text{continuous at 1}\quad]{\quad u_{\bullet}\quad}
      \bG
      \quad\text{with}\quad
      \left\{
        \begin{aligned}
          u_1
          &=1\\
          \Ad_{u_t} t
          &\in \bK
            ,\quad
            \forall\text{ elliptic }t\in U.
        \end{aligned}
      \right.
    \end{equation*}
  \end{enumerate} 
\end{theorem}
\begin{proof}
  Recall the usual approximation argument \cite[\S 4.6, Theorem]{mz}: $\bG$ has arbitrarily small normal compact subgroups with Lie quotients. This allows the standing assumption that $\bG$ is Lie.

  By \cite[Theorem 1 and Corollary]{MR6545} compact subgroups contained in sufficiently small neighborhoods of $\bK$ are conjugate to subgroups of $\bK$ by elements close to $1\in \bG$ (see also \cite[Theorem 3.4]{Chirvasitu2024} for the \emph{Banach}-Lie-group version of that result). \Cref{item:th:sel.cj:prx.el}, consequently, reduces to \Cref{item:th:sel.cj:prx.gp}. The rest of the proof focuses on the latter: the claim is that elliptic elements in judiciously-chosen almost-neighborhoods of $\bK\le \bG$ generate subgroups arbitrarily close to $\bK$.

  % % $\bK$ being the union of its maximal tori \cite[Theorem 9.32(ii)]{hm5}, every convergent net
  % % \begin{equation*}
  % %   t_{\alpha}
  % %   \xrightarrow[\quad\alpha\quad]{\quad\text{\emph{upper Vietoris topology} \cite[\S 1.2]{ct_vietoris}}\quad}
  % %   \bK
  % % \end{equation*}
  % % will contain subnets converging to maximal tori. Since the latter are mutually conjugate, there is no loss in substituting for $\bK$ a fixed maximal torus $\bT\le \bK$ whenever convenient. 
  % % 

  \begin{enumerate}[(I),wide]
  \item \textbf{: reduction to the linear case.} Recall \cite[Definition 5.32]{hm5} that Lie groups are \emph{linear} when they embed into $\mathrm{GL}(n,\bC)$; under the present (almost-)connected assumption the embedding can always be assumed closed (e.g. \cite[Proposition 5]{0801.4234v1}).

    One can always substitute for $\bG$ the image $\Ad(\bG)$ of its adjoint representation
    \begin{equation*}
      \bG
      \xrightarrow{\quad\Ad\quad}
      \mathrm{GL}(\fg)
      ,\quad
      \fg:=Lie(\bG).
    \end{equation*}
    Indeed, if the conclusion (\Cref{item:th:sel.cj:prx.gp} and hence also \Cref{item:th:sel.cj:prx.el}, as noted) is known to hold for $\Ad(\bG)$, then elliptic $t\in \bG$ sufficiently close to $\bK$ can be conjugated into $\bK\cdot \ker\Ad$ by elements close to $1\in \bG$. The conclusion follows from the fact that for \emph{central} closed $\bH\le \bG$ the identity component $\left(\bH\cdot \bK\right)_0$ of $\bH\cdot \bK$ contains $\bK$ as its \emph{unique} maximal compact subgroup.

  \item \textbf{: the linear case.} We can now assume $\bG$ to be a closed subgroup of some $\mathrm{GL}(\bC^n)$. The desired open sets $U$ will range over neighborhoods of
    \begin{equation*}
      \bK_{gen}
      :=
      \left\{s\in \bK\ :\ s\text{ \emph{generic} with respect to the embedding }\bK\le \mathrm{GL}(n,\bC)\right\}
      \overset{\text{open dense}}{\subseteq}
      \bK:
    \end{equation*}
    the weights of the underlying $\bK$-representation on $\bC^n$ take distinct values on $s$ (no matter how one realizes $s$ as an element of a maximal torus $\bT\le \bK$). Equivalently, the genericity condition says simply that the \emph{isotypic components} \cite[post Proposition II.1.14]{btd_lie_1995} of $\bC^n$ with respect to $\overline{\Braket{s}}$ coincide with those of $\bT\ni s$ for any maximal torus $\bT\le \bK$.

    For generic $s\in \bK_{gen}$ the ambient space $\bC^n$ decomposes as
    \begin{equation}\label{eq:c.wt.sp}
      \bC^n=\bigoplus_{i=1}^d \bC^n_{s,i}
      ,\quad
      \bC^n_{s,i}\text{ the weight spaces of }\Braket{s},
    \end{equation}
    with genericity ensuring this is also the weight-space decomposition for any maximal torus $\bK\ge \bT$ containing $s$. Such a torus can be identified with $\bT^d\cong\left(\bS^1\right)^d$, each circle factor respectively acting as scalars on one of the $\bC^n_{s,i}$ summands. 

    Elliptic elements $t\in \bG$ sufficiently close to $s$ will again be generic (relative to maximal compact subgroups containing them), and will induce analogous decompositions $\bC^n=\bigoplus_{i=1}^d \bC^n_{t,i}$ (same $d$). Closeness $t\simeq s$ means closeness
    \begin{equation*}
      \forall\left(1\le i\le d\right)
      \quad:\quad
      \bC^n_{t,i}\simeq \bC^n_{s,i}
    \end{equation*}
    in the respective Grassmannians of $\bC^n$, hence $T\simeq 1\in \mathrm{GL}(n,\bC)$ conjugating $t$ inside the torus $\bT^d\cong \bT$ identified above, acting diagonally with respect to \Cref{eq:c.wt.sp}.
  \end{enumerate}
\end{proof}

\begin{remark}\label{re:alm.nbhd.nec}
  The various caveats in the statement of \Cref{th:sel.cj} are certainly not all redundant. The maximality of $\bK$, for instance, does play a role: the statement does not hold for embeddings
  \begin{equation*}
    \bK:=\bS^1\le \bT^2:=\left(\bS^1\right)^2=:\bG,
  \end{equation*}
  given that the set
  \begin{equation*}
    \left\{t\in \bT^2\ :\ \overline{\Braket{t}}=\bT^2\right\}
    \subseteq
    \bT^2
  \end{equation*}
  of \emph{topological generators} is dense \cite[Theorem IV.2.11(ii)]{btd_lie_1995}, so every $s\in \bS^1$ is arbitrarily approximable by (elliptic) elements topologically generating groups $\overline{\Braket{t}}$ \emph{not} close to $\bS^1$ in the \emph{upper Vietoris topology} \cite[\S 1.2]{ct_vietoris}.

  On the other hand, \Cref{ex:alm.nbhd.nec} below shows that one cannot generally strengthen the almost-containment $U\succeq \bK$ of \Cref{th:sel.cj}\Cref{item:th:sel.cj:prx.gp} to actual containment. 
\end{remark}

\begin{example}\label{ex:alm.nbhd.nec}
  Set
  \begin{equation*}
    \bK
    :=
    \text{unitary group }\bU(n)
    \le
    \bG
    :=
    \mathrm{GL}(n,\bC).
  \end{equation*}
  Consider decompositions $\bC^n=\bC^{n-1}\oplus \ell$ for lines $\ell$ approaching $\bC^{n-1}$ in he sense that
  \begin{equation*}
    \ell
    \xrightarrow{\quad\text{upper Vietoris}\quad}
    \bP \bC^{n-1}
    \subset
    \bP \bC^n
    ,\quad
    \bP\bullet:=\text{projective space of lines in $\bullet$}. 
  \end{equation*}
  The operators $t_{\ell,\lambda}$ with
  \begin{equation*}
    \begin{aligned}
      \ker\left(1-t_{\ell,\lambda}\right)
      &=
        \bC^{n-1}\\
      \ker\left(\lambda-t_{\ell,\lambda}\right)
      &=
        \ell
    \end{aligned}
    ,\quad
    \lambda\in \bS^1
  \end{equation*}
  are all elliptic, and approach $1\in \bK$ if $\lambda\to 1$ sufficiently fast. On the other hand, if $\lambda\ne 1$ we have $|\lambda^k-1|\ge \sqrt 3$ for some $k$, so that
  \begin{equation*}
    \lim_{\ell}\sup_{k}\left\|t^k_{\lambda,\ell}-1\right\|
    =
    \lim_{\ell}\sup_{k}\left\|t_{\lambda^k,\ell}-1\right\|
    =\infty.
  \end{equation*}
  In particular, the groups $\Braket{t_{\ell,\lambda}}$ will never be contained in a sufficiently small neighborhood of $\bK=\bU(n)$. 
\end{example}

\pf{thn:conn.cpct.by.ss.solv}
\begin{thn:conn.cpct.by.ss.solv}
  As observed in the proof of \Cref{le:alm.surj.cbd}, \Cref{eq:k.by.l} splits and the resulting non-normal semidirect factors are all maximal compact and mutually conjugate, so we can fix a decomposition $\bG\cong \bL\rtimes \bK$ once and for all and identify all of the statement's $\bM$ with the single $\bK$. 

  Proposition \Cref{pr:rep.content} handles the mutual equivalence of conditions \Cref{item:thn:conn.cpct.by.ss.solv:kfr.dns}-\Cref{item:thn:conn.cpct.by.ss.solv:ntw}; denoting that cluster of claims by `$\left(\cat{rep}\right)$', we are left having to prove the unmarked implications in
  \begin{equation*}
    \begin{tikzpicture}[>=stealth,auto,baseline=(current  bounding  box.center)]
      \path[anchor=base] 
      (0,0) node (l) {$\left(\cat{rep}\right)$}
      +(2,.7) node (u) {\Cref{item:thn:conn.cpct.by.ss.solv:op.dns.ell}}
      +(2,-.7) node (d) {\Cref{item:thn:conn.cpct.by.ss.solv:dns.ell}}
      ;
      \draw[-implies,double equal sign distance] (l) to[bend left=20] node[pos=.5,auto] {$\scriptstyle $} (u);
      \draw[-implies,double equal sign distance] (u) to[bend left=20] node[pos=.5,auto] {$\scriptstyle \text{obvious}$} (d);
      \draw[-implies,double equal sign distance] (d) to[bend left=20] node[pos=.5,auto,swap] {$\scriptstyle $} (l);
    \end{tikzpicture}
  \end{equation*}

  \begin{enumerate}[label={},wide]
  \item \textbf{$\left(\cat{rep}\right)$ $\xRightarrow{\quad}$ \Cref{item:thn:conn.cpct.by.ss.solv:op.dns.ell}.} \Cref{le:all.cbdr} shows that
  \begin{equation*}
    \left(\forall s\in \bK\right)
    \left(
      1-\Ad_s\text{ invertible}
      \xRightarrow{\quad}
      \left\{x^{-1}\cdot \Ad_s x\ :\ x\in \bL\right\}
      =
      \bL
    \right).
  \end{equation*}
  The conclusion then follows from \Cref{le:alm.surj.cbd}\Cref{item:le:alm.surj.cbd:set}, given that the set of $s\in \bK$ with invertible $1-\Ad_s$ is (assuming $\left(\cat{rep}\right)$) open dense. 

  \item \textbf{\Cref{item:thn:conn.cpct.by.ss.solv:dns.ell} $\xRightarrow{\quad}$ $\left(\cat{rep}\right)$.} We argue by induction on the length of the closed derived series $\left(\bL^{((n))}\right)_{n}$ (consisting of \emph{characteristic} \cite[p.104, Definition preceding Lemma 5.20]{rot-gp}, hence $\bK$-invariant closed normal subgroups of $\bL$).

    The base case of the induction is that of abelian $\bL$, taken care of by \Cref{th:no.triv.wt}. Denote next by $\bA\trianglelefteq \bL$ the bottom layer $\bA:=\bL^{((\mathrm{max}))}$ of the derived series. The almost-ellipticity of $\bG/\bA$ (\Cref{le:alm.ell.perm}\Cref{item:le:alm.ell.perm:quot.opn}) and the induction hypothesis imply $\left(\cat{rep}\right)$ for $\Ad:\bK\circlearrowright \fl/\fa$, with $\fl:=Lie(\bL)$ and $\fa:=Lie(\bA)$. 

    Call $s\in \bK$ as \emph{non-degenerate (on $\fl$)} if $\dim\ker\left(1-\Ad_s|_{\fl}\right)$ is minimal among such dimensions when ranging over $\bK$. The induction hypothesis further allows the assumption that
    \begin{equation*}
      \ker\left(1-\Ad_s|_{\fl}\right)
      =
      \ker\left(1-\Ad_s|_{\fa}\right),
    \end{equation*}
    so the goal is to show that in fact non-degenerate $s\in \bK$ have no 1-eigenvectors in $\fa$ (they have none in $\fl/\fa$ in any case). The set $\bK_{ndg}\subseteq \bK$ of non-degenerate elements is open, and over $\bK_{ndg}$ the trivial bundle with fiber $\bL$ decomposes as a \emph{fiber product} \cite[Definition 2.4.2]{hus_fib}
    \begin{equation*}
      \bK_{ndg}\times \bL
      \cong
      E_{\mathrm{fix}}
      \times_{\bK_{ndg}}
      E_{\mathrm{ess}}
      ,\quad
      \text{fibers}
      \left\{
        \begin{aligned}
          E_{\mathrm{fix},s'}&=\bL^{s'}:=\left\{g\in \bL\ :\ \Ad_{s'}g=g\right\}\\         
          E_{\mathrm{ess},s'}&=\im\left(g\xmapsto{\quad} g^{-1}\cdot \Ad_{s'}g\right)
        \end{aligned}
      \right.
      ,\quad
      s'\in \bK_{ndg}
    \end{equation*}
    (non-linear analogue of \Cref{eq:bdl.split.u}).

    It follows that $(g,s)\in \bL\rtimes \bK$ with non-trivial $g\in \bA\le \bL$ fixed by $s\in \bK_{ndg}$ cannot be approximated arbitrarily by elements
    \begin{equation*}
      (g',s')\in \bL\rtimes \bK
      ,\quad
      g'\in E_{\mathrm{ell},s'},
    \end{equation*}
    yielding the conclusion: by \Cref{le:alm.surj.cbd}\Cref{item:le:alm.surj.cbd:set}, said elements are precisely the elliptic ones.  \qedhere
  \end{enumerate}
\end{thn:conn.cpct.by.ss.solv}

\begin{lemma}\label{le:all.cbdr}
  Let $\bL$ be a connected, simply-connected solvable Lie group and $\varphi\in \Aut(\bL)$ with $1-\varphi$ invertible on $\fl:=Lie(\bL)$.

  The map
  \begin{equation*}
    \bL\ni s
    \xmapsto{\quad\delta=\delta_{\varphi}\quad}
    s^{-1}\cdot \varphi(s)
    \in \bL
  \end{equation*}
  is onto. 
\end{lemma}
\begin{proof}
  Identifying tangent spaces
  \begin{equation*}
    T_1 \bL
    \xrightarrow[\quad\cong\quad]{\quad\text{right translation }R_{g*}\quad}
    T_g \bL
    ,\quad
    g\in \bL,
  \end{equation*}
  the differential of $\delta$ at a generic point $s\in \bL$ is
  \begin{equation*}
    T_s\bL\ni
    v
    \xmapsto{\quad D\delta \quad}
    R_{\varphi(s)*}\Ad_{s^{-1}}\left(\varphi(v)-v\right)
    \in
    T_{\varphi(s)}\bL.
  \end{equation*}
  This is by assumption bijective, so $\delta$ is at any rate a local diffeomorphism \cite[Theorem 4.5]{lee2013introduction}.  

  The rest of the argument is inductive on the length of the closed derived series
  \begin{equation*}
    \bL=\bL^{((0))}
    \ge
    \bL^{((1))}
    \ge
    \cdots
    \ge
    \bA:=\bL^{((\mathrm{max}))}
    \gneq
    \{1\},
  \end{equation*}
  the base case (of abelian $\bL$) being clear. The induction hypothesis now delivers the conclusion for $\bL/\bA$, so that the composition
  \begin{equation*}
    \bL
    \xrightarrow{\quad\delta_{\varphi}\quad}
    \bL
    \xrightarrow{\quad\pi\quad}
    \bL/\bA
  \end{equation*}
  is onto. Observe also that
  \begin{equation*}
    \forall \left(a\in \bA\right)
    \forall\left(s\in \bL\right)
    \quad:\quad
    \delta(as)=\Ad_{s^{-1}}\left(\delta a\right)\cdot \delta s,
  \end{equation*}
  so $\im\delta\subset \bL$ is an open submanifold, surjecting onto $\bL/\bA$, and invariant under left translation by $\bA$. This suffices to conclude that $\im\delta=\bL$.
\end{proof}

