\begin{proposition}\label{pr:lc.alm.conn.max.cpct.inv}
  A compact group $\bK$ acting continuously on a locally compact almost-connected group $\bG$ leaves invariant some maximal compact subgroup thereof. 
\end{proposition}
\begin{proof}
  Consider the (still locally compact, almost-connected) semidirect product $\widetilde{\bG}:=\bG\rtimes \bK$. By \cite[Lemma 3.10(i)]{zbMATH00540631} it has a maximal compact subgroup $\widetilde{\bM}$, which may as well be assumed to contain $\bK$; it follows that
  \begin{equation*}
    \widetilde{\bM}
    =
    \bM\cdot \bK
    \cong
    \bM\rtimes \bK
    ,\quad
    \bM:=\widetilde{\bM}\cap \bG,
  \end{equation*}
  and I claim that $\bM$ is maximal compact in $\bG$; the conclusion will then follow from the $\bK$-invariance of $\bM$. It thus remains to verify the claimed maximality of the compact subgroup $\bM\le \bG$. The only hypotheses needed will be
  \begin{itemize}[wide]
  \item the normality of $\bG\trianglelefteq\widetilde{\bG}$ (the semidirect-product decomposition of the larger group being irrelevant);

  \item and the fact that $\widetilde{\bM}\le \widetilde{\bG}$ is maximal compact with $\widetilde{\bG}=\bG\cdot \widetilde{\bM}$. 
  \end{itemize}

  % % OLD: ATTEMPTED DIRECT APPROACH VIA \cite[Lemma 3.10]{zbMATH00540631}
  % % 
  % % Note first that by \cite[Lemma 3.10(i)]{zbMATH00540631} $\widetilde{\bM}\cap \bG\rtimes \bK_0$ is maximal compact in the latter semidirect product, so there is no loss in assuming $\bK$ connected. Since moreover
  % % \begin{equation*}
  % %   \bG\cdot \bK
  % %   =
  % %   \widetilde{\bG}
  % %   \xlongequal[\quad]{\quad\text{\cite[Lemma 3.10(i)]{zbMATH00540631}}\quad}
  % %   \widetilde{\bG}_0 \cdot \widetilde{\bM}
  % %   =
  % %   \bG_0\cdot \bM\cdot \bK
  % %   \quad
  % %   \xRightarrow{\quad}
  % %   \quad
  % %   \bG
  % %   =
  % %   \bG_0\cdot \bM,
  % % \end{equation*}
  % % it will be enough by \cite[Lemma 3.10(iii)]{zbMATH00540631} to argue that $\bM_0$ is maximal compact in $\bG_0$. Noting that
  % % \begin{equation*}
  % %   \widetilde{\bM}\cap \widetilde{\bG}_0
  % %   \xlongequal[\quad]{\quad\text{\cite[Lemma 3.10(ii)]{zbMATH00540631}}\quad}
  % %   \widetilde{\bM}_0
  % %   \xlongequal[\quad]{\quad\text{$\bK$ is connected}\quad}
  % %   \bM_0\cdot \bK\cong \bM_0\rtimes \bK,
  % % \end{equation*}
  % % it follows that $\bM_0=\bM\cap \bG_0$ and we can assume $\bG$ connected as well. 
  % % 

  Recall first \cite[\S 4.6, Theorem]{mz} that $\widetilde{\bG}$ is \emph{pro-lie} in the sense of \cite[\S 1]{hm_pro-lie-struct}: the inverse limit of its Lie quotients; in particular $\bG$ is the inverse limit of its Lie quotients $\bK$-equivariantly, so it will suffice, for our present purposes, to assume $\bG$ Lie to begin with. Now,
  \begin{equation}\label{eq:grd}
    \bG/\bM
    \quad\cong\quad
    \bG\cdot \widetilde{\bM}/\widetilde{\bM}
    =
    \widetilde{\bG}/\widetilde{\bM}
    \quad\cong\quad
    \bR^d
    \quad
    \left(\text{homeomorphism}\right)
  \end{equation}
  for some $d\in \bZ_{\ge 0}$ by \cite[Theorem C]{zbMATH00540631} (applicable to almost-connected locally compact groups, as observed in the course of the proof of \cite[Lemma 3.10]{zbMATH00540631}). On the other hand, let $\overline{\bM}\le \bG$ be maximal compact containing $\bM$ (one such does exist by \cite[Lemma 3.10(i)]{zbMATH00540631}). The same \cite[Theorem C]{zbMATH00540631} gives
  \begin{equation}\label{eq:gre}
    \bG/\bM
    \quad\cong\quad
    \bG/\overline\bM\times \overline{\bM}/\bM
    \quad\cong\quad
    \bR^e\times \left(\text{compact manifold }\overline{\bM}/\bM\right)
    ,\quad
    e\in \bZ_{\ge 0}. 
  \end{equation}
  Compact boundary-less $(d-e)$-manifolds have non-trivial $\bZ/2$-valued cohomology in the top degree $d-e$ \cite[Corollary VI.7.14]{bred_gt_1997}, so \Cref{eq:grd,eq:gre} jointly imply that $\bM=\overline{\bM}$. 
\end{proof}

\begin{remarks}\label{res:inv.cpct.sbgps}
  \begin{enumerate}[(1),wide]
  \item There are many variations on the theme of \Cref{pr:lc.alm.conn.max.cpct.inv} in the literature: 
    \begin{itemize}[wide]
    \item Per \cite[\S 6, Lemme]{SB_1956-1958__4__73_0} (or \cite[Exercise VI.A.8(i)]{helg_dglgssp}, or \cite[Proposition 2.14]{hm_pro-lie-struct}), compact automorphism groups of semisimple Lie groups leave invariant maximal compact subgroups thereof. The first two sources rely on a fixed-point result for actions on negatively-curved Riemannian manifolds \cite[Theorem I.13.5]{helg_dglgssp}. 

    \item Cf. also \cite[Corollary X.1]{hm_split}, ``straightening'' a direct product decomposition $\bR^d\times \left(\text{compact}\right)$ into a $\bK$-invariant one whenever a compact group $\bK$ operates on such a product.

    \end{itemize}

  \item The case $\bG\cong V\rtimes \bM$ with $V\cong \bR^d$ and the compact group $\bM$ carrying $\bK$-actions and $\bM$ is represented on $V$ $\bK$-equivariantly can be cast as an instance of cohomology vanishing for compact groups.

    denote the $\bK$-actions on $V$ and $\bM$ by left-hand superscripts. Defining
    \begin{equation*}
      \tensor*[^s]{(0,g)}{}
      =:
      \left(v_{s,g},\tensor*[^s]{g}{}\right)
      ,\quad
      s\in \bK
      ,\quad
      v_{\bullet}\in V
      \quad\text{and}\quad
      g\in \bM,
    \end{equation*}
    a straightforward computation shows that
    \begin{equation*}
      \bK
      \ni s
      \xmapsto{\quad\varphi\quad}
      \left(\bM\ni g
        \xmapsto{\quad}
        v_{\tensor*[^s]{g}{},s}
        \in V
      \right)    
    \end{equation*}
    is a \emph{1-cocycle} \cite[\S 5.1]{ser_gal}
    \begin{equation*}
      \varphi
      \in
      Z^1\left(\bK,\ Z^1\left(\bM,\ V\right)\right),
    \end{equation*}
    with $\bK$ acting on the space of (continuous) 1-cocycles $\bM\to V$ by
    \begin{equation*}
      \tensor*[^s]{\psi}{}
      :=
      \tensor*[^s]{\left(\psi(\tensor*[^{s^{-1}}]{\bullet}{})\right)}{}
      ,\quad
      s\in \bK
      ,\quad
      \psi\in Z^1(\bM,V). 
    \end{equation*}
    The usual \cite[I, Theorem 2.3]{moore-ext} Haar averaging technique for compact-group cohomology shows that cocycles are coboundaries, so there must be some $v\in V$ with 
    \begin{equation*}
      \forall\left(s\in \bK\right)
      \forall\left(g\in \bM\right)
      \quad:\quad
      \tensor*[^s]{(v-gv,\ g)}{}
      =
      \left(\tensor*[^s]{v}{}-\tensor*[^s]{g}{}\tensor*[^s]{v}{},\ \tensor*[^s]{g}{}\right);
    \end{equation*}
    or: the (maximal compact) conjugate
    \begin{equation*}
      \Ad_{(v,1)}\bM
      =
      \left\{\left(v-gv,\ g\right)\ :\ g\in \bM\right\}
      \le
      V\rtimes \bM
    \end{equation*}
    of $\bM\le V\rtimes \bM$ is $\bK$-invariant.
  \end{enumerate}
\end{remarks}

We observed in the course of the proof of \Cref{pr:lc.alm.conn.max.cpct.inv} that
\begin{equation}\label{eq:int.norm.mc}
  \left.
    \begin{aligned}
      \bG&\quad\text{locally compact almost-connected}\\
      \bH&\trianglelefteq \bG\quad\text{normal}\\
      \bM&\le \bG\quad\text{maximal compact}
    \end{aligned}
  \right\}
  \quad\xRightarrow{\quad}\quad
  \bM\cap \bH\le \bH\quad\text{maximal compact}
\end{equation}
The analogous statement holds \cite[Lemma 3.10(iv)]{zbMATH00540631} for closed, possibly non-normal $\bH\le \bG$ containing $\bG_0$. We record in \Cref{le:norm.by.g0}, for completeness and future reference, a common generalization. 

\begin{lemma}\label{le:norm.by.g0}
  Let $\bG$ be a locally compact almost-connected group and $\bM\le \bG$ maximal compact.

  Whenever the closed subgroup $\bH\le \bG$ is normalized by the identity component $\bG_0$, the intersection $\bH\cap \bM\le \bH$ is maximal compact. 
\end{lemma}
\begin{proof}
  Apply \cite[Lemma 3.10(iv)]{zbMATH00540631} to the $\bG_0$-containing closed subgroup $\widetilde{\bH}:=\overline{\bG_0\cdot \bH}$ to conclude that $\bM\cap \widetilde{\bH}\le \widetilde{\bH}$ is maximal compact, and then again \Cref{eq:int.norm.mc} with $\widetilde{\bH}$ (where $\bH$ is normal) in place of $\bG$. 
\end{proof}

\begin{remark}\label{re:bagley.ea}
  The remarks preliminary to \cite[Lemma 3.10]{zbMATH00540631} refer to \cite[Lemma 1.8]{zbMATH00025545} as a slight generalization of \cite[Lemma 3.10(iv)]{zbMATH00540631}, but note that the former result deduces the maximality of $\bM\cap \bH\le \bH$ among compact \emph{normal} subgroups provided $\bH\trianglelefteq \bG$ is closed normal and $\bM\le \bG$ is maximal compact and again normal. So this is yet another variant of the result. 
\end{remark}

