        \draw[blue] (D) circle (2.5); % Circle with diameter AB
        \draw[red] (E) circle (2); % Circle with diameter AC
        \draw[green] (1.5,0) circle (1.5); % Circle with diameter BC
        \coordinate (G) at (1.92,1.44);

        \draw[dashed] (G) -- (C);
        \draw[dashed] (E) -- (G);
        \draw[dashed] (1.5,0) -- (G);
        \draw[dotted] (G) -- (J);
        \draw[dotted] (G) -- (H);
        \draw[dashed] (C) -- (D);
        \node at (A) [above left] {A};
        \node at (B) [below right] {B};
        \node at (C) [below left] {C};
        \node at (D) [right] {D};
        \node at (E) [left] {E};
        \node at (F) [below] {F};
        \node at (G) [above right] {G};
        \node at (H) [left] {H};
        \node at (J) [below] {J};
        \node at (E) [above right] {$b$};
        \node at (F) [above left] {$a$};
